-- بيانات مقرر كيمياء 1 (المقرر 2، قيد الإعداد) — الجزء 3 من 5. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C2-L4-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'المركبان A وB يتكونان من العنصرين X وY. يتحد 3.0 g من X مع 4.0 g من Y في المركب A، ويتحد 3.0 g من X مع 8.0 g من Y في المركب B. ما نسبة كتلة Y في B إلى كتلة Y في A عند كتلة ثابتة من X؟', null, '["2:1","1:2","3:4","8:3"]'::jsonb, 'تطبيق', 'تطبيق قانون النسب المتضاعفة مع كتلة ثابتة', 'سهل', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 2, 'يبيّن الجدول النسبتين المئويتين بالكتلة في مركبين للنحاس والكلور. ما كتلة النحاس المتحدة مع 1 g من الكلور في المركب I؟', '{"headers":["المركب","نحاس %","كلور %"],"rows":[["I","64.20","35.80"],["II","47.27","52.73"]]}'::jsonb, '["0.8964 g","0.5577 g","1.793 g","64.20 g"]'::jsonb, 'تطبيق', 'حساب كتلة عنصر لكل 1 g من عنصر آخر', 'متوسط', 'الكتاب ص 63 — مركبات النحاس والكلور، الجدول 5-2'),
('mcq', 3, 'في المركب I يتحد 32.0 g من الكبريت مع 32.0 g من الأكسجين، وفي المركب II يتحد 32.0 g من الكبريت مع 48.0 g من الأكسجين. ما نسبة كتلتي الأكسجين (المركب I إلى المركب II) المتحدتين مع كتلة ثابتة من الكبريت؟', null, '["3:2","2:3","1:1","2:5"]'::jsonb, 'تطبيق', 'نسبة كتلتي الأكسجين مع كبريت ثابت', 'سهل', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 4, 'عينة من المركب I تحتوي على 2.80 g نيتروجين و1.60 g أكسجين، وعينة من المركب II تحتوي على 4.20 g نيتروجين و4.80 g أكسجين. ما نسبة كتلتي الأكسجين المتحدتين مع 1 g نيتروجين (المركب II إلى المركب I)؟', null, '["3:1","3:2","1:2","2:1"]'::jsonb, 'تطبيق', 'تطبيق القانون بتثبيت كتلة النيتروجين', 'صعب', 'الكتاب ص 71 — السؤال 71'),
('mcq', 5, 'يتحد 12.0 g من الكربون مع 16.0 g من الأكسجين في المركب I، ومع 32.0 g من الأكسجين في المركب II. ما كتلة الأكسجين التي تتحد مع 6.0 g من الكربون في المركب II؟', null, '["32.0 g","16.0 g","8.0 g","64.0 g"]'::jsonb, 'تطبيق', 'حساب كتلة بتناسب النسب', 'سهل', 'الكتاب ص 71 — السؤال 71'),
('mcq', 6, 'في المركب I يتحد 3.10 g من الفوسفور مع 10.63 g من الكلور، وفي المركب II يتحد 3.10 g من الفوسفور مع 17.72 g من الكلور. أيّ العبارات الآتية صحيحة؟', null, '["نسبة كتلتي الكلور مع كتلة ثابتة من الفوسفور تقارب 5:3، وهي نسبة عددية بسيطة فينطبق القانون","نسبة كتلتي الكلور 1.67:1 ليست عددًا صحيحًا فلا ينطبق قانون النسب المتضاعفة","لا ينطبق قانون النسب المتضاعفة لأن المركبين مكوّنان من العنصرين نفسيهما","لا ينطبق قانون النسب المتضاعفة لأن كتلتي الكلور في المركبين مختلفتان"]'::jsonb, 'تحليل', 'التحقق من انطباق القانون', 'متوسط', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 7, 'في المركب I تتحد 7.00 g من الحديد مع 2.00 g من الأكسجين، وفي المركب II تتحد 14.0 g من الحديد مع 6.00 g من الأكسجين. ما نسبة كتلة الحديد المتحدة مع 1 g من الأكسجين في المركب I إلى نسبتها في المركب II؟', null, '["1:2","1:3","3:2","2:3"]'::jsonb, 'تطبيق', 'تثبيت كتلة الأكسجين وحساب النسبة', 'صعب', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('essay', 1, 'المركب I يحتوي على 75.0% كربون و25.0% هيدروجين بالكتلة، والمركب II يحتوي على 80.0% كربون و20.0% هيدروجين بالكتلة. احسب كتلة الكربون المتحدة مع 1 g من الهيدروجين في كل مركب، ثم احسب نسبتهما (I إلى II)، وبيّن هل تنطبق عليهما قاعدة النسب المتضاعفة.', null, null, 'تطبيق', 'حساب النسبة المتضاعفة من نسب مئوية', 'متوسط', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('essay', 2, 'تحتوي عينة كتلتها 36.0 g من الماء H₂O على 4.0 g هيدروجين والباقي أكسجين، وعينة كتلتها 34.0 g من فوق أكسيد الهيدروجين H₂O₂ على 2.0 g هيدروجين والباقي أكسجين. احسب كتلة الأكسجين المتحدة مع 1 g هيدروجين في كل مركب، ثم نسبتهما (H₂O₂ إلى H₂O)، وفسّر دلالة النتيجة.', null, null, 'تطبيق', 'تطبيق قانون النسب المتضاعفة على الماء وفوق الأكسيد', 'صعب', 'الكتاب ص 63 — الماء وفوق أكسيد الهيدروجين'),
('essay', 3, 'في المركب I يتحد 28.0 g نيتروجين مع 16.0 g أكسجين، وفي المركب II يتحد 14.0 g نيتروجين مع 16.0 g أكسجين. (أ) احسب نسبة كتلتي النيتروجين المتحدتين مع 16.0 g أكسجين (I إلى II). (ب) في مركب ثالث يتحد 14.0 g نيتروجين مع 32.0 g أكسجين؛ احسب كتلة النيتروجين المتحدة مع 16.0 g أكسجين فيه، ثم نسبتها إلى كتلة النيتروجين المتحدة في المركب I، وبيّن هل تتفق النتيجتان مع قانون النسب المتضاعفة.', null, null, 'تطبيق', 'حساب وتوقع نسب متضاعفة', 'صعب', 'الكتاب ص 63 — قانون النسب المتضاعفة، ص 71 — السؤال 74')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C2-L4-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'كتلة X ثابتة (3.0 g) في المركبين، فنسبة كتلتي Y في B إلى A = 8.0 ÷ 4.0 = 2:1، وهي نسبة عددية بسيطة؛ وهو الخيار الأول.', '["","هذه النسبة معكوسة (A إلى B) والمطلوب B إلى A.","قارن كتلة X (3.0 g) بكتلة Y في A، وهذه ليست نسبة كتلتي Y.","قارن كتلة Y في B بكتلة X، وليس كتلتي Y في المركبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.672Z"}'::jsonb),
('mcq', 2, 2, 'كتلة النحاس لكل 1 g كلور في المركب I = 64.20 ÷ 35.80 = 1.793 g، وهو الخيار الثالث.', '["هذه كتلة النحاس لكل 1 g كلور في المركب II (47.27 ÷ 52.73) وليس I.","هذه كتلة الكلور لكل 1 g نحاس (35.80 ÷ 64.20)؛ قُلبت النسبة.","","هذه النسبة المئوية للنحاس وليست كتلته لكل 1 g كلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.672Z"}'::jsonb),
('mcq', 3, 1, 'كتلة الكبريت ثابتة (32.0 g)، فنسبة كتلتي الأكسجين I إلى II = 32.0 ÷ 48.0 = 2:3، وهو الخيار الثاني.', '["هذه النسبة معكوسة (II إلى I).","","هذه نسبة كتلتي الكبريت المتساويتين وليست نسبة كتلتي الأكسجين.","قارن كتلة الأكسجين في I (32.0 g) بكتلة المركب II كله (80.0 g)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.673Z"}'::jsonb),
('mcq', 4, 3, 'كتلة الأكسجين لكل 1 g نيتروجين: في I = 1.60 ÷ 2.80 = 0.571 g، وفي II = 4.80 ÷ 4.20 = 1.14 g. النسبة II إلى I = 1.14 ÷ 0.571 = 2:1، وهو الخيار الرابع.', '["هذه نسبة كتلتي الأكسجين الخام (4.80 ÷ 1.60) دون جعل كتلة النيتروجين ثابتة.","هذه نسبة كتلتي النيتروجين الخام (4.20 ÷ 2.80) وليست نسبة الأكسجين.","هذه النسبة معكوسة (I إلى II).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.673Z"}'::jsonb),
('mcq', 5, 1, 'في المركب II تتحد 32.0 g أكسجين مع 12.0 g كربون، فمع 6.0 g (نصف الكمية) تتحد نصف كتلة الأكسجين: 32.0 × 6.0 ÷ 12.0 = 16.0 g، وهو الخيار الثاني.', '["هذه كتلة الأكسجين مع 12.0 g كربون وليس مع 6.0 g.","","هذه كتلة الأكسجين مع 6.0 g كربون في المركب I وليس II.","ضُربت الكتلة في 2 بدل قسمتها؛ فالكربون أقل من 12.0 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.673Z"}'::jsonb),
('mcq', 6, 0, 'كتلة الفوسفور ثابتة (3.10 g)، ونسبة كتلتي الكلور II إلى I = 17.72 ÷ 10.63 = 1.667 أي 5:3، وهي نسبة عددية بسيطة وصحيحة؛ فينطبق القانون، وهو الخيار الأول.', '["","النسبة العددية البسيطة قد تُكتب بأعداد صحيحة 5:3، فالقيمة 1.67 تكافئها ولا تنفي القانون.","القانون ينطبق تحديدًا حين يتكون مركبان مختلفان من العنصرين نفسيهما.","اختلاف كتلتي الكلور هو الذي يُقارَن بنسبة بسيطة؛ ولا ينفي القانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.674Z"}'::jsonb),
('mcq', 7, 2, 'كتلة الحديد لكل 1 g أكسجين: في I = 7.00 ÷ 2.00 = 3.50 g، وفي II = 14.0 ÷ 6.00 = 2.33 g. النسبة I إلى II = 3.50 ÷ 2.33 = 1.5 أي 3:2، وهو الخيار الثالث.', '["هذه نسبة كتلتي الحديد الخام (7.00 ÷ 14.0) دون تثبيت كتلة الأكسجين.","هذه نسبة كتلتي الأكسجين الخام (2.00 ÷ 6.00) وليست نسبة الحديد.","","هذه النسبة معكوسة (II إلى I)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.674Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في المركب I: كتلة الكربون لكل 1 g هيدروجين = 75.0 ÷ 25.0 = 3.00 g. في المركب II: = 80.0 ÷ 20.0 = 4.00 g. النسبة I إلى II = 3.00 ÷ 4.00 = 0.750 أي 3:4. هذه نسبة عددية بسيطة وصحيحة بين كتلتي الكربون المتحدتين مع كتلة ثابتة (1 g) من الهيدروجين؛ فينطبق قانون النسب المتضاعفة.', '["كتلة C لكل 1 g H في I تساوي 3.00 g","كتلة C لكل 1 g H في II تساوي 4.00 g","النسبة I إلى II تساوي 3:4","النسبة عددية بسيطة وصحيحة فينطبق القانون"]'::jsonb, '["I: 75.0 g C ÷ 25.0 g H = 3.00 g C لكل 1 g H","II: 80.0 g C ÷ 20.0 g H = 4.00 g C لكل 1 g H","النسبة I : II = 3.00 : 4.00 = 3:4"]'::jsonb, '[{"element":"كتلة الكربون لكل 1 g هيدروجين في I","marks":1},{"element":"كتلة الكربون لكل 1 g هيدروجين في II","marks":1},{"element":"النسبة 3:4","marks":1},{"element":"الحكم بانطباق القانون مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح للكتلتين والنسبة والحكم بالتعليل"},{"level":"2–3 درجات","description":"حساب صحيح لكتلة واحدة أو للكتلتين دون النسبة أو دون التعليل"},{"level":"1 درجة","description":"محاولة صحيحة الاتجاه دون نتيجة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة النسبة المئوية للهيدروجين على الكربون (قلب النسبة)","مقارنة 75.0 و80.0 مباشرة دون تثبيت كتلة الهيدروجين","عدم التعبير عن النسبة بأعداد صحيحة بسيطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.674Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كتلة الأكسجين في عينة الماء = 36.0 − 4.0 = 32.0 g، فلكل 1 g هيدروجين: 32.0 ÷ 4.0 = 8.0 g أكسجين. كتلة الأكسجين في عينة فوق أكسيد الهيدروجين = 34.0 − 2.0 = 32.0 g، فلكل 1 g هيدروجين: 32.0 ÷ 2.0 = 16.0 g أكسجين. نسبة كتلتي الأكسجين (H₂O₂ إلى H₂O) = 16.0 ÷ 8.0 = 2:1. وهي نسبة عددية بسيطة وصحيحة؛ وهذا يوافق قانون النسب المتضاعفة، إذ يتكون المركبان من العنصرين نفسيهما بنسب كتلية مختلفة، وفي H₂O₂ ضعف كمية الأكسجين المتحدة مع كتلة ثابتة من الهيدروجين.', '["كتلة الأكسجين في العينتين 32.0 g","8.0 g أكسجين لكل 1 g هيدروجين في الماء","16.0 g أكسجين لكل 1 g هيدروجين في H₂O₂","النسبة 2:1","نسبة عددية بسيطة وفق قانون النسب المتضاعفة"]'::jsonb, '["O في الماء = 36.0 − 4.0 = 32.0 g؛ لكل 1 g H: 32.0 ÷ 4.0 = 8.0 g","O في H₂O₂ = 34.0 − 2.0 = 32.0 g؛ لكل 1 g H: 32.0 ÷ 2.0 = 16.0 g","النسبة H₂O₂ : H₂O = 16.0 ÷ 8.0 = 2:1"]'::jsonb, '[{"element":"كتلة الأكسجين في العينتين بالطرح","marks":1},{"element":"كتلة الأكسجين لكل 1 g هيدروجين في المركبين","marks":2},{"element":"النسبة 2:1","marks":1},{"element":"الدلالة وفق قانون النسب المتضاعفة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كل الحسابات صحيحة، والنسبة 2:1، وتفسير صحيح بالقانون"},{"level":"3–4 درجات","description":"حسابات صحيحة مع نقص في النسبة أو التفسير"},{"level":"1–2 درجة","description":"حساب كتلة الأكسجين فقط أو حساب جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان طرح كتلة الهيدروجين لإيجاد كتلة الأكسجين","مقارنة كتلتي الأكسجين الخام (32.0 g و32.0 g) دون تثبيت كتلة الهيدروجين","قلب النسبة فتصبح 1:2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.674Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كتلة الأكسجين ثابتة (16.0 g)، فنسبة كتلتي النيتروجين I إلى II = 28.0 ÷ 14.0 = 2:1. (ب) في المركب الثالث تتحد 14.0 g نيتروجين مع 32.0 g أكسجين، فمع 16.0 g أكسجين (نصف الكمية) تتحد 14.0 × 16.0 ÷ 32.0 = 7.0 g نيتروجين. نسبة كتلة النيتروجين في I إلى الثالث = 28.0 ÷ 7.0 = 4:1. النسبتان 2:1 و4:1 عددان صحيحان بسيطان، فتتفقان مع قانون النسب المتضاعفة.', '["النسبة (أ) = 2:1","كتلة N مع 16.0 g أكسجين في المركب الثالث = 7.0 g","النسبة (ب) = 4:1","النسبتان عددان صحيحان بسيطان فيتفقان مع القانون"]'::jsonb, '["(أ) 28.0 g ÷ 14.0 g = 2، فالنسبة 2:1","(ب) كتلة N مع 16.0 g O في المركب الثالث = 14.0 × (16.0 ÷ 32.0) = 7.0 g","28.0 g ÷ 7.0 g = 4، فالنسبة 4:1"]'::jsonb, '[{"element":"النسبة 2:1 في الفرع (أ)","marks":1},{"element":"كتلة النيتروجين 7.0 g في المركب الثالث","marks":1},{"element":"النسبة 4:1","marks":1},{"element":"الحكم بالاتفاق مع القانون وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نسبتان صحيحتان وكتلة صحيحة وحكم معلل"},{"level":"2–3 درجات","description":"نسبة واحدة صحيحة أو كتلة صحيحة مع حكم ناقص"},{"level":"1 درجة","description":"خطوة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 14.0 g على 32.0 g دون تثبيت كتلة الأكسجين عند 16.0 g","قلب النسبة فتصبح 1:2 أو 1:4","عدم الربط بين نتيجة النسبة وقانون النسب المتضاعفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.675Z"}'::jsonb)
