from (values
('mcq', 1, 'لماذا تختلف خواص المركب عن خواص العناصر المكونة له؟', null, '["لأن العناصر تحتفظ بخواصها كاملة داخل المركب","لأن المركب ناتج عن تفاعل كيميائي بين العناصر فتتكون مادة جديدة","لأن كتلة المركب أكبر من مجموع كتل عناصره","لأن المركب مزيج فيزيائي من العناصر نفسها"]'::jsonb, 'فهم', 'تفسير سبب اختلاف الخواص', 'سهل', 'الكتاب ص 60 — خواص المركبات'),
('mcq', 2, 'يبيّن الجدول خواص عنصرين. اتحد هذان العنصران كيميائيًّا فتكوّن يوديد البوتاسيوم KI. أيّ العبارات الآتية تصف KI بدقة؟', '{"headers":["العنصر","الخواص عند حرارة الغرفة"],"rows":[["البوتاسيوم K","فلز فضي"],["اليود I₂","مادة صلبة سوداء"]]}'::jsonb, '["ملح أبيض تختلف خواصه عن خواص الفلز الفضي وعن الصلب الأسود","فلز فضي يشبه البوتاسيوم لأنه يحتوي عليه","مادة صلبة سوداء تشبه اليود لأنها تحتوي عليه","مزيج من فلز فضي ومادة صلبة سوداء تحتفظان بخواصهما"]'::jsonb, 'فهم', 'وصف خواص مركب مقارنة بعنصريه', 'سهل', 'الكتاب ص 60 — يوديد البوتاسيوم'),
('mcq', 3, 'أيّ المقارنات الآتية بين الماء وعنصريه الهيدروجين والأكسجين صحيحة؟', null, '["الماء غاز عديم اللون يتفاعل بشدة مع عدة عناصر مثل عنصريه","الهيدروجين والأكسجين سائلان مستقران عند الحرارة العادية مثل الماء","خواص الماء مطابقة لخواص الهيدروجين والأكسجين مجتمعين","الماء مركب مستقر سائل، وعنصراه غازان عديما اللون والرائحة شديدا التفاعل"]'::jsonb, 'فهم', 'مقارنة خواص الماء وعنصريه', 'سهل', 'الكتاب ص 60 — خواص المركبات (الماء)'),
('mcq', 4, 'لماذا يختلف الماء السائل في خواصه عن خليط غازي الهيدروجين والأكسجين؟', null, '["لأن الغازين في الخليط يفقدان خواصهما بمجرد امتزاجهما","لأن الماء يحتوي على كمية أكبر من الهيدروجين دون حدوث تفاعل","لأن العنصرين في الماء اتحدا كيميائيًّا فتكونت مادة جديدة بخواص مختلفة","لأن الماء يتكون من عنصرين مختلفين والخليط من عنصر واحد"]'::jsonb, 'فهم', 'التمييز بين مركب ومخلوط عناصره', 'متوسط', 'الكتاب ص 60، 71 — خواص المركبات، السؤال 84'),
('mcq', 5, 'عند التحليل الكهربائي للماء يتصاعد غازان عديما اللون والرائحة، ويتفاعل كل منهما بشدة مع عدة عناصر، بينما الماء سائل مستقر. ماذا يدل عليه ذلك؟', null, '["الماء مخلوط من غازين احتفظ كل منهما بخواصه","خواص الماء مطابقة لخواص الغازين الناتجين","التحليل الكهربائي عملية فيزيائية لا تنتج مواد جديدة","خواص المركب (الماء) تختلف عن خواص العنصرين الناتجين عنه"]'::jsonb, 'تحليل', 'استنتاج من ملاحظات التحليل الكهربائي', 'متوسط', 'الكتاب ص 60 — التحليل الكهربائي وخواص الماء'),
('mcq', 6, 'أيّ الملاحظات الآتية دليل على أن يوديد البوتاسيوم KI ناتج عن تفاعل كيميائي بين البوتاسيوم واليود وليس مزيجًا منهما؟', null, '["أنه يحتوي على البوتاسيوم واليود","أنه ملح أبيض خواصه تختلف عن خواص الفلز الفضي والصلب الأسود","أنه يمكن تحضيره في المختبر","أنه يتكون من عنصرين مختلفين"]'::jsonb, 'تحليل', 'اختيار الدليل على التفاعل الكيميائي', 'صعب', 'الكتاب ص 60 — يوديد البوتاسيوم'),
('mcq', 7, 'اتحد فلز فضي X مع مادة صلبة سوداء Y فتكوّنت المادة Z. ما العبارة الأصح عن خواص Z؟', null, '["Z فلز فضي صلب لأنه يحتوي على العنصر X","Z مادة صلبة سوداء لأن Y هي الأكثر كمية فيه","قد تختلف خواص Z عن خواص X وY لأنه مادة جديدة","تتوسط خواص Z بين خواص X وخواص Y تمامًا"]'::jsonb, 'تطبيق', 'تطبيق على موقف جديد', 'متوسط', 'الكتاب ص 60 — خواص المركبات'),
('essay', 1, 'البوتاسيوم K فلز فضي، واليود I₂ مادة صلبة سوداء توجد على هيئة غاز بنفسجي اللون في درجة حرارة الغرفة، ويوديد البوتاسيوم KI ملح أبيض ناتج عن اتحادهما. قارن بين خواص المركب وخواص عنصريه، ثم فسّر سبب هذا الاختلاف.', null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 60 — يوديد البوتاسيوم'),
('essay', 2, 'الماء مركب مستقر سائل عند درجات الحرارة العادية، ويمكن تحليله كهربائيًّا إلى غازين. قارن بين خواص الماء وخواص الغازين الناتجين، وبيّن ما يدل عليه ذلك، ولماذا يحتاج تفكيك الماء إلى طاقة.', null, null, 'فهم', 'مقارنة واستنتاج وتفسير', 'صعب', 'الكتاب ص 60 — التحليل الكهربائي وخواص الماء'),
('essay', 3, 'وُضع غازا الهيدروجين والأكسجين معًا في وعاء مغلق دون أن يحدث بينهما تفاعل، وفي وعاء آخر اتحدا كيميائيًّا فنتج الماء. قارن بين محتوى الوعاءين من حيث خواص المادة الموجودة، وفسّر سبب الاختلاف.', null, null, 'تحليل', 'مقارنة مخلوط ومركب من العنصرين نفسيهما', 'صعب', 'الكتاب ص 60، 71 — خواص المركبات، السؤال 84')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
