from (values
('mcq', 1, 1, 'ينتج المركب عن تفاعل كيميائي بين العناصر فتتكون مادة جديدة بخواص مختلفة عن خواص عناصرها؛ فالخيار الثاني هو الصحيح.', '["لو احتفظت العناصر بخواصها لما اختلف المركب عنها؛ وهذا وصف المخلوط وليس المركب.","","كتلة المركب تساوي مجموع كتل عناصره، وهذا لا علاقة له باختلاف الخواص.","المزيج الفيزيائي هو المخلوط، وفيه تبقى خواص المكونات؛ أما المركب فناتج عن تفاعل كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.676Z"}'::jsonb),
('mcq', 2, 0, 'يوديد البوتاسيوم KI ملح أبيض، وخواصه تختلف عن خواص البوتاسيوم (فلز فضي) واليود (مادة صلبة سوداء)؛ لأنه مادة جديدة ناتجة عن تفاعل كيميائي بينهما، وهو الخيار الأول.', '["","احتواء المركب على عنصر لا يعني أنه يشبهه؛ فـ KI ملح أبيض وليس فلزًا فضيًّا.","احتواء المركب على اليود لا يجعله مادة سوداء؛ فخواص KI مختلفة تمامًا.","KI مركب ناتج عن اتحاد كيميائي وليس مزيجًا؛ فلا تبقى فيه خواص العنصرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.676Z"}'::jsonb),
('mcq', 3, 3, 'الماء مركب مستقر وهو سائل عند درجات الحرارة العادية، أما الهيدروجين والأكسجين فغازان عديما اللون والرائحة ويتفاعلان بشدة مع عدة عناصر؛ فالخيار الرابع هو الصحيح.', '["الماء سائل مستقر عند الحرارة العادية وليس غازًا شديد التفاعل.","الهيدروجين والأكسجين غازان وليسا سائلين.","خواص الماء تختلف كثيرًا عن خواص عنصريه، وليست مطابقة لها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.676Z"}'::jsonb),
('mcq', 4, 2, 'في الماء اتحد الهيدروجين والأكسجين كيميائيًّا فتكونت مادة جديدة خواصها تختلف عن خواص العنصرين، أما في الخليط فلا يحدث تفاعل وتبقى خواص كل غاز؛ فالخيار الثالث هو الصحيح.', '["الغازان يحتفظان بخواصهما في الخليط ولا يفقدانها بالامتزاج.","الاختلاف ليس بسبب الكمية، بل بسبب حدوث تفاعل كيميائي.","","الخليط أيضًا يتكون من عنصرين (الهيدروجين والأكسجين)؛ والفرق هو حدوث الاتحاد الكيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.676Z"}'::jsonb),
('mcq', 5, 3, 'الماء سائل مستقر، أما الغازان الناتجان فعديما اللون والرائحة وشديدا التفاعل؛ فهذا يدل على أن خواص المركب تختلف عن خواص عناصره، وهو الخيار الرابع.', '["لو كان الماء مخلوطًا لبقيت خواص الغازين فيه، لكنه سائل مستقر وهما غازان شديدا التفاعل.","الماء سائل مستقر والغازان شديدا التفاعل؛ فخواصهما مختلفة.","التحليل الكهربائي تغير كيميائي ينتج مادتين جديدتين مختلفتين عن الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.677Z"}'::jsonb),
('mcq', 6, 1, 'في المزيج تبقى خواص المكونات، أما في المركب فتتكون مادة جديدة؛ ولأن KI ملح أبيض تختلف خواصه عن خواص K وI₂ فهو ناتج عن تفاعل كيميائي، وهو الخيار الثاني.', '["المزيج أيضًا يحتوي على البوتاسيوم واليود؛ فلا يميّز هذا بين المركب والمزيج.","","إمكان تحضير مادة في المختبر لا يدل على أنها مركب؛ فالمخاليط تُحضَّر كذلك.","المزيج أيضًا يتكون من عنصرين مختلفين؛ فهذا لا يميّز المركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.677Z"}'::jsonb),
('mcq', 7, 2, 'الاتحاد الكيميائي ينتج مادة جديدة تختلف خواصها عن خواص العناصر المكونة لها (كما اختلف KI عن K وI₂)، فلا يمكن افتراض أن Z يشبه X أو Y؛ والخيار الثالث هو الصحيح.', '["احتواء المركب على عنصر لا يعني أنه يحمل خواصه.","كمية العنصر لا تحدد خواص المركب؛ فخواصه تختلف عن خواص عناصره.","","خواص المركب ليست متوسطًا لخواص عناصره، بل قد تكون مختلفة تمامًا عنها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.677Z"}'::jsonb),
('essay', 1, null::int, null, null, 'خواص KI تختلف عن خواص عنصريه: فالبوتاسيوم فلز فضي، واليود مادة صلبة سوداء توجد على هيئة غاز بنفسجي، أما KI فملح أبيض. يعود الاختلاف إلى أن المركب ناتج عن تفاعل كيميائي بين العنصرين تتكون به مادة جديدة تختلف خواصها عن خواص عناصرها، فلا يحتفظ المركب بخواص العنصرين.', '["البوتاسيوم فلز فضي","اليود مادة صلبة سوداء (غاز بنفسجي)","KI ملح أبيض","الخواص تختلف بسبب تفاعل كيميائي ينتج مادة جديدة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف خواص العنصرين","marks":1},{"element":"وصف خواص KI وبيان اختلافها","marks":1},{"element":"التفسير بالتفاعل الكيميائي وتكون مادة جديدة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة للخواص وتفسير كامل بالتفاعل الكيميائي"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع تفسير ناقص"},{"level":"1 درجة","description":"ذكر خاصية أو خاصيتين دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن KI يشبه البوتاسيوم لأنه يحتوي عليه","عدّ KI مزيجًا من العنصرين","ذكر الاختلاف دون تعليله"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.677Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الماء مركب مستقر وسائل، أما الغازان الناتجان (الهيدروجين والأكسجين) فعديما اللون والرائحة ويتفاعلان بشدة مع عدة عناصر؛ فخواص الماء تختلف كثيرًا عن خواص عنصريه. وهذا يدل على أن خواص المركب تختلف عن خواص العناصر المكونة له لأنه ناتج عن تفاعل كيميائي بين العناصر. ولأن المركبات الموجودة في الطبيعة أكثر استقرارًا من حالة عناصرها، فإن تفكيك الماء يحتاج إلى طاقة كالكهرباء أو الحرارة.', '["الماء مركب مستقر وسائل","الهيدروجين والأكسجين غازان عديما اللون والرائحة يتفاعلان بشدة","خواص المركب تختلف عن خواص عناصره","السبب: تفاعل كيميائي بين العناصر","تفكيك المركب المستقر يحتاج إلى طاقة كالكهرباء"]'::jsonb, '[]'::jsonb, '[{"element":"وصف خواص الماء","marks":1},{"element":"وصف خواص الغازين","marks":1},{"element":"الاستنتاج بأن خواص المركب تختلف عن عناصره وتعليله بالتفاعل الكيميائي","marks":2},{"element":"حاجة تفكيك الماء إلى طاقة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح للخواص، واستنتاج معلل، وبيان حاجة التفكيك إلى طاقة"},{"level":"3–4 درجات","description":"وصف صحيح مع نقص في الاستنتاج أو الطاقة"},{"level":"1–2 درجة","description":"وصف جزئي للخواص دون استنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء غاز لأنه يتكون من غازين","عدّ التحليل الكهربائي تغيرًا فيزيائيًّا","عدم ذكر الطاقة اللازمة لتفكيك المركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.677Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في الوعاء الأول خليط من غازين لم يتفاعلا، فيبقى كل غاز محتفظًا بخواصه (عديم اللون والرائحة وشديد التفاعل). وفي الوعاء الثاني ماء، وهو مركب مستقر سائل خواصه تختلف عن خواص الغازين. يعود الاختلاف إلى أن الماء ناتج عن تفاعل كيميائي بين الهيدروجين والأكسجين فتكونت مادة جديدة، بينما لم يحدث تفاعل في الوعاء الأول فلم تتكون مادة جديدة.', '["الوعاء الأول: خليط، كل غاز يحتفظ بخواصه","الوعاء الثاني: ماء مركب سائل مستقر بخواص مختلفة","سبب الاختلاف: حدوث تفاعل كيميائي في الثاني","تكوّن مادة جديدة في الثاني فقط"]'::jsonb, '[]'::jsonb, '[{"element":"وصف محتوى الوعاء الأول وخواصه","marks":1},{"element":"وصف محتوى الوعاء الثاني وخواصه","marks":1},{"element":"تفسير الاختلاف بالتفاعل الكيميائي وتكوّن مادة جديدة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح للوعاءين وتفسير كامل"},{"level":"2–3 درجات","description":"وصف صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"وصف أحد الوعاءين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوعاءين يحتويان على المادة نفسها","نسبة اختلاف الخواص إلى اختلاف الكمية","عدم التمييز بين المخلوط والمركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.678Z"}'::jsonb)
