('essay', 2, 'أربع مواد مجهولة A وB وC وD، وصفت كما يأتي: A مادة نقية يمكن تحليلها كهربائيًّا إلى مادتين أبسط منها؛ B مادة نقية لا يمكن تجزئتها إلى مواد أبسط بأي طريقة فيزيائية أو كيميائية؛ C مادة تتكون من عدة مواد ويمكن تمييز مكوناتها بالعين وفصلها بالترشيح؛ D مادة مظهرها منتظم في جميع أجزائها لكنها تتكون من مادتين نقيتين يمكن فصلهما بطريقة فيزيائية. صنّف كل مادة منها، وبيّن الأساس الذي اعتمدت عليه في كل تصنيف.', null, null, 'تحليل', 'تصنيف من خواص وطرائق فصل', 'صعب', 'الكتاب ص 60، 61 — فصل المركبات، تصنيف المادة'),
('essay', 3, 'عند اتحاد غاز الهيدروجين H₂ مع غاز الأكسجين O₂ يتكون الماء، أما خلط غاز النيتروجين N₂ مع غاز الأكسجين O₂ فينتج الهواء. صنّف الناتج في كل حالة (مركب أو مخلوط)، وفسّر سبب التصنيف، وبيّن الفرق بين الناتجين من حيث إمكان فصل مكوناتهما.', null, null, 'تحليل', 'تمييز مركب من مخلوط', 'صعب', 'الكتاب ص 71 — السؤال 84')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
