from (values
('mcq', 1, 2, 'الذهب عنصر، أي مادة كيميائية نقية لا يمكن تجزئتها إلى مواد أبسط منها بطرائق فيزيائية أو كيميائية؛ فالخيار الثالث هو الصحيح.', '["ملح الطعام (كلوريد الصوديوم) مركب يتكون من عنصري Na وCl.","السكر مركب يتكون من الكربون والهيدروجين والأكسجين.","","الدم مخلوط غير متجانس وليس مادة نقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.678Z"}'::jsonb),
('mcq', 2, 3, 'CO₂ مادة نقية تتكون من عنصرين مختلفين هما الكربون والأكسجين متحدين كيميائيًّا؛ فهي مركب، وهو الخيار الرابع.', '["العنصر يتكون من نوع واحد من الذرات، أما CO₂ ففيه رمزان لعنصرين مختلفين.","المخلوط المتجانس مزيج من مادتين نقيتين أو أكثر؛ وCO₂ مادة نقية واحدة.","المخلوط غير المتجانس مزيج من عدة مواد؛ وCO₂ مادة نقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.678Z"}'::jsonb),
('mcq', 3, 1, 'وجود أكثر من مادة نقية يعني أنها مخلوط، وانتظام تركيبها في جميع أجزائها يعني أنه متجانس؛ فهي مخلوط متجانس، وهو الخيار الثاني.', '["العنصر مادة نقية واحدة، والمادة المذكورة تتكون من أكثر من مادة نقية.","","المخلوط غير المتجانس تُميَّز مكوناته ويختلف تركيبه من جزء إلى آخر.","المركب مادة نقية واحدة، وليس مزيجًا من عدة مواد نقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.678Z"}'::jsonb),
('mcq', 4, 0, 'الحليب مخلوط غير متجانس، والذهب عنصر، والسكر مركب؛ فالخيار الأول وحده صحيح في المواد الثلاث.', '["","الحليب مخلوط غير متجانس وليس متجانسًا.","الذهب عنصر والسكر مركب، وليس العكس.","الحليب مخلوط وليس مركبًا، والسكر مركب وليس مخلوطًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.679Z"}'::jsonb),
('mcq', 5, 2, 'لم يحدث تفاعل كيميائي بين الغازين فلم يتكون مركب، وتبقى المادتان محتفظتين بخواصهما وتنتشران انتشارًا منتظمًا؛ فالناتج مخلوط متجانس، وهو الخيار الثالث.', '["الناتج يحتوي على غازين مختلفين، فليس عنصرًا واحدًا.","المركب ينتج عن تفاعل كيميائي، ولم يحدث هنا تفاعل.","","الغازان ينتشران انتشارًا منتظمًا فلا تُميَّز مكوناتهما، فالمخلوط متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.679Z"}'::jsonb),
('mcq', 6, 0, 'الدم مخلوط غير متجانس، أما الفولاذ والجازولين والشاي فمخاليط متجانسة؛ فالخيار الأول هو الصحيح.', '["","الفولاذ مخلوط متجانس (سبيكة منتظمة التركيب).","الجازولين مخلوط متجانس من عدة سوائل.","الشاي مخلوط متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.679Z"}'::jsonb),
('mcq', 7, 3, 'الحديد عنصر، والسكر مركب، والشاي مخلوط متجانس؛ فالمجموعة الرابعة هي الوحيدة التي تحقق الترتيب المطلوب.', '["الحديد والذهب كلاهما عنصر؛ فلا يوجد مركب في الوسط.","الملح مركب وليس عنصرًا، والدم مخلوط غير متجانس.","الأكسجين عنصر، لكن الدم والحليب كلاهما مخلوط غير متجانس؛ فلا مركب فيها ولا مخلوط متجانس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.679Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الهيليوم: عنصر؛ لأنه مادة نقية لا يمكن تجزئتها إلى مواد أبسط منها. ماء الشرب النقي: مركب؛ لأنه مادة نقية مكونة من الهيدروجين والأكسجين متحدين كيميائيًّا. الماء المالح: مخلوط متجانس؛ لأن الملح يذوب في الماء فيكون تركيبه منتظمًا. الدم: مخلوط غير متجانس؛ لأن مكوناته غير موزعة بانتظام. الفولاذ: مخلوط متجانس؛ لأنه مزيج منتظم التركيب من الحديد والكربون. ملح الطعام: مركب؛ لأنه مادة نقية مكونة من الصوديوم والكلور متحدين كيميائيًّا.', '["الهيليوم عنصر","ماء الشرب النقي مركب","الماء المالح مخلوط متجانس","الدم مخلوط غير متجانس","الفولاذ مخلوط متجانس","ملح الطعام مركب","مبرر مناسب لكل تصنيف"]'::jsonb, '[]'::jsonb, '[{"element":"الهيليوم مع المبرر","marks":1},{"element":"ماء الشرب النقي مع المبرر","marks":1},{"element":"الماء المالح مع المبرر","marks":1},{"element":"الدم مع المبرر","marks":1},{"element":"الفولاذ مع المبرر","marks":1},{"element":"ملح الطعام مع المبرر","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف المواد الست تصنيفًا صحيحًا مع مبرر لكل منها"},{"level":"4–5 درجات","description":"تصنيف صحيح لأربع أو خمس مواد مع مبرراتها"},{"level":"1–3 درجات","description":"تصنيف صحيح لمادة إلى ثلاث مواد، أو تصنيف دون مبررات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الماء المالح مركبًا لأنه يبدو مادة واحدة","عدّ الفولاذ عنصرًا لأنه فلز","عدّ الدم مخلوطًا متجانسًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.679Z"}'::jsonb),
('essay', 2, null::int, null, null, 'A مركب؛ لأنه مادة نقية يمكن تحليلها كيميائيًّا (كهربائيًّا) إلى مواد أبسط. B عنصر؛ لأنه مادة نقية لا يمكن تجزئتها إلى مواد أبسط بطرائق فيزيائية أو كيميائية. C مخلوط غير متجانس؛ لأنه يتكون من عدة مواد يمكن تمييزها بالعين وفصلها فيزيائيًّا. D مخلوط متجانس؛ لأنه يتكون من مادتين نقيتين وتركيبه منتظم في جميع أجزائه.', '["A مركب لقابليته للتحليل الكهربائي إلى مواد أبسط","B عنصر لتعذر تجزئته بطرائق فيزيائية أو كيميائية","C مخلوط غير متجانس لتمييز مكوناته بالعين","D مخلوط متجانس لانتظام تركيبه مع كونه مزيجًا من مادتين"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف A مع الأساس","marks":1},{"element":"تصنيف B مع الأساس","marks":1},{"element":"تصنيف C مع الأساس","marks":1},{"element":"تصنيف D مع الأساس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف المواد الأربع صحيح مع أساس صحيح لكل منها"},{"level":"2–3 درجات","description":"تصنيف صحيح لمادتين أو ثلاث مع أساس"},{"level":"1 درجة","description":"تصنيف صحيح لمادة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المادة D مركبًا لأن مظهرها منتظم","الخلط بين العنصر والمركب لأن كليهما مادة نقية","عدّ المادة C مركبًا بسبب وجود عدة مكونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.680Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الماء مركب؛ لأن الهيدروجين والأكسجين اتحدا كيميائيًّا فتكونت مادة جديدة واحدة نقية خواصها تختلف عن خواص الغازين، ولا تُفصل مكوناتها إلا بطرائق كيميائية تحتاج إلى طاقة كالتحليل الكهربائي. أما الهواء الناتج عن خلط النيتروجين والأكسجين فمخلوط؛ لأنه لم يحدث تفاعل كيميائي فيبقى كل غاز محتفظًا بخواصه، ويمكن فصل مكوناته بطرائق فيزيائية.', '["الماء مركب لأن العنصرين اتحدا كيميائيًّا","الهواء مخلوط لأن الغازين لم يتفاعلا","المركب مادة جديدة بخواص مختلفة، وفي المخلوط تبقى الخواص","فصل المركب يحتاج إلى طرائق كيميائية، وفصل المخلوط بطرائق فيزيائية"]'::jsonb, '[]'::jsonb, '[{"element":"الماء مركب مع التعليل بالاتحاد الكيميائي","marks":1},{"element":"الهواء مخلوط مع التعليل بعدم حدوث تفاعل","marks":1},{"element":"الفرق في الخواص بين المركب والمخلوط","marks":1},{"element":"الفرق في طريقة الفصل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح معلل للناتجين وبيان الفرق في الخواص وطريقة الفصل"},{"level":"2–3 درجات","description":"تصنيف صحيح معلل مع نقص في بيان الفرق"},{"level":"1 درجة","description":"تصنيف صحيح لناتج واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الهواء مركبًا لأنه يتكون من عنصرين","القول إن الماء يمكن فصله بطرائق فيزيائية بسيطة","عدم ذكر التفاعل الكيميائي سببًا لتكوّن المركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.680Z"}'::jsonb)
