('mcq', 2, 'اشتُقت كلمة «ذرة» (Atom) من الكلمة الإغريقية atomos. ما معنى هذه الكلمة؟', null, '["الجزء الذي يتحرك في الفراغ","الجزء الذي لا يُرى بالعين","الجزء الذي يتحد مع غيره","الجزء الذي لا يتجزأ"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 77 — مفردات أكاديمية (الذرة)'),
('mcq', 3, 'قال معلم: «أول من اقترح وجود الذرات فيلسوف إغريقي». أيّ العبارات الآتية تصف هذا الفيلسوف وصفًا صحيحًا؟', null, '["اعتقد أن المادة من أجزاء صغيرة تسمى ذرات تتحرك في الفراغ","رفض وجود الفراغ واعتقد أن المادة من التراب والنار والهواء والماء","نشر عام 1803م نظرية ذرية قائمة على تجارب علمية كثيرة","اكتشف أول جسيم مكوّن للذرة وهو الإلكترون"]'::jsonb, 'فهم', 'تمييز صفة صاحب الفكرة', 'متوسط', 'الكتاب ص 77 — الجدول 3-1'),
('mcq', 4, 'متى ظهرت فكرة وجود الذرات لأول مرة؟', null, '["في أوائل القرن التاسع عشر الميلادي على يد دالتون","في أواخر القرن التاسع عشر الميلادي بعد اكتشاف الإلكترون","قبل أكثر من ألفي عام في عصر الفلاسفة الإغريق","في القرن العشرين الميلادي بعد اكتشاف النواة"]'::jsonb, 'تذكر', 'تذكر زمن', 'سهل', 'الكتاب ص 77 — ديموقريطوس'),
('mcq', 5, 'ما الذي اقترحه ديموقريطوس بشأن المادة؟', null, '["المادة قابلة للانقسام إلى أجزاء أصغر باستمرار دون حد","المادة غير قابلة للانقسام إلى ما لا نهاية؛ إذ تتكون من ذرات","المادة مكونة من التراب والنار والهواء والماء","المادة مكونة من ذرات تحتوي على بروتونات ونيوترونات وإلكترونات"]'::jsonb, 'تذكر', 'تذكر مضمون الفكرة', 'متوسط', 'الكتاب ص 77 — ديموقريطوس'),
('mcq', 6, 'قال طالب في نقاش صفي: «أول من اقترح وجود الذرات هو جون دالتون عام 1803م». ما التصحيح الدقيق لهذه العبارة؟', null, '["العبارة صحيحة، فلم يقترح أحد وجود الذرات قبل دالتون","أول من اقترحها أرسطو، ثم أنكرها دالتون بعد ذلك","أول من اقترحها ديموقريطوس، وأحيا دالتون الفكرة وبدأ دراستها علميًّا","أول من اقترحها طومسون عند اكتشافه الإلكترون"]'::jsonb, 'تطبيق', 'تصحيح عبارة خاطئة', 'صعب', 'الكتاب ص 77، 78 — ديموقريطوس ودالتون'),
('mcq', 7, 'ما الخصائص التي نسبها أول من اقترح وجود الذرات إلى الذرات؟', null, '["صلبة ومتجانسة، ولا تفنى ولا تتجزأ","قابلة للتجزئة إلى إلكترونات وبروتونات ونيوترونات","متماثلة في الحجم والشكل في جميع أنواعها","مكونة من جسيمات مشحونة تتحرك حول النواة"]'::jsonb, 'فهم', 'تمييز الخصائص المنسوبة', 'متوسط', 'الكتاب ص 77 — الجدول 3-1'),
('essay', 1, 'اذكر اسم الفيلسوف الإغريقي الذي يُعدّ أول من اقترح وجود الذرات، وبيّن ما الذي اقترحه عن المادة، وما معنى كلمة atomos التي اشتُقت منها كلمة «ذرة».', null, null, 'تذكر', 'تذكر مع بيان', 'متوسط', 'الكتاب ص 77 — ديموقريطوس'),
('essay', 2, 'اعترض طالب قائلًا: «جون دالتون هو من اقترح وجود الذرات». وضّح موقف دالتون الصحيح من هذه الفكرة، مبيّنًا من هو أول من اقترحها.', null, null, 'فهم', 'تصحيح مفهوم خاطئ', 'صعب', 'الكتاب ص 77، 78 — ديموقريطوس ودالتون'),
('essay', 3, 'اذكر ثلاثًا من الأفكار التي نسبها ديموقريطوس إلى الذرات، ثم بيّن ما الذي يحدد خواص المادة بحسب فكرته.', null, null, 'فهم', 'ذكر وتحديد', 'صعب', 'الكتاب ص 77 — الجدول 3-1')
