from (values
('mcq', 1, 1, 'الفيلسوف الإغريقي ديموقريطوس (460–370 ق.م) هو أول من اقترح أن المادة ليست قابلة للانقسام إلى ما لا نهاية، وأنها مكونة من أجزاء صغيرة تسمى الذرات.', '["أرسطو رفض فكرة الذرات ولم يقترحها، فقد أنكر وجودها.","","دالتون أحيا فكرة الذرات في القرن التاسع عشر وبدأ دراستها العلمية، لكنه لم يكن أول من اقترح وجودها.","طومسون اكتشف الإلكترون وهو أول جسيم مكوّن للذرة، ولم يقترح وجود الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.681Z"}'::jsonb),
('mcq', 2, 3, 'كلمة atomos الإغريقية تعني «لا تتجزأ»، وقد استعملها ديموقريطوس لأنه اعتقد أن المادة مكونة من أجزاء صغيرة لا يمكن تجزئتها.', '["حركة الذرات في الفراغ فكرة نسبت إلى ديموقريطوس، لكنها ليست معنى الكلمة الإغريقية.","الصغر الشديد صفة للذرة، لكن الكلمة لا تعني «ما لا يُرى».","اتحاد الذرات لتكوين المركبات فكرة من نظرية دالتون، وليست معنى الكلمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.681Z"}'::jsonb),
('mcq', 3, 0, 'هذا وصف ديموقريطوس، أول من اقترح وجود الذرات، فقد اعتقد أن المادة مكونة من ذرات صغيرة تتحرك في الفراغ.', '["","هذا وصف أرسطو الذي أنكر وجود الذرات والفراغ، وليس من اقترح وجود الذرات.","هذا وصف جون دالتون الذي بدأ الدراسة العلمية للذرة في القرن التاسع عشر، بعد ديموقريطوس بقرون طويلة.","هذا وصف طومسون الذي اكتشف الإلكترون، وهو عالم حديث وليس فيلسوفًا إغريقيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.681Z"}'::jsonb),
('mcq', 4, 2, 'اقترح الفيلسوف الإغريقي ديموقريطوس (460–370 ق.م) فكرة الذرات، أي قبل أكثر من ألفي عام من بدء الدراسة العلمية للذرة.', '["في هذا الوقت بدأت الدراسة العلمية للذرة مع دالتون، لكن فكرة الذرات اقتُرحت قبله بقرون طويلة.","الإلكترون اكتُشف في هذه الفترة، أما فكرة الذرات فأقدم منها بكثير.","","اكتشاف النواة حدث في القرن العشرين، أما فكرة الذرات فاقتُرحت قبل ذلك بأكثر من ألفي عام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.681Z"}'::jsonb),
('mcq', 5, 1, 'اقترح ديموقريطوس أن المادة ليست قابلة للانقسام إلى ما لا نهاية، وأنها تتكون من أجزاء صغيرة تسمى الذرات.', '["هذا عكس فكرة ديموقريطوس؛ فقد رأى أن الانقسام ينتهي عند الذرات.","","هذه فكرة أرسطو والفلاسفة الإغريق عن المادة، وليست فكرة ديموقريطوس.","تركيب الذرة من جسيمات دون ذرية فكرة حديثة جاءت بعد قرون من ديموقريطوس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.681Z"}'::jsonb),
('mcq', 6, 2, 'ديموقريطوس هو أول من اقترح وجود الذرات قبل أكثر من ألفي عام، أما دالتون فأحيا الفكرة وراجعها اعتمادًا على تجارب علمية، فبدأت معه الدراسة العلمية للذرة.', '["هذا خطأ؛ فقد اقترح ديموقريطوس وجود الذرات قبل دالتون بأكثر من ألفي عام.","أرسطو رفض فكرة الذرات ولم يقترحها، ودالتون لم ينكرها بل أحياها.","","طومسون جاء بعد دالتون واكتشف أول جسيم مكوّن للذرة، ولم يكن أول من اقترح وجود الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.682Z"}'::jsonb),
('mcq', 7, 0, 'رأى ديموقريطوس، أول من اقترح وجود الذرات، أن الذرات صلبة ومتجانسة، ولا تفنى ولا تتجزأ، وأن أنواعها المختلفة تختلف في الحجم والشكل.', '["","تجزؤ الذرة إلى جسيمات دون ذرية اكتشاف حديث يناقض اعتقاد ديموقريطوس بأن الذرات لا تتجزأ.","اعتقد ديموقريطوس أن الأنواع المختلفة من الذرات لها أحجام وأشكال مختلفة.","وصف الذرة بنواة تتحرك حولها الإلكترونات من الفكر الذري الحديث، وليس من أفكار ديموقريطوس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.682Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفيلسوف هو ديموقريطوس (460–370 ق.م). اقترح أن المادة ليست قابلة للانقسام إلى ما لا نهاية، وأنها مكونة من أجزاء صغيرة جدًّا تسمى الذرات. وكلمة atomos إغريقية تعني «لا تتجزأ».', '["ديموقريطوس","المادة ليست قابلة للانقسام إلى ما لا نهاية","المادة مكونة من أجزاء صغيرة تسمى الذرات","كلمة atomos تعني لا تتجزأ"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر اسم ديموقريطوس","marks":1},{"element":"بيان أن المادة مكونة من ذرات ليست قابلة للانقسام إلى ما لا نهاية","marks":2},{"element":"ذكر معنى كلمة atomos (لا تتجزأ)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اسم الفيلسوف صحيح، وفكرته كاملة، ومعنى الكلمة صحيح"},{"level":"2–3 درجات","description":"اسم صحيح مع فكرة ناقصة أو دون معنى الكلمة"},{"level":"1 درجة","description":"ذكر الاسم الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة الفكرة إلى أرسطو أو إلى دالتون","الاكتفاء بالاسم دون ذكر الفكرة","القول إن كلمة atomos تعني «الصغير جدًّا» بدل «لا يتجزأ»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.682Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أول من اقترح وجود الذرات هو الفيلسوف الإغريقي ديموقريطوس قبل أكثر من ألفي عام. أما جون دالتون فقد أحيا هذه الفكرة في القرن التاسع عشر وراجعها اعتمادًا على نتائج تجارب علمية وقياسات دقيقة، فبدأت معه الدراسة العلمية للذرة وطرح نظريته الذرية عام 1803م.', '["أول من اقترح وجود الذرات هو ديموقريطوس","دالتون أحيا فكرة الذرات وراجعها","اعتمد دالتون على تجارب علمية وقياسات دقيقة","بدأت الدراسة العلمية للذرة مع دالتون (نظريته عام 1803م)"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد ديموقريطوس بوصفه أول من اقترح الذرات","marks":1},{"element":"بيان أن دالتون أحيا الفكرة وراجعها","marks":1},{"element":"ذكر اعتماد دالتون على التجارب والقياسات","marks":1},{"element":"بيان أن الدراسة العلمية للذرة بدأت مع دالتون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد ديموقريطوس، وبيان دور دالتون في إحياء الفكرة بالتجارب وبدء الدراسة العلمية"},{"level":"2–3 درجات","description":"تحديد ديموقريطوس مع دور ناقص لدالتون"},{"level":"1 درجة","description":"ذكر أحدهما فقط دون تمييز الدور"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد قول الطالب ونسبة الاقتراح الأول إلى دالتون","نسبة الاقتراح الأول إلى أرسطو","إغفال أن دالتون اعتمد على التجارب العلمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.682Z"}'::jsonb),
('essay', 3, null::int, null, null, 'من أفكار ديموقريطوس عن الذرات: المادة تتكون من ذرات تتحرك في الفراغ؛ والذرات صلبة ومتجانسة لا تفنى ولا تتجزأ؛ والأنواع المختلفة من الذرات لها أحجام وأشكال مختلفة. وبحسب فكرته فإن حجم الذرات وشكلها وحركتها هي التي تحدد خواص المادة.', '["ذكر ثلاث أفكار صحيحة من: تتحرك في الفراغ، صلبة متجانسة، لا تفنى ولا تتجزأ، تختلف أحجامها وأشكالها","حجم الذرات وشكلها وحركتها تحدد خواص المادة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر ثلاث أفكار صحيحة (درجة لكل فكرة)","marks":3},{"element":"تحديد ما يحدد خواص المادة (الحجم والشكل والحركة)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاث أفكار صحيحة، وتحديد الحجم والشكل والحركة عاملًا يحدد الخواص"},{"level":"2–3 درجات","description":"فكرتان أو ثلاث أفكار صحيحة دون تحديد ما يحدد الخواص"},{"level":"1 درجة","description":"فكرة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["خلط أفكار ديموقريطوس بفرضيات دالتون، كقول إن ذرات العنصر الواحد متشابهة","نسبة فكرة «لا وجود للفراغ» إلى ديموقريطوس","القول إن الذرات قابلة للتجزئة بحسب ديموقريطوس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.682Z"}'::jsonb)
