from (values
('mcq', 1, 'أيّ الأفكار الآتية يشترك فيها ديموقريطوس ودالتون ولا يقول بها أرسطو؟', null, '["لا وجود للفراغ، ولذلك لا تتحرك فيه ذرات","المادة مكونة من التراب والنار والهواء والماء","المادة مكونة من ذرات لا تتجزأ ولا تفنى","ذرات العنصر الواحد متشابهة في الكتلة والخواص الكيميائية"]'::jsonb, 'تحليل', 'استخراج المشترك بين أفكار', 'متوسط', 'الكتاب ص 77، 78 — الجدولان 3-1 و3-2'),
('mcq', 2, 'تعرض البيانات الآتية أفكار ثلاثة مفكرين دون ذكر أسمائهم. أيّ المفكرين يمثل أفكار أرسطو؟', '{"headers":["المفكر","الأفكار المنسوبة إليه"],"rows":[["X","المادة من ذرات صلبة متجانسة تتحرك في الفراغ"],["Y","لا وجود للفراغ، والمادة من التراب والنار والهواء والماء"],["Z","ذرات العنصر الواحد متشابهة، وتتحد ذرات العناصر بنسب عددية بسيطة"]]}'::jsonb, '["المفكر X","المفكر Y","المفكر Z","المفكران X وZ"]'::jsonb, 'تطبيق', 'مطابقة أفكار بصاحبها', 'سهل', 'الكتاب ص 77، 78 — الجدولان 3-1 و3-2'),
('mcq', 3, 'ما الذي يميز نظرية دالتون الذرية عن فكرة ديموقريطوس من حيث أساس كل منهما؟', null, '["أنها قالت إن المادة تتكون من أجزاء صغيرة تسمى الذرات","أنها أنكرت وجود الذرات اعتمادًا على أفكار عن الطبيعة","أنها قسّمت المادة إلى التراب والنار والهواء والماء","أنها استندت إلى تجارب وقياسات دقيقة للتفاعلات الكيميائية"]'::jsonb, 'تحليل', 'تحديد وجه الاختلاف', 'صعب', 'الكتاب ص 77، 78 — ديموقريطوس ودالتون'),
('mcq', 4, 'أيّ العبارات الآتية تمثل خلافًا بين ديموقريطوس وأرسطو؟', null, '["الأول قال بذرات تتحرك في الفراغ، والثاني لم يعتقد بوجود الفراغ","الأول لم يعتقد بوجود الفراغ، والثاني قال بذرات تتحرك فيه","الأول قال إن المادة من أربعة عناصر، والثاني قال إنها من ذرات","الأول أنكر وجود الذرات، والثاني اقترح أنها لا تتجزأ"]'::jsonb, 'تحليل', 'مقارنة بين موقفين', 'سهل', 'الكتاب ص 77 — ديموقريطوس وأرسطو'),
('mcq', 5, 'إلى من تُنسب العبارة: «تتحد ذرات العناصر المختلفة بنسب عددية بسيطة لتكوين المركبات»؟', null, '["ديموقريطوس","أرسطو","جون دالتون","طومسون"]'::jsonb, 'تذكر', 'نسبة فكرة لصاحبها', 'متوسط', 'الكتاب ص 78 — الجدول 3-2'),
('mcq', 6, 'تسجّل الصفوف الآتية فكرةً منسوبة إلى كل مفكر. أيّ الصفوف ينسب فكرة إلى غير صاحبها؟', '{"headers":["الصف","المفكر","الفكرة المنسوبة إليه"],"rows":[["الأول","ديموقريطوس","الذرات صلبة ومتجانسة لا تفنى ولا تتجزأ"],["الثاني","أرسطو","المادة مكونة من التراب والنار والهواء والماء"],["الثالث","دالتون","ذرات العنصر الواحد متشابهة في الحجم والكتلة والخواص الكيميائية"],["الرابع","ديموقريطوس","لا وجود للفراغ"]]}'::jsonb, '["الصف الأول","الصف الثاني","الصف الثالث","الصف الرابع"]'::jsonb, 'تحليل', 'كشف خطأ في جدول مقارنة', 'صعب', 'الكتاب ص 77، 78 — الجدولان 3-1 و3-2'),
('mcq', 7, 'ما العلاقة بين نظرية دالتون الذرية وفكرة ديموقريطوس عن الذرة؟', null, '["أحيا دالتون فكرة الذرات وراجعها اعتمادًا على بحث علمي، مع وجود أوجه تشابه بينهما","رفض دالتون فكرة ديموقريطوس كلها وأنكر وجود الذرات","اعتمد دالتون على فكرة أرسطو أن المادة من أربعة عناصر","طابقت نظرية دالتون فكرة ديموقريطوس تمامًا دون أي مراجعة"]'::jsonb, 'فهم', 'بيان العلاقة بين فكرتين', 'متوسط', 'الكتاب ص 78 — جون دالتون'),
('essay', 1, 'قارن بين أفكار ديموقريطوس وأرسطو وجون دالتون عن المادة والذرة، مبيّنًا موقف كل منهم من وجود الذرات، وممّ تتكون المادة عنده، ثم بيّن أيها بُنيت أفكاره على التجارب العلمية.', null, null, 'تحليل', 'مقارنة ثلاثية', 'متوسط', 'الكتاب ص 77، 78 — الجدولان 3-1 و3-2'),
('essay', 2, 'حدّد وجهَي تشابه ووجهَي اختلاف بين فكرة ديموقريطوس عن الذرة ونظرية دالتون الذرية.', null, null, 'تحليل', 'مقارنة تشابه واختلاف', 'صعب', 'الكتاب ص 77، 78 — الجدولان 3-1 و3-2'),
('essay', 3, 'انسب كل فكرة من الأفكار الآتية إلى صاحبها (ديموقريطوس أو أرسطو أو دالتون): (أ) لا وجود للفراغ. (ب) الذرات صلبة ومتجانسة. (ج) ذرات العنصر الواحد متشابهة في الكتلة. (د) المادة من التراب والنار والهواء والماء. (هـ) تتحد الذرات بنسب عددية بسيطة. (و) حجم الذرات وشكلها وحركتها تحدد خواص المادة.', null, null, 'تطبيق', 'تصنيف أفكار حسب أصحابها', 'سهل', 'الكتاب ص 77، 78 — الجدولان 3-1 و3-2')
