from (values
('mcq', 1, 2, 'كل من ديموقريطوس ودالتون يرى أن المادة مكونة من ذرات لا تتجزأ ولا تفنى، بينما أنكر أرسطو وجود الذرات.', '["نفي الفراغ فكرة أرسطو وحده، أما ديموقريطوس فاعتقد أن الذرات تتحرك في الفراغ.","هذه فكرة أرسطو وحده، وليست فكرة ديموقريطوس ولا دالتون.","","هذه فرضية دالتون وحده؛ فديموقريطوس رأى أن لأنواع الذرات المختلفة أحجامًا وأشكالًا مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.683Z"}'::jsonb),
('mcq', 2, 1, 'أرسطو نفى وجود الفراغ، واعتقد أن المادة مكونة من التراب والنار والهواء والماء، وهذا ما ينطبق على المفكر Y.', '["المفكر X يمثل ديموقريطوس الذي قال بذرات تتحرك في الفراغ.","","المفكر Z يمثل دالتون الذي قال بتشابه ذرات العنصر الواحد واتحادها بنسب بسيطة.","كلا المفكرين X وZ يقول بوجود الذرات، بينما أنكر أرسطو وجودها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.683Z"}'::jsonb),
('mcq', 3, 3, 'اعتمد دالتون على تجارب كثيرة وملاحظات وقياسات دقيقة للتفاعلات الكيميائية، أما أفكار ديموقريطوس فكانت مجرد أفكار دون تجارب ضابطة.', '["القول بأن المادة من ذرات يشترك فيه دالتون وديموقريطوس، فلا يميز إحداهما عن الأخرى.","إنكار الذرات موقف أرسطو، وليس موقف دالتون.","هذه فكرة أرسطو عن المادة، وليست من نظرية دالتون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.683Z"}'::jsonb),
('mcq', 4, 0, 'اعتقد ديموقريطوس أن الذرات تتحرك في الفراغ، بينما لم يعتقد أرسطو بوجود الفراغ، وكان هذا أهم انتقاداته لفكرة الذرات.', '["","هذه العبارة تعكس موقف كل منهما؛ فالذي لم يعتقد بالفراغ هو أرسطو لا ديموقريطوس.","هذه العبارة تعكس الموقفين؛ فالتراب والنار والهواء والماء من أفكار أرسطو، والذرات من أفكار ديموقريطوس.","هذه العبارة تعكس الموقفين؛ فديموقريطوس هو من اقترح الذرات التي لا تتجزأ، وأرسطو هو من أنكرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.683Z"}'::jsonb),
('mcq', 5, 2, 'اتحاد ذرات العناصر بنسب عددية بسيطة لتكوين المركبات إحدى فرضيات نظرية دالتون الذرية التي طرحها عام 1803م.', '["ديموقريطوس لم يتناول اتحاد الذرات بنسب عددية، وإنما قال إن الذرات صلبة وتتحرك في الفراغ.","أرسطو أنكر الذرات، فلا يمكن أن ينسب إليه اتحادها بنسب عددية.","","طومسون عالم اكتشف الإلكترون، وليست هذه الفرضية من أفكاره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.683Z"}'::jsonb),
('mcq', 6, 3, 'فكرة «لا وجود للفراغ» لأرسطو وليست لديموقريطوس، الذي اعتقد أن الذرات تتحرك في الفراغ؛ فالصف الرابع هو الخطأ.', '["الصف الأول صحيح؛ فديموقريطوس رأى أن الذرات صلبة ومتجانسة لا تفنى ولا تتجزأ.","الصف الثاني صحيح؛ فأرسطو رأى أن المادة من التراب والنار والهواء والماء.","الصف الثالث صحيح؛ فهذه إحدى فرضيات دالتون عن ذرات العنصر الواحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.683Z"}'::jsonb),
('mcq', 7, 0, 'أحيا دالتون فكرة ديموقريطوس وراجعها اعتمادًا على نتائج بحثه التجريبي، وهناك تشابه بين أفكارهما في عدة وجوه، كأن المادة من ذرات لا تتجزأ ولا تفنى.', '["","دالتون لم يرفض الفكرة بل أحياها؛ فنظريته تقوم على أن المادة مكونة من ذرات.","هذه فكرة أرسطو التي لم يعتمد عليها دالتون، فنظريته تقوم على وجود الذرات.","هناك فروق مهمة؛ فنظرية دالتون قامت على التجارب، وتضمنت فرضيات جديدة كاتحاد الذرات بنسب عددية بسيطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.684Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ديموقريطوس: المادة مكونة من ذرات صلبة متجانسة لا تفنى ولا تتجزأ، تتحرك في الفراغ، وتختلف أنواعها في الحجم والشكل. أرسطو: أنكر وجود الذرات ولم يعتقد بوجود الفراغ، ورأى أن المادة مكونة من التراب والنار والهواء والماء. دالتون: المادة مكونة من ذرات لا تتجزأ ولا تفنى، وذرات العنصر الواحد متشابهة وتختلف عن ذرات العناصر الأخرى، وتتحد بنسب عددية بسيطة لتكوين المركبات. وقد بُنيت أفكار دالتون على تجارب علمية وقياسات دقيقة، أما أفكار ديموقريطوس وأرسطو فكانت أفكارًا لا تستند إلى تجارب ضابطة.', '["ديموقريطوس: المادة من ذرات تتحرك في الفراغ، صلبة متجانسة لا تفنى ولا تتجزأ","أرسطو: ينكر الذرات والفراغ، والمادة من التراب والنار والهواء والماء","دالتون: المادة من ذرات، ذرات العنصر الواحد متشابهة وتتحد بنسب عددية بسيطة","أفكار دالتون وحدها قائمة على تجارب علمية"]'::jsonb, '[]'::jsonb, '[{"element":"موقف ديموقريطوس وتركيب المادة عنده","marks":2},{"element":"موقف أرسطو وتركيب المادة عنده","marks":2},{"element":"موقف دالتون وتركيب المادة عنده","marks":2},{"element":"تحديد دالتون صاحب الأفكار القائمة على التجارب","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"مقارنة صحيحة وكاملة للمفكرين الثلاثة مع تحديد أن أفكار دالتون وحدها بُنيت على التجارب"},{"level":"5–6 درجات","description":"مقارنة صحيحة للثلاثة مع نقص في بعض التفاصيل أو دون تحديد الأساس التجريبي"},{"level":"3–4 درجات","description":"مقارنة صحيحة لمفكرين اثنين فقط"},{"level":"1–2 درجة","description":"ذكر فكرة صحيحة عن مفكر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة وجود الفراغ إلى أرسطو أو نفيه إلى ديموقريطوس","القول إن أرسطو قدّم نموذجًا ذريًّا","نسبة اتحاد الذرات بنسب عددية بسيطة إلى ديموقريطوس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.684Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التشابه: (1) كلاهما يرى أن المادة مكونة من ذرات. (2) كلاهما يرى أن الذرات لا تتجزأ ولا تفنى. الاختلاف: (1) نظرية دالتون قامت على تجارب علمية وقياسات دقيقة، أما فكرة ديموقريطوس فكانت مجرد أفكار دون تجارب ضابطة. (2) نصّت نظرية دالتون على أن ذرات العنصر الواحد متشابهة وتختلف عن ذرات العناصر الأخرى، وأنها تتحد بنسب عددية بسيطة لتكوين المركبات، ولم يقل ديموقريطوس ذلك، وإنما قال إن لأنواع الذرات المختلفة أحجامًا وأشكالًا مختلفة.', '["تشابه: المادة مكونة من ذرات","تشابه: الذرات لا تتجزأ ولا تفنى","اختلاف: أساس دالتون التجارب والقياسات","اختلاف: فرضيات دالتون عن تشابه ذرات العنصر الواحد والاتحاد بنسب بسيطة"]'::jsonb, '[]'::jsonb, '[{"element":"وجه التشابه الأول","marks":1},{"element":"وجه التشابه الثاني","marks":1},{"element":"وجه الاختلاف الأول","marks":1},{"element":"وجه الاختلاف الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وجها تشابه ووجها اختلاف صحيحان"},{"level":"2–3 درجات","description":"اثنان أو ثلاثة من الأوجه صحيحة"},{"level":"1 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ إنكار الفراغ وجه تشابه بين ديموقريطوس ودالتون","ذكر وجه اختلاف غير مدعوم، كالقول إن ديموقريطوس رأى أن الذرات تتجزأ","تكرار الوجه نفسه بصياغتين مختلفتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.684Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) أرسطو. (ب) ديموقريطوس. (ج) دالتون. (د) أرسطو. (هـ) دالتون. (و) ديموقريطوس.', '["أ: أرسطو","ب: ديموقريطوس","ج: دالتون","د: أرسطو","هـ: دالتون","و: ديموقريطوس"]'::jsonb, '[]'::jsonb, '[{"element":"الفكرة (أ)","marks":1},{"element":"الفكرة (ب)","marks":1},{"element":"الفكرة (ج)","marks":1},{"element":"الفكرة (د)","marks":1},{"element":"الفكرة (هـ)","marks":1},{"element":"الفكرة (و)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"نسبة الأفكار الست إلى أصحابها نسبة صحيحة"},{"level":"4–5 درجات","description":"أربع أو خمس أفكار منسوبة نسبة صحيحة"},{"level":"2–3 درجات","description":"فكرتان أو ثلاث أفكار منسوبة نسبة صحيحة"},{"level":"1 درجة","description":"فكرة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة «لا وجود للفراغ» إلى ديموقريطوس","نسبة تشابه ذرات العنصر الواحد إلى ديموقريطوس","نسبة المادة من التراب والنار والهواء والماء إلى دالتون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.684Z"}'::jsonb)
