('mcq', 3, 'تحلل 36.0 g من الماء كهربائيًّا إلى هيدروجين وأكسجين، فتكوّن 4.0 g من الهيدروجين. ما كتلة الأكسجين الناتج وفق قانون حفظ الكتلة؟', null, '["40.0 g","9.0 g","144 g","32.0 g"]'::jsonb, 'تطبيق', 'حساب بتطبيق القانون', 'متوسط', 'الكتاب ص 79 — قانون حفظ الكتلة (تطبيق عددي)'),
('mcq', 4, 'اتحدت 5 ذرات من العنصر X مع 10 ذرات من العنصر Y اتحادًا تامًّا لتكوين مركب. كم مجموع عدد ذرات X وY في المركب الناتج وفق نظرية دالتون؟', null, '["50 ذرة","15 ذرة","10 ذرات","5 ذرات"]'::jsonb, 'تطبيق', 'تطبيق عددي على ثبات عدد الذرات', 'سهل', 'الكتاب ص 79 — قانون حفظ الكتلة'),
