('mcq', 6, 'تعرض البيانات الآتية عدد ذرات العنصرين X وY قبل التفاعل وبعده في ثلاث تجارب. أيّ التجارب يتفق مع تفسير دالتون لقانون حفظ الكتلة؟', '{"headers":["التجربة","ذرات X قبل","ذرات Y قبل","ذرات X بعد","ذرات Y بعد"],"rows":[["1","6","12","6","12"],["2","6","12","6","9"],["3","6","12","8","12"]]}'::jsonb, '["التجربة 2 فقط","التجربة 1 فقط","التجربة 3 فقط","التجربتان 2 و3 معًا"]'::jsonb, 'تحليل', 'تحليل بيانات تجارب', 'صعب', 'الكتاب ص 79 — قانون حفظ الكتلة'),
