from (values
('mcq', 1, 2, 'ينص قانون حفظ الكتلة على أن الكتلة ثابتة (محفوظة) في التفاعلات الكيميائية، أي أنها لا تنقص ولا تزيد.', '["الكتلة لا تزداد في التفاعل الكيميائي؛ فكتلة النواتج تساوي كتلة المتفاعلات.","الكتلة لا تنقص في التفاعل الكيميائي، بل تبقى كتلة النواتج مساوية لكتلة المتفاعلات.","","القانون يتعلق بثبات الكتلة لا بعدد الجزيئات؛ فقد يختلف عدد الجزيئات قبل التفاعل وبعده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.685Z"}'::jsonb),
('mcq', 2, 0, 'بحسب دالتون، ما يحدث للذرات في التفاعل هو انفصال أو اتحاد أو إعادة ترتيب فقط؛ فلا تتحطم ذرات ولا تُستحدث أخرى، فيبقى عدد ذرات كل عنصر قبل التفاعل وبعده نفسه، وتبقى الكتلة ثابتة.', '["","نظرية دالتون تنص على أن الذرات لا تتجزأ، فلا تفسير لحفظ الكتلة بتجزؤ الذرات.","في نظرية دالتون لا تتحول ذرات عنصر إلى ذرات عنصر آخر؛ فلكل عنصر ذراته الخاصة.","في نظرية دالتون الذرات لا تفنى، فلا حاجة إلى انتقال كتلة ذرات فانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-18T03:27:04.685Z"}'::jsonb),
('mcq', 3, 3, 'كتلة النواتج تساوي كتلة المتفاعلات: كتلة الأكسجين = 36.0 g − 4.0 g = 32.0 g.', '["هذا ناتج جمع الكتلتين (36.0 + 4.0)؛ والصحيح طرح كتلة الهيدروجين من كتلة الماء.","هذا ناتج قسمة 36.0 على 4.0، ولا يمثل أي علاقة في قانون حفظ الكتلة.","هذا ناتج ضرب 36.0 في 4.0، وهو خطأ؛ فالكتلة تُحسب بالطرح لا بالضرب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.685Z"}'::jsonb),
('mcq', 4, 1, 'الذرات لا تفنى ولا تُستحدث في التفاعل، فيبقى عدد الذرات كما هو: 5 + 10 = 15 ذرة.', '["هذا ناتج ضرب 5 في 10؛ والصحيح أن العدد الكلي للذرات يُجمع ولا يُضرب.","","هذا عدد ذرات Y فقط، وقد أُهملت ذرات X التي بقيت في المركب.","هذا عدد ذرات X فقط، وقد أُهملت ذرات Y التي بقيت في المركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.685Z"}'::jsonb),
('mcq', 5, 0, 'تفسير دالتون قائم على أن الذرات لا تُستحدث ولا تفنى؛ فزيادة عدد ذرات عنصر في النواتج تعني استحداث ذرات جديدة، وهذا يتعارض مع تفسيره ومع حفظ الكتلة.', '["","الانفصال ثم إعادة الترتيب هو ما يحدث فعلًا للذرات بحسب دالتون، فلا تعارض فيه.","بقاء عدد ذرات كل عنصر ثابتًا هو أساس تفسير دالتون لحفظ الكتلة.","اتحاد ذرات عنصرين لتكوين مركب منسجم مع نظرية دالتون ولا يغيّر عدد الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.685Z"}'::jsonb),
('mcq', 6, 1, 'يتفق مع دالتون أن يبقى عدد ذرات كل عنصر ثابتًا قبل التفاعل وبعده، وهذا يتحقق في التجربة 1 فقط (6 ذرات X و12 ذرة Y في الحالتين).', '["في التجربة 2 نقص عدد ذرات Y من 12 إلى 9، أي فنيت ذرات، وهذا يخالف نظرية دالتون.","","في التجربة 3 زاد عدد ذرات X من 6 إلى 8، أي استُحدثت ذرات، وهذا يخالف نظرية دالتون.","في كلتا التجربتين 2 و3 تغيّر عدد ذرات أحد العنصرين، فلا تتفقان مع تفسير دالتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.686Z"}'::jsonb),
('mcq', 7, 3, 'كتلة النواتج تساوي كتلة المتفاعلات: 12.0 g + 32.0 g = 44.0 g من ثاني أكسيد الكربون.', '["هذا ناتج طرح الكتلتين (32.0 − 12.0)؛ والصحيح جمع كتلتي المتفاعلين.","هذا ناتج ضرب الكتلتين، وهو خطأ؛ فالكتلة الكلية تُجمع.","هذه كتلة الكربون وحدها، وقد أُهملت كتلة الأكسجين المتحد معه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.686Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينص القانون على أن الكتلة ثابتة (محفوظة) في التفاعلات الكيميائية، فلا تنقص ولا تزيد. وفسّرته نظرية دالتون بأن ما يحدث للذرات في التفاعل هو انفصال أو اتحاد أو إعادة ترتيب فقط؛ فالذرات لا تتحطم ولا تستحدث ذرات أخرى، ولذلك يبقى عدد ذرات كل عنصر قبل التفاعل وبعده نفسه، فتبقى كتلة المواد ثابتة.', '["الكتلة ثابتة في التفاعل الكيميائي فلا تنقص ولا تزيد","الذرات تنفصل أو تتحد أو يُعاد ترتيبها فقط","الذرات لا تتحطم ولا تُستحدث ذرات أخرى","عدد ذرات كل عنصر ثابت قبل التفاعل وبعده فتثبت الكتلة"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":1},{"element":"انفصال الذرات أو اتحادها أو إعادة ترتيبها فقط","marks":1},{"element":"الذرات لا تتحطم ولا تُستحدث","marks":1},{"element":"ثبات عدد ذرات كل عنصر وبالتالي ثبات الكتلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص صحيح للقانون وتفسير كامل يربط ثبات عدد الذرات بثبات الكتلة"},{"level":"2–3 درجات","description":"نص صحيح مع تفسير ناقص، أو تفسير صحيح دون نص القانون"},{"level":"1 درجة","description":"ذكر فكرة صحيحة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرات تفنى ويتكون غيرها في التفاعل","ذكر القانون دون ربطه بعدد الذرات","القول إن عدد الجزيئات هو الذي يبقى ثابتًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-18T03:27:04.686Z"}'::jsonb),
('essay', 2, null::int, null, null, 'استُعمل قانون حفظ الكتلة: كتلة النواتج = كتلة المتفاعلات. كتلة كبريتيد الحديد = 7.0 g + 4.0 g = 11.0 g.', '["قانون حفظ الكتلة","كتلة الناتج = مجموع كتلتي المتفاعلين","11.0 g"]'::jsonb, '["كتلة النواتج = كتلة المتفاعلات (قانون حفظ الكتلة)","كتلة كبريتيد الحديد = 7.0 g + 4.0 g","كتلة كبريتيد الحديد = 11.0 g"]'::jsonb, '[{"element":"ذكر قانون حفظ الكتلة","marks":1},{"element":"جمع كتلتي المتفاعلين","marks":1},{"element":"النتيجة الصحيحة 11.0 g مع الوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر القانون، وحساب صحيح، ونتيجة بالوحدة الصحيحة"},{"level":"2 درجتان","description":"حساب صحيح دون ذكر القانون، أو ذكر القانون مع خطأ في الوحدة"},{"level":"1 درجة","description":"ذكر القانون فقط أو بداية صحيحة للحل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح الكتلتين بدل جمعهما فتكون النتيجة 3.0 g","ضرب الكتلتين فتكون النتيجة 28 g","إهمال الوحدة g في النتيجة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.686Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كتلة المتفاعلات = 4 + 8 = 12 وحدة كتلة. وكتلة النواتج تساوي كتلة المتفاعلات = 12 وحدة كتلة. (ب) ذرات A في النواتج = 4 جزيئات × 1 = 4 ذرات. ذرات B = 4 جزيئات × 2 = 8 ذرات. (ج) الذرات لا تتحطم ولا تُستحدث في التفاعل، بل تنفصل وتتحد ويُعاد ترتيبها، فبقي عدد ذرات كل عنصر كما كان (4 من A و8 من B)، ولذلك بقيت الكتلة ثابتة.', '["كتلة المتفاعلات 12 وحدة كتلة","كتلة النواتج 12 وحدة كتلة","عدد ذرات A في النواتج 4 وعدد ذرات B 8","الذرات لا تتحطم ولا تستحدث وإنما يعاد ترتيبها","ثبات عدد الذرات يعني ثبات الكتلة"]'::jsonb, '["كتلة المتفاعلات = 4 + 8 = 12 وحدة كتلة","كتلة النواتج = كتلة المتفاعلات = 12 وحدة كتلة","ذرات A = 4 × 1 = 4 ذرات","ذرات B = 4 × 2 = 8 ذرات"]'::jsonb, '[{"element":"كتلة المتفاعلات 12 وحدة كتلة","marks":1},{"element":"كتلة النواتج 12 وحدة كتلة","marks":1},{"element":"عدد ذرات A وB في النواتج (4 و8)","marks":2},{"element":"التفسير: الذرات لا تتحطم ولا تُستحدث وعددها ثابت","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حسابات الكتلة وعدد الذرات صحيحة مع تفسير كامل"},{"level":"4–5 درجات","description":"الحسابات صحيحة مع تفسير ناقص، أو خطأ بسيط في أحد الحسابات"},{"level":"2–3 درجات","description":"جزء صحيح من الحسابات دون تفسير"},{"level":"1 درجة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار عدد ذرات B في النواتج 4 بدل 8","القول إن كتلة النواتج أقل لأن الذرات اتحدت","تفسير تساوي الكتلتين دون ذكر ثبات عدد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.686Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
