('mcq', 1, 'لماذا رفض أرسطو فكرة الذرات؟', null, '["لأنها لا تتفق مع أفكاره حول الطبيعة","لأن تجارب ضابطة أثبتت أن المادة لا تتكون من ذرات","لأنه اكتشف أن الذرات تتجزأ إلى جسيمات أصغر","لأن أبحاث دالتون بيّنت خطأ فكرة الذرات"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 77 — أرسطو'),
('mcq', 2, 'ما أهم انتقادات أرسطو لفكرة ديموقريطوس عن الذرات؟', null, '["أن الذرات صلبة ومتجانسة في تكوينها","أن الذرات لا تتجزأ ولا تفنى أبدًا","أن الذرات تتحرك في الفراغ وهو لا يعتقد بوجوده","أن لأنواع الذرات المختلفة أحجامًا وأشكالًا مختلفة"]'::jsonb, 'فهم', 'تحديد سبب الاعتراض', 'متوسط', 'الكتاب ص 77 — أرسطو'),
('mcq', 3, 'ما العامل الذي أدى إلى رفض نظرية ديموقريطوس في عصره؟', null, '["ظهور تجارب علمية في ذلك العصر تنفي وجود الذرات","التأثير الكبير لأرسطو بوصفه أحد أبرز الفلاسفة الإغريق","إثبات دالتون خطأ فكرة الذرات بالتجارب","غياب فلاسفة آخرين يهتمون بطبيعة المادة"]'::jsonb, 'فهم', 'تفسير سبب', 'متوسط', 'الكتاب ص 77 — أرسطو'),
('mcq', 4, 'لماذا لم يتمكن ديموقريطوس من اختبار صدق فكرته عن الذرات؟', null, '["لأنه أنكر وجود الفراغ الذي تتحرك فيه الذرات","لأنه اعتقد أن الذرات قابلة للتجزئة باستمرار","لأن أرسطو أثبت بالتجربة خطأ فكرته","لأنه لم يكن قادرًا على إجراء تجارب ضابطة"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 77 — ديموقريطوس (ماذا قرأت)'),
('mcq', 5, 'أيّ الأسئلة الآتية لم يستطع ديموقريطوس الإجابة عنه؟', null, '["ما الذي يربط الذرات معًا؟","هل المادة قابلة للانقسام إلى ما لا نهاية؟","ما اسم الأجزاء الصغيرة التي لا تتجزأ؟","أين تتحرك الذرات؟"]'::jsonb, 'تذكر', 'تذكر', 'متوسط', 'الكتاب ص 77 — ديموقريطوس'),
('mcq', 6, 'ادّعى طالب أن أرسطو رفض فكرة الذرات لأن التجارب أثبتت خطأ فكرة ديموقريطوس. ما التعليق الصحيح على هذا الادعاء؟', null, '["صحيح؛ فقد أجرى أرسطو تجارب ضابطة بيّنت عدم وجود الذرات","غير صحيح؛ فلم تُعرف التجارب الضابطة حينئذٍ، ورفضها لتعارضها مع أفكاره","صحيح؛ فقد أثبتت التجارب في عصره أن الذرات تتجزأ","غير صحيح؛ لأن أرسطو أيّد فكرة الذرات واعترض على الفراغ فقط"]'::jsonb, 'تحليل', 'تقويم ادعاء', 'صعب', 'الكتاب ص 77، 78 — أرسطو، ماذا قرأت'),
('mcq', 7, 'ما نتيجة رفض فكرة الذرات بتأثير أرسطو على التقدم العلمي المتعلق بالذرات؟', null, '["تسارع الكشف عن مكونات الذرة في ذلك العصر","ثبتت فكرة ديموقريطوس بوصفها حقيقة علمية","ظل التقدم العلمي المتعلق بالذرات بدائيًّا","عُرف ما يربط الذرات معًا خلال سنوات قليلة"]'::jsonb, 'فهم', 'تفسير نتيجة', 'صعب', 'الكتاب ص 77 — أرسطو'),
('essay', 1, 'فسّر لماذا رفض أرسطو فكرة الذرات التي اقترحها ديموقريطوس، ولماذا رُفضت نظرية ديموقريطوس بسبب ذلك.', null, null, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 77 — أرسطو'),
('essay', 2, 'فسّر لماذا لم يتمكن ديموقريطوس من إثبات أفكاره عن الذرات، واذكر السؤال الذي لم يستطع الإجابة عنه.', null, null, 'فهم', 'تفسير سبب', 'متوسط', 'الكتاب ص 77، 78 — ديموقريطوس، ماذا قرأت'),
('essay', 3, 'هل كان اقتراح ديموقريطوس وجود الذرات قائمًا على طرائق وأفكار علمية؟ اشرح رأيك، وبيّن ما الذي كان ينقصه ليصبح علمًا، وكيف اختلف موقف دالتون عنه.', null, null, 'تقويم', 'حكم معلّل', 'صعب', 'الكتاب ص 77، 78 — ديموقريطوس ودالتون')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
