from (values
('mcq', 1, 0, 'رفض أرسطو فكرة الذرات لأنها لا تتفق مع أفكاره حول الطبيعة، ومنها اعتقاده بعدم وجود الفراغ.', '["","لم تكن التجارب الضابطة معروفة في ذلك الوقت، فلم يستند رفضه إلى تجارب.","تجزؤ الذرة اكتشاف حديث بعد قرون طويلة، ولم يكن سبب رفض أرسطو.","دالتون جاء بعد أرسطو بأكثر من ألفي عام، بل إنه أحيا فكرة الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.687Z"}'::jsonb),
('mcq', 2, 2, 'كان أهم انتقادات أرسطو متعلقًا بفكرة أن الذرات تتحرك في الفراغ؛ لأنه لم يكن يعتقد بوجود فراغ.', '["هذه من أفكار ديموقريطوس عن الذرات، ولم تكن أهم ما انتقده أرسطو.","هذه من أفكار ديموقريطوس، وأهم انتقادات أرسطو كان متعلقًا بالفراغ.","","اختلاف أحجام الذرات وأشكالها من أفكار ديموقريطوس، وليس أهم ما اعترض عليه أرسطو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.687Z"}'::jsonb),
('mcq', 3, 1, 'كان أرسطو أحد فلاسفة الإغريق ذوي التأثير الكبير، وقد رفض فكرة الذرات، فرُفضت بذلك نظرية ديموقريطوس.', '["لم تكن هناك تجارب ضابطة في ذلك العصر، فلم تُرفض النظرية بسبب تجارب.","","دالتون أحيا فكرة الذرات ودعمها بالتجارب، ولم ينفها، وجاء بعد ذلك بأكثر من ألفي عام.","على العكس؛ فقد اهتم فلاسفة كثيرون بطبيعة المادة، ووُجّهت إلى ديموقريطوس انتقادات منهم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.687Z"}'::jsonb),
('mcq', 4, 3, 'لم يكن بإمكان ديموقريطوس إجراء تجارب ضابطة، لذلك ظلت أفكاره مجرد أفكار وليست علمًا يمكن اختبار صدقه.', '["ديموقريطوس اعتقد بوجود الفراغ؛ فالذرات عنده تتحرك فيه، أما الذي أنكره فهو أرسطو.","ديموقريطوس رأى أن الذرات لا تتجزأ، وليس سبب عجزه عن الإثبات فكرة قابلية التجزئة.","أرسطو لم يجرِ تجارب تنفي فكرة الذرات، فقد رفضها لأنها تتعارض مع أفكاره.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.687Z"}'::jsonb),
('mcq', 5, 0, 'تساءل الفلاسفة الآخرون عمّا يربط الذرات معًا، ولم يستطع ديموقريطوس الإجابة، وانقضى أكثر من ألفي عام قبل أن يعرف العلماء الجواب.', '["","أجاب ديموقريطوس عن هذا السؤال بأن المادة ليست قابلة للانقسام إلى ما لا نهاية.","سمّى ديموقريطوس هذه الأجزاء «الذرات».","أجاب ديموقريطوس بأن الذرات تتحرك في الفراغ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.687Z"}'::jsonb),
('mcq', 6, 1, 'لم يكن أحد في ذلك العصر يعرف التجربة الضابطة، ورفض أرسطو للذرات كان لأنها لا تتفق مع أفكاره حول الطبيعة، لا لأن التجارب نفتها.', '["لم يجرِ أرسطو تجارب ضابطة؛ فالتجربة الضابطة لم تكن معروفة في ذلك الوقت.","","لم تُجرَ تجارب في ذلك العصر، وتجزؤ الذرة اكتشاف حديث لاحق.","أرسطو رفض فكرة الذرات نفسها وأنكر وجودها، ولم يقتصر اعتراضه على الفراغ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.687Z"}'::jsonb),
('mcq', 7, 2, 'بسبب تأثير أرسطو العظيم ظل التقدم العلمي في موضوع الذرات بدائيًّا، ومضى أكثر من ألفي سنة قبل أن يعرف العلماء ما يربط الذرات معًا.', '["لم يتسارع الكشف؛ فقد أدى رفض الفكرة إلى بقاء التقدم بدائيًّا.","فكرة ديموقريطوس رُفضت ولم تصبح علمًا مثبتًا في ذلك العصر.","","مضى أكثر من ألفي سنة قبل أن يعرف العلماء الجواب، لا سنوات قليلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.688Z"}'::jsonb),
('essay', 1, null::int, null, null, 'رفض أرسطو فكرة الذرات لأنها لا تتفق مع أفكاره حول الطبيعة. وكان أهم انتقاداته أن ديموقريطوس اعتقد أن الذرات تتحرك في الفراغ، بينما لم يكن أرسطو يعتقد بوجود الفراغ. ولأن أرسطو كان من فلاسفة الإغريق ذوي التأثير الكبير، فقد رُفضت نظرية ديموقريطوس وظل التقدم العلمي المتعلق بالذرات بدائيًّا.', '["فكرة الذرات تتعارض مع أفكار أرسطو عن الطبيعة","ديموقريطوس قال إن الذرات تتحرك في الفراغ","أرسطو لم يعتقد بوجود الفراغ","تأثير أرسطو الكبير أدى إلى رفض النظرية"]'::jsonb, '[]'::jsonb, '[{"element":"تعارض الفكرة مع أفكار أرسطو عن الطبيعة","marks":1},{"element":"حركة الذرات في الفراغ عند ديموقريطوس","marks":1},{"element":"عدم اعتقاد أرسطو بوجود الفراغ","marks":1},{"element":"تأثير أرسطو الكبير وأثره في رفض النظرية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يذكر الفراغ والتعارض مع أفكار أرسطو وتأثيره الكبير"},{"level":"2–3 درجات","description":"تفسير صحيح ينقصه عنصر أو عنصران"},{"level":"1 درجة","description":"ذكر عنصر صحيح واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن أرسطو رفضها لأن التجارب بيّنت خطأها","نسبة إنكار الفراغ إلى ديموقريطوس","إغفال تأثير أرسطو الكبير في رفض النظرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.688Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لم يكن بإمكان ديموقريطوس إجراء تجارب ضابطة تختبر صدق فكرته، فظلت أفكاره مجرد أفكار وليست علمًا. كما وُجّهت إليه انتقادات تساءلت: ما الذي يربط الذرات معًا؟ ولم يستطع الإجابة عن هذا السؤال، ومضى أكثر من ألفي سنة قبل أن يعرف العلماء الجواب.', '["لم يستطع إجراء تجارب ضابطة","أفكاره مجرد أفكار وليست علمًا لأنها لم تُختبر","السؤال: ما الذي يربط الذرات معًا؟","مضى أكثر من ألفي سنة قبل معرفة الجواب"]'::jsonb, '[]'::jsonb, '[{"element":"عدم القدرة على إجراء تجارب ضابطة","marks":1},{"element":"بيان أن أفكاره بقيت أفكارًا لم تُختبر","marks":1},{"element":"ذكر سؤال ما الذي يربط الذرات معًا","marks":1},{"element":"ذكر أن الجواب تأخر أكثر من ألفي سنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع ذكر السؤال والفترة الطويلة قبل معرفة الجواب"},{"level":"2–3 درجات","description":"تفسير صحيح ينقصه عنصر أو عنصران"},{"level":"1 درجة","description":"ذكر عنصر صحيح واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن ديموقريطوس أنكر وجود الفراغ","القول إن سبب العجز هو رفض أرسطو وحده","ذكر سؤال لم يُطرح عليه، كسؤال عن عدد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.688Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لم يكن اقتراح ديموقريطوس قائمًا على طرائق علمية؛ فقد كانت أفكاره مجرد أفكار مبنية على التفكير الذهني وليست علمًا. وكان ينقصه القدرة على إجراء تجارب ضابطة يختبر بها صدق فكرته. أما دالتون فقد أحيا الفكرة بعد قرون وراجعها اعتمادًا على نتائج تجارب علمية وقياسات دقيقة، فبدأت معه الدراسة العلمية للذرة.', '["اقتراح ديموقريطوس لم يكن علميًّا بل أفكارًا","اعتمد على التفكير الذهني دون اختبار","ينقصه تجارب ضابطة لاختبار الفكرة","دالتون اعتمد على تجارب وقياسات دقيقة","بدأت الدراسة العلمية للذرة مع دالتون"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن اقتراح ديموقريطوس لم يكن علميًّا","marks":1},{"element":"تعليل ذلك بأنه أفكار مبنية على التفكير الذهني دون اختبار","marks":1},{"element":"ذكر أن ما ينقصه هو التجارب الضابطة","marks":1},{"element":"بيان اعتماد دالتون على التجارب والقياسات الدقيقة","marks":1},{"element":"بيان أن الدراسة العلمية للذرة بدأت مع دالتون","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم معلّل بالأدلة مع تحديد ما ينقصه ومقارنة صحيحة مع دالتون"},{"level":"3–4 درجات","description":"حكم صحيح مع تعليل ناقص أو دون مقارنة بدالتون"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل، أو عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن فكرته علمية لأنها صحيحة جزئيًّا","الخلط بين صحة الفكرة وكونها مبنية على طرائق علمية","إغفال دور التجارب الضابطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.688Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
