('mcq', 3, 'ما الذي يحدث للذرات في التفاعلات الكيميائية بحسب نظرية دالتون؟', null, '["تتحطم وتُستحدث ذرات جديدة","تتجزأ إلى جسيمات أصغر منها","تنفصل أو تتحد أو يُعاد ترتيبها","تتحول ذرات عنصر إلى ذرات عنصر آخر"]'::jsonb, 'تذكر', 'تذكر فرضية', 'سهل', 'الكتاب ص 78 — الجدول 3-2'),
('mcq', 4, 'ماذا تنص فرضيات دالتون على العلاقة بين ذرات عنصرين مختلفين؟', null, '["ذراتهما متشابهة في الكتلة والحجم","تختلف ذرات كل عنصر عن ذرات العنصر الآخر","يمكن أن تتحول ذرات أحدهما إلى ذرات الآخر","ذراتهما قابلة للتجزئة إلى الأجزاء نفسها"]'::jsonb, 'تذكر', 'تذكر فرضية', 'متوسط', 'الكتاب ص 78 — الجدول 3-2'),
('mcq', 5, 'كتب طالب أربع عبارات عن نظرية دالتون الذرية. أيّ هذه العبارات ليست من فرضيات النظرية؟', null, '["تتكون المادة من أجزاء صغيرة جدًّا تسمى الذرات","الذرات لا تتجزأ ولا تفنى","تتحد الذرات المختلفة بنسبة عددية بسيطة لتكوين المركبات","لا وجود للفراغ، والمادة من التراب والنار والهواء والماء"]'::jsonb, 'فهم', 'تمييز فرضية من غيرها', 'صعب', 'الكتاب ص 77، 78 — الجدولان 3-1 و3-2'),
('mcq', 6, 'تتحد ذرتا هيدروجين مع ذرة أكسجين واحدة لتكوين جزيء الماء. أيّ فرضيات دالتون تفسر النسبة 2 : 1 بين عدد الذرتين؟', null, '["الذرات لا تتجزأ ولا تفنى","ذرات العنصر الواحد متشابهة في الكتلة والحجم","تتحد ذرات العناصر بنسب عددية بسيطة لتكوين المركبات","تنفصل الذرات أو تتحد أو يُعاد ترتيبها في التفاعل"]'::jsonb, 'تطبيق', 'ربط فرضية بمثال', 'صعب', 'الكتاب ص 78 — الجدول 3-2'),
('mcq', 7, 'في أي عام طرح جون دالتون نظريته الذرية؟', null, '["1803م","1766م","1844م","1906م"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 78، 83 — جون دالتون'),
('essay', 1, 'اذكر الفرضيات الرئيسة لنظرية دالتون الذرية.', null, null, 'تذكر', 'تعداد فرضيات', 'سهل', 'الكتاب ص 78 — الجدول 3-2'),
('essay', 2, 'حدّد الفرضية من فرضيات دالتون التي تفسر كل ملاحظة من الملاحظات الآتية، مع تبرير مختصر: (أ) ذرات الكربون في قطعة فحم تتصرف كيميائيًّا التصرف نفسه. (ب) في جزيء CO₂ تتحد ذرة كربون واحدة مع ذرتي أكسجين. (ج) عند تفاعل الهيدروجين مع الأكسجين لتكوين الماء لا تختفي أي ذرة، وإنما تُعاد ترتيبها.', null, null, 'تطبيق', 'ربط فرضيات بملاحظات', 'صعب', 'الكتاب ص 78 — الجدول 3-2'),
('essay', 3, 'اكتب «صحيحة» أو «خاطئة» أمام كل عبارة من العبارات الآتية عن فرضيات دالتون، ثم صحّح العبارة الخاطئة: (1) تتجزأ ذرات العنصر الواحد إلى أجزاء أصغر في التفاعل. (2) تختلف ذرات أي عنصر عن ذرات العناصر الأخرى. (3) تتحد ذرات العناصر بأي نسبة عددية. (4) تفنى بعض الذرات في أثناء التفاعل الكيميائي.', null, null, 'فهم', 'حكم وتصحيح', 'متوسط', 'الكتاب ص 78 — الجدول 3-2')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
