('mcq', 5, 3, 'العبارة الأخيرة من أفكار أرسطو وليست من فرضيات دالتون؛ أما العبارات الثلاث الأخرى فهي من فرضياته.', '["هذه أولى فرضيات دالتون.","هذه من فرضيات دالتون: الذرات لا تتجزأ ولا تفنى.","هذه من فرضيات دالتون عن اتحاد الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.690Z"}'::jsonb),
('mcq', 6, 2, 'النسبة 2 : 1 نسبة عددية بسيطة، وهي مثال على فرضية دالتون: تتحد ذرات العناصر بنسب عددية بسيطة لتكوين المركبات.', '["عدم تجزؤ الذرات وفنائها لا يحدد نسبة اتحادها.","تشابه ذرات العنصر الواحد لا يفسر نسبة اتحاد ذرات عنصرين.","","هذه الفرضية تصف ما يحدث للذرات في التفاعل، ولا تحدد النسبة العددية بين الذرات المتحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.690Z"}'::jsonb),
('mcq', 7, 0, 'طرح دالتون نظريته الذرية عام 1803م بعد دراسته الكثير من التفاعلات الكيميائية وتسجيله ملاحظات وقياسات دقيقة.', '["","1766م هو عام ميلاد دالتون، وليس عام طرح نظريته.","1844م هو عام وفاة دالتون، وليس عام طرح نظريته.","1906م هو عام حصول طومسون على جائزة نوبل لاكتشافه الإلكترون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.690Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفرضيات الرئيسة: (1) تتكون المادة من أجزاء صغيرة جدًّا تسمى الذرات. (2) الذرات لا تتجزأ ولا تفنى. (3) ذرات العنصر الواحد متشابهة في الحجم والكتلة والخواص الكيميائية، وتختلف عن ذرات العناصر الأخرى. (4) تتحد ذرات العناصر المختلفة بنسبة عددية بسيطة لتكوين المركبات. (5) في التفاعلات الكيميائية تنفصل الذرات أو تتحد أو يُعاد ترتيبها.', '["المادة من أجزاء صغيرة جدًّا تسمى الذرات","الذرات لا تتجزأ ولا تفنى","ذرات العنصر الواحد متشابهة وتختلف عن ذرات العناصر الأخرى","تتحد الذرات بنسب عددية بسيطة لتكوين المركبات","في التفاعل تنفصل الذرات أو تتحد أو يُعاد ترتيبها"]'::jsonb, '[]'::jsonb, '[{"element":"المادة من ذرات","marks":1},{"element":"الذرات لا تتجزأ ولا تفنى","marks":1},{"element":"تشابه ذرات العنصر الواحد واختلافها عن ذرات العناصر الأخرى","marks":1},{"element":"الاتحاد بنسب عددية بسيطة","marks":1},{"element":"الانفصال أو الاتحاد أو إعادة الترتيب في التفاعل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ذكر الفرضيات الخمس ذكرًا صحيحًا"},{"level":"3–4 درجات","description":"ذكر ثلاث أو أربع فرضيات ذكرًا صحيحًا"},{"level":"1–2 درجة","description":"ذكر فرضية أو فرضيتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إدخال أفكار ديموقريطوس مثل حركة الذرات في الفراغ","القول إن ذرات العنصر الواحد تختلف في الكتلة","إغفال فرضية اتحاد الذرات بنسب عددية بسيطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.690Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) فرضية تشابه ذرات العنصر الواحد في الحجم والكتلة والخواص الكيميائية؛ فكل ذرات الكربون متماثلة ولذلك تتصرف تصرفًا واحدًا. (ب) فرضية اتحاد ذرات العناصر بنسب عددية بسيطة لتكوين المركبات؛ فالنسبة 1 : 2 نسبة عددية بسيطة. (ج) فرضية أن الذرات لا تفنى، وأنها في التفاعل تنفصل أو تتحد أو يُعاد ترتيبها؛ فلا تختفي ذرات ولا تُستحدث غيرها.', '["أ: تشابه ذرات العنصر الواحد في الخواص الكيميائية","ب: الاتحاد بنسب عددية بسيطة (1 : 2)","ج: الذرات لا تفنى وتنفصل أو تتحد أو يُعاد ترتيبها"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الفرضية في (أ)","marks":1},{"element":"تبرير (أ)","marks":1},{"element":"تحديد الفرضية في (ب)","marks":1},{"element":"تبرير (ب)","marks":1},{"element":"تحديد الفرضية في (ج)","marks":1},{"element":"تبرير (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تحديد الفرضيات الثلاث تحديدًا صحيحًا مع تبرير كل منها"},{"level":"4–5 درجات","description":"تحديد صحيح للفرضيات الثلاث مع نقص في بعض التبريرات"},{"level":"2–3 درجات","description":"تحديد صحيح لفرضيتين مع تبريرهما أو دون تبرير"},{"level":"1 درجة","description":"تحديد فرضية واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الملاحظة (ب) بفرضية عدم تجزؤ الذرات","الخلط بين فرضية الاتحاد بنسب بسيطة وفرضية إعادة الترتيب","ذكر الفرضية دون تبريرها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.690Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) خاطئة؛ والصحيح أن الذرات لا تتجزأ. (2) صحيحة. (3) خاطئة؛ والصحيح أن ذرات العناصر تتحد بنسب عددية بسيطة. (4) خاطئة؛ والصحيح أن الذرات لا تفنى، وإنما تنفصل أو تتحد أو يُعاد ترتيبها.', '["1: خاطئة، الذرات لا تتجزأ","2: صحيحة","3: خاطئة، تتحد بنسب عددية بسيطة","4: خاطئة، الذرات لا تفنى"]'::jsonb, '[]'::jsonb, '[{"element":"العبارة (1) حكمًا وتصحيحًا","marks":1},{"element":"العبارة (2) حكمًا","marks":1},{"element":"العبارة (3) حكمًا وتصحيحًا","marks":1},{"element":"العبارة (4) حكمًا وتصحيحًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح على العبارات الأربع مع تصحيح الخاطئة"},{"level":"2–3 درجات","description":"حكم صحيح على ثلاث عبارات أو تصحيح ناقص"},{"level":"1 درجة","description":"حكم صحيح على عبارة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بالحكم دون تصحيح العبارة الخاطئة","اعتبار العبارة (2) خاطئة","تصحيح العبارة (3) بنسبة 1 : 1 فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.691Z"}'::jsonb)
