('mcq', 2, 'قال دالتون إن ذرات العنصر الواحد متماثلة، لكن تبيّن لاحقًا أنها قد تختلف قليلًا. في أيّ خاصية تختلف ذرات العنصر الواحد؟', null, '["العدد الذري للذرة","العنصر الذي تنتمي إليه","الخواص الكيميائية للذرة","كتلة الذرة الواحدة"]'::jsonb, 'فهم', 'تحديد وجه الخطأ', 'متوسط', 'الكتاب ص 79، 91 — النظائر'),
('mcq', 3, 'أيّ الاكتشافات الآتية دلّ على خطأ دالتون في قوله إن الذرات لا يمكن تجزئتها؟', null, '["اكتشاف جسيم مشحون كتلته أقل كثيرًا من كتلة ذرة الهيدروجين","اكتشاف أن ذرات العناصر المختلفة تتحد بنسب عددية بسيطة","اكتشاف أن الكتلة تبقى ثابتة في التفاعلات الكيميائية","اكتشاف أن ذرة الهيدروجين أصغر ذرة معروفة"]'::jsonb, 'فهم', 'ربط دليل بخطأ', 'متوسط', 'الكتاب ص 83 — اكتشاف طومسون الإلكترون'),
('mcq', 4, 'تعرض البيانات الآتية ذرتين من عنصر النحاس. ماذا تستنتج منها عن فرضية دالتون أن جميع ذرات العنصر الواحد متماثلة؟', '{"headers":["الذرة","العدد الذري","العدد الكتلي"],"rows":[["ذرة نحاس 1","29","63"],["ذرة نحاس 2","29","65"]]}'::jsonb, '["الفرضية صحيحة؛ لأن للذرتين العدد الذري نفسه","الفرضية صحيحة؛ لأن الذرتين متساويتان في الكتلة","الفرضية غير دقيقة؛ فالذرتان تختلفان في الكتلة لاختلاف عدد النيوترونات (34 و36)","الفرضية غير دقيقة؛ لأن الذرتين تنتميان إلى عنصرين مختلفين"]'::jsonb, 'تحليل', 'تحليل بيانات النظائر', 'صعب', 'الكتاب ص 91 — النظائر (نظيرا النحاس)'),
('mcq', 5, 'ما سبب اختلاف كتل ذرات العنصر الواحد (النظائر)؟', null, '["اختلاف عدد البروتونات في أنويتها","اختلاف عدد النيوترونات في أنويتها","اختلاف العنصر الذي تنتمي إليه","اختلاف شحنة الإلكترونات التي تحيط بها"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 91 — النظائر وكتلة النظائر'),
('mcq', 6, 'أيّ العبارات الآتية تقيّم نظرية دالتون الذرية تقييمًا صحيحًا؟', null, '["صحيحة كلها ولم تحتج إلى أي تعديل","خاطئة كلها وأُلغيت تمامًا","لم تؤثر في تطور النموذج الذري الحالي","خطوة كبيرة نحو النموذج الذري الحالي لكنها لم تكن دقيقة"]'::jsonb, 'تقويم', 'تقويم نظرية', 'صعب', 'الكتاب ص 79 — تقويم نظرية دالتون'),
('mcq', 7, 'تعرض البيانات الآتية أربع عبارات من نظرية دالتون. كم عبارة منها تبيّن لاحقًا أنها خاطئة؟', '{"headers":["الرقم","العبارة"],"rows":[["1","الذرات لا تتجزأ"],["2","تختلف ذرات أي عنصر عن ذرات العناصر الأخرى"],["3","جميع ذرات العنصر الواحد متماثلة"],["4","تتحد ذرات العناصر بنسب عددية بسيطة لتكوين المركبات"]]}'::jsonb, '["عبارتان","عبارة واحدة","ثلاث عبارات","أربع عبارات"]'::jsonb, 'تحليل', 'تقويم عبارات النظرية', 'متوسط', 'الكتاب ص 79، 91 — الأخطاء في نظرية دالتون'),
('essay', 1, 'بيّن جانبين من جوانب الخطأ في نظرية دالتون الذرية، مع ذكر ما يدل على خطأ كل منهما.', null, null, 'تحليل', 'تحديد الخطأ مع الدليل', 'سهل', 'الكتاب ص 79، 83، 91 — الأخطاء في نظرية دالتون'),
('essay', 2, 'توجد ثلاثة أنواع من ذرات البوتاسيوم في الطبيعة، يحتوي كل منها على 19 بروتونًا، وعدد النيوترونات فيها 20 و21 و22 على الترتيب. (أ) احسب العدد الكتلي لكل نوع. (ب) أيّ فرضيات دالتون تناقضها هذه المعطيات؟ فسّر. (ج) ما اسم ذرات العنصر الواحد التي تختلف في عدد النيوترونات؟', null, null, 'تحليل', 'تحليل بيانات النظائر', 'صعب', 'الكتاب ص 91 — النظائر (نظائر البوتاسيوم)'),
('essay', 3, 'قيّم نظرية دالتون الذرية: لماذا تُعدّ خطوة كبيرة نحو النموذج الذري الحالي رغم أخطائها؟ وما الذي دفع العلماء إلى إعادة النظر فيها؟', null, null, 'تقويم', 'تقويم نظرية علمية', 'متوسط', 'الكتاب ص 79 — تقويم نظرية دالتون')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
