from (values
('mcq', 1, 1, 'تبيّن أن الذرة تتجزأ إلى جسيمات أصغر هي الإلكترونات والبروتونات والنيوترونات؛ فكان دالتون مخطئًا في قوله إنها لا تُجزَّأ.', '["المادة مكونة من ذرات فعلًا؛ وهذه الفرضية لم يثبت خطؤها.","","ذرات العناصر المختلفة تختلف بالفعل؛ وهذه الفرضية لم يثبت خطؤها.","اتحاد الذرات بنسب عددية بسيطة لتكوين المركبات لم يثبت خطؤه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:27:04.691Z"}'::jsonb),
('mcq', 2, 3, 'ذرات العنصر الواحد لها العدد نفسه من البروتونات والإلكترونات، لكن عدد النيوترونات قد يختلف، فتختلف كتلتها قليلًا.', '["العدد الذري هو عدد البروتونات، وهو واحد لجميع ذرات العنصر الواحد.","ذرات العنصر الواحد تنتمي إلى العنصر نفسه مهما اختلفت كتلتها.","ذرات العنصر الواحد لها السلوك الكيميائي نفسه رغم اختلاف كتلتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.691Z"}'::jsonb),
('mcq', 3, 0, 'استنتج طومسون أن كتلة الجسيم المشحون أقل كثيرًا من كتلة ذرة الهيدروجين، أصغر ذرة معروفة؛ أي أن هذا الجسيم (الإلكترون) أصغر من الذرة، وبذلك يمكن تجزئة الذرات.', '["","اتحاد الذرات بنسب عددية بسيطة لا يتعلق بتجزؤ الذرة.","ثبات الكتلة في التفاعلات يتفق مع نظرية دالتون ولا يبيّن أن الذرة تتجزأ.","كون ذرة الهيدروجين أصغر ذرة معروفة لا يدل على تجزؤ الذرة؛ فالدليل هو وجود جسيم أصغر منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.691Z"}'::jsonb),
('mcq', 4, 2, 'عدد النيوترونات = العدد الكتلي − العدد الذري: 63 − 29 = 34 و65 − 29 = 36. الذرتان من العنصر نفسه لكنهما تختلفان في الكتلة، فالفرضية غير دقيقة.', '["تساوي العدد الذري لا يعني التماثل التام؛ فالذرتان تختلفان في عدد النيوترونات وبالتالي في الكتلة.","العددان الكتليان مختلفان (63 و65)، فالذرتان غير متساويتين في الكتلة.","","الذرتان تنتميان إلى النحاس نفسه لأن لهما العدد الذري نفسه (29)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.692Z"}'::jsonb),
('mcq', 5, 1, 'النظائر ذرات لها عدد البروتونات نفسه لكنها تختلف في عدد النيوترونات، والنظير الأكثر نيوترونات تكون كتلته أكبر.', '["عدد البروتونات هو العدد الذري، وهو ثابت في ذرات العنصر الواحد.","","النظائر ذرات للعنصر نفسه، فلا يختلف العنصر الذي تنتمي إليه.","شحنة الإلكترون واحدة (−1) في جميع الذرات، وليست سبب اختلاف الكتل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.692Z"}'::jsonb),
('mcq', 6, 3, 'كانت نظرية دالتون خطوة كبيرة نحو النموذج الذري الحالي للمادة، لكنها لم تكن دقيقة؛ إذ أخطأ في أن الذرات لا تتجزأ وفي أن ذرات العنصر الواحد متماثلة.', '["النظرية تضمنت خطأين مهمين استلزما إعادة النظر فيها.","لم تُلغَ النظرية تمامًا؛ فكثير من فرضياتها ما زال صحيحًا، وعُدّلت فرضيتان منها.","كانت النظرية خطوة كبيرة نحو النموذج الذري الحالي، فقد أثّرت فيه تأثيرًا كبيرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.692Z"}'::jsonb),
('mcq', 7, 0, 'الخطآن هما العبارة 1 (فالذرة تتجزأ إلى جسيمات أصغر) والعبارة 3 (فالنظائر تختلف في الكتلة). أما العبارتان 2 و4 فلم يثبت خطؤهما، فعدد العبارات الخاطئة اثنتان.', '["","هناك خطآن لا خطأ واحد؛ فكلٌّ من تجزؤ الذرة واختلاف كتل ذرات العنصر الواحد يبيّن خطأ في النظرية.","العبارتان 2 و4 لم يثبت خطؤهما، فليست ثلاث عبارات خاطئة.","لم يثبت خطأ جميع العبارات؛ فالعبارتان 2 و4 ما زالتا مقبولتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:27:04.692Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الجانب الأول: اعتقد دالتون أن الذرات لا يمكن تجزئتها، وتبيّن أنها تتجزأ إلى جسيمات أصغر هي الإلكترونات والبروتونات والنيوترونات؛ ودليل ذلك اكتشاف طومسون الإلكترون، وهو جسيم مشحون كتلته أقل كثيرًا من كتلة ذرة الهيدروجين. الجانب الثاني: قال دالتون إن جميع ذرات العنصر الواحد متماثلة، وتبيّن أنها قد تختلف في كتلتها لاختلاف عدد النيوترونات في أنويتها، وهذه الذرات تسمى النظائر.', '["الذرات لا تتجزأ: خطأ، فهي تتجزأ إلى إلكترونات وبروتونات ونيوترونات","دليل التجزؤ: جسيم الإلكترون أخف كثيرًا من ذرة الهيدروجين","ذرات العنصر الواحد متماثلة: خطأ، فقد تختلف في الكتلة","دليل الاختلاف: النظائر تختلف في عدد النيوترونات"]'::jsonb, '[]'::jsonb, '[{"element":"الجانب الأول: خطأ القول بعدم تجزؤ الذرة","marks":1},{"element":"دليل تجزؤ الذرة (الإلكترون أصغر من الذرة)","marks":1},{"element":"الجانب الثاني: خطأ القول بتماثل ذرات العنصر الواحد","marks":1},{"element":"دليل اختلافها (النظائر وعدد النيوترونات)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جانبا الخطأ صحيحان مع دليل لكل منهما"},{"level":"2–3 درجات","description":"جانبا الخطأ مع دليل ناقص، أو جانب واحد مع دليله"},{"level":"1 درجة","description":"ذكر جانب واحد دون دليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ فرضية اتحاد الذرات بنسب بسيطة خطأ","القول إن ذرات العنصر الواحد تختلف في الخواص الكيميائية","ذكر الخطأ دون دليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.692Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) العدد الكتلي = العدد الذري + عدد النيوترونات؛ فالأنواع الثلاثة: 19 + 20 = 39، و19 + 21 = 40، و19 + 22 = 41. (ب) تناقض فرضية دالتون أن جميع ذرات العنصر الواحد متماثلة؛ فهذه الذرات من عنصر واحد (للجميع 19 بروتونًا) لكنها تختلف في عدد النيوترونات، وبالتالي في الكتلة. (ج) تسمى النظائر.', '["العدد الكتلي 39 و40 و41","الفرضية المناقضة: تماثل ذرات العنصر الواحد","التفسير: العدد الذري واحد لكن عدد النيوترونات والكتلة مختلفان","الاسم: النظائر"]'::jsonb, '["العدد الكتلي = العدد الذري + عدد النيوترونات","النوع الأول: 19 + 20 = 39","النوع الثاني: 19 + 21 = 40","النوع الثالث: 19 + 22 = 41"]'::jsonb, '[{"element":"حساب الأعداد الكتلية الثلاثة (39 و40 و41)","marks":2},{"element":"تحديد فرضية تماثل ذرات العنصر الواحد","marks":1},{"element":"التفسير: اختلاف عدد النيوترونات والكتلة مع ثبات العدد الذري","marks":1},{"element":"اسم النظائر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح للأعداد الكتلية، وتحديد الفرضية وتفسيرها، وذكر اسم النظائر"},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في التفسير أو الاسم"},{"level":"1–2 درجة","description":"حساب جزئي صحيح أو عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح عدد النيوترونات من العدد الذري بدل جمعه","القول إن اختلاف عدد البروتونات هو سبب اختلاف النظائر","عدّ الذرات الثلاث لعناصر مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.692Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُعدّ نظرية دالتون خطوة كبيرة نحو النموذج الذري الحالي للمادة لأنها اعتمدت على تجارب علمية وقدّمت تفسيرًا واضحًا لبنية المركبات ولحفظ الكتلة، فحظيت بقبول عام. لكنها لم تكن دقيقة، وهذا ما يحدث غالبًا في العلوم؛ فقد كان من الضروري إعادة النظر فيها بعد التوصل إلى معلومات جديدة لم يمكن تفسيرها بالنظرية، مثل تجزؤ الذرة إلى جسيمات أصغر (اكتشاف الإلكترون)، واختلاف كتل ذرات العنصر الواحد (النظائر).', '["اعتمدت النظرية على تجارب علمية وفسرت المركبات وحفظ الكتلة","خطوة كبيرة نحو النموذج الذري الحالي","لم تكن دقيقة","ظهور معلومات جديدة لم تفسرها النظرية استلزم إعادة النظر","مثالان على الخطأ: تجزؤ الذرة، والنظائر"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أهمية النظرية (قامت على تجارب وفسرت المركبات وحفظ الكتلة)","marks":1},{"element":"اعتبارها خطوة نحو النموذج الحالي","marks":1},{"element":"الإقرار بأنها لم تكن دقيقة","marks":1},{"element":"ذكر أن معلومات جديدة لم تفسرها النظرية استدعت المراجعة","marks":1},{"element":"مثالان على الخطأ (تجزؤ الذرة والنظائر)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقييم متوازن يبيّن قيمة النظرية وعدم دقتها ويدعم ذلك بمثالين"},{"level":"3–4 درجات","description":"تقييم صحيح ينقصه عنصر أو عنصران"},{"level":"1–2 درجة","description":"ذكر جانب واحد فقط (القيمة أو الخطأ)"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن النظرية خاطئة كلها","الحكم بأن النظرية صحيحة كلها","ذكر الأخطاء دون بيان قيمة النظرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.692Z"}'::jsonb)
