('mcq', 1, 1, 'الذرة هي أصغر جزء في العنصر يحتفظ بخواص ذلك العنصر؛ فذرة النحاس مثلًا هي أصغر جزء يبقى محتفظًا بخواص النحاس.', '["الذرة ليست أصغر جسيم في الكون؛ فهي تتكون من إلكترونات وبروتونات ونيوترونات، أي يمكن تجزئتها إلى جسيمات أصغر.","","أصغر جزء يحتفظ بخواص المركب هو الجزيء أو الوحدة البنائية له، أما الذرة فتُعرَّف بالنسبة إلى العنصر.","هذا وصف النواة (جزء من الذرة)، وليس تعريف الذرة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.693Z"}'::jsonb),
('mcq', 2, 3, 'أصغر جزء في العنصر يحتفظ بخواص العنصر يُسمّى الذرة؛ لذا يكون هذا الجسيم ذرة النحاس.', '["النواة جزء من الذرة، ولا تحتفظ وحدها بخواص النحاس.","الإلكترون جسيم أصغر من الذرة، ولا يحتفظ بخواص العنصر.","النحاس عنصر وليس مركبًا، وأصغر جزء فيه يحتفظ بخواصه هو الذرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.693Z"}'::jsonb),
('mcq', 3, 0, 'الذرة هي أصغر جزء يحتفظ بخواص العنصر؛ لذا فإن الجسيمات الأصغر منها (الإلكترونات والبروتونات والنيوترونات) لا يحتفظ أي منها بخواص النحاس.', '["","لو احتفظ كل جسيم بخواص النحاس لكانت الذرة غير الحد الأصغر الذي يحتفظ بها؛ فالخواص تظهر عند مستوى الذرة لا دونه.","البروتون جسيم مشترك في ذرات العناصر كلها، ولا يحمل وحده خواص النحاس.","الإلكترون جسيم مشترك في ذرات العناصر كلها، ولا يحمل وحده خواص النحاس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.693Z"}'::jsonb),
('mcq', 4, 2, 'تحتوي قطعة صلبة من العملة النحاسية على نحو 2.9 × 10²² ذرة، وهو عدد هائل يدل على صغر الذرة الواحدة.', '["هذا عدد ذرات النحاس اللازمة لتكوين خط طوله أقل من متر واحد إذا وُضعت جنبًا إلى جنب، وليس عدد ذرات القطعة.","6.02 × 10²³ هو عدد الجسيمات في المول، وليس عدد ذرات هذه القطعة.","","عدد الذرات لا يمكن أن يكون أقل من واحد؛ فالأس السالب خطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.693Z"}'::jsonb),
('mcq', 5, 3, 'الذرة أصغر جزء يحتفظ بخواص العنصر، لكنها ليست أصغر الجسيمات؛ فهي تتكون من نواة تحتوي على بروتونات ونيوترونات تحيط بها إلكترونات.', '["الذرة تُعرَّف بالنسبة إلى العنصر لا المركب، وهذا لا يصحح فكرة أنها غير قابلة للتجزئة.","الذرة ليست أكبر جزء بل أصغر جزء يحتفظ بخواص العنصر.","الذرة تحتفظ بخواص العنصر، وهذا جوهر تعريفها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.694Z"}'::jsonb),
('mcq', 6, 0, 'يبلغ قطر ذرة النحاس الواحدة نحو 1.28 × 10⁻¹⁰ m، وهي أصغر بكثير من أن تُرى بالعين المجردة.', '["","هذه القيمة أكبر بنحو عشرة آلاف مرة من قطر الذرة، وتقارب حجم خلية حية صغيرة.","هذه القيمة بحجم جسيم مرئي بالعين، وهي أكبر بملايين المرات من قطر الذرة.","هذه القيمة تقارب 13 cm، وهي أكبر بكثير جدًّا من قطر الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.694Z"}'::jsonb),
('mcq', 7, 2, 'إذا كُبّرت الذرة حتى تصبح بحجم برتقالة، فكأن البرتقالة كُبّرت بنسبة التكبير نفسها حتى صارت بحجم الكرة الأرضية، وهذا يدل على صغر الذرة الشديد.', '["التشبيه المعروف يبدأ بتكبير الذرة إلى حجم برتقالة لا إلى حجم الكرة الأرضية، وتكبير البرتقالة إلى قطعة نقدية لا يعبّر عن نسبة التكبير نفسها.","ملعب كرة القدم أصغر بكثير من الكرة الأرضية، فلا يعبّر عن نسبة التكبير المقصودة.","","حجم الشمس أكبر بكثير من حجم الكرة الأرضية، فلا يمثل نسبة تكبير البرتقالة المقابلة لتكبير الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.694Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الذرة هي أصغر جزء في العنصر يحتفظ بخواص ذلك العنصر. فإذا قُسّمت قطعة نحاس إلى قطع أصغر فأصغر فإن كل قطعة تبقى محتفظة بخواص النحاس، وإذا استمرت التجزئة بأدوات خاصة حتى نصل إلى جسيمات لا يمكن تجزئتها بالطرائق العادية فإن هذه الجسيمات الصغيرة تبقى محتفظة بخواص النحاس، وكل جسيم منها هو ذرة نحاس.', '["الذرة أصغر جزء في العنصر","تحتفظ الذرة بخواص العنصر","تجزئة قطعة النحاس إلى جسيمات أصغر فأصغر مع بقاء الخواص","الوصول إلى جسيم لا يُجزَّأ بالطرائق العادية هو ذرة النحاس"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الذرة بأنها أصغر جزء في العنصر","marks":1},{"element":"ذكر احتفاظها بخواص العنصر","marks":1},{"element":"وصف تجزئة النحاس والوصول إلى ذرة النحاس","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف كامل مع ربط صحيح بمثال النحاس"},{"level":"2 درجة","description":"تعريف صحيح مع نقص في المثال، أو مثال صحيح مع تعريف ناقص"},{"level":"1 درجة","description":"ذكر جزء من التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرة أصغر جسيم في الكون","نسيان ذكر احتفاظ الذرة بخواص العنصر","الخلط بين الذرة والنواة أو الإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.694Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المقصود بعبارة أصغر جزء في العنصر أنها أصغر جزء يحتفظ بخواص ذلك العنصر، لا أنها أصغر جسيم في الوجود. فالذرة تتكون من جسيمات أصغر منها هي الإلكترونات والبروتونات والنيوترونات. وعند تجاوز الذرة إلى هذه الجسيمات لا يبقى أي منها محتفظًا بخواص العنصر؛ فالإلكترون والبروتون والنيوترون جسيمات مشتركة في ذرات العناصر كلها، ولذلك تظهر خواص العنصر عند مستوى الذرة فقط.', '["أصغر جزء يحتفظ بخواص العنصر وليس أصغر جسيم","الذرة تتكون من الإلكترونات والبروتونات والنيوترونات","الجسيمات الأصغر من الذرة لا تحتفظ بخواص العنصر","الجسيمات الأصغر مشتركة بين ذرات العناصر المختلفة"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح معنى «أصغر جزء» بأنه أصغر جزء يحتفظ بالخواص","marks":1},{"element":"ذكر أن الذرة تتكون من جسيمات أصغر","marks":1},{"element":"بيان أن الجسيمات الأصغر لا تحتفظ بخواص العنصر","marks":1},{"element":"تعليل ذلك بأنها مشتركة بين ذرات العناصر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح المعنى، وذكر الجسيمات الأصغر، وبيان فقدان الخواص مع التعليل"},{"level":"2–3 درجات","description":"توضيح صحيح للمعنى مع نقص في ذكر الجسيمات أو التعليل"},{"level":"1 درجة","description":"ذكر أن الذرة تحتفظ بخواص العنصر دون ربط بالاعتراض"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرة لا تتجزأ","القول إن الجسيمات الأصغر من الذرة تحتفظ بخواص العنصر","عدم التفريق بين «أصغر جزء يحتفظ بالخواص» و«أصغر جسيم»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.694Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يدل العدد الهائل للذرات (2.9 × 10²² ذرة) في قطعة صغيرة على أن الذرة الواحدة صغيرة جدًّا، ويدل قطرها 1.28 × 10⁻¹⁰ m، وهو جزء ضئيل جدًّا من المتر، على أنها لا ترى بالعين المجردة. ومن التشبيهات أنه لو كُبّرت الذرة حتى تصبح بحجم برتقالة، فكأن البرتقالة كُبّرت بنسبة التكبير نفسها حتى أصبحت بحجم الكرة الأرضية.', '["العدد الهائل للذرات في قطعة صغيرة يدل على صغر الذرة","قطر الذرة جزء ضئيل جدًّا من المتر","تشبيه تكبير الذرة إلى برتقالة وتكبير البرتقالة إلى الكرة الأرضية"]'::jsonb, '[]'::jsonb, '[{"element":"ربط العدد الهائل للذرات بصغر الذرة","marks":1},{"element":"ربط قيمة القطر بصغر الذرة","marks":1},{"element":"ذكر تشبيه صحيح لصغر الذرة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير الرقمين وذكر التشبيه الصحيح"},{"level":"2 درجة","description":"تفسير أحد الرقمين مع التشبيه، أو تفسير الرقمين دون تشبيه"},{"level":"1 درجة","description":"ذكر أن الذرة صغيرة دون استناد إلى الأرقام أو التشبيه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم الربط بين الأس السالب في القطر وصغر الحجم","ذكر تشبيه معكوس بين حجم الذرة والبرتقالة والأرض","اعتبار العدد الكبير للذرات دليلًا على كبر الذرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.695Z"}'::jsonb)
