from (values
('mcq', 1, 2, 'تتكون الذرة من ثلاثة جسيمات أساسية هي الإلكترون والبروتون والنيوترون.', '["جسيم ألفا ليس من مكونات الذرة الأساسية، بل جسيم يُطلق على صفيحة الذهب في تجربة رذرفورد.","النواة ليست جسيمًا أساسيًّا مستقلًّا؛ فهي مكوّنة من البروتونات والنيوترونات، والإلكترون جسيم أساسي لا بد من ذكره.","","الكواركات مكونات للبروتونات والنيوترونات، وليست من الجسيمات الذرية الأساسية الثلاثة، وينقص هذا الخيار البروتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.695Z"}'::jsonb),
('mcq', 2, 0, 'توجد البروتونات والنيوترونات كلها في نواة الذرة الصغيرة الكثيفة في مركزها.', '["","الفراغ المحيط بالنواة هو موضع حركة الإلكترونات، لا البروتونات والنيوترونات.","توزع الشحنة الموجبة بانتظام في الذرة هو فكرة نموذج طومسون، أما في الذرة الحديثة فالبروتونات مجتمعة في النواة.","لا يوجد أي بروتون أو نيوترون خارج النواة؛ فهي كلها داخل النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.695Z"}'::jsonb),
('mcq', 3, 3, 'تتحرك الإلكترونات في الفراغ المحيط بالنواة، وترتبط بالذرة من خلال التجاذب مع الشحنات الموجبة في النواة.', '["النواة تحتوي على البروتونات والنيوترونات فقط، ولا توجد فيها الإلكترونات.","الإلكترونات لا تلتصق بالنواة، بل تتحرك بسرعة كبيرة في الفراغ المحيط بها.","هذا وصف نموذج طومسون القديم، وليس موقع الإلكترونات في الذرة وفق نموذج النواة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.695Z"}'::jsonb),
('mcq', 4, 1, 'النيوترون جسيم متعادل لا يحمل شحنة كهربائية (شحنته صفر)، بينما يحمل الإلكترون شحنة (–1) ويحمل البروتون شحنة (+1).', '["الإلكترون يحمل شحنة سالبة مقدارها (–1).","","البروتون يحمل شحنة موجبة مقدارها (+1).","نواة ذرة الهيدروجين بروتون واحد فقط، فهي موجبة الشحنة (+1)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.695Z"}'::jsonb),
('mcq', 5, 0, 'الجسيم س في النواة وشحنته (+1) فهو بروتون، والجسيم ص في النواة وشحنته صفر فهو نيوترون، والجسيم ع يتحرك حول النواة وشحنته (–1) وكتلته 1/1840 فهو إلكترون؛ فالترتيب: بروتون، نيوترون، إلكترون.', '["","عكس هذا الترتيب بين س وص؛ فالجسيم س شحنته (+1) وهو بروتون لا نيوترون.","الإلكترون لا يوجد في النواة ولا شحنته (+1) ولا كتلته 1، فلا يمكن أن يكون س.","الجسيم ص شحنته صفر فهو نيوترون وليس إلكترونًا، والجسيم ع في الفراغ المحيط بالنواة فهو إلكترون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.696Z"}'::jsonb),
('mcq', 6, 3, 'نواة ذرة الهيدروجين الأكثر شيوعًا تحتوي على بروتون واحد فقط ولا تحتوي على نيوترونات، وهي الاستثناء بين نوى الذرات التي تحتوي على نيوترونات.', '["وجود نيوترون في نواة الهيدروجين الشائع غير صحيح؛ فنواته لا تحتوي على نيوترونات.","النيوترون متعادل ولا يمكن أن يكون وحده النواة الموجبة لذرة الهيدروجين المتعادلة بإلكترون واحد.","نواة الهيدروجين تحتوي على بروتون واحد لا اثنين؛ فذرته فيها إلكترون واحد يعادل عدد بروتوناتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.696Z"}'::jsonb),
('mcq', 7, 1, 'تتكون الذرة من نواة صغيرة كثيفة في المركز تحتوي على البروتونات والنيوترونات، وتتحرك الإلكترونات في الفراغ المحيط بها.', '["هذا عكس التركيب الصحيح؛ فالنواة هي التي في المركز، والإلكترونات حولها.","","الإلكترونات لا توجد في النواة، والنيوترونات توجد في النواة لا حولها.","هذا وصف نموذج طومسون، لا تركيب الذرة المعروف بنواتها الصغيرة الكثيفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.696Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تتكون الذرة من ثلاثة جسيمات أساسية: البروتون ويوجد في النواة وشحنته (+1)، والنيوترون ويوجد في النواة وهو متعادل (شحنته صفر)، والإلكترون ويتحرك في الفراغ المحيط بالنواة وشحنته (–1).', '["الجسيمات الثلاثة: البروتون والنيوترون والإلكترون","البروتون في النواة وشحنته (+1)","النيوترون في النواة وشحنته صفر","الإلكترون في الفراغ المحيط بالنواة وشحنته (–1)"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الجسيمات الثلاثة","marks":1},{"element":"موقع البروتون وشحنته","marks":1},{"element":"موقع النيوترون وشحنته","marks":1},{"element":"موقع الإلكترون وشحنته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر الجسيمات الثلاثة مع موقع كل منها وشحنته"},{"level":"2–3 درجات","description":"ذكر الجسيمات الثلاثة مع موقع أو شحنة بعضها فقط"},{"level":"1 درجة","description":"ذكر جسيم أو جسيمين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع الإلكترونات داخل النواة","نسبة شحنة موجبة إلى النيوترون","ذكر النواة على أنها جسيم أساسي ثالث"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.696Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) النواة. (ب) البروتونات. (ج) النيوترونات. (د) سحابة الإلكترونات، وهي الفراغ المحيط بالنواة الذي تتحرك فيه الإلكترونات سالبة الشحنة.', '["الكرة الصغيرة الكثيفة هي النواة","الكريات الموجبة هي البروتونات","الكريات المتعادلة هي النيوترونات","السحابة المحيطة هي الإلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية النواة","marks":1},{"element":"تسمية البروتونات","marks":1},{"element":"تسمية النيوترونات","marks":1},{"element":"تسمية سحابة الإلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسمية الأجزاء الأربعة تسمية صحيحة"},{"level":"2–3 درجات","description":"تسمية جزأين أو ثلاثة أجزاء صحيحة"},{"level":"1 درجة","description":"تسمية جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل البروتونات والنيوترونات","تسمية السحابة بأنها النواة","وضع الإلكترونات داخل الكرة المركزية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.696Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تحتوي ذرة الهيدروجين الأكثر شيوعًا على بروتون واحد في النواة وإلكترون واحد يتحرك في الفراغ المحيط بالنواة. وما يميز نواتها أنها تحتوي على بروتون واحد فقط ولا تحتوي على نيوترونات، بينما تحتوي نوى معظم الذرات الأخرى على بروتونات ونيوترونات معًا.', '["بروتون واحد في النواة","إلكترون واحد في الفراغ المحيط بالنواة","نواة الهيدروجين لا تحتوي على نيوترونات","نوى معظم الذرات الأخرى تحتوي على بروتونات ونيوترونات"]'::jsonb, '[]'::jsonb, '[{"element":"بروتون واحد في النواة","marks":1},{"element":"إلكترون واحد حول النواة","marks":1},{"element":"غياب النيوترونات من نواة الهيدروجين","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد الجسيمين ومكانيهما وذكر غياب النيوترونات"},{"level":"2 درجة","description":"تحديد الجسيمين مع إغفال ما يميز النواة"},{"level":"1 درجة","description":"ذكر جسيم واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن نواة الهيدروجين تحتوي على نيوترون","وضع الإلكترون داخل النواة","ذكر أن ذرة الهيدروجين بلا إلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.696Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
