select (select id from public.objectives where code = 'K1-C3-L2-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يحتاج العلماء إلى جهاز المجهر النفقي الماسح (STM) لدراسة الذرات؟', null, '["لأن الذرات تكوّن أشعة المهبط التي تحتاج إلى جهاز خاص","لأن الذرات أكبر من أن تُرى بالعين المجردة","لأن الذرات تُرى بالعين لكن بصورة غير واضحة","لأن الذرات صغيرة جدًّا ولا يمكن رؤيتها إلا بجهاز خاص يسمح برؤيتها"]'::jsonb, 'فهم', 'تعليل أهمية جهاز', 'سهل', 'الكتاب ص 81 — الربط مع علم الأحياء'),
('mcq', 2, 'في تقنية النانو يستعمل العلماء جهاز STM من أجل:', null, '["قياس شحنة الإلكترون بقطرات الزيت","جعل ذرات مفردة تتحرك لتكوّن أشكالًا وأنماطًا وآلات بسيطة","تحويل ذرات عنصر إلى ذرات عنصر آخر","إنتاج أشعة المهبط في أنبوب مفرغ من الهواء"]'::jsonb, 'فهم', 'ربط الجهاز بتطبيقه', 'سهل', 'الكتاب ص 81 — الربط مع علم الأحياء، تقنية النانو'),
('mcq', 3, 'يشبه جهاز STM في دراسة الذرات المجهر المستعمل في دراسة الخلايا الحية؛ فما وجه الشبه بينهما؟', null, '["كلاهما يقيس كتلة الجسيمات التي يفحصها","كلاهما يفصل الجسيمات المفحوصة عن بعضها","كلاهما يمكّن من رؤية أجسام صغيرة جدًّا لا تُرى بالعين المجردة","كلاهما يعتمد على أشعة المهبط لتكوين الصورة"]'::jsonb, 'فهم', 'تفسير بالتشبيه', 'متوسط', 'الكتاب ص 81 — الربط مع علم الأحياء'),
('mcq', 4, 'تريد باحثة فحص ترتيب ذرات الكربون على سطح الجرافيت. أيّ الأجهزة الآتية يناسب هذه الدراسة؟', null, '["المجهر النفقي الماسح STM","أنبوب أشعة المهبط","جهاز ميليكان لقطرة الزيت","المجهر المستعمل لدراسة الخلايا"]'::jsonb, 'تطبيق', 'اختيار جهاز لموقف', 'متوسط', 'الكتاب ص 87 — مختبر تحليل البيانات'),
('mcq', 5, 'تُظهر صورة STM لسطح الجرافيت حلقات سداسية، تتكون كل حلقة منها من ثلاث بقع لامعة تفصلها ثلاث بقع معتمة. ما سبب ظهور البقع اللامعة؟', null, '["انعكاس الضوء المرئي عن سطح الجرافيت","تتابع ذرات الكربون في سطح الجرافيت","ارتداد جسيمات ألفا عن نوى الكربون","اصطدام أشعة المهبط بطلاء الفوسفور"]'::jsonb, 'فهم', 'تفسير صورة', 'متوسط', 'الكتاب ص 87 — مختبر تحليل البيانات'),
('mcq', 6, 'أظهر المقطع العرضي لصورة STM لسطح الجرافيت أن المسافة بين ذرات الكربون تتكرر دوريًّا بقيمة واحدة. ماذا يدل ذلك؟', null, '["الذرات في الجرافيت موزعة توزيعًا عشوائيًّا","الذرات في الجرافيت تتحرك باستمرار بسرعات مختلفة","ترتيب ذرات الكربون في بلورة الجرافيت منتظم والمسافة بينها ثابتة التكرار","الذرات في الجرافيت ملتصقة بحيث لا توجد مسافات بينها"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 87 — مختبر تحليل البيانات'),
('mcq', 7, 'قال طالب: «لا توجد أي طريقة لرؤية الذرات لأنها صغيرة جدًّا». ما الرد العلمي المناسب؟', null, '["توجد طريقة؛ فجهاز STM يسمح برؤية ذرات مفردة","عبارتك صحيحة؛ فلا يوجد جهاز يرى الذرات","توجد طريقة؛ فالمجهر الضوئي العادي يُظهر الذرات","توجد طريقة؛ فأنبوب أشعة المهبط يصوّر الذرات"]'::jsonb, 'فهم', 'تصحيح تصور خاطئ', 'سهل', 'الكتاب ص 81 — الربط مع علم الأحياء'),
('essay', 1, 'وضّح أهمية جهاز المجهر النفقي الماسح (STM) في دراسة الذرات، مستعينًا بالمقارنة مع المجهر المستعمل لدراسة الخلايا.', null, null, 'فهم', 'توضيح أهمية', 'متوسط', 'الكتاب ص 81 — الربط مع علم الأحياء'),
('essay', 2, 'اشرح كيف أسهم جهاز STM في ظهور ما يُعرف بتقنية النانو، موضحًا ما يستطيع العلماء فعله بالذرات المفردة.', null, null, 'فهم', 'شرح علاقة جهاز بتقنية', 'صعب', 'الكتاب ص 81 — تقنية النانو'),
('essay', 3, 'أظهرت صورة STM لسطح بلورة الجرافيت حلقات سداسية، كل حلقة تتكون من ثلاث بقع لامعة تفصلها ثلاث بقع معتمة، وأظهر المقطع العرضي مسافات بين الذرات تتكرر دوريًّا بقيمة واحدة. فسّر ما تمثله البقع اللامعة، وماذا يدل عليه تكرار المسافة، ثم وضّح كيف تبرز هذه الدراسة أهمية جهاز STM.', null, null, 'تطبيق', 'تفسير بيانات صورة', 'صعب', 'الكتاب ص 87 — مختبر تحليل البيانات')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C3-L2-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الذرات صغيرة جدًّا فلا تُرى بالعين المجردة، ويسمح جهاز STM برؤيتها ودراستها، فيحتاج إليه العلماء.', '["أشعة المهبط سيل من الإلكترونات يظهر في أنابيب خاصة، وليست ناتجة عن الذرات بوصفها سببًا لحاجة العلماء إلى STM.","الذرات لا تُرى لأنها أصغر من أن تُرى، لا لأنها أكبر.","الذرة الواحدة لا تُرى بالعين إطلاقًا، وليس المشكلة في وضوح الصورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:27:04.697Z"}'::jsonb),
('mcq', 2, 1, 'يتيح جهاز STM للعلماء التحكم في ذرات مفردة وجعلها تتحرك لتكوّن أشكالًا وأنماطًا وآلات بسيطة، وهذا أساس تقنية النانو.', '["قياس شحنة الإلكترون تم بجهاز ميليكان لقطرة الزيت وليس بجهاز STM.","","STM لا يحوّل عنصرًا إلى عنصر آخر، بل يرى الذرات ويحركها.","أشعة المهبط تُنتَج في أنبوب أشعة المهبط، لا في جهاز STM."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.697Z"}'::jsonb),
('mcq', 3, 2, 'كما يمكّن المجهر من رؤية الخلايا الصغيرة، يمكّن جهاز STM من رؤية الذرات الأصغر منها بكثير؛ فوجه الشبه أن كليهما يُظهر أجسامًا لا تُرى بالعين المجردة.', '["المجهر لا يقيس الكتلة؛ وظيفته إظهار الأجسام الصغيرة لا قياس كتلتها.","الفصل ليس وظيفة المجهرين؛ فهما يُظهران الجسيمات للدراسة.","","أشعة المهبط ليست أساس عمل المجهر الذي يدرس الخلايا ولا أساس تفسير عمل STM هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.698Z"}'::jsonb),
('mcq', 4, 0, 'جهاز STM هو الذي يسمح برؤية الذرات المفردة على السطح ودراستها، لذلك يناسب فحص ترتيب ذرات الكربون في الجرافيت.', '["","أنبوب أشعة المهبط يُستعمل لدراسة الجسيمات المشحونة (الإلكترونات) لا لتصوير الذرات.","جهاز ميليكان يُستعمل لتحديد شحنة الإلكترون بقطرات الزيت، لا لتصوير الذرات.","مجهر الخلايا لا يصل إلى دقة تُظهر الذرات المفردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.698Z"}'::jsonb),
('mcq', 5, 1, 'البقع اللامعة في صورة STM ناشئة عن تتابع ذرات الكربون في سطح الجرافيت، ولذلك تدل الصورة على مواضع الذرات.', '["الصورة لا تعتمد على انعكاس الضوء المرئي؛ فالذرات أصغر من أن تُرى بالضوء المعتاد.","","ارتداد جسيمات ألفا ظاهرة في تجربة رذرفورد مع صفيحة الذهب، وليس سبب صورة STM.","هذا ما يحدث في أنبوب أشعة المهبط، وليس أساس تكوين صورة STM."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:27:04.698Z"}'::jsonb),
('mcq', 6, 2, 'تكرار المسافة نفسها بين ذرات الكربون دوريًّا يدل على أن الذرات مرتبة ترتيبًا منتظمًا في البلورة، وهذا ما يكشفه جهاز STM.', '["التوزيع العشوائي يعني اختلاف المسافات وعدم تكرارها، وهذا يخالف ما أظهرته الصورة.","المقطع يبين مسافات متكررة بين الذرات، لا سرعات حركتها.","","الصورة تُظهر ذرات منفصلة تفصلها مسافات متكررة، لا ذرات بلا مسافات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.698Z"}'::jsonb),
('mcq', 7, 0, 'يوجد جهاز خاص هو المجهر النفقي الماسح STM يسمح برؤية الذرات المفردة، فعبارة الطالب غير صحيحة.', '["","عبارة الطالب خاطئة؛ فجهاز STM يرى الذرات المفردة.","المجهر الضوئي العادي لا يُظهر الذرات المفردة؛ فالذي يفعل ذلك هو STM.","أنبوب أشعة المهبط يُستعمل لدراسة الإلكترونات لا لتصوير الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.698Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الذرات صغيرة جدًّا فلا يمكن رؤيتها بالعين المجردة، ويسمح جهاز STM برؤية الذرات المفردة ودراستها؛ فكما يحتاج الباحث في الأحياء إلى مجهر لدراسة الخلايا، يحتاج الكيميائي إلى جهاز STM لدراسة الذرات وتصوير أماكنها على سطح المادة.', '["الذرات صغيرة جدًّا ولا تُرى بالعين","STM يسمح برؤية ذرات مفردة","المقارنة بالمجهر المستعمل لدراسة الخلايا"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر صغر الذرات وتعذر رؤيتها","marks":1},{"element":"ذكر أن STM يسمح برؤية الذرات المفردة","marks":1},{"element":"المقارنة الصحيحة بمجهر الخلايا","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"توضيح كامل للأهمية مع المقارنة"},{"level":"2 درجة","description":"توضيح الأهمية دون مقارنة، أو مقارنة دون ذكر رؤية الذرات المفردة"},{"level":"1 درجة","description":"ذكر أن الجهاز يُستعمل لدراسة الذرات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن STM يرى الذرات بالضوء المعتاد","الخلط بين STM وأنبوب أشعة المهبط","القول إن الجهاز يرى الإلكترونات والنواة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:27:04.698Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لأن جهاز STM يسمح برؤية الذرات المفردة، أصبح العلماء قادرين على جعل ذرات مفردة تتحرك لتكوّن أشكالًا وأنماطًا وآلات بسيطة. وتعتمد تقنية النانو على ذلك، فهي تعِد بصناعة المواد على المستوى الجزيئي وبناء آلات بحجم صغير جدًّا (حجم الجزيء).', '["STM يسمح برؤية الذرات المفردة","تحريك ذرات مفردة لتكوين أشكال وأنماط","تكوين آلات بسيطة","تقنية النانو: صناعة على المستوى الجزيئي وآلات بحجم صغير جدًّا"]'::jsonb, '[]'::jsonb, '[{"element":"رؤية الذرات المفردة بـ STM","marks":1},{"element":"تحريك الذرات لتكوين أشكال وأنماط","marks":1},{"element":"تكوين آلات بسيطة","marks":1},{"element":"تعريف تقنية النانو بالصناعة على المستوى الجزيئي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ربط صحيح بين STM وتقنية النانو مع ذكر ما يفعله العلماء بالذرات"},{"level":"2–3 درجات","description":"ذكر بعض العناصر دون ربط كامل"},{"level":"1 درجة","description":"ذكر أن الجهاز يرى الذرات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العلماء يحوّلون الذرات إلى عناصر جديدة","الخلط بين النانو وحجم الخلية","إغفال أن الأمر يتم على ذرات مفردة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.699Z"}'::jsonb),
('essay', 3, null::int, null, null, 'البقع اللامعة ناشئة عن تتابع ذرات الكربون في سطح الجرافيت، فهي تمثل مواضع الذرات. وتكرار المسافة نفسها دوريًّا بين الذرات يدل على أن ذرات الكربون مرتبة ترتيبًا منتظمًا في البلورة. وتبرز هذه الدراسة أهمية جهاز STM لأنه يعطي صورة سطحية على المستوى الذري، فيسمح برؤية الذرات المفردة وقياس المسافات بينها، وهذا لا يمكن بالوسائل المعتادة.', '["البقع اللامعة تمثل ذرات الكربون","تكرار المسافة يدل على ترتيب منتظم للذرات في البلورة","STM يعطي صورة على المستوى الذري","STM يسمح برؤية الذرات المفردة وقياس المسافات بينها"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير البقع اللامعة بأنها ذرات الكربون","marks":1},{"element":"تفسير تكرار المسافة بالترتيب المنتظم","marks":1},{"element":"ذكر أن STM يعطي صورة على المستوى الذري","marks":1},{"element":"ربط ذلك بأهمية الجهاز في رؤية الذرات المفردة وقياس المسافات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير البقع والمسافات وربطهما بأهمية الجهاز"},{"level":"2–3 درجات","description":"تفسير صحيح لبعض العناصر مع نقص في الربط بالأهمية"},{"level":"1 درجة","description":"ذكر أن الصورة تمثل الذرات دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار البقع المعتمة هي وحدها الذرات دون تعليل","القول إن الصورة التقطت بالضوء المعتاد","عدم الربط بين النتيجة وأهمية الجهاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:27:04.699Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
