insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C3-L2-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في أنبوب أشعة المهبط، في أي اتجاه تسير أشعة المهبط؟', null, '["من المهبط (الكاثود) إلى المصعد (الأنود)","من المصعد (الأنود) إلى المهبط (الكاثود)","تتحرك في الاتجاهين بالتساوي","لا تتحرك بل تتوهج في مكانها"]'::jsonb, 'تذكر', 'تذكر وصف الجهاز', 'سهل', 'الكتاب ص 82 — أنبوب أشعة المهبط'),
('mcq', 2, 'أيّ المشاهدات الآتية دليل على أن أشعة المهبط تتكون من جسيمات مشحونة؟', null, '["توهج طلاء الفوسفور عند الطرف الآخر للأنبوب","عدم تأثرها بتغيير الغاز داخل الأنبوب","انحرافها عند مرورها في مجال مغناطيسي","خروجها من المهبط وسيرها نحو المصعد"]'::jsonb, 'فهم', 'ربط دليل باستنتاج', 'سهل', 'الكتاب ص 82 — الشكل 3-7'),
('mcq', 3, 'ما إشارة شحنة جسيمات أشعة المهبط، وما الدليل على ذلك؟', null, '["موجبة؛ لأنها تنحرف نحو الصفيحة الموجبة في المجال الكهربائي","سالبة؛ لأنها تنحرف نحو الصفيحة الموجبة في المجال الكهربائي","سالبة؛ لأنها تنحرف نحو الصفيحة السالبة في المجال الكهربائي","متعادلة؛ لأنها لا تنحرف في المجال المغناطيسي"]'::jsonb, 'فهم', 'استنتاج نوع الشحنة', 'متوسط', 'الكتاب ص 82 — الشكل 3-7'),
('mcq', 4, 'لماذا استنتج العلماء أن الجسيمات السالبة الشحنة لأشعة المهبط موجودة في جميع أشكال المادة؟', null, '["لأن أشعة المهبط تُرى بوضوح داخل الأنبوب المفرغ","لأن الأشعة تنتقل من المهبط إلى المصعد دائمًا","لأن الأشعة تنحرف في المجال المغناطيسي","لأن تغيير فلز القطبين أو الغاز في الأنبوب لا يؤثر في الأشعة الناتجة"]'::jsonb, 'فهم', 'تعليل استنتاج', 'متوسط', 'الكتاب ص 82 — أشعة المهبط والإلكترونات'),
('mcq', 5, 'وجد طومسون أن كتلة جسيم أشعة المهبط أقل كثيرًا من كتلة ذرة الهيدروجين، وهي أصغر ذرة معروفة. ماذا استنتج من ذلك؟', null, '["أن الذرة لا تتجزأ كما قال دالتون","أن أشعة المهبط تتكون من ذرات هيدروجين","أن الذرة يمكن تجزئتها إلى جسيمات أصغر منها","أن الجسيم الجديد موجب الشحنة"]'::jsonb, 'فهم', 'استنتاج من بيانات', 'متوسط', 'الكتاب ص 83 — كتلة الجسيم المشحون'),
('mcq', 6, 'أيّ الأحداث الآتية يُنسب إلى طومسون؟', null, '["اكتشاف النواة عام 1911م","اكتشاف الإلكترون عام 1897م","اكتشاف النيوترون عام 1932م","تحديد شحنة الإلكترون عام 1910م"]'::jsonb, 'تذكر', 'تذكر عالم واكتشاف', 'سهل', 'الكتاب ص 83 — اكتشاف الإلكترون، ص 84'),
('mcq', 7, 'ظهر بريق أخضر عند أحد طرفي أنبوب أشعة المهبط المغلف بكبريتيد الخارصين عند تشغيل الأنبوب. ما سبب هذا البريق؟', null, '["تسخين المصعد بفعل التيار فيتوهج","تفاعل المهبط كيميائيًّا مع الغاز المتبقي","ارتداد جسيمات ألفا عن الطلاء","اصطدام أشعة المهبط بالطلاء المغلف للطرف"]'::jsonb, 'تطبيق', 'تفسير مشاهدة', 'صعب', 'الكتاب ص 82 — الشكل 3-7'),
('essay', 1, 'اشرح كيف اكتُشف الإلكترون داخل الذرة، مبيّنًا التجارب التي أجراها العلماء على أنبوب أشعة المهبط وما استنتجوه منها.', null, null, 'فهم', 'شرح تسلسل اكتشاف', 'متوسط', 'الكتاب ص 81–83 — الإلكترون'),
('essay', 2, 'كانت نظرية دالتون تعتبر الذرة جسيمًا لا يتجزأ. وضّح كيف نقضت نتائج طومسون هذه الفكرة، مع ذكر ما وجده من كتلة جسيمات أشعة المهبط ومقارنتها بأصغر ذرة معروفة.', null, null, 'فهم', 'تفسير استنتاج علمي', 'صعب', 'الكتاب ص 83 — كتلة الجسيم المشحون'),
('essay', 3, 'في أنبوب أشعة مهبط تمر الأشعة بين صفيحتين مشحونتين: العليا موجبة والسفلى سالبة، فتنحرف الأشعة نحو الصفيحة العليا. تنبأ بما يحدث لمسار الأشعة إذا عُكست قطبية الصفيحتين، وعلّل تنبؤك، ثم بيّن ما تدل عليه ملاحظة الانحراف عن نوع شحنة جسيمات الأشعة.', null, null, 'تطبيق', 'تنبؤ مع تعليل', 'صعب', 'الكتاب ص 82 — الشكل 3-7')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
