from (values
('mcq', 1, 0, 'أشعة المهبط هي الشعاع الذي يخرج من المهبط (القطب السالب) إلى المصعد (القطب الموجب)، ومنه جاء اسمها.', '["","هذا عكس الاتجاه الصحيح؛ فالأشعة تخرج من المهبط لا من المصعد.","الحركة في اتجاه واحد هو من المهبط إلى المصعد، وليس في الاتجاهين.","الأشعة جسيمات تنتقل داخل الأنبوب، والتوهج يظهر فقط حين تصطدم بطلاء خاص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.699Z"}'::jsonb),
('mcq', 2, 2, 'انحراف الأشعة في المجال المغناطيسي دليل على أنها جسيمات مشحونة؛ فالجسيمات المتعادلة لا تنحرف في المجالات الكهربائية والمغناطيسية.', '["التوهج يدل على اصطدام الأشعة بالطلاء، لا على أنها مشحونة.","عدم تأثرها بنوع الغاز يدل على وجود الجسيمات في جميع المواد، لا على كونها مشحونة.","","اتجاه حركتها يبين مصدرها ومسارها، لكنه لا يثبت أنها مشحونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.700Z"}'::jsonb),
('mcq', 3, 1, 'تنحرف أشعة المهبط في المجال الكهربائي نحو الصفيحة الموجبة، والشحنات المختلفة تتجاذب؛ فجسيماتها سالبة الشحنة.', '["الجسيم الموجب لا يمكن أن ينجذب إلى الصفيحة الموجبة؛ فالشحنات المتشابهة تتنافر.","","الانحراف نحو الصفيحة السالبة غير مشاهد؛ فالأشعة تنحرف نحو الصفيحة الموجبة.","الأشعة تنحرف في المجال المغناطيسي، فهي ليست متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.700Z"}'::jsonb),
('mcq', 4, 3, 'لم يتغير سلوك أشعة المهبط عند تغيير فلز القطبين أو الغاز داخل الأنبوب، فاستنتج العلماء أن جسيماتها السالبة موجودة في جميع أشكال المادة وسُميت الإلكترونات.', '["رؤية الأشعة لا تدل على وجود جسيماتها في كل المواد.","اتجاه الحركة لا يبين أن هذه الجسيمات موجودة في جميع المواد.","الانحراف يدل على أن الجسيمات مشحونة، لا على وجودها في جميع المواد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.700Z"}'::jsonb),
('mcq', 5, 2, 'كتلة الجسيم أقل كثيرًا من كتلة أصغر ذرة، فهو أصغر من الذرة؛ إذن يمكن تجزئة الذرات إلى جسيمات أصغر، وكان دالتون مخطئًا في قوله إنها لا تتجزأ.', '["هذا رأي دالتون الذي نقضه استنتاج طومسون.","كتلة الجسيم أقل كثيرًا من كتلة ذرة الهيدروجين، فليس ذرة هيدروجين.","","الجسيم سالب الشحنة؛ فهو ينحرف نحو الصفيحة الموجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.700Z"}'::jsonb),
('mcq', 6, 1, 'اكتشف طومسون الإلكترون عام 1897م باستعمال أنبوب أشعة المهبط، ونال جائزة نوبل عام 1906م عن ذلك.', '["اكتشاف النواة (1911م) تم على يد رذرفورد بتجربة صفيحة الذهب.","","اكتشاف النيوترون (1932م) تم على يد شادويك.","تحديد شحنة الإلكترون (1910م) تم على يد ميليكان بتجربة قطرة الزيت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.700Z"}'::jsonb),
('mcq', 7, 3, 'يتوهج الطلاء (كبريتيد الخارصين) بريقًا أخضر عندما تصطدم به الإلكترونات القادمة من المهبط، وهذا ما جعل الأشعة قابلة للكشف.', '["البريق ناتج عن اصطدام الأشعة بالطلاء، وليس عن تسخين المصعد.","لا يحدث تفاعل كيميائي بين المهبط والغاز يسبب هذا البريق؛ فسلوك الأشعة لا يتغير بتغير الغاز.","جسيمات ألفا لا علاقة لها بأنبوب أشعة المهبط؛ فهي تُستعمل في تجربة رذرفورد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.700Z"}'::jsonb),
('essay', 1, null::int, null, null, 'استعمل العلماء أنبوبًا زجاجيًّا مفرغًا من الهواء فيه قطبان: مهبط (كاثود) موصول بالقطب السالب للبطارية ومصعد (أنود) موصول بالقطب الموجب، فخرج شعاع من المهبط إلى المصعد سُمّي أشعة المهبط. وتبين أن هذه الأشعة سيل من جسيمات مشحونة؛ إذ تنحرف في المجالين المغناطيسي والكهربائي، وانحرافها نحو الصفيحة الموجبة يدل على أنها سالبة الشحنة. ولأن تغيير فلز القطبين أو الغاز في الأنبوب لم يؤثر في الأشعة، استنتجوا أن هذه الجسيمات السالبة موجودة في جميع أشكال المادة، وسُمّيت الإلكترونات ورمزها e⁻. ثم وجد طومسون أن كتلتها أقل كثيرًا من كتلة ذرة الهيدروجين، فاستنتج أن الذرة تتجزأ إلى جسيمات أصغر منها، وأن الإلكترون أول جسيم مكوِّن للذرة يُكتشف.', '["أنبوب زجاجي مفرغ من الهواء فيه مهبط ومصعد","أشعة المهبط تخرج من المهبط إلى المصعد","الأشعة سيل من جسيمات سالبة الشحنة تنحرف في المجالين الكهربائي والمغناطيسي","تغيير فلز القطبين أو الغاز لا يؤثر فيها فهي موجودة في جميع المواد","كتلة الجسيم أقل كثيرًا من كتلة ذرة الهيدروجين فالذرة تتجزأ"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الأنبوب والأشعة من المهبط إلى المصعد","marks":1},{"element":"الأشعة جسيمات سالبة تنحرف في المجالين","marks":1},{"element":"عدم تأثرها بفلز القطبين أو الغاز وبالتالي وجودها في جميع المواد","marks":1},{"element":"تسميتها الإلكترونات","marks":1},{"element":"كتلتها أقل كثيرًا من كتلة ذرة الهيدروجين فالذرة تتجزأ","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"شرح متسلسل يشمل الأنبوب، وطبيعة الأشعة، وعدم تأثرها بالفلز والغاز، والتسمية، والاستنتاج عن كتلتها"},{"level":"3–4 درجات","description":"شرح صحيح مع إغفال عنصر أو عنصرين"},{"level":"1–2 درجة","description":"ذكر أنبوب أشعة المهبط أو أن الأشعة سالبة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأشعة تخرج من المصعد","القول إن الأشعة موجبة الشحنة","إغفال أن عدم تأثر الأشعة بنوع الفلز أو الغاز هو الدليل على وجودها في كل المواد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.701Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وجد طومسون أن كتلة جسيم أشعة المهبط المشحون أقل كثيرًا من كتلة ذرة الهيدروجين، وهي أصغر ذرة معروفة. وهذا يعني أن هذا الجسيم أصغر من الذرة، وبالتالي يمكن تجزئة الذرات إلى جسيمات أصغر، فكان دالتون مخطئًا في اعتبار الذرة لا تتجزأ. وكان استنتاجه مفاجئًا، وبه اكتشف أول جسيم مكوّن للذرة وهو الإلكترون ونال جائزة نوبل عام 1906م.', '["نظرية دالتون: الذرة لا تتجزأ","كتلة جسيم أشعة المهبط أقل كثيرًا من كتلة ذرة الهيدروجين","الجسيم أصغر من أصغر ذرة معروفة","الذرة يمكن تجزئتها فكان دالتون مخطئًا"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر نتيجة طومسون بشأن كتلة الجسيم مقارنة بذرة الهيدروجين","marks":1},{"element":"استنتاج أن الجسيم أصغر من الذرة","marks":1},{"element":"استنتاج أن الذرة تتجزأ وأن فكرة دالتون غير صحيحة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ربط كامل بين مقارنة الكتلة واستنتاج تجزؤ الذرة"},{"level":"2 درجة","description":"ذكر المقارنة والاستنتاج دون توضيح الصلة بينهما"},{"level":"1 درجة","description":"ذكر أن الإلكترون اكتُشف دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كتلة الجسيم أكبر من كتلة ذرة الهيدروجين","الاستمرار في اعتبار الذرة غير قابلة للتجزئة","عدم ربط صغر الكتلة بكون الجسيم أصغر من الذرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.701Z"}'::jsonb),
('essay', 3, null::int, null, null, 'إذا عُكست القطبية فأصبحت الصفيحة العليا سالبة والسفلى موجبة، فإن الأشعة تنحرف نحو الصفيحة السفلى بدل العليا؛ لأن جسيمات الأشعة تنجذب دائمًا نحو الصفيحة الموجبة. ويدل انحرافها نحو الصفيحة الموجبة على أن جسيماتها سالبة الشحنة؛ لأن الشحنات المختلفة تتجاذب.', '["تنحرف الأشعة نحو الصفيحة السفلى بعد عكس القطبية","التعليل: تنجذب جسيمات الأشعة نحو الصفيحة الموجبة","الانحراف نحو الصفيحة الموجبة يدل على شحنة سالبة","الشحنات المختلفة تتجاذب"]'::jsonb, '[]'::jsonb, '[{"element":"التنبؤ بانحراف الأشعة نحو الصفيحة السفلى","marks":1},{"element":"تعليل ذلك بانجذاب الجسيمات إلى الصفيحة الموجبة","marks":1},{"element":"استنتاج أن جسيمات الأشعة سالبة الشحنة","marks":1},{"element":"ذكر أن الشحنات المختلفة تتجاذب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تنبؤ صحيح وتعليل صحيح واستنتاج نوع الشحنة"},{"level":"2–3 درجات","description":"تنبؤ صحيح مع نقص في التعليل أو الاستنتاج"},{"level":"1 درجة","description":"ذكر انحراف الأشعة دون تحديد اتجاهه الصحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأشعة تبقى منحرفة نحو الصفيحة العليا","القول إن الأشعة تنجذب نحو الصفيحة السالبة","استنتاج أن الأشعة موجبة الشحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.701Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
