from (values
('mcq', 1, 'ما الكمية التي حدّدها طومسون بدراسة تأثير المجالين المغناطيسي والكهربائي في جسيمات أشعة المهبط؟', null, '["شحنة الإلكترون وحدها","نسبة شحنة الجسيم إلى كتلته","كتلة الإلكترون وحدها","سرعة سقوط قطرات الزيت"]'::jsonb, 'تذكر', 'تذكر ما قاسه عالم', 'سهل', 'الكتاب ص 82 — نسبة الشحنة إلى الكتلة'),
('mcq', 2, 'ما الكمية التي حدّدها ميليكان بتجربة قطرة الزيت؟', null, '["شحنة الإلكترون","كتلة الإلكترون وحدها","نسبة الشحنة إلى الكتلة","كتلة ذرة الهيدروجين"]'::jsonb, 'تذكر', 'تذكر ما قاسه عالم', 'سهل', 'الكتاب ص 83 — تجربة قطرة الزيت وشحنة الإلكترون'),
('mcq', 3, 'قاس ميليكان شحنات ثلاث قطرات زيت وسجلها في الجدول الآتي. ما أكبر شحنة تكون شحنة كل قطرة مضاعفًا صحيحًا لها، وتمثل شحنة إلكترون واحد؟', '{"headers":["القطرة","الشحنة (C)"],"rows":[["أ","3.204 × 10⁻¹⁹"],["ب","4.806 × 10⁻¹⁹"],["ج","8.010 × 10⁻¹⁹"]]}'::jsonb, '["3.204 × 10⁻¹⁹ C","4.806 × 10⁻¹⁹ C","1.602 × 10⁻¹⁸ C","1.602 × 10⁻¹⁹ C"]'::jsonb, 'تطبيق', 'تحليل بيانات تجربة', 'متوسط', 'الكتاب ص 83 — تجربة قطرة الزيت وشحنة الإلكترون'),
('mcq', 4, 'لماذا لم يستطع طومسون تحديد كتلة الإلكترون من تجاربه وحدها؟', null, '["لأن أشعة المهبط لا تنحرف في المجال الكهربائي","لأنه لم يكن يعلم أن أشعة المهبط مشحونة","لأن تجاربه أعطت نسبة الشحنة إلى الكتلة فقط دون كل منهما على حدة","لأن كتلة الإلكترون أكبر من أن تُقاس بالأجهزة"]'::jsonb, 'فهم', 'تفسير حدود التجربة', 'متوسط', 'الكتاب ص 82–83 — نسبة الشحنة إلى الكتلة'),
('mcq', 5, 'نسبة شحنة الإلكترون إلى كتلته تساوي 1.76 × 10⁸ C/g، وشحنته 1.602 × 10⁻¹⁹ C. ما كتلة الإلكترون؟', null, '["9.10 × 10⁻²⁸ g","2.82 × 10⁻¹¹ g","1.10 × 10²⁷ g","9.10 × 10⁻³¹ g"]'::jsonb, 'تطبيق', 'حساب كتلة الإلكترون', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — حساب كتلة الإلكترون من الشحنة ونسبة الشحنة إلى الكتلة'),
('mcq', 6, 'كيف استطاع ميليكان ضبط سرعة سقوط قطرات الزيت في جهازه؟', null, '["بتغيير كمية الزيت المرشوشة في الجهاز","بتغيير شدة المجال الكهربائي بين الصفيحتين","بتغيير فلز الصفيحتين المشحونتين","بتغيير حجم الثقب في الصفيحة العليا"]'::jsonb, 'فهم', 'تفسير إجراء', 'سهل', 'الكتاب ص 83 — تجربة قطرة الزيت وشحنة الإلكترون'),
('mcq', 7, 'ما دور أشعة X في تجربة ميليكان لقطرة الزيت؟', null, '["تقيس سرعة سقوط قطرات الزيت بين الصفيحتين","تُحدث الثقب الصغير في الصفيحة العليا للجهاز","تُبخّر الزيت قبل رشّه فوق الصفيحتين المشحونتين","تصطدم بالإلكترونات بين الصفيحتين فتلتصق بقطرات الزيت وتشحنها"]'::jsonb, 'فهم', 'تفسير دور عامل في تجربة', 'متوسط', 'الكتاب ص 83 — تجربة قطرة الزيت وشحنة الإلكترون'),
('essay', 1, 'اشرح كيف استعمل ميليكان جهاز قطرة الزيت لتحديد شحنة الإلكترون، وما القيمة التي توصل إليها ودلالتها.', null, null, 'فهم', 'شرح إجراء تجربة', 'متوسط', 'الكتاب ص 83 — تجربة قطرة الزيت وشحنة الإلكترون'),
('essay', 2, 'وضّح كيف حُسبت كتلة الإلكترون اعتمادًا على تجربتي طومسون وميليكان، ثم احسبها باستعمال القيمتين: نسبة الشحنة إلى الكتلة 1.76 × 10⁸ C/g، وشحنة الإلكترون 1.602 × 10⁻¹⁹ C.', null, null, 'تطبيق', 'حساب كتلة مع توضيح الطريقة', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — حساب كتلة الإلكترون من الشحنة ونسبة الشحنة إلى الكتلة'),
('essay', 3, 'قاس باحث شحنات ثلاث قطرات زيت في جهاز ميليكان فحصل على: 6.408 × 10⁻¹⁹ C و9.612 × 10⁻¹⁹ C و11.214 × 10⁻¹⁹ C. بيّن كيف تستنتج من هذه القيم شحنة الإلكترون الواحد، واحسب عدد الإلكترونات على كل قطرة.', null, null, 'تطبيق', 'تحليل بيانات واستنتاج', 'صعب', 'الكتاب ص 83 — تجربة قطرة الزيت وشحنة الإلكترون')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
