insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'قاس طومسون مقدار انحراف جسيمات أشعة المهبط في المجالين فحدّد نسبة شحنتها إلى كتلتها، ولم يحدّد الشحنة وحدها ولا الكتلة وحدها.', '["الانحراف يعطي نسبة الشحنة إلى الكتلة فقط، أما الشحنة وحدها فحدّدها ميليكان.","","الكتلة لا تُعرف من نسبة الشحنة إلى الكتلة وحدها، بل بعد معرفة الشحنة من تجربة ميليكان.","سرعة سقوط قطرات الزيت كمية تتعلق بتجربة ميليكان لا بتجربة طومسون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.701Z"}'::jsonb),
('mcq', 2, 0, 'حدّد ميليكان بتجربة قطرة الزيت شحنة الإلكترون، وهي 1.602 × 10⁻¹⁹ C.', '["","الكتلة حُسبت لاحقًا من الشحنة ونسبة الشحنة إلى الكتلة، ولم يقسها ميليكان مباشرة.","نسبة الشحنة إلى الكتلة قاسها طومسون لا ميليكان.","كتلة ذرة الهيدروجين كانت معروفة ومقارنة بها، وليست ما حدّده ميليكان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.702Z"}'::jsonb),
('mcq', 3, 3, '3.204 ÷ 1.602 = 2 و4.806 ÷ 1.602 = 3 و8.010 ÷ 1.602 = 5، فكل شحنة مضاعف صحيح للقيمة 1.602 × 10⁻¹⁹ C، وهي شحنة إلكترون واحد.', '["هذه أصغر القيم المقيسة، لكن 4.806 لا يساوي مضاعفًا صحيحًا لها، فهي ليست الوحدة المشتركة.","4.806 × 10⁻¹⁹ C ليست قاسمًا للقيمتين الأخريين؛ فـ 3.204 ÷ 4.806 ليس عددًا صحيحًا.","خطأ في الأس؛ فهذه القيمة تساوي عشرة أضعاف الوحدة الصحيحة، وهي أكبر من كل الشحنات المقيسة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.702Z"}'::jsonb),
('mcq', 4, 2, 'قياس الانحراف يعطي النسبة شحنة ÷ كتلة فقط؛ ولا يمكن استخراج الكتلة منها دون معرفة الشحنة، التي حدّدها ميليكان لاحقًا.', '["الأشعة تنحرف في المجالين الكهربائي والمغناطيسي، وهذا أساس قياس طومسون.","طومسون عرف أن الأشعة مشحونة، وهذا ما مكّنه من قياس نسبة الشحنة إلى الكتلة.","","كتلة الإلكترون صغيرة جدًّا لا كبيرة، والمشكلة ليست في الأجهزة بل في أن القياس يعطي نسبة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.702Z"}'::jsonb),
('mcq', 5, 0, 'الكتلة = الشحنة ÷ (الشحنة/الكتلة) = (1.602 × 10⁻¹⁹ C) ÷ (1.76 × 10⁸ C/g) = 9.10 × 10⁻²⁸ g.', '["","هذا ناتج ضرب الشحنة في النسبة (1.602 × 10⁻¹⁹ × 1.76 × 10⁸)، والصحيح قسمة الشحنة على النسبة.","هذا ناتج قسمة النسبة على الشحنة، أي قلب القسمة؛ والصحيح قسمة الشحنة على النسبة.","الناتج 9.10 × 10⁻³¹ هو الكتلة بوحدة kg إذا حُوّلت من g، لكن الوحدة هنا g فالقيمة غير صحيحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.702Z"}'::jsonb),
('mcq', 6, 1, 'غيّر ميليكان شدة المجال الكهربائي بين الصفيحتين المشحونتين، فتحكّم في سرعة سقوط القطرات المشحونة ومنه حسب شحنة كل قطرة.', '["كمية الزيت لا تتحكم في سرعة سقوط القطرة المشحونة تحت تأثير المجال.","","نوع فلز الصفيحتين ليس العامل الذي استعمله للتحكم في سرعة السقوط.","الثقب يسمح بمرور الزيت فقط، ولا يضبط سرعة السقوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.702Z"}'::jsonb),
('mcq', 7, 3, 'تصطدم أشعة X بالإلكترونات الموجودة بين الصفيحتين، فتلتصق هذه الإلكترونات بقطرات الزيت وتشحنها بشحنة سالبة، وبذلك يمكن قياس شحنة كل قطرة.', '["السرعة تُلاحَظ بالتلسكوب ولا تقيسها أشعة X.","الثقب موجود أصلًا في الصفيحة العليا ويسمح بمرور الزيت.","الزيت يُرش بالبخاخ ولا تُبخّره أشعة X.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.702Z"}'::jsonb),
('essay', 1, null::int, null, null, 'رُشّ الزيت بالبخاخ فوق صفيحتين متوازيتين مشحونتين، وتحتوي الصفيحة العليا على ثقب صغير تمر منه قطرات الزيت. وتصطدم أشعة X بالإلكترونات الموجودة بين الصفيحتين فتلتصق بالقطرات وتشحنها بشحنة سالبة. وبتغيير شدة المجال الكهربائي ضبط ميليكان سرعة سقوط القطرات، وحدّد شحنة كل قطرة، ووجد أن شحنات القطرات تزداد بكميات محددة أي بمضاعفات صحيحة لقيمة صغرى، وأن أبسط مقدار مشترك يعادل 1.602 × 10⁻¹⁹ C، وهي شحنة إلكترون واحد؛ أي أن شحنة الإلكترون (–1).', '["رش الزيت فوق صفيحتين مشحونتين","أشعة X تجعل الإلكترونات تلتصق بالقطرات فتشحنها","تغيير شدة المجال الكهربائي لضبط سرعة السقوط","شحنات القطرات مضاعفات محددة لأصغر قيمة","أصغر قيمة 1.602 × 10⁻¹⁹ C وهي شحنة إلكترون واحد (–1)"]'::jsonb, '[]'::jsonb, '[{"element":"وصف رش الزيت بين صفيحتين مشحونتين","marks":1},{"element":"دور أشعة X في شحن القطرات","marks":1},{"element":"ضبط السرعة بتغيير شدة المجال الكهربائي","marks":1},{"element":"كون الشحنات مضاعفات لأصغر قيمة 1.602 × 10⁻¹⁹ C وأنها شحنة إلكترون واحد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح لخطوات التجربة والقيمة ودلالتها"},{"level":"2–3 درجات","description":"وصف صحيح لبعض الخطوات مع القيمة أو دونها"},{"level":"1 درجة","description":"ذكر أن ميليكان قاس الشحنة بقطرات الزيت فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن ميليكان قاس كتلة الإلكترون مباشرة","نسبة قياس نسبة الشحنة إلى الكتلة إلى ميليكان","إغفال أن أصغر قيمة مشتركة تمثل شحنة إلكترون واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.703Z"}'::jsonb),
('essay', 2, null::int, null, null, 'قاس طومسون نسبة شحنة الإلكترون إلى كتلته، لكنه لم يستطع تحديد الشحنة وحدها أو الكتلة وحدها، وحدّد ميليكان الشحنة بتجربة قطرة الزيت، وبمعرفة الشحنة والنسبة يمكن حساب الكتلة: الكتلة = الشحنة ÷ (الشحنة/الكتلة) = 1.602 × 10⁻¹⁹ C ÷ 1.76 × 10⁸ C/g = 9.10 × 10⁻²⁸ g، أي نحو 1/1840 من كتلة ذرة الهيدروجين.', '["طومسون: نسبة الشحنة إلى الكتلة","ميليكان: الشحنة","الكتلة = الشحنة ÷ النسبة","الناتج 9.10 × 10⁻²⁸ g"]'::jsonb, '["نكتب العلاقة: الكتلة = الشحنة ÷ (الشحنة/الكتلة)","نعوّض: الكتلة = 1.602 × 10⁻¹⁹ C ÷ 1.76 × 10⁸ C/g","نحسب: الكتلة = 9.10 × 10⁻²⁸ g"]'::jsonb, '[{"element":"ذكر أن طومسون قاس نسبة الشحنة إلى الكتلة وميليكان قاس الشحنة","marks":1},{"element":"كتابة العلاقة: الكتلة = الشحنة ÷ النسبة","marks":1},{"element":"التعويض الصحيح","marks":1},{"element":"الناتج 9.10 × 10⁻²⁸ g بوحدته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح دور العالمين، والعلاقة، والتعويض، والناتج بوحدته"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة مع خطأ في الحساب أو الوحدة"},{"level":"1 درجة","description":"ذكر دور أحد العالمين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الشحنة في النسبة بدلًا من قسمتها عليها","قلب القسمة (قسمة النسبة على الشحنة)","إهمال الوحدة أو كتابة g بدل kg عند التحويل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.703Z"}'::jsonb),
('essay', 3, null::int, null, null, 'شحنة كل قطرة مضاعف صحيح لشحنة إلكترون واحد؛ فنبحث عن أكبر قيمة تقبل بها القيم الثلاث مضاعفات صحيحة. الفرق بين القيمتين الأخيرتين 11.214 – 9.612 = 1.602 × 10⁻¹⁹ C، وبقسمة كل شحنة على 1.602 × 10⁻¹⁹ C نحصل على 4 و6 و7. إذن شحنة الإلكترون الواحد 1.602 × 10⁻¹⁹ C، وعدد الإلكترونات: 4 و6 و7 على الترتيب.', '["الشحنات مضاعفات صحيحة لشحنة الإلكترون","شحنة الإلكترون 1.602 × 10⁻¹⁹ C","عدد الإلكترونات على القطرات: 4 و6 و7"]'::jsonb, '["الفرق بين 11.214 و9.612 يساوي 1.602 (× 10⁻¹⁹ C)، فهي القيمة المرشحة لشحنة إلكترون واحد","6.408 ÷ 1.602 = 4","9.612 ÷ 1.602 = 6","11.214 ÷ 1.602 = 7","إذن على القطرات 4 و6 و7 إلكترونات على الترتيب"]'::jsonb, '[{"element":"التوصل إلى أن شحنة الإلكترون 1.602 × 10⁻¹⁹ C مع التبرير","marks":2},{"element":"قسمة كل شحنة بالطريقة الصحيحة","marks":1},{"element":"ذكر عدد الإلكترونات 4 و6 و7","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد شحنة الإلكترون مع التبرير وحساب أعداد الإلكترونات الصحيحة"},{"level":"2–3 درجات","description":"تحديد الشحنة صحيحًا مع خطأ في عدد الإلكترونات أو غياب التبرير"},{"level":"1 درجة","description":"ذكر أن الشحنات مضاعفات صحيحة دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار أصغر شحنة مقيسة هي شحنة إلكترون واحد","عدم الانتباه إلى أن عدد الإلكترونات يجب أن يكون عددًا صحيحًا","قسمة الشحنات على بعضها بدل قسمتها على شحنة الإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.703Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
