from (values
('mcq', 1, 'ما أبرز اختلاف بين نموذجي طومسون ورذرفورد في توزيع الشحنة الموجبة داخل الذرة؟', null, '["متركزة في نواة صغيرة في نموذج طومسون، وموزعة بانتظام في نموذج رذرفورد","متركزة في نواة صغيرة كثيفة في المركز في كلا النموذجين","موزعة بانتظام في نموذج طومسون، ومتركزة في نواة صغيرة في نموذج رذرفورد","موزعة بانتظام في كرة موجبة في كلا النموذجين"]'::jsonb, 'فهم', 'مقارنة نموذجين', 'سهل', 'الكتاب ص 84، 86 — نموذج طومسون ونموذج رذرفورد'),
('mcq', 2, 'ما الصفة المشتركة بين نموذجي طومسون ورذرفورد للذرة؟', null, '["وجود نواة صغيرة كثيفة في المركز","وجود فراغ كبير تتحرك فيه الإلكترونات","توزع الشحنة الموجبة بانتظام في الذرة","الذرة متعادلة كهربائيًّا وتحتوي إلكترونات سالبة الشحنة"]'::jsonb, 'تحليل', 'تحديد وجه شبه', 'سهل', 'الكتاب ص 84، 86 — نموذج طومسون ونموذج رذرفورد'),
('mcq', 3, 'أيّ مما يأتي يفسره نموذج رذرفورد ولا يفسره نموذج طومسون؟', null, '["انحراف عدد قليل من جسيمات ألفا بزوايا كبيرة وارتداد عدد قليل جدًّا منها","تعادل الذرة كهربائيًّا بوجود شحنات موجبة وسالبة","وجود إلكترونات سالبة الشحنة داخل الذرة","كون كتلة الإلكترون أقل كثيرًا من كتلة ذرة الهيدروجين"]'::jsonb, 'تحليل', 'تحديد ما يفسره نموذج', 'متوسط', 'الكتاب ص 86 — نموذج رذرفورد للذرة'),
('mcq', 4, 'وفق نموذج طومسون، ماذا كان متوقعًا لجسيمات ألفا عند إطلاقها نحو صفيحة رقيقة من الذهب؟', null, '["ترتد معظمها إلى الخلف","تمر معظمها وتنحرف انحرافًا قليلًا فقط","تنحرف جميعها بزوايا كبيرة","تمتصها الصفيحة جميعها"]'::jsonb, 'فهم', 'تنبؤ وفق نموذج', 'سهل', 'الكتاب ص 86 — الشكل 3-12'),
('mcq', 5, 'مرّ معظم جسيمات ألفا خلال صفيحة الذهب في تجربة رذرفورد دون انحراف يُذكر. ماذا استنتج رذرفورد من ذلك؟', null, '["أن الشحنة الموجبة موزعة بانتظام في الذرة","أن الذرة كرة صلبة مملوءة بالمادة","أن النواة تشغل معظم حجم الذرة","أن الذرة تتكون في معظمها من فراغ تتحرك فيه الإلكترونات"]'::jsonb, 'تحليل', 'استنتاج من ملاحظة', 'متوسط', 'الكتاب ص 86 — نموذج رذرفورد للذرة'),
('mcq', 6, 'ما سبب انحراف بعض جسيمات ألفا بزوايا كبيرة وارتداد قليل منها عند اصطدامها بصفيحة الذهب؟', null, '["قوة التنافر بين جسيمات ألفا الموجبة والنواة الموجبة الشحنة","تجاذب جسيمات ألفا الموجبة مع النواة الموجبة الشحنة","اصطدام جسيمات ألفا بإلكترونات ثقيلة في الذرة","امتصاص ذرات الذهب لجسيمات ألفا ثم إطلاقها"]'::jsonb, 'تحليل', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 86 — الشكل 3-13'),
('mcq', 7, 'قطر الذرة يعادل نحو عشرة آلاف مرة قطر نواتها. إذا كان قطر نواة ذرة ما 1 × 10⁻¹⁴ m فما قطر الذرة تقريبًا؟', null, '["1 × 10⁻¹⁸ m","1 × 10⁻¹⁰ m","1 × 10⁻¹¹ m","1 × 10⁻⁹ m"]'::jsonb, 'تطبيق', 'حساب نسبة الأقطار', 'متوسط', 'الكتاب ص 86 — نموذج رذرفورد للذرة'),
('essay', 1, 'قارن بين نموذج طومسون ونموذج رذرفورد للذرة من حيث: (أ) توزيع الشحنة الموجبة، (ب) موضع الإلكترونات والفراغ في الذرة، (ج) تفسير نتائج تجربة صفيحة الذهب، ثم اذكر صفة تشترك فيها الذرة في النموذجين.', null, null, 'تحليل', 'مقارنة نموذجين', 'متوسط', 'الكتاب ص 84، 86 — نموذج طومسون ونموذج رذرفورد'),
('essay', 2, 'لاحظ رذرفورد في تجربته أن معظم جسيمات ألفا مرّت خلال صفيحة الذهب دون انحراف يُذكر، وأن نسبة قليلة انحرفت بزوايا كبيرة، وأن عددًا قليلًا جدًّا ارتدّ إلى الخلف. حلّل كل ملاحظة من هذه الملاحظات الثلاث، واذكر ما استنتجه رذرفورد منها عن تركيب الذرة، ووضّح لماذا لا يتوافق ذلك مع نموذج طومسون.', null, null, 'تحليل', 'تحليل نتائج تجربة', 'صعب', 'الكتاب ص 85–86 — تجربة رذرفورد ونموذجه'),
('essay', 3, 'قال طالب: «نموذج رذرفورد أفضل من نموذج طومسون لأنه فسّر كل ما يتعلق بالذرة». قوِّم هذه العبارة بذكر ما فسّره نموذج رذرفورد مما لم يفسره نموذج طومسون، ثم اذكر حدًّا بقي فيه نموذج رذرفورد قاصرًا.', null, null, 'تقويم', 'تقويم عبارة علمية', 'صعب', 'الكتاب ص 86 — نموذج رذرفورد للذرة، ص 84')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
