('mcq', 1, 2, 'في نموذج طومسون الشحنة الموجبة موزعة بانتظام في كرة تتناثر فيها الإلكترونات، أما في نموذج رذرفورد فمعظم الشحنة الموجبة متركزة في نواة صغيرة كثيفة في المركز.', '["هذا عكس الصحيح؛ فالنواة الصغيرة هي فكرة رذرفورد، وتوزع الشحنة بانتظام هو فكرة طومسون.","طومسون لم يفترض وجود نواة؛ فالشحنة الموجبة عنده موزعة بانتظام.","","رذرفورد استنتج من تجربته أن الشحنة الموجبة متركزة في نواة، لا موزعة بانتظام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.704Z"}'::jsonb),
('mcq', 2, 3, 'يشترك النموذجان في أن الذرة متعادلة كهربائيًّا؛ إذ تعادل الشحنة الموجبة الشحنة السالبة للإلكترونات، وفي أن الإلكترونات سالبة الشحنة موجودة فيها.', '["النواة الصغيرة الكثيفة خاصة بنموذج رذرفورد فقط.","الفراغ الكبير حول النواة استنتاج رذرفورد، أما كرة طومسون فمملوءة بالشحنة الموجبة.","توزع الشحنة الموجبة بانتظام خاص بنموذج طومسون فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.704Z"}'::jsonb),
('mcq', 3, 0, 'نموذج طومسون توقع انحرافًا طفيفًا فقط لجسيمات ألفا، ولم يفسر انحراف بعضها بزوايا كبيرة وارتداد قليل منها، أما رذرفورد ففسره بوجود نواة صغيرة كثيفة موجبة.', '["","تعادل الذرة كهربائيًّا يفسره النموذجان معًا.","وجود الإلكترونات السالبة في الذرة يتضمنه النموذجان معًا.","هذه الحقيقة نتيجة تجارب أشعة المهبط، ولا يفسرها أي من النموذجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.704Z"}'::jsonb),
('mcq', 4, 1, 'بما أن الشحنة الموجبة موزعة بانتظام في ذرات الذهب، توقع رذرفورد وفق نموذج طومسون أن تمر جسيمات ألفا خلال الصفيحة وأن تنحرف انحرافًا قليلًا فقط.', '["الارتداد إلى الخلف نتيجة لوحظت فعلًا في تجربة رذرفورد ولكن بعدد قليل جدًّا، ولم يتوقعها نموذج طومسون.","","الانحراف الكبير لوحظ لنسبة قليلة من الجسيمات فقط، ولم يتوقعه نموذج طومسون لجميعها.","الصفيحة لم تمتص جسيمات ألفا؛ فنموذج طومسون توقع مرورها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.704Z"}'::jsonb),
('mcq', 5, 3, 'مرور معظم جسيمات ألفا دون انحراف يدل على أن الذرة غالبًا فراغ تتحرك فيه الإلكترونات، وأن النواة المركزة صغيرة جدًّا.', '["هذه فكرة طومسون، ولو صحّت لانحرفت الجسيمات انحرافًا قليلًا ولما ارتد بعضها.","لو كانت الذرة كرة صلبة مملوءة لما مرّ معظم الجسيمات خلالها.","النواة صغيرة جدًّا (قطر الذرة نحو عشرة آلاف مرة قطر النواة)، فلا تشغل معظم الحجم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.704Z"}'::jsonb),
('mcq', 6, 0, 'جسيمات ألفا موجبة الشحنة والنواة موجبة الشحنة، فتنشأ قوة تنافر بينهما تحرف الجسيمات التي تمر قريبة من النواة، وقد ترتد القليلة جدًّا منها.', '["","الشحنتان متشابهتان (موجبتان) فتتنافران ولا تتجاذبان.","الإلكترونات كتلتها صغيرة جدًّا، ولا تستطيع أن تحرف جسيمات ألفا الكبيرة الكتلة بزوايا كبيرة.","لم يُلاحظ امتصاص جسيمات ألفا؛ فالانحراف ناتج عن قوة التنافر مع النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.704Z"}'::jsonb),
('mcq', 7, 1, 'قطر الذرة ≈ 10⁴ × قطر النواة = 10⁴ × 1 × 10⁻¹⁴ m = 1 × 10⁻¹⁰ m.', '["هذه القيمة ناتجة عن قسمة القطر على 10⁴ بدل ضربه فيها.","","هذه القيمة ناتجة عن ضرب القطر في ألف (10³) بدل عشرة آلاف.","هذه القيمة ناتجة عن ضرب القطر في مئة ألف (10⁵) بدل عشرة آلاف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.705Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في نموذج طومسون الشحنة الموجبة موزعة بانتظام في كرة، أما في نموذج رذرفورد فمعظم الشحنة الموجبة ومعظم الكتلة متركزان في نواة صغيرة كثيفة في مركز الذرة. (ب) في نموذج طومسون الإلكترونات مغروسة في الكرة الموجبة، وفي نموذج رذرفورد تتحرك الإلكترونات في فراغ كبير حول النواة وترتبط بها بالتجاذب. (ج) لم يفسر نموذج طومسون نتائج تجربة رقاقة الذهب (انحراف بعض جسيمات ألفا بزوايا كبيرة وارتداد قليل منها)، بينما فسّرها نموذج رذرفورد بوجود النواة الموجبة التي تتنافر مع جسيمات ألفا. والصفة المشتركة: الذرة متعادلة كهربائيًّا وتحتوي إلكترونات سالبة الشحنة.', '["طومسون: شحنة موجبة موزعة بانتظام","رذرفورد: نواة صغيرة كثيفة تحمل معظم الشحنة والكتلة","طومسون: إلكترونات مغروسة في الكرة، رذرفورد: إلكترونات تتحرك في فراغ كبير حول النواة","نموذج طومسون لم يفسر تجربة الذهب ونموذج رذرفورد فسّرها","الذرة متعادلة وتحتوي إلكترونات سالبة في النموذجين"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في توزيع الشحنة الموجبة","marks":1},{"element":"المقارنة في موضع الإلكترونات والفراغ","marks":1},{"element":"ذكر أن طومسون لم يفسر تجربة الذهب","marks":1},{"element":"تفسير رذرفورد بوجود النواة","marks":1},{"element":"ذكر الصفة المشتركة (التعادل والإلكترونات السالبة)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة في الجوانب الثلاثة مع ذكر الصفة المشتركة"},{"level":"3–4 درجات","description":"مقارنة صحيحة في جانبين أو ثلاثة مع نقص في بعض العناصر"},{"level":"1–2 درجة","description":"وصف أحد النموذجين فقط أو مقارنة جزئية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة النواة إلى نموذج طومسون","القول إن رذرفورد أنكر وجود الإلكترونات","الخلط بين توزيع الشحنة في النموذجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.705Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مرور معظم الجسيمات دون انحراف يدل على أن الذرة غالبًا فراغ تتحرك فيه الإلكترونات. وانحراف نسبة قليلة بزوايا كبيرة وارتداد عدد قليل جدًّا يدلان على وجود مركز صغير كثيف موجب الشحنة (النواة) يتنافر مع جسيمات ألفا الموجبة، ويحمل معظم الشحنة الموجبة ومعظم كتلة الذرة. ولا يتوافق ذلك مع نموذج طومسون لأن الشحنة الموجبة فيه موزعة بانتظام، فلا ينتظر منه سوى انحراف طفيف لجسيمات ألفا، ولا يفسر الانحراف الكبير أو الارتداد.', '["مرور معظم الجسيمات: الذرة غالبًا فراغ","انحراف قليل بزوايا كبيرة: وجود مركز موجب صغير كثيف يتنافر مع ألفا","الارتداد القليل جدًّا: تركز معظم الشحنة والكتلة في النواة","نموذج طومسون يتوقع انحرافًا طفيفًا فقط لتوزع الشحنة بانتظام"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل مرور معظم الجسيمات واستنتاج الفراغ","marks":1},{"element":"تحليل الانحراف الكبير واستنتاج النواة الموجبة","marks":1},{"element":"تحليل الارتداد وتركز الكتلة والشحنة","marks":1},{"element":"بيان عدم توافق النتائج مع نموذج طومسون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل الملاحظات الثلاث واستنتاجاتها مع بيان تعارضها مع نموذج طومسون"},{"level":"2–3 درجات","description":"تحليل صحيح لملاحظتين أو ثلاث مع إغفال المقارنة بنموذج طومسون"},{"level":"1 درجة","description":"ذكر الملاحظات دون استنتاجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الانحراف بسبب تجاذب ألفا مع النواة","القول إن معظم حجم الذرة هو النواة","عدم الربط بين ملاحظة الارتداد وتركز الكتلة والشحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.706Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة صحيحة جزئيًّا فقط. فنموذج رذرفورد أفضل لأنه فسّر نتائج تجربة صفيحة الذهب (مرور معظم جسيمات ألفا، وانحراف قليل منها بزوايا كبيرة بسبب التنافر مع النواة الموجبة) وهو ما عجز عنه نموذج طومسون، كما وضّح أن الذرة متعادلة لأن شحنة النواة الموجبة تعادل الشحنة السالبة للإلكترونات. لكنه لم يفسر كتلة الذرة تفسيرًا كاملًا؛ إذ لا تكفي كتلة الشحنات الموجبة وحدها، وقد اكتُشف لاحقًا (1932م) النيوترون المتعادل في النواة الذي يسهم في الكتلة. لذلك لا يصح القول إنه فسّر كل شيء.', '["العبارة صحيحة جزئيًّا فقط","رذرفورد فسّر نتائج تجربة صفيحة الذهب بوجود النواة الموجبة","نموذج رذرفورد يبين تعادل الذرة كهربائيًّا","لم يفسر النموذج كتلة الذرة","اكتشف لاحقًا النيوترون في النواة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة بأنها صحيحة جزئيًّا","marks":1},{"element":"ذكر تفسير رذرفورد لتجربة الذهب الذي عجز عنه طومسون","marks":1},{"element":"ذكر أن النموذج لم يفسر كتلة الذرة","marks":1},{"element":"تعليل القصور أو ذكر اكتشاف النيوترون لاحقًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع ذكر نقطة القوة وحد القصور وتعليله"},{"level":"2–3 درجات","description":"ذكر نقطة القوة أو حد القصور دون تعليل كامل"},{"level":"1 درجة","description":"حكم دون تبرير علمي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة كما هي دون ذكر حدود النموذج","القول إن نموذج رذرفورد لم يفسر تجربة الذهب","نسبة اكتشاف النيوترون إلى رذرفورد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.706Z"}'::jsonb)
