('mcq', 3, 'لاحظ رذرفورد أن معظم جسيمات ألفا مرت خلال صفيحة الذهب دون انحراف أو بانحراف قليل. ماذا استنتج من هذه الملاحظة؟', null, '["أن الذرة تكون في معظمها فراغًا","أن الشحنة الموجبة موزعة بانتظام في الذرة","أن الذرة كرة مصمتة من المادة","أن جسيمات ألفا لا تتأثر بالشحنات مطلقًا"]'::jsonb, 'فهم', 'استنتاج من ملاحظة', 'متوسط', 'الكتاب ص 85، 86 — تجربة رذرفورد ونموذجه'),
('mcq', 4, 'ارتدّ عدد قليل جدًّا من جسيمات ألفا إلى الخلف في اتجاه مصدرها بعد اصطدامها بصفيحة الذهب. ما الذي يدل عليه ذلك؟', null, '["أن الإلكترونات ثقيلة بما يكفي لصدّ جسيمات ألفا","أن الشحنة الموجبة تنتشر في الذرة كلها بالتساوي","أن في مركز الذرة جزءًا صغيرًا كثيفًا موجب الشحنة","أن الذرة متعادلة فلا تؤثر في جسيمات ألفا"]'::jsonb, 'فهم', 'استنتاج من ملاحظة', 'متوسط', 'الكتاب ص 85، 86 — تجربة رذرفورد، النواة'),
('mcq', 5, 'بحسب نموذج طومسون، كيف توقع رذرفورد أن تسلك جسيمات ألفا عند مرورها بصفيحة الذهب؟', null, '["ترتد نصفها إلى الخلف وتمر النصف الآخر","تمر معظمها وينحرف جزء قليل منها انحرافًا طفيفًا فقط","تنحرف جميعها بزوايا كبيرة","تمتصها الصفيحة جميعها"]'::jsonb, 'تطبيق', 'توقع نتيجة بناء على نموذج', 'متوسط', 'الكتاب ص 86 — تجربة رذرفورد، نموذج طومسون'),
('mcq', 6, 'ما القوة المسببة لانحراف جسيمات ألفا الموجبة بزوايا كبيرة عند اقترابها من مركز ذرة الذهب؟', null, '["تجاذب جسيمات ألفا مع الإلكترونات السالبة","تجاذب جسيمات ألفا مع النواة الموجبة","قوة الجاذبية بين جسيمات ألفا والصفيحة","تنافر جسيمات ألفا الموجبة مع النواة الموجبة"]'::jsonb, 'فهم', 'تفسير سبب الانحراف', 'صعب', 'الكتاب ص 86 — نموذج رذرفورد للذرة'),
('mcq', 7, 'لماذا استنتج رذرفورد أن نموذج طومسون للذرة غير صحيح؟', null, '["لأن النموذج لا يفسر انحراف بعض جسيمات ألفا بزوايا كبيرة وارتداد بعضها","لأن النموذج يُنكر وجود الإلكترونات في الذرة","لأن جسيمات ألفا لم تمر خلال صفيحة الذهب","لأن النموذج يفترض أن الذرة غير متعادلة كهربائيًّا"]'::jsonb, 'تحليل', 'تحليل أسباب رفض نموذج', 'صعب', 'الكتاب ص 86 — نموذج رذرفورد للذرة'),
('essay', 1, 'اشرح تجربة رذرفورد عام 1911م، موضحًا ما فعله وما لاحظه وما استنتجه من ملاحظاته.', null, null, 'فهم', 'شرح تجربة', 'متوسط', 'الكتاب ص 85، 86 — تجربة رذرفورد، النواة'),
('essay', 2, 'قارن بين ما توقعه رذرفورد من تجربته اعتمادًا على نموذج طومسون وما لاحظه فعلًا، ثم بيّن كيف فسّر الفرق بينهما.', null, null, 'تحليل', 'مقارنة توقع بنتيجة وتفسير', 'صعب', 'الكتاب ص 86 — تجربة رذرفورد، نموذج طومسون'),
('essay', 3, 'اقترح طالب أن سبب ارتداد بعض جسيمات ألفا إلى الخلف هو اصطدامها بالإلكترونات الموجودة في ذرات الذهب. قوّم هذا التفسير في ضوء تجربة رذرفورد، مبيّنًا التفسير الصحيح.', null, null, 'تقويم', 'تقويم تفسير', 'صعب', 'الكتاب ص 86 — نموذج رذرفورد للذرة')
