insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'وجّه رذرفورد شعاعًا رفيعًا من جسيمات ألفا الموجبة الشحنة نحو صفيحة رقيقة من الذهب، ثم رصد مواضع اصطدامها بالشاشة؛ فالخيار الصحيح هو جسيمات ألفا الموجبة الشحنة.', '["أشعة المهبط (الإلكترونات) استُعملت في أنابيب أشعة المهبط لاكتشاف الإلكترون، لا في تجربة صفيحة الذهب.","","لم يكن النيوترون قد اكتُشف عام 1911م، فقد أثبت شادويك وجوده عام 1932م.","لم يستعمل رذرفورد ذرات متعادلة؛ فقد احتاج إلى جسيمات مشحونة بشحنة موجبة ليرصد تأثير شحنة الذرة فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.706Z"}'::jsonb),
('mcq', 2, 3, 'تُضيء الشاشة المغلفة بكبريتيد الخارصين ومضة عند اصطدام جسيمة ألفا بها، فتُحدَّد أماكن وصول الجسيمات ومقدار انحرافها عن مسارها؛ لذا فوظيفتها إظهار الومضات الضوئية.', '["الشاشة لا تمنع الجسيمات من الخروج، وإنما تكشف أماكن اصطدامها بإصدار الضوء.","مصدر جسيمات ألفا هو المادة المشعة داخل مكعب الرصاص، وليس الشاشة.","الشاشة لا علاقة لها بتسخين الصفيحة؛ وظيفتها الكشف عن الجسيمات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.706Z"}'::jsonb),
('mcq', 3, 0, 'مرور معظم الجسيمات دون انحراف يعني أنها لم تصطدم بشيء كثيف في طريقها، أي أن الذرة تتكون غالبًا من فراغ تتحرك فيه الإلكترونات؛ فالخيار الصحيح هو أن الذرة في معظمها فراغ.', '["","هذا نموذج طومسون، وقد توقع بموجبه انحرافًا قليلًا فقط لجميع الجسيمات، ولا يفسر الانحراف الكبير والارتداد.","لو كانت الذرة كرة مصمتة لارتدت جسيمات ألفا بكثرة، لكن معظمها نفذ دون انحراف.","جسيمات ألفا تتأثر بالشحنات، وهو ما يفسر انحراف بعضها عند اقترابها من النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.707Z"}'::jsonb),
('mcq', 4, 2, 'ارتداد جسيمة ألفا السريعة الثقيلة الموجبة لا يحدث إلا عند تنافرها مع جزء كثيف موجب الشحنة تتركز فيه الكتلة؛ فاستنتج رذرفورد وجود نواة صغيرة كثيفة موجبة في مركز الذرة.', '["كتلة الإلكترون صغيرة جدًّا، ولا تستطيع أن تردّ جسيمة ألفا الثقيلة السريعة إلى الخلف.","لو كانت الشحنة موزعة بانتظام لما حدث انحراف كبير أو ارتداد، كما في نموذج طومسون.","","تعادل الذرة لا يمنع التأثير في جسيمات ألفا؛ فالنواة الموجبة تنفّر جسيمات ألفا الموجبة منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.707Z"}'::jsonb),
('mcq', 5, 1, 'في نموذج طومسون الشحنة الموجبة موزعة بانتظام والإلكترونات خفيفة، فلا يوجد ما يحرف جسيمات ألفا الثقيلة بشدة؛ لذا توقع رذرفورد مرور الجسيمات مع انحراف قليل فقط لبعضها.', '["الارتداد بنسبة كبيرة لا يتوقعه نموذج طومسون؛ فقد لوحظ ارتداد عدد قليل جدًّا فقط، وهذا مخالف للتوقع.","","الانحراف بزوايا كبيرة لم يكن متوقعًا في نموذج طومسون، بل لوحظ لنسبة قليلة من الجسيمات وفاجأ رذرفورد.","لا يوجد في نموذج طومسون ما يجعل الصفيحة تمتص جسيمات ألفا جميعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.707Z"}'::jsonb),
('mcq', 6, 3, 'جسيمات ألفا موجبة والنواة موجبة، والشحنتان المتشابهتان تتنافران؛ فتعمل قوة التنافر على انحراف جسيمات ألفا بزوايا كبيرة عند مرورها قرب النواة.', '["الإلكترونات خفيفة جدًّا، فتأثيرها في جسيمات ألفا الثقيلة ضئيل ولا يسبب انحرافًا بزوايا كبيرة.","النواة موجبة وجسيمات ألفا موجبة، والشحنات المتشابهة تتنافر ولا تتجاذب.","ليست الجاذبية هي المسؤولة؛ فالانحراف الكبير ناتج عن قوة كهربائية بين شحنتين موجبتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.707Z"}'::jsonb),
('mcq', 7, 0, 'نموذج طومسون يتوقع انحرافًا قليلًا فقط، بينما انحرفت نسبة قليلة من الجسيمات بزوايا كبيرة وارتد عدد قليل جدًّا إلى الخلف؛ ولأن النموذج لم يفسر نتائج التجربة عُدّ غير صحيح.', '["","نموذج طومسون يتضمن إلكترونات مغروسة في كرة موجبة، ولم يكن عدم وجودها سبب رفضه.","معظم جسيمات ألفا مرت فعلًا خلال الصفيحة، وهذا لا يناقض النموذج.","نموذج طومسون يجعل الذرة متعادلة؛ فالشحنة الموجبة توازن شحنات الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.707Z"}'::jsonb),
('essay', 1, null::int, null, null, 'وجّه رذرفورد شعاعًا رفيعًا من جسيمات ألفا الموجبة الشحنة نحو صفيحة رقيقة جدًّا من الذهب، ووضع حولها شاشة مغلفة بكبريتيد الخارصين تومض عند اصطدام جسيمات ألفا بها، فتبيّن أماكن وصولها ومقدار انحرافها. لاحظ أن معظم الجسيمات مرت دون انحراف أو بانحراف قليل، وأن نسبة قليلة انحرفت بزوايا كبيرة، وأن عددًا قليلًا جدًّا ارتد إلى الخلف. استنتج أن الذرة في معظمها فراغ تتحرك فيه الإلكترونات، وأن معظم الشحنة الموجبة وكتلة الذرة متركزة في مركزها داخل نواة صغيرة كثيفة موجبة الشحنة، تنفّر جسيمات ألفا الموجبة عند اقترابها منها.', '["توجيه شعاع من جسيمات ألفا الموجبة نحو صفيحة ذهب رقيقة وشاشة كبريتيد الخارصين تومض عند الاصطدام","معظم الجسيمات مرت دون انحراف أو بانحراف قليل","نسبة قليلة انحرفت بزوايا كبيرة وعدد قليل جدًّا ارتد إلى الخلف","الذرة في معظمها فراغ","الشحنة الموجبة ومعظم الكتلة متركزتان في نواة صغيرة كثيفة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف ما فعله رذرفورد (جسيمات ألفا وصفيحة الذهب والشاشة)","marks":1},{"element":"ذكر الملاحظات الثلاث (مرور، انحراف كبير، ارتداد)","marks":2},{"element":"استنتاج أن الذرة في معظمها فراغ","marks":1},{"element":"استنتاج وجود نواة صغيرة كثيفة موجبة تتركز فيها الكتلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف التجربة والملاحظات الثلاث والاستنتاجين (الفراغ والنواة) بصورة صحيحة"},{"level":"3–4 درجات","description":"وصف التجربة والملاحظات مع استنتاج واحد صحيح أو نقص في الملاحظات"},{"level":"1–2 درجة","description":"ذكر عناصر التجربة أو ملاحظة واحدة فقط دون استنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن رذرفورد استعمل أشعة المهبط أو الإلكترونات بدلًا من جسيمات ألفا","ذكر الملاحظات دون الاستنتاج","الخلط بين استنتاج رذرفورد (النواة) واستنتاج طومسون (الإلكترون)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.707Z"}'::jsonb),
('essay', 2, null::int, null, null, 'توقع رذرفورد اعتمادًا على نموذج طومسون، حيث الشحنة الموجبة موزعة بانتظام والإلكترونات خفيفة، أن تمر جسيمات ألفا خلال الصفيحة وأن ينحرف جزء قليل منها انحرافًا طفيفًا فقط. أما ما لوحظ فعلًا فهو مرور معظمها، وانحراف نسبة قليلة بزوايا كبيرة، وارتداد عدد قليل جدًّا إلى الخلف. فسّر رذرفورد هذا الفرق بوجود نواة صغيرة كثيفة موجبة الشحنة في مركز الذرة تتركز فيها الشحنة الموجبة ومعظم الكتلة؛ فتتنافر جسيمات ألفا الموجبة معها عند مرورها قريبًا منها فتنحرف بزوايا كبيرة أو ترتد.', '["المتوقع: مرور الجسيمات مع انحراف قليل فقط","الملاحظ: انحراف بزوايا كبيرة وارتداد لعدد قليل","التفسير: وجود نواة صغيرة كثيفة موجبة الشحنة","التنافر بين جسيمات ألفا الموجبة والنواة الموجبة هو سبب الانحراف الكبير"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر المتوقع حسب نموذج طومسون","marks":1},{"element":"ذكر الملاحظ فعلًا","marks":1},{"element":"تفسير الفرق بوجود نواة كثيفة موجبة","marks":1},{"element":"ربط الانحراف الكبير بالتنافر بين شحنتين موجبتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة بين المتوقع والملاحظ مع تفسير الفرق بالنواة والتنافر"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع تفسير ناقص أو غير مكتمل"},{"level":"1 درجة","description":"ذكر المتوقع أو الملاحظ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن نموذج طومسون توقع انحرافًا كبيرًا","تفسير الانحراف بتجاذب جسيمات ألفا مع النواة","عدم ذكر دور التنافر بين الشحنتين الموجبتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.708Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفسير غير صحيح. فجسيمات ألفا سريعة وذات كتلة كبيرة، أما كتلة الإلكترون فصغيرة جدًّا، لذلك لا يستطيع الإلكترون أن يردّ جسيمة ألفا إلى الخلف، بل يسبب لها انحرافًا قليلًا في أقصى الحالات. وكذلك الإلكترونات سالبة فتجذب جسيمات ألفا ولا تنفّرها. التفسير الصحيح أن في مركز الذرة نواة صغيرة كثيفة موجبة الشحنة تحوي معظم الكتلة، فتتنافر معها جسيمات ألفا الموجبة، فتنحرف بزوايا كبيرة أو ترتد عندما تقترب منها اقترابًا شديدًا.', '["الحكم بأن التفسير غير صحيح","كتلة الإلكترون صغيرة جدًّا ولا تستطيع ردّ جسيمات ألفا الثقيلة السريعة","الإلكترونات سالبة وجسيمات ألفا موجبة فلا يحدث تنافر معها","التفسير الصحيح: التنافر مع نواة صغيرة كثيفة موجبة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على التفسير مع التعليل بصغر كتلة الإلكترون","marks":2},{"element":"ذكر أن شحنة الإلكترون سالبة فلا تنفّر ألفا الموجبة","marks":1},{"element":"ذكر التفسير الصحيح (نواة كثيفة موجبة وتنافر)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح معلل بالكتلة والشحنة مع ذكر التفسير الصحيح"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل واحد أو تفسير صحيح بلا تعليل كافٍ"},{"level":"1 درجة","description":"حكم صحيح دون تعليل ولا تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول التفسير دون مناقشة كتلة الإلكترون","القول إن النواة سالبة الشحنة","تفسير الارتداد بأن الذرة كرة مصمتة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.708Z"}'::jsonb)
