('mcq', 3, 3, 'بيّن شادويك وجود النيوترونات في النواة عام 1932م، ونال جائزة نوبل عام 1935م؛ فالإجابة الصحيحة 1932م.', '["في عام 1897م اكتشف طومسون الإلكترون باستعمال أنبوب أشعة المهبط.","في عام 1911م أجرى رذرفورد تجربة صفيحة الذهب واكتشف النواة.","في عام 1913م نشر نيلز بور نظريته عن تركيب الذرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.709Z"}'::jsonb),
('mcq', 4, 1, 'النيوترون يقع داخل النواة مع البروتونات، أما الإلكترونات فتتحرك في الفراغ المحيط بالنواة؛ لذا فالخيار الصحيح هو داخل النواة مع البروتونات.', '["الفراغ المحيط بالنواة مكان الإلكترونات وحدها، وليس النيوترونات.","","توزع الجسيمات بانتظام ينسب إلى نموذج طومسون، أما النيوترونات فمتركزة في النواة.","ليس للذرة سطح تقع عليه الجسيمات؛ والإلكترونات هي التي تتحرك حول النواة، أما النيوترون فداخلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.709Z"}'::jsonb),
('mcq', 5, 2, 'يُرمز للنيوترون بالرمز n، وهو لا يحمل شحنة كهربائية أي أن شحنته صفر؛ فالخيار الصحيح هو الرمز n وشحنته صفر.', '["الرمز p وشحنة +1 هما رمز البروتون وشحنته.","الرمز e⁻ وشحنة −1 هما رمز الإلكترون وشحنته.","","الرمز n صحيح للنيوترون، لكن شحنته صفر وليست +1؛ فشحنة +1 للبروتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.709Z"}'::jsonb),
('mcq', 6, 0, 'حصل شادويك عام 1935م على جائزة نوبل في الفيزياء لإثباته وجود النيوترون؛ فالإجابة الصحيحة الفيزياء.', '["","لم تكن جائزته في الكيمياء، بل في الفيزياء.","جائزة الطب لا علاقة لها باكتشاف جسيمات الذرة، وقد نال شادويك جائزة الفيزياء.","جائزة السلام لا علاقة لها بهذا الاكتشاف العلمي؛ فقد نال شادويك جائزة الفيزياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.709Z"}'::jsonb),
('mcq', 7, 3, 'النيوترون جسيم لا يحمل شحنة، يقع في النواة، وكتلته (1.675×10⁻²⁴ g) قريبة من كتلة البروتون (1.673×10⁻²⁴ g)؛ فالخيار الصحيح هو الجسيم المتعادل في النواة الذي كتلته قريبة من كتلة البروتون.', '["هذا وصف البروتون في شحنته؛ أما النيوترون فلا يحمل شحنة.","هذا خلط بين النيوترون والإلكترون؛ فالإلكترون سالب يتحرك حول النواة لكن كتلته أصغر كثيرًا.","الجسيم الذي كتلته أصغر كثيرًا من كتلة البروتون هو الإلكترون، والنيوترون يقع في النواة لا حولها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.709Z"}'::jsonb),
('essay', 1, null::int, null, null, 'بيّن العالم جيمس شادويك عام 1932م أن النواة تحتوي على جسيمات متعادلة سُميت النيوترونات. شحنة النيوترون صفر فهو لا يحمل شحنة كهربائية، وموقعه في نواة الذرة مع البروتونات، ويُرمز له بالرمز n، وكتلته قريبة من كتلة البروتون.', '["العالم جيمس شادويك","عام 1932م","شحنة النيوترون صفر (متعادل)","موقعه في النواة","رمزه n"]'::jsonb, '[]'::jsonb, '[{"element":"اسم العالم جيمس شادويك","marks":1},{"element":"عام الاكتشاف 1932م","marks":1},{"element":"شحنة النيوترون صفر","marks":1},{"element":"موقعه في النواة","marks":1},{"element":"رمزه n","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ذكر العالم والعام والشحنة والموقع والرمز كلها بصورة صحيحة"},{"level":"3–4 درجات","description":"ذكر ثلاثة أو أربعة عناصر صحيحة"},{"level":"1–2 درجة","description":"ذكر عنصر واحد أو اثنين صحيحين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة اكتشاف النيوترون إلى طومسون أو رذرفورد","القول إن النيوترون يحمل شحنة موجبة صغيرة","وضع النيوترون في الفراغ المحيط بالنواة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.709Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الشحنة النسبية للبروتون +1 وللنيوترون صفر. شحنة النواة = (6 × +1) + (6 × 0) = +6. النيوترونات لا تحمل شحنة، لذلك لا تسهم في شحنة النواة، وتتحدد شحنة النواة بعدد البروتونات فقط؛ فلو أُضيف نيوترون آخر لبقيت الشحنة +6.', '["شحنة البروتون +1 وشحنة النيوترون صفر","شحنة النواة = +6","النيوترونات لا تسهم في شحنة النواة"]'::jsonb, '["شحنة البروتون +1 وشحنة النيوترون صفر","شحنة البروتونات = 6 × (+1) = +6","شحنة النيوترونات = 6 × 0 = صفر","شحنة النواة = (+6) + 0 = +6","وجود النيوترونات لا يغير شحنة النواة لأنها متعادلة"]'::jsonb, '[{"element":"ذكر الشحنة النسبية للبروتون والنيوترون","marks":1},{"element":"حساب شحنة النواة = +6","marks":2},{"element":"توضيح أن النيوترونات لا تؤثر في الشحنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعويض صحيح وحساب الشحنة +6 وتوضيح أثر النيوترونات"},{"level":"2–3 درجات","description":"حساب صحيح دون توضيح الأثر، أو توضيح صحيح مع خطأ في الحساب"},{"level":"1 درجة","description":"ذكر شحنة البروتون والنيوترون فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع عدد البروتونات والنيوترونات للحصول على الشحنة (+12)","عدّ شحنة النيوترون +1","كتابة شحنة النواة صفر بسبب وجود جسيمات متعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.709Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجسيم Y هو النيوترون؛ لأنه الوحيد الذي شحنته صفر (متعادل)، ولأنه يقع في النواة وكتلته قريبة من كتلة البروتون (X). أما X فشحنته +1 فهو البروتون، وZ شحنته −1 وكتلته صغيرة جدًّا ويقع حول النواة فهو الإلكترون. والعالم الذي أثبت وجود النيوترون هو جيمس شادويك عام 1932م.', '["تحديد Y على أنه النيوترون","التعليل بالشحنة صفر","التعليل بموقعه في النواة وكتلته القريبة من كتلة البروتون","تمييز X بروتونًا وZ إلكترونًا","العالم جيمس شادويك"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد Y نيوترونًا","marks":1},{"element":"التعليل بالشحنة صفر وبالموقع والكتلة","marks":2},{"element":"تمييز X وZ","marks":1},{"element":"ذكر جيمس شادويك","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح مع تعليل كامل وتمييز الجسيمين الآخرين وذكر شادويك"},{"level":"3–4 درجات","description":"تحديد صحيح مع تعليل جزئي أو نقص في العناصر الأخرى"},{"level":"1–2 درجة","description":"تحديد صحيح دون تعليل، أو ذكر شادويك فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار X بسبب تقارب كتلته من كتلة Y","نسبة الاكتشاف إلى طومسون أو رذرفورد","التعليل بالموقع فقط دون الشحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.710Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
