('mcq', 5, 'وجد العلماء أن تغيير فلز القطبين أو تغيير الغاز داخل الأنبوب لا يؤثر في أشعة المهبط الناتجة. ماذا استنتجوا من ذلك؟', null, '["أن الأشعة تنشأ من الغاز الموجود في الأنبوب وحده","أن الأشعة تتغير شحنتها بتغير نوع الغاز","أن الأشعة خاصة بفلز المهبط المستعمل فقط","أن جسيماتها السالبة موجودة في جميع أشكال المادة"]'::jsonb, 'فهم', 'استنتاج من نتائج تجارب', 'صعب', 'الكتاب ص 82 — أنبوب أشعة المهبط'),
('mcq', 6, 'مرّ شعاع من أشعة المهبط بين قطبي مغناطيس فانحرف عن مساره المستقيم. ما الذي يدل عليه انحرافه؟', null, '["أن الشعاع يتكون من جسيمات متعادلة","أن الشعاع يتكون من جسيمات مشحونة","أن الشعاع موجات ضوئية عديمة الكتلة","أن الغاز داخل الأنبوب هو الذي انحرف"]'::jsonb, 'تطبيق', 'تطبيق على موقف تجريبي', 'متوسط', 'الكتاب ص 82 — أنبوب أشعة المهبط'),
('mcq', 7, 'أجرى طالب تجربة بأنبوب أشعة مهبط قطباه من النحاس ويحتوي على غاز الهيدروجين، ثم كرر التجربة بقطبين من الحديد وغاز النيون. ماذا يتوقع أن يلاحظ؟', null, '["تتحول الأشعة إلى جسيمات موجبة الشحنة","تتغير شحنة الأشعة بحسب فلز القطبين","تبقى خصائص الأشعة وسلوكها كما هي في التجربتين","تتوقف الأشعة عن الظهور عند تغيير الغاز"]'::jsonb, 'تطبيق', 'توقع نتيجة تجربة', 'صعب', 'الكتاب ص 82 — أنبوب أشعة المهبط'),
