from (values
('mcq', 1, 3, 'أشعة المهبط سيل من جسيمات مشحونة بشحنة سالبة تسير من المهبط إلى المصعد داخل أنبوب مفرغ؛ فالخيار الصحيح هو سيل الجسيمات السالبة الشحنة.', '["الجسيمات موجبة الشحنة لا تنحرف نحو الصفيحة الموجبة، بينما تنحرف أشعة المهبط نحوها لأنها سالبة.","أشعة المهبط جسيمات مشحونة تنحرف في المجالين المغناطيسي والكهربائي، وليست موجات ضوئية غير مشحونة.","الجسيمات المتعادلة لا تنحرف في المجال المغناطيسي أو الكهربائي، لكن أشعة المهبط تنحرف فيهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.710Z"}'::jsonb),
('mcq', 2, 1, 'سُميت الأشعة بأشعة المهبط لأنها تخرج من المهبط (الكاثود) المتصل بالطرف السالب للبطارية وتسير إلى المصعد (الأنود)؛ فالاتجاه الصحيح من المهبط إلى المصعد.', '["هذا عكس الاتجاه الصحيح؛ فالأشعة تخرج من المهبط ولا تتجه نحوه.","","الجسيمات تسير في مسار محدد من القطب السالب إلى القطب الموجب، وليس بصورة عشوائية.","الجسيمات تتحرك ولا تبقى ساكنة؛ فهي تسير من المهبط نحو المصعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:27:04.710Z"}'::jsonb),
('mcq', 3, 2, 'تنحرف أشعة المهبط نحو الصفيحة الموجبة لأن جسيماتها سالبة الشحنة، والشحنات المختلفة تتجاذب؛ فالإجابة الصحيحة نحو الصفيحة الموجبة.', '["الانحراف نحو الصفيحة السالبة يعني أن الجسيمات موجبة، لكن جسيمات أشعة المهبط سالبة.","الأشعة تنحرف في المجال الكهربائي لأن جسيماتها مشحونة، ولو لم تنحرف لكانت متعادلة.","","الجسيمات كلها سالبة، فلا تنقسم بين الصفيحتين بل تنحرف جميعها نحو الموجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.711Z"}'::jsonb),
('mcq', 4, 0, 'عُرفت الجسيمات السالبة الشحنة المكوِّنة لأشعة المهبط بالإلكترونات، ويُرمز لها بالرمز e⁻؛ لذا فالخيار الأول صحيح.', '["","البروتونات جسيمات موجبة توجد في النواة، ولا تتكون منها أشعة المهبط السالبة.","النيوترونات جسيمات متعادلة، بينما جسيمات أشعة المهبط مشحونة بشحنة سالبة.","الاسم صحيح، لكن الرمز p هو رمز البروتون؛ ورمز الإلكترون e⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:27:04.711Z"}'::jsonb),
('mcq', 5, 3, 'بقاء خصائص الأشعة ثابتة مهما اختلف فلز القطبين أو الغاز يدل على أن الجسيمات السالبة المكونة لها ليست خاصة بمادة بعينها، بل موجودة في جميع أشكال المادة؛ وهي الإلكترونات.', '["لو كان مصدرها الغاز فقط لتغيرت الأشعة بتغير الغاز، لكنها لم تتغير.","لم تتغير الأشعة بتغير الغاز؛ فشحنتها وسلوكها ثابتان.","لو كانت خاصة بفلز المهبط لتغيرت بتغيير الفلز، لكنها لم تتغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.711Z"}'::jsonb),
('mcq', 6, 1, 'الجسيمات المتعادلة لا تتأثر بالمجال المغناطيسي، أما انحراف الشعاع فيه فيدل على أن جسيماته مشحونة؛ فالخيار الصحيح أن الشعاع يتكون من جسيمات مشحونة.', '["لو كانت الجسيمات متعادلة لما انحرفت في المجال المغناطيسي.","","الانحراف في المجال المغناطيسي يدل على جسيمات مشحونة، وليس على موجات ضوئية.","الغاز داخل الأنبوب مفرغ في معظمه، والمنحرف هو الشعاع الصادر من المهبط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.711Z"}'::jsonb),
('mcq', 7, 2, 'لا يتغير سلوك أشعة المهبط بتغير فلز القطبين أو الغاز في الأنبوب، فتبقى سالبة الشحنة وتنحرف نحو الصفيحة الموجبة في الحالتين؛ لذا فالتوقع الصحيح أن تبقى خصائصها كما هي.', '["أشعة المهبط تبقى سالبة الشحنة دائمًا ولا تتحول إلى موجبة.","شحنة الأشعة لا تتأثر بنوع الفلز؛ فهي سالبة مهما تغير فلز القطبين.","","تغيير الغاز لا يوقف الأشعة ولا يؤثر فيها؛ فالجسيمات المكونة لها موجودة في جميع المواد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.711Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أشعة المهبط سيل من الجسيمات المشحونة بشحنة سالبة تسير داخل أنبوب مفرغ من المهبط (الكاثود) إلى المصعد (الأنود). تنحرف عند مرورها في المجال المغناطيسي، وتنحرف في المجال الكهربائي نحو الصفيحة الموجبة. وعُرفت جسيماتها بالإلكترونات ويُرمز لها بالرمز e⁻.', '["سيل من جسيمات مشحونة","الشحنة سالبة","تسير من المهبط إلى المصعد داخل أنبوب مفرغ","تنحرف في المجال المغناطيسي","تنحرف نحو الصفيحة الموجبة في المجال الكهربائي"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أنها سيل من جسيمات مشحونة سالبة","marks":1},{"element":"اتجاه سيرها من المهبط إلى المصعد","marks":1},{"element":"انحرافها في المجال المغناطيسي","marks":1},{"element":"انحرافها نحو الصفيحة الموجبة في المجال الكهربائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر الطبيعة والشحنة والاتجاه والسلوك في المجالين بصورة صحيحة"},{"level":"2–3 درجات","description":"ذكر ثلاث خصائص أو اثنتين صحيحتين"},{"level":"1 درجة","description":"ذكر خاصية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن أشعة المهبط موجبة الشحنة","عكس اتجاه السير من المصعد إلى المهبط","القول إن الأشعة تنحرف نحو الصفيحة السالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.711Z"}'::jsonb),
('essay', 2, null::int, null, null, 'انحرفت الأشعة عند مرورها في المجال المغناطيسي، وهذا يدل على أن جسيماتها مشحونة. وانحرفت في المجال الكهربائي نحو الصفيحة الموجبة، وهذا يدل على أن شحنتها سالبة لأن الشحنات المختلفة تتجاذب. ولما لم يؤثر تغيير فلز القطبين ولا تغيير الغاز في الأنبوب في الأشعة الناتجة، استنتجوا أن هذه الجسيمات السالبة (الإلكترونات) ليست خاصة بمادة معينة، بل موجودة في جميع أشكال المادة.', '["الانحراف في المجال المغناطيسي يدل على أن الجسيمات مشحونة","الانحراف نحو الصفيحة الموجبة يدل على أن الشحنة سالبة","عدم تأثر الأشعة بتغيير فلز القطبين أو الغاز","الاستنتاج: الإلكترونات موجودة في جميع أشكال المادة"]'::jsonb, '[]'::jsonb, '[{"element":"الانحراف في المجال المغناطيسي دليل على الشحنة","marks":1},{"element":"الانحراف نحو الصفيحة الموجبة دليل على الشحنة السالبة","marks":1},{"element":"عدم تأثر الأشعة بتغيير الفلز أو الغاز","marks":1},{"element":"الاستنتاج أن الإلكترونات موجودة في جميع المواد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ربط كل ملاحظة بالاستنتاج الصحيح المناسب لها"},{"level":"2–3 درجات","description":"ذكر ملاحظات صحيحة مع ربط ناقص بالاستنتاجات"},{"level":"1 درجة","description":"ذكر ملاحظة واحدة دون استنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الاستنتاج دون الاستناد إلى الملاحظة","الخلط بين دلالة الانحراف المغناطيسي (شحنة) والكهربائي (نوع الشحنة)","نسبة وجود الجسيمات إلى الفلز المستعمل وحده"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.711Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تدعم النتائج استنتاجين: الأول أن جسيمات الأشعة سالبة الشحنة، لأنها انحرفت في الحالات كلها نحو الصفيحة الموجبة، والشحنات المختلفة تتجاذب. والثاني أن الأشعة لا تتغير بتغير فلز القطبين (نحاس أو حديد) ولا بتغير الغاز (نيون أو هيدروجين)، فجسيماتها ليست خاصة بفلز أو غاز معين، بل هي الإلكترونات الموجودة في جميع أشكال المادة.', '["الجسيمات سالبة الشحنة لانحرافها نحو الصفيحة الموجبة","السلوك واحد رغم تغير الفلز","السلوك واحد رغم تغير الغاز","الجسيمات هي الإلكترونات الموجودة في جميع أشكال المادة"]'::jsonb, '[]'::jsonb, '[{"element":"استنتاج أن الشحنة سالبة مع التعليل بالانحراف نحو الموجبة","marks":1},{"element":"ملاحظة عدم تأثر الأشعة بتغير الفلز","marks":1},{"element":"ملاحظة عدم تأثر الأشعة بتغير الغاز","marks":1},{"element":"استنتاج أن الإلكترونات موجودة في جميع المواد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"استنتاج الشحنة السالبة وعدم الاعتماد على الفلز والغاز ووجود الإلكترونات في كل المواد مع التعليل"},{"level":"2–3 درجات","description":"استنتاج صحيح واحد مع تعليل، أو استنتاجان بتعليل ناقص"},{"level":"1 درجة","description":"ذكر نتيجة واحدة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الانحراف نحو الموجبة يدل على أن الجسيمات موجبة","الاكتفاء بذكر الشحنة دون الاستنتاج الثاني","القول إن الغاز مصدر الجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.712Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
