('mcq', 3, 'تحتوي ذرة متعادلة على 6 بروتونات و6 نيوترونات و6 إلكترونات. ما شحنة نواتها؟', null, '["صفر","+6","+12","−6"]'::jsonb, 'فهم', 'حساب شحنة النواة', 'متوسط', 'الكتاب ص 86، 88 — نموذج رذرفورد، إكمال نموذج الذرة'),
('mcq', 4, 'ذرة تحتوي على 8 بروتونات و8 إلكترونات و10 نيوترونات. ما شحنتها الكلية؟', null, '["شحنتها +8","شحنتها +18","شحنتها −8","شحنتها صفر"]'::jsonb, 'تحليل', 'حساب الشحنة الكلية', 'متوسط', 'الكتاب ص 88 — إكمال نموذج الذرة'),
('mcq', 5, 'لماذا لا يؤدي وجود النيوترونات في نواة الذرة إلى اختلال تعادلها الكهربائي؟', null, '["لأن النيوترونات لا تحمل شحنة فلا تغير مجموع الشحنات","لأن النيوترونات تحمل شحنة سالبة تعادل شحنة البروتونات","لأن النيوترونات تحمل شحنة موجبة صغيرة جدًّا","لأن النيوترونات تقع خارج النواة بعيدًا عن البروتونات"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 87، 88 — النيوترون، إكمال نموذج الذرة'),
('mcq', 6, 'قال طالب: «الذرة متعادلة لأن عدد بروتوناتها يساوي عدد نيوتروناتها». أيّ التقويمات الآتية لقوله صحيح؟', null, '["صحيح، لأن النيوترون يلغي شحنة البروتون","صحيح، لأن النواة وحدها متعادلة كهربائيًّا","غير صحيح، فالتعادل سببه تساوي عدد البروتونات وعدد الإلكترونات","غير صحيح، فالتعادل سببه تساوي عدد النيوترونات وعدد الإلكترونات"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 88 — إكمال نموذج الذرة'),
('mcq', 7, 'لا نتعرض لصعقة كهربائية عند لمس الأجسام العادية. ما التفسير المناسب لذلك؟', null, '["لأن المادة لا تحتوي على إلكترونات","لأن المادة مكونة من ذرات متعادلة تتساوى فيها الشحنات الموجبة والسالبة","لأن المادة تحتوي على شحنات موجبة فقط","لأن الإلكترونات في المادة ساكنة لا تتحرك"]'::jsonb, 'فهم', 'ربط بظاهرة', 'صعب', 'الكتاب ص 84 — نموذج طومسون'),
('essay', 1, 'فسّر لماذا تكون الذرة متعادلة كهربائيًّا على الرغم من احتوائها على جسيمات مشحونة.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 86، 88 — نموذج رذرفورد، إكمال نموذج الذرة'),
('essay', 2, 'ذرة متعادلة تحتوي نواتها على 17 بروتونًا و18 نيوترونًا. احسب عدد الإلكترونات فيها، وشحنة نواتها، وشحنة الذرة الكلية، مستعملًا الشحنات النسبية للجسيمات.', null, null, 'تطبيق', 'حساب الشحنات', 'متوسط', 'الكتاب ص 88 — إكمال نموذج الذرة'),
('essay', 3, 'قارن بين نموذج طومسون ونموذج رذرفورد في تفسير تعادل الذرة كهربائيًّا، مبيّنًا كيف تتوزع الشحنتان الموجبة والسالبة في كل منهما.', null, null, 'تحليل', 'مقارنة نموذجين', 'صعب', 'الكتاب ص 84، 86 — نموذج طومسون، نموذج رذرفورد')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
