select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الذرة متعادلة لأن عدد البروتونات الموجبة في النواة يساوي عدد الإلكترونات السالبة المحيطة بها، فتلغي الشحنات الموجبة الشحنات السالبة؛ فالخيار الأول هو الصحيح.', '["","الذرة تحتوي جسيمات مشحونة (البروتونات والإلكترونات)، لكن شحناتها متساوية ومتعاكسة فتتعادل.","عدد البروتونات لا يساوي بالضرورة عدد النيوترونات، والتعادل لا علاقة له بالنيوترونات.","النيوترونات لا تحمل شحنة، فلا تلغي شحنة الإلكترونات؛ وإنما تلغيها شحنة البروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.712Z"}'::jsonb),
('mcq', 2, 2, 'تتعادل الذرة عندما يساوي عدد الإلكترونات عدد البروتونات؛ وبما أن في النواة 11 بروتونًا فإن عدد الإلكترونات 11 إلكترونًا.', '["هذا عدد النيوترونات، والنيوترونات لا تحمل شحنة فلا تحدد عدد الإلكترونات.","هذا مجموع البروتونات والنيوترونات (11 + 12)، والنيوترونات متعادلة فلا تُحسب.","","هذا ضعف عدد البروتونات، فسيعطي شحنة سالبة زائدة وتفقد الذرة تعادلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.712Z"}'::jsonb),
('mcq', 3, 1, 'النواة تضم البروتونات الموجبة والنيوترونات المتعادلة، فشحنتها = 6 × (+1) + 6 × 0 = +6؛ أما الذرة ككل فشحنتها صفر بسبب الإلكترونات الستة السالبة.', '["صفر هي شحنة الذرة كاملة، أما النواة وحدها فموجبة لأنها لا تضم الإلكترونات.","","+12 ناتجة عن عدّ النيوترونات موجبة، لكن النيوترونات لا تحمل شحنة.","−6 هي شحنة الإلكترونات وحدها، وليست شحنة النواة التي تضم البروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:27:04.712Z"}'::jsonb),
('mcq', 4, 3, 'الشحنة الكلية = 8 × (+1) + 8 × (−1) + 10 × 0 = صفر؛ فالشحنة الموجبة للبروتونات تساوي الشحنة السالبة للإلكترونات، والذرة متعادلة.', '["هذه شحنة البروتونات وحدها، مع إهمال الإلكترونات السالبة.","حُسبت فيها البروتونات والنيوترونات موجبة وأُهملت الإلكترونات، والنيوترونات لا تحمل شحنة.","هذه شحنة الإلكترونات وحدها، مع إهمال البروتونات الموجبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:27:04.713Z"}'::jsonb),
('mcq', 5, 0, 'النيوترونات جسيمات متعادلة شحنتها صفر، فلا تضيف شحنة موجبة ولا سالبة؛ لذلك يبقى تعادل الذرة محددًا بتساوي عدد البروتونات والإلكترونات.', '["","الشحنة السالبة هي شحنة الإلكترونات؛ أما النيوترونات فلا تحمل شحنة.","النيوترونات لا تحمل أي شحنة، لا كبيرة ولا صغيرة.","النيوترونات تقع داخل النواة مع البروتونات، وليست خارجها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.713Z"}'::jsonb),
('mcq', 6, 2, 'قول الطالب خاطئ؛ فالنيوترونات لا تحمل شحنة، والتعادل ينتج عن تساوي عدد البروتونات الموجبة وعدد الإلكترونات السالبة، فتلغي كل شحنة موجبة شحنة سالبة.', '["النيوترون لا يحمل شحنة فلا يلغي شحنة البروتون؛ إنما يلغيها الإلكترون.","النواة موجبة الشحنة لاحتوائها البروتونات، وليست متعادلة.","","النيوترونات لا تحمل شحنة، فلا يؤثر عددها في التعادل مقارنة بعدد الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.713Z"}'::jsonb),
('mcq', 7, 1, 'المادة متعادلة كهربائيًّا لأن ذراتها متعادلة، إذ تساوي شحنة البروتونات الموجبة شحنة الإلكترونات السالبة؛ لذلك لا نشعر بصعقة عند لمسها.', '["الإلكترونات موجودة في جميع المواد، وقد دلّت على ذلك تجارب أشعة المهبط.","","لو كانت المادة تحتوي شحنات موجبة فقط لكانت مشحونة، لكنها تحتوي أيضًا الإلكترونات السالبة المعادلة لها.","الإلكترونات سريعة الحركة في الفراغ المحيط بالنواة، وليست ساكنة؛ وسبب التعادل تساوي الشحنات لا سكون الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.713Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تحتوي نواة الذرة على بروتونات موجبة الشحنة (+1 لكل بروتون)، وتحيط بها إلكترونات سالبة الشحنة (−1 لكل إلكترون). وفي الذرة المتعادلة يساوي عدد البروتونات عدد الإلكترونات، فيكون مجموع الشحنات الموجبة مساويًا في المقدار لمجموع الشحنات السالبة، فيلغي كل منهما الآخر وتكون الشحنة الكلية للذرة صفرًا. أما النيوترونات فلا تحمل شحنة فلا تؤثر في ذلك.', '["البروتونات موجبة في النواة والإلكترونات سالبة حولها","عدد البروتونات يساوي عدد الإلكترونات","الشحنات الموجبة والسالبة متساوية المقدار فتلغي إحداها الأخرى","الشحنة الكلية للذرة صفر","النيوترونات لا تحمل شحنة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الجسيمات المشحونة وشحنة كل منها وموقعه","marks":1},{"element":"تساوي عدد البروتونات وعدد الإلكترونات","marks":1},{"element":"إلغاء الشحنات الموجبة والسالبة وكون الشحنة الكلية صفرًا","marks":1},{"element":"ذكر أن النيوترونات لا تؤثر في التعادل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط تساوي العددين وإلغاء الشحنات والدور المحايد للنيوترونات"},{"level":"2–3 درجات","description":"ذكر تساوي عدد البروتونات والإلكترونات مع نقص في التفسير"},{"level":"1 درجة","description":"ذكر أن الذرة تحتوي شحنات موجبة وسالبة دون ربط بالتساوي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرة لا تحتوي جسيمات مشحونة","نسب التعادل إلى النيوترونات","الخلط بين تعادل الذرة وتعادل النواة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.714Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الذرة متعادلة، فعدد الإلكترونات يساوي عدد البروتونات = 17 إلكترونًا. شحنة النواة = 17 × (+1) + 18 × 0 = +17. شحنة الذرة الكلية = (+17) + 17 × (−1) = صفر.', '["عدد الإلكترونات = عدد البروتونات = 17","شحنة النواة = +17","الشحنة الكلية = صفر"]'::jsonb, '["الذرة متعادلة، إذن عدد الإلكترونات = عدد البروتونات = 17 إلكترونًا","شحنة النواة = 17 × (+1) + 18 × 0 = +17","شحنة الإلكترونات = 17 × (−1) = −17","الشحنة الكلية = (+17) + (−17) = صفر"]'::jsonb, '[{"element":"عدد الإلكترونات = 17","marks":1},{"element":"شحنة النواة = +17 مع إهمال النيوترونات","marks":2},{"element":"الشحنة الكلية = صفر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب العدد والشحنتين حسابًا صحيحًا مع خطوات واضحة"},{"level":"2–3 درجات","description":"خطأ في شحنة النواة أو الخطوات مع صحة الباقي"},{"level":"1 درجة","description":"حساب عدد الإلكترونات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ النيوترونات في شحنة النواة (+35)","جعل عدد الإلكترونات 18 أو 35","كتابة شحنة النواة صفرًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.714Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في نموذج طومسون الذرة كرة موجبة الشحنة موزعة بانتظام تنغرس فيها إلكترونات سالبة، وتتعادل الذرة لأن الشحنة الموجبة الكلية تساوي مجموع شحنات الإلكترونات. وفي نموذج رذرفورد تتركز الشحنة الموجبة في نواة صغيرة كثيفة، وتحيط بها الإلكترونات السالبة في الفراغ، وتتعادل الذرة لأن شحنة النواة الموجبة (عدد البروتونات) تعادل الشحنة السالبة لإلكترونات الذرة. فالنموذجان يتفقان على التعادل بتساوي الشحنتين، ويختلفان في توزيع الشحنة الموجبة (منتظمة أم متركزة في النواة).', '["طومسون: شحنة موجبة موزعة بانتظام والإلكترونات مغروسة فيها","رذرفورد: شحنة موجبة متركزة في نواة والإلكترونات حولها","في كلا النموذجين الشحنة الموجبة تساوي الشحنة السالبة فتتعادل الذرة","الاختلاف في توزيع الشحنة الموجبة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف توزيع الشحنات في نموذج طومسون","marks":1},{"element":"وصف توزيع الشحنات في نموذج رذرفورد","marks":1},{"element":"تفسير التعادل بتساوي الشحنتين في النموذجين","marks":1},{"element":"تحديد وجه الاختلاف بين النموذجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة للنموذجين مع تفسير التعادل ووجه الاختلاف"},{"level":"2–3 درجات","description":"وصف صحيح لنموذج واحد مع تفسير التعادل، أو مقارنة ناقصة"},{"level":"1 درجة","description":"ذكر عبارة عامة عن تعادل الذرة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن نموذج طومسون لا يفسر التعادل","وصف نواة موجبة في نموذج طومسون","الخلط بين الإلكترونات والبروتونات في موقعيهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.714Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
