('mcq', 1, 1, 'الشحنة النسبية للبروتون +1، وهي مساوية في المقدار لشحنة الإلكترون لكنها موجبة؛ فالخيار الصحيح +1.', '["−1 هي الشحنة النسبية للإلكترون.","","صفر هي الشحنة النسبية للنيوترون.","لا يحمل البروتون شحنة +2؛ فشحنته تساوي شحنة الإلكترون في المقدار (+1)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.715Z"}'::jsonb),
('mcq', 2, 0, 'كتلة الإلكترون 9.11×10⁻²⁸ g وكتلة البروتون 1.673×10⁻²⁴ g وكتلة النيوترون 1.675×10⁻²⁴ g؛ فالترتيب التصاعدي إلكترون ثم بروتون ثم نيوترون.', '["","هذا الترتيب تنازلي وليس تصاعديًّا.","كتلة النيوترون (1.675×10⁻²⁴ g) أكبر قليلًا من كتلة البروتون (1.673×10⁻²⁴ g)، فلا يسبقه.","كتلة الإلكترون أصغر كثيرًا من كتلة البروتون، فلا يأتي بعده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.715Z"}'::jsonb),
('mcq', 3, 3, 'الجسيم X شحنته +1 ويقع في النواة فهو البروتون، والجسيم Y شحنته صفر ويقع في النواة فهو النيوترون، والجسيم Z شحنته −1 وكتلته 1/1840 ويقع حول النواة فهو الإلكترون؛ فالخيار الأخير صحيح.', '["هذا يعكس تحديد X وY؛ فالنيوترون شحنته صفر والبروتون شحنته +1.","الإلكترون شحنته −1 وكتلته صغيرة وموقعه خارج النواة، وليس X.","الجسيم Y شحنته صفر فهو ليس الإلكترون، والجسيم Z سالب فهو ليس البروتون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.715Z"}'::jsonb),
('mcq', 4, 2, 'كتلة كل من البروتون والنيوترون النسبية 1 ويقع كلاهما في النواة؛ أما الإلكترون فكتلته النسبية 1/1840 ويقع في الفراغ المحيط بالنواة، فالزوج الصحيح البروتون والنيوترون.', '["كتلة الإلكترون النسبية 1/1840 وموقعه خارج النواة، بينما البروتون كتلته النسبية 1 وموقعه النواة.","الإلكترون يختلف عن النيوترون في الكتلة النسبية وفي الموقع.","","البروتون والنيوترون متساويان في الكتلة النسبية (1) ويقعان معًا في النواة، فهذا الخيار غير صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.716Z"}'::jsonb),
('mcq', 5, 1, 'النسبة = (1.673×10⁻²⁴ g) ÷ (9.11×10⁻²⁸ g) = 1.84×10³ ≈ 1840 مرة، وهذا يتفق مع الكتلة النسبية للإلكترون 1/1840.', '["ناتجة عن خطأ في الأس بمقدار واحد عند القسمة، فتخرج النتيجة أصغر بعشر مرات من الصحيحة.","","ناتجة عن خطأ في الأسس يعطي نتيجة أكبر بعشر مرات.","ناتجة عن قسمة كتلة الإلكترون على كتلة البروتون، أي عكس النسبة المطلوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-18T03:27:04.716Z"}'::jsonb),
('mcq', 6, 3, 'شحنة النواة = 3 × (+1) + 4 × 0 = +3. وكتلة الإلكترونات الثلاثة 2.733×10⁻²⁷ g لا تشكل سوى حوالي 0.023% من كتلة الذرة، فمعظم الكتلة في النواة؛ لذا فالخيار الأخير هو الصحيح.', '["+7 ناتجة عن عدّ النيوترونات شحنة موجبة، لكن النيوترونات متعادلة.","الإلكترونات كتلتها صغيرة جدًّا (1/1840 من كتلة البروتون)، فمعظم الكتلة ليس فيها.","النواة تحتوي بروتونات موجبة، فشحنتها لا تساوي صفرًا؛ والصفر شحنة الذرة كلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.716Z"}'::jsonb),
('mcq', 7, 0, 'شحنة البروتون +1 وشحنة الإلكترون −1، فمقدار الشحنة واحد ونوعها مختلف؛ أما بقية العبارات فتخالف خصائص الجسيمات المعروفة، فالعبارة الأولى هي الصحيحة.', '["","كتلة الإلكترون النسبية 1/1840 وكتلة النيوترون النسبية 1، فهما غير متساويين.","شحنة البروتون +1 وشحنة النيوترون صفر، فهما مختلفان.","البروتون وحده في النواة، أما الإلكترون فيقع في الفراغ المحيط بالنواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.716Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الإلكترون: الرمز e⁻، شحنته النسبية −1، كتلته النسبية 1/1840، يقع في الفراغ المحيط بالنواة. البروتون: الرمز p، شحنته النسبية +1، كتلته النسبية 1، يقع في النواة. النيوترون: الرمز n، شحنته النسبية صفر، كتلته النسبية 1، يقع في النواة. فالبروتون والإلكترون متساويان في مقدار الشحنة ومختلفان في نوعها، والبروتون والنيوترون متساويان تقريبًا في الكتلة، أما كتلة الإلكترون فصغيرة جدًّا.', '["الإلكترون: e⁻ و −1 و 1/1840 وحول النواة","البروتون: p و +1 و 1 وفي النواة","النيوترون: n وصفر و 1 وفي النواة","تقارب كتلتي البروتون والنيوترون وصغر كتلة الإلكترون"]'::jsonb, '[]'::jsonb, '[{"element":"بيانات الإلكترون الأربعة","marks":2},{"element":"بيانات البروتون الأربعة","marks":2},{"element":"بيانات النيوترون الأربعة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة صحيحة للجسيمات الثلاثة في الصفات الأربع"},{"level":"4–5 درجات","description":"مقارنة صحيحة لجسيمين كاملين مع أخطاء قليلة في الثالث"},{"level":"2–3 درجات","description":"مقارنة صحيحة لجسيم واحد كاملًا أو عدة بيانات صحيحة متفرقة"},{"level":"1 درجة","description":"ذكر بيان واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ كتلة الإلكترون مساوية لكتلة البروتون","وضع الإلكترون في النواة","عدّ شحنة النيوترون +1 أو −1"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.716Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نحوّل الكتلتين إلى الصيغة نفسها: كتلة الإلكترون = 0.000911×10⁻²⁴ g. الفرق = 1.673×10⁻²⁴ − 0.000911×10⁻²⁴ = 1.672×10⁻²⁴ g. نحوّل إلى kg بالقسمة على 1000: 1.672×10⁻²⁷ kg. البروتون أكبر كتلة، ونسبة كتلته إلى كتلة الإلكترون = (1.673×10⁻²⁴) ÷ (9.11×10⁻²⁸) ≈ 1840 مرة.', '["توحيد الأسس قبل الطرح","الفرق = 1.672×10⁻²⁴ g","تحويل g إلى kg بالقسمة على 1000 ليصبح 1.672×10⁻²⁷ kg","البروتون أكبر بحوالي 1840 مرة"]'::jsonb, '["كتلة الإلكترون = 9.11×10⁻²⁸ g = 0.000911×10⁻²⁴ g","الفرق = 1.673×10⁻²⁴ g − 0.000911×10⁻²⁴ g = 1.672×10⁻²⁴ g","التحويل: 1.672×10⁻²⁴ g ÷ 1000 = 1.672×10⁻²⁷ kg","النسبة = 1.673×10⁻²⁴ ÷ 9.11×10⁻²⁸ ≈ 1.84×10³ ≈ 1840 مرة"]'::jsonb, '[{"element":"توحيد الأسس وحساب الفرق بالجرام","marks":2},{"element":"التحويل الصحيح إلى kg","marks":1},{"element":"تحديد الأكبر كتلة وحساب النسبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الفرق 1.672×10⁻²⁷ kg مع خطوات صحيحة وتحديد النسبة"},{"level":"2–3 درجات","description":"حساب الفرق بالجرام صحيحًا مع خطأ في التحويل أو غياب النسبة"},{"level":"1 درجة","description":"تحديد أن البروتون أكبر كتلة دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح الأسس بدل توحيدها (1.673 − 9.11)","الضرب في 1000 بدل القسمة عند التحويل من g إلى kg","قسمة كتلة الإلكترون على كتلة البروتون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-18T03:27:04.716Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كتلة الإلكترونات = 3 × 9.11×10⁻²⁸ = 2.733×10⁻²⁷ g. كتلة النواة = 3 × 1.673×10⁻²⁴ + 4 × 1.675×10⁻²⁴ = 1.172×10⁻²³ g. كتلة الذرة = 1.172×10⁻²³ + 2.7×10⁻²⁷ ≈ 1.172×10⁻²³ g. النسبة المئوية لكتلة الإلكترونات = (2.733×10⁻²⁷ ÷ 1.172×10⁻²³) × 100 ≈ 0.023%. إذن معظم كتلة الذرة (أكثر من 99.9%) في النواة، لأن كتلة الإلكترونات ضئيلة جدًّا.', '["كتلة الإلكترونات 2.733×10⁻²⁷ g","كتلة النواة 1.172×10⁻²³ g","نسبة كتلة الإلكترونات حوالي 0.023%","معظم الكتلة في النواة"]'::jsonb, '["كتلة الإلكترونات = 3 × 9.11×10⁻²⁸ g = 2.733×10⁻²⁷ g","كتلة البروتونات = 3 × 1.673×10⁻²⁴ g = 5.019×10⁻²⁴ g","كتلة النيوترونات = 4 × 1.675×10⁻²⁴ g = 6.700×10⁻²⁴ g","كتلة النواة = 5.019×10⁻²⁴ + 6.700×10⁻²⁴ = 1.172×10⁻²³ g","النسبة المئوية للإلكترونات = 2.733×10⁻²⁷ ÷ (1.172×10⁻²³ + 2.7×10⁻²⁷) × 100 ≈ 0.023%","الاستنتاج: معظم كتلة الذرة في النواة"]'::jsonb, '[{"element":"حساب كتلة الإلكترونات","marks":1},{"element":"حساب كتلة النواة","marks":2},{"element":"حساب النسبة المئوية لكتلة الإلكترونات","marks":1},{"element":"الاستنتاج أن معظم الكتلة في النواة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة للكتل والنسبة مع الاستنتاج"},{"level":"3–4 درجات","description":"حسابات صحيحة مع خطأ في النسبة أو غياب الاستنتاج"},{"level":"1–2 درجة","description":"حساب كتلة الإلكترونات أو النواة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال ضرب كتلة كل جسيم في عدده","عدّ النيوترونات 3 بدل 4","الخطأ في الأسس عند جمع الكتل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.717Z"}'::jsonb)
