('mcq', 5, 3, 'قطر النواة = قطر الذرة ÷ 10⁴ = (1.28×10⁻¹⁰ m) ÷ 10⁴ = 1.28×10⁻¹⁴ m؛ فالخيار الأخير صحيح.', '["ناتجة عن القسمة على 10³ بدل 10⁴.","ناتجة عن ضرب قطر الذرة في 10⁴ بدل القسمة، فخرج قطر أكبر من قطر الذرة نفسها.","ناتجة عن القسمة على 10⁶ بدل 10⁴.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.718Z"}'::jsonb),
('mcq', 6, 0, 'قطر النواة = قطر الذرة ÷ 10⁴ = 100 m ÷ 10⁴ = 0.01 m = 1 cm؛ أي بحجم حبة صغيرة، وهذا يبيّن أن معظم حجم الذرة فراغ.', '["","ناتجة عن القسمة على 10³ بدل 10⁴ (100 m ÷ 1000 = 0.1 m).","ناتجة عن القسمة على 100 فقط بدل 10⁴.","ناتجة عن القسمة على 10 فقط بدل 10⁴."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.718Z"}'::jsonb),
('mcq', 7, 2, 'النواة صغيرة جدًّا وتحوي أكثر من 99.97% من كتلة الذرة فهي كثيفة، والإلكترونات تتحرك في فراغ كبير حولها يشكل معظم حجم الذرة؛ فالعبارة الثالثة هي الصحيحة.', '["النواة تحوي معظم الكتلة لكنها لا تشغل معظم الحجم؛ فمعظم حجم الذرة فراغ.","هذا يخالف ما تبيّنه تجربة رذرفورد؛ فالكتلة متركزة في النواة وليست موزعة بانتظام.","","الإلكترونات كتلتها صغيرة جدًّا، ومعظم الكتلة في النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.718Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مرّ معظم جسيمات ألفا في تجربة رذرفورد خلال صفيحة الذهب دون انحراف أو بانحراف قليل، مما يدل على أنها لم تصادف في طريقها إلا فراغًا. كما أن قطر الذرة يعادل تقريبًا عشرة آلاف مرة قطر النواة، أي أن النواة تشغل حيزًا صغيرًا جدًّا من الذرة، والإلكترونات تتحرك سريعًا في الفراغ المحيط بالنواة؛ لذلك يكون معظم حجم الذرة فراغًا.', '["مرور معظم جسيمات ألفا دون انحراف","قطر الذرة حوالي عشرة آلاف مرة قطر النواة","النواة تشغل حيزًا صغيرًا جدًّا","الإلكترونات تتحرك في الفراغ حول النواة"]'::jsonb, '[]'::jsonb, '[{"element":"الاستدلال بمرور معظم جسيمات ألفا","marks":1},{"element":"ذكر نسبة القطرين (10000 مرة)","marks":1},{"element":"أن النواة تشغل حيزًا صغيرًا جدًّا","marks":1},{"element":"أن الإلكترونات تتحرك في الفراغ المحيط بالنواة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يجمع الدليل التجريبي ونسبة القطرين ووصف الفراغ"},{"level":"2–3 درجات","description":"ذكر عنصرين أو ثلاثة صحيحة من العناصر"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفراغ في الذرة يحتوي مادة موزعة بانتظام","الخطأ في نسبة القطرين","عدم ربط الفراغ بحركة الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.718Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكثافة = الكتلة ÷ الحجم؛ والنواة تحوي أكثر من 99.97% من كتلة الذرة في حيز صغير جدًّا، فتكون كثافتها كبيرة جدًّا. وبالنسبة نفسها بين القطرين: قطر النواة = 200 m ÷ 10⁴ = 0.02 m = 2 cm تقريبًا.', '["الكثافة = الكتلة ÷ الحجم","النواة تحوي أكثر من 99.97% من كتلة الذرة","حجم النواة صغير جدًّا فالكثافة كبيرة","قطر النواة المكبرة = 0.02 m = 2 cm"]'::jsonb, '["قطر النواة = قطر الذرة ÷ 10⁴","قطر النواة = 200 m ÷ 10⁴ = 0.02 m","0.02 m = 2 cm"]'::jsonb, '[{"element":"تفسير الكثافة بتركز الكتلة في حيز صغير","marks":2},{"element":"القسمة على 10⁴ بصورة صحيحة","marks":1},{"element":"الناتج 0.02 m (2 cm) مع الوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للكثافة وحساب صحيح للقطر مع الوحدة"},{"level":"2–3 درجات","description":"تفسير صحيح مع خطأ في الحساب، أو حساب صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"ذكر أن النواة تحوي معظم الكتلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب قطر الذرة في 10⁴ بدل القسمة","نسبة الكثافة إلى كبر حجم النواة","نسيان تحويل 0.02 m إلى cm أو كتابة الوحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.718Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالكتلة لا تحدد الحجم. النواة تحوي معظم كتلة الذرة (أكثر من 99.97%) لكنها تشغل حيزًا صغيرًا جدًّا منها، فقطر الذرة يعادل نحو عشرة آلاف مرة قطر النواة. ومعظم حجم الذرة فراغ تتحرك فيه الإلكترونات السريعة. وبسبب تركز معظم الكتلة في حيز صغير جدًّا تكون النواة شديدة الكثافة.', '["الحكم بأن العبارة غير صحيحة","النواة تحوي معظم الكتلة لكن حجمها صغير جدًّا","قطر الذرة حوالي عشرة آلاف مرة قطر النواة، ومعظم الحجم فراغ تتحرك فيه الإلكترونات","الكثافة كبيرة لتركز الكتلة في حيز صغير"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة مع التعليل","marks":1},{"element":"أن معظم حجم الذرة فراغ تتحرك فيه الإلكترونات","marks":1},{"element":"ذكر نسبة الأقطار أو صغر حجم النواة","marks":1},{"element":"تفسير كثافة النواة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع التفسيرين الصحيحين (الفراغ والكثافة)"},{"level":"2–3 درجات","description":"حكم صحيح مع تفسير واحد أو تفسيرين ناقصين"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الكتلة والحجم","قبول العبارة أو تعديلها دون تفسير","القول إن الفراغ يحتوي مادة غير مرئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.719Z"}'::jsonb)
