from (values
('mcq', 1, 0, 'العدد الذري لذرة العنصر هو عدد البروتونات الموجودة في نواتها، وهو الذي يحدد نوع الذرة.', '["","عدد النيوترونات يختلف بين نظائر العنصر الواحد، أما العدد الذري فيبقى ثابتًا للعنصر.","هذا هو العدد الكتلي وليس العدد الذري.","عدد مستويات الطاقة لا علاقة له بتعريف العدد الذري، فهو يرتبط بتوزيع الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.719Z"}'::jsonb),
('mcq', 2, 1, 'عدد البروتونات في النواة هو الذي يحدد نوع الذرة، ويُسمى العدد الذري؛ فلكل عنصر عدد بروتونات خاص به.', '["عدد النيوترونات قد يختلف بين ذرات العنصر الواحد (النظائر) دون أن يتغير العنصر.","","المجموع هو العدد الكتلي، وهو يختلف بين نظائر العنصر الواحد فلا يحدد هويته.","الكتلة قد تختلف بين ذرات العنصر الواحد، فهي لا تحدد نوع العنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.719Z"}'::jsonb),
('mcq', 3, 2, 'يُكتب العدد الذري أعلى الرمز الكيميائي للعنصر في خانته، كما في الهيدروجين إذ يظهر الرقم 1 فوق الرمز H.', '["الرقم الموجود أسفل الرمز هو متوسط الكتلة الذرية وليس العدد الذري.","لا يوجد في الخانة شيء أسفل متوسط الكتلة الذرية؛ فالعدد الذري يقع في أعلى الخانة.","","اسم العنصر يُكتب في أعلى الخانة ولا يُكتب العدد الذري على يساره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.719Z"}'::jsonb),
('mcq', 4, 3, 'العدد الذري يساوي عدد البروتونات في النواة؛ فالعدد الذري 3 يعني أن نواة ذرة الليثيوم تحوي 3 بروتونات.', '["النيوترونات لا يدل عليها العدد الذري، بل يُحسب عددها بطرح العدد الذري من العدد الكتلي.","مجموع البروتونات والنيوترونات هو العدد الكتلي، وليس العدد الذري.","العدد الذري لا يعبّر عن عدد مستويات الطاقة، بل عن عدد البروتونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.719Z"}'::jsonb),
('mcq', 5, 1, 'العدد الذري هو عدد البروتونات، وهو ما يميز عنصرًا عن آخر؛ لذلك يكون ثابتًا لجميع ذرات العنصر الواحد.', '["الذي يختلف داخل العنصر الواحد هو عدد النيوترونات (النظائر)، أما العدد الذري فثابت.","","لا توجد علاقة ثابتة تجعل العدد الذري نصف الكتلة الذرية؛ فعدد النيوترونات يختلف من عنصر لآخر.","عدد النيوترونات يُحسب من الفرق بين العدد الكتلي والعدد الذري، وليس مساويًا له بالضرورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.719Z"}'::jsonb),
('mcq', 6, 3, 'تساوي العدد الذري يعني تساوي عدد البروتونات، وهذا يعني أن الذرتين من العنصر نفسه حتى لو اختلفت كتلتاهما.', '["العدد الكتلي قد يختلف لأن عدد النيوترونات قد يختلف مع ثبات العدد الذري.","قد تختلف الذرتان في عدد النيوترونات، وهذا ما يحدث في النظائر.","اختلاف عدد النيوترونات يغيّر الكتلة، فلا يلزم تساوي الكتلتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.720Z"}'::jsonb),
('mcq', 7, 2, 'عدد البروتونات في الذرة يساوي عددها الذري؛ وبما أن العدد الذري 11 فإن النواة تحوي 11 بروتونًا.', '["العدد 23 لا يمكن استنتاجه من العدد الذري؛ عدد البروتونات يساوي العدد الذري مباشرة.","المعطيات لا تدل على هذا العدد؛ فالعدد الذري هو نفسه عدد البروتونات.","","قسمة العدد الذري على 2 لا أساس لها؛ فعدد البروتونات يساوي العدد الذري كاملًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.720Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العدد الذري لذرة العنصر هو عدد البروتونات في نواتها. يُكتب أعلى الرمز الكيميائي للعنصر في خانته بالجدول الدوري. ولأن عدد البروتونات يختلف من عنصر لآخر ويكون ثابتًا لذرات العنصر الواحد، فإن العدد الذري هو الذي يحدد هوية الذرة ويميز العنصر عن غيره.', '["العدد الذري = عدد البروتونات في النواة","يُكتب أعلى الرمز الكيميائي في خانة العنصر","ثابت لجميع ذرات العنصر الواحد","يحدد هوية الذرة ويميز العنصر عن غيره"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف الصحيح للعدد الذري","marks":2},{"element":"موضع العدد الذري في الخانة","marks":1},{"element":"دوره في تمييز العناصر وتحديد الهوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح مع ذكر الموضع والدور في تحديد هوية الذرة"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في الموضع أو الدور"},{"level":"1 درجة","description":"ذكر معلومة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف العدد الذري بأنه مجموع البروتونات والنيوترونات","الخلط بين العدد الذري ومتوسط الكتلة الذرية في الخانة","عدم ربط العدد الذري بتحديد هوية العنصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.720Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العدد الذري يساوي عدد البروتونات؛ فالعدد الذري للكربون 6 وللنيتروجين 7. وبما أن عدد البروتونات هو الذي يحدد نوع الذرة، فإن اختلاف العدد الذري (6 و7) يعني أن الذرتين لعنصرين مختلفين، فالذرة التي تحوي 6 بروتونات هي ذرة كربون والتي تحوي 7 بروتونات هي ذرة نيتروجين.', '["العدد الذري للكربون 6","العدد الذري للنيتروجين 7","العدد الذري يساوي عدد البروتونات","اختلاف عدد البروتونات يعني اختلاف نوع الذرة أي اختلاف العنصر"]'::jsonb, '["العدد الذري = عدد البروتونات","الكربون: 6 بروتونات فالعدد الذري 6","النيتروجين: 7 بروتونات فالعدد الذري 7","العددان مختلفان فالعنصران مختلفان"]'::jsonb, '[{"element":"العدد الذري للكربون والنيتروجين (6 و7)","marks":2},{"element":"ربط العدد الذري بعدد البروتونات","marks":1},{"element":"تفسير اختلاف العنصرين باختلاف العدد الذري","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"العددان الذريان صحيحان مع تفسير كامل لاختلاف العنصرين"},{"level":"3–4 درجات","description":"العددان صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"عدد ذري واحد صحيح أو تفسير جزئي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة العدد الكتلي بدل العدد الذري","تفسير الاختلاف بعدد النيوترونات","ذكر العددين دون ربطهما بهوية العنصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.720Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العدد الذري يمثل عدد البروتونات في النواة، أما العدد الكتلي فيمثل مجموع عدد البروتونات وعدد النيوترونات. العدد الذري هو الذي يحدد هوية العنصر لأن لكل عنصر عددًا خاصًا من البروتونات. أما العدد الكتلي فقد يختلف بين ذرات العنصر الواحد لأن عدد النيوترونات قد يختلف بينها (النظائر) بينما يبقى عدد البروتونات ثابتًا.', '["العدد الذري = عدد البروتونات","العدد الكتلي = عدد البروتونات + عدد النيوترونات","العدد الذري يحدد هوية العنصر","العدد الكتلي قد يختلف بين ذرات العنصر الواحد لاختلاف عدد النيوترونات"]'::jsonb, '[]'::jsonb, '[{"element":"ما يمثله العدد الذري","marks":1},{"element":"ما يمثله العدد الكتلي","marks":1},{"element":"العدد الذري هو المحدد للهوية","marks":1},{"element":"العدد الكتلي قد يختلف مع التعليل بالنيوترونات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة وصحيحة مع التعليل"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص في التعليل أو في أحد التعريفين"},{"level":"1–2 درجة","description":"تعريف واحد صحيح أو معلومة جزئية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العدد الكتلي هو الذي يحدد هوية العنصر","الخلط بين دور البروتونات والنيوترونات","نسيان أن العدد الكتلي يشمل البروتونات أيضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.720Z"}'::jsonb)
