('mcq', 2, 0, 'العدد الذري يساوي عدد البروتونات (8)، والعنصر الذي عدده الذري 8 هو الأكسجين O. وعدد الإلكترونات في الذرة المتعادلة يساوي عدد البروتونات، أي 8.', '["","العنصر صحيح، لكن عدد الإلكترونات يساوي عدد البروتونات (8) وليس ضعفه.","العدد الذري للنيتروجين 7 لا 8؛ فهو ليس العنصر المطلوب.","العدد الذري للفلور 9 لا 8؛ فهو ليس العنصر المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.721Z"}'::jsonb),
('mcq', 3, 3, 'عدد الإلكترونات في الذرة المتعادلة يساوي عدد البروتونات وهو العدد الذري؛ فالعدد الذري 30، والعنصر الذي عدده الذري 30 في الجدول الدوري هو الخارصين Zn.', '["عدد ذري 20 يعني 20 إلكترونًا لا 30.","النحاس Cu عدده الذري 29، أي أن ذرته المتعادلة فيها 29 إلكترونًا.","الغاليوم Ga عدده الذري 31، أي أن ذرته المتعادلة فيها 31 إلكترونًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.721Z"}'::jsonb),
('mcq', 4, 1, 'العدد الذري للمغنيسيوم 12، ومنه فعدد البروتونات 12، وفي الذرة المتعادلة يتساوى عدد الإلكترونات مع عدد البروتونات فيكون 12.', '["عدد الإلكترونات في الذرة المتعادلة يساوي عدد البروتونات وليس ضعفه.","","عدد البروتونات يساوي العدد الذري (12) وليس ضعفه.","وجود 10 إلكترونات مع 12 بروتونًا يعني أيونًا موجبًا وليس ذرة متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.721Z"}'::jsonb),
('mcq', 5, 0, 'عدد البروتونات هو العدد الذري، والعنصر الذي عدده الذري 14 في الجدول الدوري هو السيليكون Si.', '["","الكربون عدده الذري 6، أي أن ذرته تحوي 6 بروتونات.","الألومنيوم عدده الذري 13، أي أن ذرته تحوي 13 بروتونًا.","النيتروجين عدده الذري 7، أي أن ذرته تحوي 7 بروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.721Z"}'::jsonb),
('mcq', 6, 2, 'عدد البروتونات يساوي العدد الذري فيكون x = 13، وفي الذرة المتعادلة يساوي عدد الإلكترونات عدد البروتونات فيكون y = 13.', '["y = 10 تعني إلكترونات أقل من البروتونات، أي أيونًا موجبًا وليس ذرة متعادلة.","27 لا يمكن استنتاجه من العدد الذري، فعدد البروتونات يساوي العدد الذري 13.","","عدد البروتونات يساوي العدد الذري تمامًا، وليس أكبر منه بواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.721Z"}'::jsonb),
('mcq', 7, 3, 'في الذرة المتعادلة يساوي عدد الإلكترونات عدد البروتونات؛ فالذرة الأولى فيها 17 بروتونًا أيضًا، فكلتاهما عددها الذري 17 وهما من العنصر نفسه (الكلور).', '["عدد الإلكترونات في الذرة المتعادلة يساوي عدد البروتونات، فالذرتان لهما العدد الذري نفسه وهما للعنصر نفسه.","تساوي عدد البروتونات لا يعني تساوي عدد النيوترونات، ولا تدل المعطيات عليه.","الكتلة تعتمد على عدد النيوترونات أيضًا، وهو غير معلوم هنا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.721Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) العدد الذري للكالسيوم 20، فعدد البروتونات 20 وعدد الإلكترونات 20. (b) العدد الذري يساوي عدد البروتونات فهو 16، والعنصر الكبريت S، وعدد الإلكترونات 16. (c) عدد البروتونات يساوي عدد الإلكترونات فهو 26، والعدد الذري 26، والعنصر الحديد Fe.', '["Ca: العدد الذري 20، بروتونات 20، إلكترونات 20","16 بروتونًا: العدد الذري 16، العنصر S، إلكترونات 16","26 إلكترونًا: العدد الذري 26 وبروتونات 26، العنصر Fe"]'::jsonb, '["العدد الذري = عدد البروتونات = عدد الإلكترونات في الذرة المتعادلة","Ca: العدد الذري 20 فالبروتونات 20 والإلكترونات 20","16 بروتونًا: العدد الذري 16 والعنصر S والإلكترونات 16","26 إلكترونًا: العدد الذري 26 والبروتونات 26 والعنصر Fe"]'::jsonb, '[{"element":"الفرع (a): الأعداد الثلاثة صحيحة","marks":2},{"element":"الفرع (b): العنصر S والعددان","marks":2},{"element":"الفرع (c): العنصر Fe والعددان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الفروع الثلاثة صحيحة كاملة"},{"level":"4–5 درجات","description":"فرعان صحيحان أو أخطاء بسيطة في فرع"},{"level":"1–3 درجات","description":"فرع واحد صحيح أو إجابات جزئية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة العدد الكتلي بدل العدد الذري","الخطأ في تحديد العنصر من الجدول الدوري","نسيان أن عدد الإلكترونات يساوي عدد البروتونات في الذرة المتعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.722Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عدد البروتونات يساوي العدد الذري فهو 17، وعدد الإلكترونات في الذرة المتعادلة يساوي 17 أيضًا، والعنصر هو الكلور Cl. يجب أن يتساوى العددان لأن الذرة المتعادلة لا شحنة كلية لها؛ فالشحنة الموجبة للبروتونات يلغيها تمامًا عدد مساوٍ من الإلكترونات السالبة.', '["عدد البروتونات 17","عدد الإلكترونات 17","العنصر الكلور Cl","الذرة متعادلة فالشحنات الموجبة تساوي السالبة"]'::jsonb, '["عدد البروتونات = العدد الذري = 17","عدد الإلكترونات = عدد البروتونات = 17","العنصر ذو العدد الذري 17 هو الكلور Cl","تعادل الذرة يتطلب تساوي الشحنة الموجبة والسالبة"]'::jsonb, '[{"element":"عدد البروتونات وعدد الإلكترونات","marks":2},{"element":"اسم العنصر","marks":1},{"element":"تفسير تساوي العددين بتعادل الشحنة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان، والعنصر، وتفسير كامل للتعادل"},{"level":"3–4 درجات","description":"حسابات صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"عدد واحد صحيح أو تفسير جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحديد العنصر","تفسير تساوي العددين دون ذكر تعادل الشحنة","اعتبار عدد الإلكترونات مختلفًا عن عدد البروتونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.722Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ هو عدد الإلكترونات؛ فالذرة المتعادلة يتساوى فيها عدد الإلكترونات وعدد البروتونات، لذلك فهي تحوي 11 إلكترونًا لا 12. أما وجود 12 إلكترونًا مع 11 بروتونًا فيعني أن الجسيم مشحون بشحنة سالبة (1−) أي أيون سالب، وليس ذرة متعادلة، لأن عدد الإلكترونات السالبة أكبر من عدد البروتونات الموجبة.', '["عدد البروتونات 11 صحيح","الخطأ في عدد الإلكترونات والصحيح 11","في الذرة المتعادلة عدد الإلكترونات = عدد البروتونات","12 إلكترونًا مع 11 بروتونًا يعني جسيمًا مشحونًا سالبًا لا ذرة متعادلة"]'::jsonb, '["العدد الذري 11 فعدد البروتونات 11","الذرة المتعادلة: عدد الإلكترونات = عدد البروتونات = 11","الفرق 12 − 11 = 1 إلكترون زائد فالشحنة 1−"]'::jsonb, '[{"element":"تحديد الخطأ في عدد الإلكترونات","marks":1},{"element":"التصحيح إلى 11 إلكترونًا مع التعليل","marks":2},{"element":"تفسير 12 إلكترونًا مع 11 بروتونًا (جسيم سالب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ، والتصحيح مع التعليل، وتفسير الجسيم المشحون"},{"level":"2–3 درجات","description":"تصحيح صحيح مع نقص في التعليل أو التفسير"},{"level":"1 درجة","description":"تحديد الخطأ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عدد الإلكترونات يزيد بواحد على عدد البروتونات في كل ذرة","تصحيح عدد البروتونات بدل عدد الإلكترونات","عدم الربط بين اختلاف العددين والشحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.722Z"}'::jsonb)
