from (values
('mcq', 1, 1, 'النظائر ذرات لعنصر واحد لها عدد البروتونات نفسه (العدد الذري نفسه)، لكنها تختلف في عدد النيوترونات.', '["ذرات العناصر المختلفة لها أعداد بروتونات مختلفة، فلا تُعدّ نظائر مهما تساوى عددها الكتلي.","","اختلاف عدد البروتونات يعني اختلاف العنصر، فلا تكون الذرتان نظيرين.","تساوي عدد النيوترونات بين عنصرين لا يجعلهما نظيرين؛ فالنظائر تكون للعنصر الواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:27:04.723Z"}'::jsonb),
('mcq', 2, 3, 'عدد النيوترونات = العدد الكتلي − العدد الذري = 41 − 19 = 22 نيوترونًا.', '["19 هو عدد البروتونات وليس النيوترونات.","41 هو العدد الكتلي، أي مجموع البروتونات والنيوترونات.","20 هو عدد النيوترونات في نظير البوتاسيوم-39 وليس البوتاسيوم-41.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.723Z"}'::jsonb),
('mcq', 3, 0, 'للذرتين A وB عدد البروتونات نفسه (6) فهما للعنصر نفسه، وتختلفان في عدد النيوترونات (6 و8)؛ لذلك هما نظيران.', '["","عدد بروتونات A هو 6 وC هو 7، فهما لعنصرين مختلفين وليستا نظيرين.","عدد بروتونات C هو 7 وD هو 8، فهما لعنصرين مختلفين رغم تساوي نيوتروناتهما مع بروتوناتهما.","عدد بروتونات B هو 6 وD هو 8، فهما لعنصرين مختلفين رغم تساوي عدد النيوترونات (8) فيهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.723Z"}'::jsonb),
('mcq', 4, 2, 'النظيران لعنصر واحد يتفقان في عدد البروتونات، ويختلفان في عدد النيوترونات، ولذلك تختلف كتلتاهما.', '["العدد الذري ثابت للعنصر الواحد، فلا يختلف بين نظائره.","عدد الإلكترونات في الذرة المتعادلة يساوي عدد البروتونات، وهو متساوٍ بين النظائر.","","عدد البروتونات هو العدد الذري، وهو ثابت في جميع نظائر العنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.723Z"}'::jsonb),
('mcq', 5, 3, 'للذرتين العدد نفسه من البروتونات (29) فهما ذرتان للنحاس، واختلاف العددين الكتليين (63 و65) يعني اختلاف عدد النيوترونات؛ فهما نظيران.', '["اختلاف الكتلة بسبب النيوترونات لا يغير العنصر؛ فعدد البروتونات واحد (29).","الأيونات تختلف في عدد الإلكترونات، أما هنا فالاختلاف في عدد النيوترونات.","المركب يتكون من عنصرين أو أكثر، والذرتان هنا لعنصر واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.723Z"}'::jsonb),
('mcq', 6, 1, 'نظائر العنصر الواحد تختلف في عدد النيوترونات وفي الكتلة، لكنها تتشابه في السلوك الكيميائي لأن السلوك الكيميائي يحدده عدد الإلكترونات.', '["اختلاف الكتلة بسبب النيوترونات لا يغيّر السلوك الكيميائي للنظائر.","","الأعداد الذرية متساوية في النظائر؛ لأنها ذرات للعنصر نفسه.","النظائر تختلف في عدد النيوترونات، فتختلف كتلها؛ والنظير الأكثر نيوترونات أكبر كتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.723Z"}'::jsonb),
('mcq', 7, 0, 'وجود النظائر يبين أن ذرات العنصر الواحد قد تختلف في عدد النيوترونات وفي الكتلة، وهذا يخالف فكرة تطابق ذراته.', '["","هذه العبارة خاطئة علميًا؛ فالبروتونات موجبة والإلكترونات سالبة والنيوترونات متعادلة.","تعادل ذرات العنصر لا يتعارض مع تشابهها، فلا يدل على خطأ الفكرة.","اختلاف العناصر في أعدادها الذرية لا يتعلق بتشابه ذرات العنصر الواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.724Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النظائر ذرات العنصر الواحد التي لها عدد البروتونات نفسه لكنها تختلف في عدد النيوترونات. في نظائر البوتاسيوم الثلاثة يتفق كل نظير في وجود 19 بروتونًا و19 إلكترونًا في الذرة المتعادلة، ويختلف في عدد النيوترونات (20 و21 و22)، فيختلف عددها الكتلي (39 و40 و41) وتختلف كتلها.', '["تعريف النظائر","الاتفاق في عدد البروتونات (19) وعدد الإلكترونات","الاختلاف في عدد النيوترونات (20 و21 و22)","الاختلاف في العدد الكتلي والكتلة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النظائر","marks":1},{"element":"ما تتفق فيه (البروتونات والإلكترونات)","marks":1},{"element":"ما تختلف فيه (النيوترونات)","marks":1},{"element":"نتيجة الاختلاف في العدد الكتلي والكتلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح مع بيان ما تتفق فيه وما تختلف فيه ونتيجته"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في المثال"},{"level":"1 درجة","description":"معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النظائر تختلف في عدد البروتونات","نسيان أن الاختلاف في النيوترونات يغير الكتلة","الخلط بين العدد الذري والعدد الكتلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.724Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الذرتان X وY نظيران لعنصر واحد؛ لأن لكل منهما 12 بروتونًا (العدد الذري نفسه) بينما تختلفان في عدد النيوترونات (12 و13). أما الذرة Z فلعنصر مختلف لأن فيها 13 بروتونًا، فعددها الذري يختلف عن العدد الذري للذرتين X وY، ولذلك ليست نظيرًا لهما رغم قرب عدد نيوتروناتها.', '["X وY نظيران","تساوي عدد البروتونات (12) في X وY","اختلاف عدد النيوترونات (12 و13)","Z لعنصر مختلف لأن بروتوناتها 13"]'::jsonb, '["نقارن عدد البروتونات: X = 12، Y = 12، Z = 13","X وY متساويتان في البروتونات ومختلفتان في النيوترونات فهما نظيران","Z تختلف في عدد البروتونات فهي لعنصر آخر"]'::jsonb, '[{"element":"تحديد X وY نظيرين","marks":1},{"element":"التعليل بتساوي البروتونات واختلاف النيوترونات","marks":2},{"element":"تحديد Z لعنصر مختلف مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للنظيرين والذرة المختلفة مع تعليل كامل"},{"level":"3–4 درجات","description":"تحديد صحيح مع تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد صحيح جزئي دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ Y وZ نظيرين لقرب عدد النيوترونات","الاعتماد على عدد النيوترونات وحده في الحكم","عدم تعليل الاختيار بعدد البروتونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.724Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كل من النظيرين يحوي 29 بروتونًا و29 إلكترونًا؛ لأن العدد الذري 29 والذرة متعادلة. عدد النيوترونات في نحاس-63 يساوي 63 − 29 = 34، وفي نحاس-65 يساوي 65 − 29 = 36. النظير نحاس-65 أكبر كتلة لأنه يحوي عددًا أكبر من النيوترونات (36 مقابل 34).', '["البروتونات 29 في كل منهما","الإلكترونات 29 في كل منهما","نيوترونات نحاس-63 هي 34 ونحاس-65 هي 36","نحاس-65 أكبر كتلة لزيادة النيوترونات"]'::jsonb, '["البروتونات = العدد الذري = 29 لكلا النظيرين","الإلكترونات = البروتونات = 29","نيوترونات Cu-63 = 63 − 29 = 34","نيوترونات Cu-65 = 65 − 29 = 36","النظير الأكبر نيوترونات هو الأكبر كتلة: Cu-65"]'::jsonb, '[{"element":"عدد البروتونات والإلكترونات (29 و29)","marks":1},{"element":"عدد نيوترونات نحاس-63 (34)","marks":1},{"element":"عدد نيوترونات نحاس-65 (36)","marks":1},{"element":"تحديد النظير الأكبر كتلة مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأعداد كلها صحيحة مع تحديد النظير الأكبر كتلة وتعليله"},{"level":"3–4 درجات","description":"الأعداد صحيحة مع نقص في التعليل"},{"level":"1–2 درجة","description":"عدد أو عددان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عدد الإلكترونات يختلف بين النظيرين","حساب النيوترونات بجمع العدد الذري والعدد الكتلي","اختيار نحاس-63 أكبر كتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.724Z"}'::jsonb)
