('essay', 3, null::int, null, null, 'نفرض أن العدد الذري Z، فيكون عدد النيوترونات Z + 2. العدد الكتلي = Z + (Z + 2) = 40، ومنه 2Z = 38 و Z = 19. إذن عدد البروتونات 19، وعدد الإلكترونات 19، وعدد النيوترونات 21. العنصر الذي عدده الذري 19 هو البوتاسيوم K.', '["فرض العدد الذري Z وعدد النيوترونات Z + 2","تكوين المعادلة 2Z + 2 = 40","عدد البروتونات والإلكترونات 19","عدد النيوترونات 21","العنصر البوتاسيوم K"]'::jsonb, '["العدد الكتلي = العدد الذري + عدد النيوترونات","40 = Z + (Z + 2)","2Z = 38 ومنه Z = 19","عدد النيوترونات = 19 + 2 = 21","العدد الذري 19 هو البوتاسيوم K"]'::jsonb, '[{"element":"تكوين المعادلة من قانون العدد الكتلي","marks":1},{"element":"حل المعادلة وإيجاد 19 بروتونًا و19 إلكترونًا","marks":2},{"element":"عدد النيوترونات 21","marks":1},{"element":"تحديد العنصر K","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المعادلة والحل والأعداد الثلاثة والعنصر صحيحة"},{"level":"3–4 درجات","description":"خطوات صحيحة مع خطأ حسابي أو نقص في تحديد العنصر"},{"level":"1–2 درجة","description":"تكوين المعادلة فقط أو عدد واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح 2 من 40 والقول إن العدد الذري 38","قسمة 40 على 2 دون مراعاة الفرق بين العددين","عدم تحديد العنصر بعد إيجاد العدد الذري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.727Z"}'::jsonb)
