('essay', 1, 'عرّف وحدة الكتل الذرية (amu)، واذكر الذرة المعيارية التي تُعرَّف بها، ثم وضّح لماذا لجأ العلماء إلى استعمال هذه الوحدة بدل الجرام.', null, null, 'تذكر', 'تعريف وتعليل', 'متوسط', 'الكتاب ص 93 — وحدة الكتل الذرية'),
('essay', 2, 'عرّف الكتلة الذرية لعنصر ما، ثم فسّر لماذا تُعرَّف بأنها متوسط لا كتلة ذرة واحدة، مستعينًا بمثال الكلور الذي يوجد في الطبيعة على هيئة نظيرين هما كلور-35 وكلور-37 وكتلته الذرية 35.453 amu.', null, null, 'فهم', 'تعريف وتفسير بمثال', 'متوسط', 'الكتاب ص 93 — الكتلة الذرية، الشكل 3-18'),
('essay', 3, 'كتلة البروتون 1.007276 amu، وكتلة النيوترون 1.008665 amu، وكتلة الإلكترون 0.000549 amu. احسب كتلة 6 بروتونات و6 نيوترونات و6 إلكترونات معًا (مكونات ذرة كربون-12)، وبيّن كم تقارب النتيجة كتلة الكربون-12 المعيارية (12 amu)، وماذا يدل ذلك على دور الإلكترونات في كتلة الذرة.', null, null, 'تطبيق', 'حساب واستنتاج', 'صعب', 'الكتاب ص 93 — الجدول 3-4')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
