from (values
('mcq', 1, 0, 'وحدة الكتل الذرية تعادل 1/12 من كتلة ذرة الكربون-12، فتكون كتلة ذرة الكربون-12 مساوية 12 amu بالتعريف.', '["","كتلة ذرة الكربون-12 كاملة تساوي 12 amu، وليست وحدة واحدة.","الجزء المعتمد هو 1/12 وليس 1/6.","الذرة المعيارية هي الكربون-12 وليس الهيدروجين، والوحدة جزء من كتلتها لا كتلة ذرة كاملة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:27:04.727Z"}'::jsonb),
('mcq', 2, 2, 'الذرة المعيارية المعتمدة لقياس كتل الذرات هي ذرة الكربون-12، التي كتلتها 12 amu.', '["الهيدروجين-1 ليس الذرة المعيارية المعتمدة، فالمقياس هو الكربون-12.","الأكسجين-16 ليس الذرة المعيارية المعتمدة، فالمقياس هو الكربون-12.","","الكلور-35 أحد نظيري الكلور وليس ذرة معيارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.727Z"}'::jsonb),
('mcq', 3, 1, 'لأن 1 amu تعادل 1/12 من كتلة الكربون-12 الذي فيه 6 بروتونات و6 نيوترونات، فهي تقارب كتلة بروتون واحد أو نيوترون واحد.', '["كتلة الإلكترون أصغر بكثير (حوالي 1/1840 من كتلة البروتون)، فلا تساوي 1 amu.","","كتلة ذرة الكربون-12 تساوي 12 amu وليس 1 amu.","ألف بروتون تعادل حوالي ألف amu وليس وحدة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:27:04.727Z"}'::jsonb),
('mcq', 4, 3, 'الكتلة الذرية للعنصر هي متوسط كتل نظائره الموجودة في الطبيعة، ويدخل في هذا المتوسط كل نظير بحسب نسبة وجوده.', '["الكتلة الذرية لا تقتصر على النظير الأخف، بل تشمل جميع النظائر.","النظير الأكثر وجودًا يؤثر أكثر في المتوسط، لكن الكتلة الذرية تشمل جميع النظائر الموجودة.","المجموع يعطي قيمة أكبر من كتل النظائر كلها؛ والكتلة الذرية متوسط لا مجموع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.728Z"}'::jsonb),
('mcq', 5, 2, 'يُرمز لوحدة الكتل الذرية بالرمز amu أو بالرمز u، وكلاهما صحيح ويعبّران عن الوحدة نفسها.', '["الرمز g هو رمز الجرام، وهو وحدة أكبر بكثير من وحدة الكتل الذرية.","الرمز mol يمثل المول وحدة كمية المادة وليس وحدة الكتل الذرية.","","الرمز atm يمثل وحدة الضغط (الضغط الجوي) وليس وحدة الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.728Z"}'::jsonb),
('mcq', 6, 0, 'كتلة الإلكترون (0.000549 amu) أصغر بكثير من كتلة البروتون (1.007276 amu)، فهي حوالي 1/1840 من كتلة البروتون أو النيوترون.', '["","1/12 هو الجزء الذي تُعرَّف به وحدة الكتل الذرية من كتلة الكربون-12، وليس نسبة كتلة الإلكترون.","نصف الكتلة مبالغة كبيرة؛ فكتلة الإلكترون جزء ضئيل جدًا.","هذه النسبة معكوسة؛ فالإلكترون هو الأخف وليس الأثقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.728Z"}'::jsonb),
('mcq', 7, 3, 'كتلة الإلكترون صغيرة جدًا، أما كتلة البروتون والنيوترون فقريبة من 1 amu لكل منهما؛ لذلك تعتمد كتلة الذرة أساسًا على عدد البروتونات وعدد النيوترونات.', '["الإلكترونات خفيفة جدًا (حوالي 1/1840 من كتلة البروتون) فلا تحدد كتلة الذرة.","مستويات الطاقة لا تحدد كتلة الذرة؛ فالكتلة مصدرها جسيمات النواة.","حجم السحابة الإلكترونية يتعلق بحجم الذرة، وليس بكتلتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.728Z"}'::jsonb),
('essay', 1, null::int, null, null, 'وحدة الكتل الذرية (amu) تعادل 1/12 من كتلة ذرة الكربون-12، وهي الذرة المعيارية التي كتلتها 12 amu، وتساوي تقريبًا كتلة بروتون واحد أو نيوترون واحد. استعمل العلماء هذه الوحدة لأن كتل الذرات صغيرة جدًا (كتلة البروتون أو النيوترون حوالي 1.67 × 10⁻²⁴ g) ويصعب التعامل معها بالجرام، فتُقاس كتلة الذرة بالنسبة إلى كتلة الذرة المعيارية.', '["amu تساوي 1/12 من كتلة الكربون-12","الذرة المعيارية هي الكربون-12","تساوي تقريبًا كتلة بروتون أو نيوترون","السبب: كتل الذرات صغيرة جدًا يصعب التعامل بالجرام"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف amu بـ 1/12 من كتلة الكربون-12","marks":1},{"element":"تحديد الكربون-12 ذرة معيارية","marks":1},{"element":"المقابل التقريبي (بروتون أو نيوترون)","marks":1},{"element":"تعليل استعمال الوحدة بصغر كتل الذرات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وذرة معيارية وتقدير وتعليل كلها صحيحة"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في عنصر أو عنصرين"},{"level":"1 درجة","description":"معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن amu هي كتلة ذرة الكربون-12 كاملة","الخلط بين الجزء 1/12 و 1/6","عدم تعليل سبب استعمال الوحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.728Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكتلة الذرية للعنصر هي متوسط كتل نظائره الموجودة في الطبيعة. تُعرَّف بالمتوسط لأن للعنصر الواحد نظائر تختلف في كتلها بحسب عدد النيوترونات، ويوجد كل نظير بنسبة معينة. ففي الكلور يوجد نظيران: كلور-35 وكلور-37، والكتلة الذرية للكلور 35.453 amu وهي قيمة تقع بين كتلتي النظيرين، وأقرب إلى كتلة كلور-35 لأن نسبة وجوده أكبر.', '["الكتلة الذرية = متوسط كتل النظائر الموجودة في الطبيعة","للعنصر نظائر مختلفة الكتلة","لكل نظير نسبة وجود","مثال الكلور: 35.453 amu بين 35 و37 وأقرب إلى كلور-35"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكتلة الذرية","marks":1},{"element":"ذكر اختلاف كتل النظائر ونسب وجودها","marks":1},{"element":"تطبيق على الكلور (35.453 amu بين النظيرين)","marks":1},{"element":"تعليل القرب من كلور-35 بنسبة وجوده الأكبر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وتفسير ومثال وتعليل صحيحة"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في التفسير أو المثال"},{"level":"1 درجة","description":"معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الكتلة الذرية بأنها كتلة ذرة واحدة","اعتبار الكتلة الذرية مجموع كتل النظائر","إغفال نسبة وجود النظائر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.729Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كتلة 6 بروتونات = 6 × 1.007276 = 6.043656 amu. كتلة 6 نيوترونات = 6 × 1.008665 = 6.05199 amu. مجموع كتلتي البروتونات والنيوترونات = 12.095646 amu وهو قريب من 12 amu. كتلة 6 إلكترونات = 6 × 0.000549 = 0.003294 amu وهي صغيرة جدًا. إذن تعتمد كتلة الذرة أساسًا على البروتونات والنيوترونات، ودور الإلكترونات في الكتلة ضئيل جدًا.', '["كتلة البروتونات 6.043656 amu","كتلة النيوترونات 6.05199 amu","المجموع 12.0956 amu قريب من 12 amu","كتلة الإلكترونات 0.003294 amu ضئيلة","الكتلة تعتمد أساسًا على البروتونات والنيوترونات"]'::jsonb, '["6 × 1.007276 = 6.043656 amu","6 × 1.008665 = 6.05199 amu","6.043656 + 6.05199 = 12.095646 amu ≈ 12 amu","6 × 0.000549 = 0.003294 amu","الاستنتاج: الإلكترونات لا تؤثر تقريبًا في كتلة الذرة"]'::jsonb, '[{"element":"كتلة البروتونات والنيوترونات (حسابان صحيحان)","marks":2},{"element":"المجموع ومقارنته بـ 12 amu","marks":1},{"element":"كتلة الإلكترونات","marks":1},{"element":"الاستنتاج حول دور الإلكترونات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات كلها صحيحة مع المقارنة والاستنتاج"},{"level":"3–4 درجات","description":"حسابات صحيحة مع نقص في المقارنة أو الاستنتاج"},{"level":"1–2 درجة","description":"حساب واحد صحيح أو استنتاج دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الضرب في 12 بدل 6 عند حساب كتلة الجسيمات","إهمال وحدة amu في النتائج","القول إن الإلكترونات تساهم مساهمة كبيرة في الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.729Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
