('essay', 3, null::int, null, null, 'إسهام بروم-79 = 0.5069 × 78.918 = 40.00 amu. إسهام بروم-81 = 0.4931 × 80.917 = 39.90 amu. الكتلة الذرية للبروم = 40.00 + 39.90 = 79.90 amu، وهي قريبة من 80 amu. لكن هذه القيمة متوسط لنظيرين (79 و81) بنسبتين متقاربتين، وليست كتلة ذرة موجودة بذاتها؛ فلا يوجد نظير بروم-80 في الطبيعة بنسبة تُذكر.', '["إسهام بروم-79 = 40.00 amu","إسهام بروم-81 = 39.90 amu","الكتلة الذرية = 79.90 amu","القيمة متوسط لنظيرين متقاربي النسبة لا كتلة ذرة فعلية"]'::jsonb, '["0.5069 × 78.918 = 40.00 amu","0.4931 × 80.917 = 39.90 amu","40.00 + 39.90 = 79.90 amu","79.90 قريبة من 80 لأن نسبتي النظيرين متقاربتان، وليست كتلة ذرة موجودة"]'::jsonb, '[{"element":"إسهام بروم-79","marks":1},{"element":"إسهام بروم-81","marks":1},{"element":"الكتلة الذرية 79.90 amu","marks":1},{"element":"التفسير: متوسط لنظيرين لا كتلة ذرة موجودة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح كامل مع تفسير صحيح"},{"level":"3–4 درجات","description":"حساب صحيح مع تفسير ناقص"},{"level":"1–2 درجة","description":"إسهام واحد صحيح أو تفسير دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استنتاج وجود نظير كتلته 80 amu من الكتلة الذرية","الضرب في النسبة المئوية دون تحويلها إلى كسر","حساب المتوسط البسيط (79.918)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.733Z"}'::jsonb)
