('mcq', 5, 'الكتلة الذرية للنحاس 63.55 amu. ماذا تعني هذه القيمة؟', null, '["كل ذرة نحاس كتلتها 63.55 amu","للنحاس نظير واحد كتلته 63.55 amu","عدد النيوترونات في ذرة النحاس 63.55","متوسط كتل نظائر النحاس بحسب نسب وجودها"]'::jsonb, 'فهم', 'تفسير دلالة القيمة', 'متوسط', 'الكتاب ص 93 — الكتلة الذرية'),
('mcq', 6, 'الكتلة الذرية للكلور 35.453 amu أقرب إلى كتلة كلور-35 منها إلى كتلة كلور-37. ما سبب ذلك؟', null, '["أن كلور-35 يحوي عددًا أكبر من النيوترونات","أن نسبة وجود كلور-35 في الطبيعة أكبر من نسبة وجود كلور-37","أن كلور-35 يحوي بروتونات أقل","أن كلور-37 غير موجود في الطبيعة"]'::jsonb, 'فهم', 'تفسير أثر نسبة الوجود', 'متوسط', 'الكتاب ص 94 — الكتلة الذرية للكلور'),
('mcq', 7, 'عنصر له نظير واحد فقط في الطبيعة. ما التوقع الأنسب لكتلته الذرية؟', null, '["تساوي كتلة ذلك النظير وتقرب من عدد صحيح","متوسط بين عددين صحيحين متتاليين دائمًا","أكبر من كتلة ذلك النظير","أصغر من كتلة ذلك النظير"]'::jsonb, 'تحليل', 'استنتاج من حالة خاصة', 'صعب', 'الكتاب ص 94 — الفلور-19'),
('essay', 1, 'للكلور نظيران: كلور-35 كتلته 34.969 amu ونسبة وجوده 75.78%، وكلور-37 كتلته 36.966 amu ونسبة وجوده 24.22%. احسب الكتلة الذرية للكلور، ثم فسّر لماذا لا تكون هذه الكتلة عددًا صحيحًا.', null, null, 'فهم', 'حساب وتفسير', 'متوسط', 'الكتاب ص 93 — الشكل 3-18'),
('essay', 2, 'قال طالب: كتلة كل من البروتون والنيوترون قريبة من 1 amu، ولذلك يجب أن تكون الكتلة الذرية لكل عنصر عددًا صحيحًا. بيّن لماذا يبدو هذا التوقع منطقيًا في البداية، ثم وضّح لماذا هو غير صحيح في الواقع.', null, null, 'فهم', 'نقد توقع وتفسير', 'متوسط', 'الكتاب ص 93 — الكتلة الذرية'),
('essay', 3, 'الكتلة الذرية للفلور F قريبة من 19 amu، أما الكتلة الذرية للكلور فتساوي 35.453 amu. فسّر سبب قرب كتلة الفلور من عدد صحيح وبعد كتلة الكلور عنه، ثم استنتج ماذا تدل عليه قيمة الفلور بشأن نظائره في الطبيعة.', null, null, 'تحليل', 'مقارنة وتعليل واستنتاج', 'صعب', 'الكتاب ص 94 — الفلور والكلور')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
