from (values
('mcq', 1, 2, 'للكلور نظيران في الطبيعة بكتلتين مختلفتين؛ والكتلة الذرية متوسط كتلتيهما بحسب نسبة وجود كل نظير، فلا تكون عددًا صحيحًا.', '["كتلة الإلكترونات صغيرة جدًا (حوالي 1/1840 من كتلة البروتون) فلا تفسر الكسر العشري الكبير.","كتلتا البروتون والنيوترون متقاربتان (حوالي 1 amu لكل منهما) فلا يكون الاختلاف بينهما هو السبب.","","هذا ليس هو سبب الكسر العشري في الكتلة الذرية؛ والسبب هو التوسط بين كتل النظائر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:27:04.733Z"}'::jsonb),
('mcq', 2, 3, 'كتلة كل من البروتون والنيوترون قريبة من 1 amu، وكتلة الذرة تعتمد أساسًا على عدد هذه الجسيمات؛ لذلك يُتوقع أن تكون كتلتها قريبة من عدد صحيح.', '["كتلة الإلكترون أصغر بكثير من 1 amu (0.000549 amu).","عدد النيوترونات لا يساوي عدد البروتونات دائمًا؛ فالنظائر تختلف في عدد النيوترونات.","نوى ذرات العنصر الواحد ليست ثابتة الكتلة، فللعنصر نظائر تختلف في الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.733Z"}'::jsonb),
('mcq', 3, 0, 'الكتلة الذرية متوسط لكتلتي النظيرين، فتقع بينهما (بين 34.969 و36.966)، وتكون أقرب إلى كتلة النظير الأخف لأنه الأكثر وجودًا؛ والقيمة 35.45 amu تحقق ذلك.', '["","هذه القيمة أقل من كتلتي النظيرين معًا، والمتوسط لا يقل عن أخف نظير.","هذه القيمة تساوي كتلة النظير الأثقل، والمتوسط يكون أقل منها لوجود النظير الأخف.","هذه القيمة أكبر من كتلتي النظيرين معًا، والمتوسط لا يزيد على أثقل نظير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.733Z"}'::jsonb),
('mcq', 4, 1, 'النظيران لعنصر واحد لهما العدد الذري نفسه (17 بروتونًا و17 إلكترونًا) ويختلفان في عدد النيوترونات (18 و20)؛ فالاختلاف في النيوترونات هو سبب اختلاف الكتلتين.', '["عدد البروتونات واحد (17) في النظيرين لأنهما للعنصر نفسه.","","عدد الإلكترونات واحد (17) في الذرتين المتعادلتين.","العدد الذري واحد (17) في النظيرين، فلا يفسر اختلاف الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.734Z"}'::jsonb),
('mcq', 5, 3, 'الكتلة الذرية قيمة متوسطة لكتل نظائر العنصر في الطبيعة بحسب نسب وجودها؛ ولذلك قد لا توجد ذرة نحاس كتلتها هذه القيمة بالضبط.', '["ذرات النحاس تتكون من نظيرين مختلفي الكتلة، فليست كل ذرة بهذه الكتلة.","للنحاس نظيران (نحاس-63 ونحاس-65)، والقيمة 63.55 متوسط لكتلتيهما.","عدد النيوترونات عدد صحيح دائمًا، فلا يمكن أن يكون 63.55.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.734Z"}'::jsonb),
('mcq', 6, 1, 'كلور-35 أكثر وجودًا (حوالي 76%) من كلور-37 (حوالي 24%)، فيكون تأثيره في المتوسط أكبر فتقترب الكتلة الذرية من كتلته.', '["كلور-37 هو الذي يحوي عددًا أكبر من النيوترونات (20 مقابل 18) لا كلور-35.","","للنظيرين عدد البروتونات نفسه (17) لأنهما للعنصر نفسه.","كلور-37 موجود في الطبيعة بنسبة حوالي 24%، وهو يسهم في المتوسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:27:04.734Z"}'::jsonb),
('mcq', 7, 0, 'الكتلة الذرية متوسط كتل النظائر الموجودة، وعند وجود نظير واحد فقط يكون المتوسط هو كتلة هذا النظير نفسه، وهي قريبة من عدد صحيح (كالفلور-19).', '["","المتوسط بين عددين لا ينشأ إلا عند وجود نظائر متعددة، وهنا نظير واحد فقط.","المتوسط لا يزيد على أثقل نظير، وهنا النظير الوحيد هو الأثقل والأخف معًا.","المتوسط لا يقل عن أخف نظير، وهنا النظير الوحيد هو الأخف والأثقل معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.734Z"}'::jsonb),
('essay', 1, null::int, null, null, 'إسهام كلور-35 = 0.7578 × 34.969 = 26.50 amu. إسهام كلور-37 = 0.2422 × 36.966 = 8.953 amu. الكتلة الذرية = 26.50 + 8.953 = 35.45 amu. هذه القيمة ليست عددًا صحيحًا لأن الكتلة الذرية للعنصر متوسط كتل نظائره في الطبيعة، وللنظيرين كتلتان مختلفتان بسبب اختلاف عدد النيوترونات، فيكون المتوسط بين العددين 35 و37 ولا يكون عددًا صحيحًا.', '["إسهام كلور-35 = 26.50 amu","إسهام كلور-37 = 8.953 amu","الكتلة الذرية = 35.45 amu","السبب: الكتلة الذرية متوسط لكتل نظائر مختلفة"]'::jsonb, '["0.7578 × 34.969 = 26.50 amu","0.2422 × 36.966 = 8.953 amu","الكتلة الذرية = 26.50 + 8.953 = 35.45 amu","القيمة متوسط لنظيرين مختلفي الكتلة فلا تكون عددًا صحيحًا"]'::jsonb, '[{"element":"إسهام النظيرين صحيحان","marks":2},{"element":"الكتلة الذرية 35.45 amu","marks":1},{"element":"التفسير بالمتوسط واختلاف كتل النظائر","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات صحيحة مع تفسير كامل"},{"level":"3–4 درجات","description":"حساب صحيح مع تفسير ناقص أو العكس"},{"level":"1–2 درجة","description":"إسهام واحد صحيح أو تفسير جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل الكسر العشري بكتلة الإلكترونات","حساب المتوسط البسيط دون اعتبار نسبة الوجود","نسيان أن النظيرين يختلفان في عدد النيوترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.734Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يبدو التوقع منطقيًا لأن كتلة الذرة تعتمد أساسًا على عدد البروتونات والنيوترونات، وكتلة كل منها قريبة من 1 amu، وكتلة الإلكترونات ضئيلة جدًا؛ فيُتوقع أن تكون الكتلة قريبة من عدد صحيح. لكنه غير صحيح لأن الكتلة الذرية للعنصر هي متوسط كتل نظائره الموجودة في الطبيعة، ولهذه النظائر كتل مختلفة بحسب عدد النيوترونات ونسب وجود مختلفة؛ فيكون المتوسط قيمة كسرية في الغالب (مثل الكلور 35.453 amu).', '["كتلة البروتون والنيوترون قريبة من 1 amu","كتلة الذرة تعتمد أساسًا على البروتونات والنيوترونات","الكتلة الذرية متوسط كتل النظائر","النظائر مختلفة الكتلة ونسب وجودها مختلفة فينتج عدد غير صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"سبب منطقية التوقع (1 amu لكل جسيم)","marks":2},{"element":"تعريف الكتلة الذرية بالمتوسط","marks":1},{"element":"ربط ذلك باختلاف كتل النظائر ونسب وجودها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير التوقع وتصحيحه بالمتوسط والنظائر"},{"level":"2–3 درجات","description":"تفسير جزئي لأحد الجانبين"},{"level":"1 درجة","description":"ذكر معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الطالب محق لأن الجسيمات كتلتها 1 amu","تفسير الكسر بكتلة الإلكترونات","إغفال نسبة وجود النظائر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.735Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكتلة الذرية متوسط كتل نظائر العنصر. الكلور له نظيران مهمان (كلور-35 وكلور-37) بنسبتين مختلفتين (حوالي 76% و24%)، فيقع متوسطهما بين العددين ولا يكون عددًا صحيحًا. أما كتلة الفلور فقريبة من عدد صحيح (19 amu) لأن الفلور الموجود في الطبيعة هو في الغالب نظير واحد هو الفلور-19؛ فمتوسطه هو كتلة هذا النظير تقريبًا. وهذا يدل على أن الفلور الموجود في الطبيعة هو على الأرجح فلور-19 فقط.', '["الكتلة الذرية متوسط كتل النظائر","الكلور له نظيران بنسب مختلفة فمتوسطه كسري","الفلور في الطبيعة نظير واحد تقريبًا فكتلته قريبة من عدد صحيح","الفلور-19 هو النظير الموجود في الطبيعة على الأرجح"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الكلور بنظيريه ونسبتيهما","marks":2},{"element":"تفسير الفلور بنظير واحد تقريبًا","marks":2},{"element":"الاستنتاج: الفلور في الطبيعة هو فلور-19","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للعنصرين مع الاستنتاج"},{"level":"3–4 درجات","description":"تفسير صحيح لأحد العنصرين مع استنتاج ناقص"},{"level":"1–2 درجة","description":"معلومة صحيحة واحدة أو اثنتان دون ربط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفلور بلا نظائر لأنه عنصر خفيف دون الربط بالمتوسط","الخلط بين الكتلة الذرية والعدد الكتلي","إغفال نسب وجود نظيري الكلور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.735Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
