('mcq', 4, 0, 'العدد الذري 8 يدل على الأكسجين، والعدد الكتلي = 8 + 10 = 18؛ فاسم النظير أكسجين-18.', '["","العدد 8 هو العدد الذري، أما العدد الذي يظهر في الاسم فهو العدد الكتلي 18.","العدد 10 هو عدد النيوترونات، أما العدد الذي يظهر في الاسم فهو العدد الكتلي 18.","الفلور عدده الذري 9، وهو يختلف عن العنصر الذي يحوي 8 بروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.736Z"}'::jsonb),
('mcq', 5, 1, 'العدد الذري = عدد البروتونات = 19، والعدد الكتلي = 19 + 21 = 40؛ فيُكتب الرمز ⁴⁰₁₉K.', '["تبدّل موضعا العددين في هذا الرمز؛ فالعدد الكتلي يُكتب أعلى والعدد الذري أسفل.","","العدد 21 هو عدد النيوترونات وليس العدد الكتلي.","العدد 21 المكتوب أسفل الرمز ليس العدد الذري؛ فالعدد الذري هو 19."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.736Z"}'::jsonb),
('mcq', 6, 2, 'يُسمّى النظير باسم العنصر والعدد الكتلي: كلور-37، وعدد نيوتروناته = 37 − 17 = 20 نيوترونًا.', '["العدد 17 هو العدد الذري وليس جزءًا من الاسم؛ وعدد النيوترونات هو 20 لا 37.","الاسم صحيح، لكن عدد النيوترونات 37 − 17 = 20 وليس 17 (وهو عدد البروتونات).","","العدد 20 هو عدد النيوترونات وليس العدد الكتلي الذي يظهر في الاسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.736Z"}'::jsonb),
('mcq', 7, 0, 'العدد الكتلي = 26 + 31 = 57؛ فالاسم حديد-57، ويُكتب الرمز بالعدد الكتلي أعلى يسار Fe والعدد الذري أسفله: ⁵⁷₂₆Fe.', '["","العدد 31 هو عدد النيوترونات وليس العدد الكتلي الذي يُستعمل في الاسم والرمز.","العدد 26 هو العدد الذري، وقد جُعل هنا العدد الكتلي، وكُتب 31 أسفل الرمز خطأً.","الاسم صحيح لكن موضعا العددين في الرمز مبدّلان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.736Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُسمّى النظير باسم العنصر والعدد الكتلي، ويُكتب رمزه بالعدد الكتلي أعلى يسار رمز العنصر والعدد الذري أسفل يساره. الكالسيوم: الاسم كالسيوم-46 والرمز ⁴⁶₂₀Ca. الحديد: الاسم حديد-57 والرمز ⁵⁷₂₆Fe. الزئبق: الاسم زئبق-204 والرمز ²⁰⁴₈₀Hg.', '["كالسيوم-46 و ⁴⁶₂₀Ca","حديد-57 و ⁵⁷₂₆Fe","زئبق-204 و ²⁰⁴₈₀Hg","العدد الكتلي أعلى والعدد الذري أسفل"]'::jsonb, '["الاسم = اسم العنصر - العدد الكتلي","الرمز: العدد الكتلي أعلى يسار الرمز والعدد الذري أسفل يساره","Ca: كالسيوم-46 و ⁴⁶₂₀Ca","Fe: حديد-57 و ⁵⁷₂₆Fe","Hg: زئبق-204 و ²⁰⁴₈₀Hg"]'::jsonb, '[{"element":"اسم النظير والرمز للكالسيوم","marks":2},{"element":"اسم النظير والرمز للحديد","marks":2},{"element":"اسم النظير والرمز للزئبق","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأسماء والرموز الثلاثة صحيحة بمواضع الأعداد الصحيحة"},{"level":"4–5 درجات","description":"خطأ واحد في اسم أو رمز"},{"level":"1–3 درجات","description":"عنصر واحد صحيح أو أخطاء متعددة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل موضعي العدد الكتلي والعدد الذري","استعمال العدد الذري في الاسم بدل العدد الكتلي","نسيان كتابة العدد الذري أسفل الرمز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.736Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العدد الذري = عدد البروتونات، والعدد الكتلي = عدد البروتونات + عدد النيوترونات. (a) العدد الكتلي 11 + 12 = 23، فالاسم صوديوم-23 والرمز ²³₁₁Na. (b) العدد الكتلي 17 + 18 = 35، فالاسم كلور-35 والرمز ³⁵₁₇Cl. (c) العدد الكتلي 6 + 8 = 14، فالاسم كربون-14 والرمز ¹⁴₆C.', '["صوديوم-23 و ²³₁₁Na","كلور-35 و ³⁵₁₇Cl","كربون-14 و ¹⁴₆C","حساب العدد الكتلي بجمع البروتونات والنيوترونات"]'::jsonb, '["العدد الكتلي = عدد البروتونات + عدد النيوترونات","(a) 11 + 12 = 23 → صوديوم-23، ²³₁₁Na","(b) 17 + 18 = 35 → كلور-35، ³⁵₁₇Cl","(c) 6 + 8 = 14 → كربون-14، ¹⁴₆C"]'::jsonb, '[{"element":"الفرع (a): العدد الكتلي والاسم والرمز","marks":2},{"element":"الفرع (b): العدد الكتلي والاسم والرمز","marks":2},{"element":"الفرع (c): العدد الكتلي والاسم والرمز","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الفروع الثلاثة صحيحة كاملة"},{"level":"4–5 درجات","description":"خطأ جزئي واحد"},{"level":"1–3 درجات","description":"فرع واحد صحيح أو أخطاء متعددة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة عدد النيوترونات في الاسم بدل العدد الكتلي","تبديل موضعي العددين في الرمز","الخطأ في جمع البروتونات والنيوترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.736Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العدد 65 المكتوب أعلى الرمز هو العدد الكتلي، أي مجموع البروتونات والنيوترونات، والعدد 29 المكتوب أسفله هو العدد الذري، أي عدد البروتونات. عدد البروتونات = 29. عدد الإلكترونات في الذرة المتعادلة = 29. عدد النيوترونات = 65 − 29 = 36. اسم النظير نحاس-65.', '["65 هو العدد الكتلي","29 هو العدد الذري = عدد البروتونات","عدد الإلكترونات 29","عدد النيوترونات 36","الاسم نحاس-65"]'::jsonb, '["العدد الكتلي = 65 والعدد الذري = 29","عدد البروتونات = 29 وعدد الإلكترونات = 29","عدد النيوترونات = 65 − 29 = 36","الاسم: نحاس-65"]'::jsonb, '[{"element":"دلالة العددين 65 و29","marks":2},{"element":"عدد البروتونات والإلكترونات","marks":1},{"element":"عدد النيوترونات 36","marks":1},{"element":"الاسم نحاس-65","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"3–4 درجات","description":"عنصر أو عنصران ناقصان أو خطأ حسابي"},{"level":"1–2 درجة","description":"معلومات جزئية صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار 65 هو العدد الذري","حساب عدد النيوترونات بجمع العددين","تسمية النظير نحاس-29"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.736Z"}'::jsonb)
