('mcq', 2, 'للنيتروجين نظيران في الطبيعة هما نيتروجين-14 ونيتروجين-15، وكتلته الذرية 14.007 amu. أيّ النظيرين نسبة وجوده أكبر، ولماذا؟', null, '["نيتروجين-15، لأن كتلته أكبر","النظيران متساويان في نسبة الوجود","لا يمكن تحديد ذلك دون حساب دقيق","نيتروجين-14، لأن الكتلة الذرية أقرب إلى كتلته"]'::jsonb, 'تحليل', 'تحديد النظير الأكثر وجودًا', 'متوسط', 'الكتاب ص 95 — مسألة تدريبية 19'),
('mcq', 3, 'للبروم نظيران: بروم-79 كتلته 78.918 amu وبروم-81 كتلته 80.917 amu، والكتلة الذرية للبروم 79.904 amu. أيّ العبارات الآتية صحيحة؟', null, '["بروم-81 هو الأكثر وجودًا لأن كتلته أكبر","بروم-79 هو الأكثر وجودًا لأن الكتلة الذرية أقل من منتصف كتلتي النظيرين (79.918 amu)","الكتلة الذرية قريبة من 80 amu، فالأكثر وجودًا نظير بروم-80","النظيران بنسبتي وجود متساويتين تمامًا"]'::jsonb, 'تحليل', 'استدلال من قيم الكتل', 'صعب', 'الكتاب ص 94 — البروم-79 والبروم-81'),
('mcq', 4, 'لعنصر X نظيران كتلتاهما 24.0 amu و26.0 amu، والكتلة الذرية للعنصر 24.3 amu. أيّ النظيرين هو الأكثر وجودًا؟', null, '["النظير الذي كتلته 26.0 amu","النظيران متساويان في نسبة الوجود","النظير الذي كتلته 24.0 amu","لا يمكن تحديد ذلك من البيانات"]'::jsonb, 'تحليل', 'تحديد النظير الأكثر وجودًا', 'سهل', 'الكتاب ص 94 — نسبة النظائر'),
('mcq', 5, 'يبيّن الجدول نظائر النيون ونسبة وجودها. أيّ النظائر أكثر وجودًا، وما أقرب عدد صحيح للكتلة الذرية للنيون؟', '{"headers":["النظير","الكتلة (amu)","نسبة الوجود"],"rows":[["نيون-20","19.992","90.48%"],["نيون-21","20.994","0.27%"],["نيون-22","21.991","9.25%"]]}'::jsonb, '["نيون-22، والعدد 22","نيون-20، والعدد 20","نيون-21، والعدد 21","نيون-20، والعدد 21"]'::jsonb, 'تحليل', 'تحليل جدول نسب الوجود', 'متوسط', 'الكتاب ص 94 — الكتلة الذرية المتوسطة'),
('mcq', 6, 'عندما تكون الكتلة الذرية لعنصر أقرب إلى كتلة أحد نظائره منها إلى كتل النظائر الأخرى، فماذا يدل ذلك؟', null, '["أن هذا النظير يحوي أكبر عدد من النيوترونات","أن هذا النظير هو الأقل وجودًا في الطبيعة","أن العنصر ليس له نظائر أخرى","أن هذا النظير هو الأكثر وجودًا في الطبيعة"]'::jsonb, 'فهم', 'تعميم من علاقة الكتلة بالوجود', 'سهل', 'الكتاب ص 94 — نسبة النظائر'),
('mcq', 7, 'لعنصر نظيران كتلتاهما 10.0 amu و11.0 amu، وكتلته الذرية 10.2 amu. ما نسبة وجود النظير الأخف تقريبًا؟', null, '["20%","50%","80%","100%"]'::jsonb, 'تحليل', 'تقدير نسبة وجود من الكتلة الذرية', 'صعب', 'الكتاب ص 94 — نسبة النظائر'),
('essay', 1, 'للنيتروجين نظيران في الطبيعة هما نيتروجين-14 (كتلته 14.003 amu) ونيتروجين-15 (كتلته 15.000 amu)، والكتلة الذرية للنيتروجين 14.007 amu. حدّد أيّ النظيرين هو الأكثر وجودًا مع التعليل، ثم قدّر نسبة وجود نيتروجين-15 تقريبًا.', null, null, 'تحليل', 'استدلال وحساب', 'صعب', 'الكتاب ص 95 — مسألة تدريبية 19'),
('essay', 2, 'قال طالب: الكتلة الذرية للبروم 79.904 amu وهي قريبة من 80 amu، لذلك فإن بروم-80 هو النظير الأكثر وجودًا في الطبيعة. يوجد للبروم نظيران فقط هما بروم-79 (كتلته 78.918 amu) وبروم-81 (كتلته 80.917 amu). قيّم قول الطالب، ثم حدّد أيّ النظيرين أكثر وجودًا مع التعليل.', null, null, 'تقويم', 'تقييم استدلال', 'صعب', 'الكتاب ص 94 — البروم-79 والبروم-81'),
('essay', 3, 'للسيليكون Si ثلاثة نظائر: سيليكون-28 كتلته 27.977 amu ونسبة وجوده 92.23%، وسيليكون-29 كتلته 28.976 amu ونسبة وجوده 4.68%، وسيليكون-30 كتلته 29.974 amu ونسبة وجوده 3.09%. احسب الكتلة الذرية للسيليكون، ثم حدّد النظير الأكثر وجودًا وبيّن علاقته بقيمة الكتلة الذرية.', null, null, 'تطبيق', 'حساب وتحديد النظير الأكثر وجودًا', 'متوسط', 'الكتاب ص 94 — نسبة النظائر، ص 95 — المثال 3-3')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
