from (values
('mcq', 1, 0, 'الكتلة الذرية متوسط كتل النظائر وتقترب من كتلة النظير الأكثر وجودًا؛ وبما أن كتلة الفلور الذرية قريبة من 19 amu فالنظير الموجود في الطبيعة على الأرجح هو فلور-19.', '["","لو كان فلور-18 هو الأكثر وجودًا لاقتربت الكتلة الذرية من 18 amu.","لو كان فلور-20 هو الأكثر وجودًا لاقتربت الكتلة الذرية من 20 amu.","لو كان فلور-17 هو الأكثر وجودًا لاقتربت الكتلة الذرية من 17 amu."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.737Z"}'::jsonb),
('mcq', 2, 3, 'الكتلة الذرية للنيتروجين (14.007 amu) أقرب بكثير إلى 14 منها إلى 15، وهذا يدل على أن النظير الأكثر وجودًا هو نيتروجين-14.', '["لو كان نيتروجين-15 الأكثر وجودًا لاقتربت الكتلة الذرية من 15 amu.","لو تساوت النسبتان لكانت الكتلة الذرية قريبة من 14.5 amu.","يمكن الاستدلال على النظير الأكثر وجودًا من قرب الكتلة الذرية من كتلته دون حساب دقيق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.737Z"}'::jsonb),
('mcq', 3, 1, 'منتصف كتلتي النظيرين = (78.918 + 80.917) ÷ 2 = 79.918 amu، والكتلة الذرية للبروم (79.904 amu) أقل منه قليلًا؛ فهي أقرب إلى كتلة بروم-79، فهو الأكثر وجودًا (بفارق بسيط).', '["لو كان بروم-81 هو الأكثر وجودًا لزادت الكتلة الذرية على منتصف الكتلتين (79.918 amu).","","لا يوجد نظير بروم-80 في الطبيعة؛ والقيمة القريبة من 80 ناتجة عن متوسط النظيرين 79 و81.","لو تساوت النسبتان لكانت الكتلة الذرية مساوية لمنتصف الكتلتين (79.918 amu)، وهي هنا أقل منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:27:04.737Z"}'::jsonb),
('mcq', 4, 2, 'الكتلة الذرية 24.3 amu أقرب كثيرًا إلى 24.0 منها إلى 26.0؛ لذلك النظير الأكثر وجودًا هو الذي كتلته 24.0 amu.', '["لو كان النظير الأثقل هو الأكثر وجودًا لكانت الكتلة الذرية أقرب إلى 26.0 amu.","لو تساوت النسبتان لكانت الكتلة الذرية 25.0 amu (المنتصف).","","البيانات كافية: قرب الكتلة الذرية من كتلة نظير يدل على أنه الأكثر وجودًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.738Z"}'::jsonb),
('mcq', 5, 1, 'أكبر نسبة وجود لنيون-20 (90.48%)، فتقترب الكتلة الذرية من كتلته؛ إذ الكتلة الذرية = 20.18 amu وأقرب عدد صحيح إليها 20.', '["نيون-22 نسبة وجوده 9.25% فقط، وليس الأكثر وجودًا.","","نيون-21 أقل النظائر وجودًا (0.27%) فلا يجذب المتوسط إلى كتلته.","النظير صحيح، لكن الكتلة الذرية 20.18 amu أقرب إلى 20 لا 21."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.738Z"}'::jsonb),
('mcq', 6, 3, 'الكتلة الذرية متوسط مرجَّح بنسب الوجود؛ فالنظير الأكثر وجودًا له التأثير الأكبر في المتوسط، فتقترب الكتلة الذرية من كتلته.', '["عدد النيوترونات يحدد كتلة النظير لا نسبة وجوده، وقد يكون النظير الأقرب هو الأخف.","النظير الأقل وجودًا له أقل تأثير في المتوسط، فتبتعد الكتلة الذرية عن كتلته.","قد توجد نظائر أخرى لكن بنسب قليلة؛ فقرب الكتلة لا يعني انعدام النظائر الأخرى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.738Z"}'::jsonb),
('mcq', 7, 2, 'إذا كانت نسبة النظير الأخف x فإن 10.0x + 11.0(1 − x) = 10.2، ومنه x = 0.8؛ أي أن نسبة وجوده حوالي 80%، وهو النظير الأكثر وجودًا.', '["نسبة 20% للنظير الأخف تعطي كتلة ذرية 10.8 amu، فهذه نسبة النظير الأثقل.","نسبة 50% تعطي كتلة ذرية 10.5 amu، وهي أكبر من 10.2 amu.","","نسبة 100% تعني وجود نظير واحد كتلته 10.0 amu، فتكون الكتلة الذرية 10.0 amu."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.738Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النظير الأكثر وجودًا هو نيتروجين-14؛ لأن الكتلة الذرية (14.007 amu) أقرب إلى كتلته (14.003 amu) بكثير من قربها إلى كتلة نيتروجين-15 (15.000 amu)، والكتلة الذرية متوسط يقترب من كتلة النظير الأكثر وجودًا. وبافتراض أن نسبة نيتروجين-15 هي y فإن 15.000y + 14.003(1 − y) = 14.007، ومنه y = (14.007 − 14.003) ÷ (15.000 − 14.003) ≈ 0.004، أي نسبته حوالي 0.4% فقط.', '["النظير الأكثر وجودًا نيتروجين-14","التعليل: الكتلة الذرية أقرب إلى كتلته","تكوين المعادلة 15.000y + 14.003(1 − y) = 14.007","نسبة نيتروجين-15 ≈ 0.4%"]'::jsonb, '["الكتلة الذرية 14.007 أقرب إلى 14.003 منها إلى 15.000 فنيتروجين-14 أكثر وجودًا","نفرض نسبة نيتروجين-15 هي y ونسبة نيتروجين-14 هي 1 − y","15.000y + 14.003(1 − y) = 14.007","y = (14.007 − 14.003) ÷ 0.997 ≈ 0.0040","نسبة نيتروجين-15 ≈ 0.40%"]'::jsonb, '[{"element":"تحديد نيتروجين-14 هو الأكثر وجودًا","marks":1},{"element":"التعليل بقرب الكتلة الذرية من كتلته","marks":1},{"element":"تكوين المعادلة الصحيحة","marks":1},{"element":"الناتج ≈ 0.4%","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد وتعليل ومعادلة وناتج صحيحة"},{"level":"2–3 درجات","description":"تحديد وتعليل صحيحان مع نقص في الحساب"},{"level":"1 درجة","description":"تحديد النظير دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار النظير الأثقل لأن كتلته أكبر","عدم الانتباه إلى أن الكتلة الذرية تقترب من النظير الأكثر وجودًا","نسيان تحويل النسبة إلى مئوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.739Z"}'::jsonb),
('essay', 2, null::int, null, null, 'قول الطالب غير صحيح؛ لأن بروم-80 غير موجود في الطبيعة، ولبروم نظيران فقط هما 79 و81. الكتلة الذرية 79.904 amu متوسط لكتلتي النظيرين وليست كتلة نظير بعينه. منتصف الكتلتين = (78.918 + 80.917) ÷ 2 = 79.918 amu، والكتلة الذرية أقل منه قليلًا؛ فهي أقرب إلى كتلة بروم-79، لذلك فإن بروم-79 هو الأكثر وجودًا بفارق بسيط عن بروم-81.', '["قول الطالب غير صحيح","بروم-80 غير موجود في الطبيعة","الكتلة الذرية متوسط لكتلتي النظيرين","منتصف الكتلتين 79.918 amu والكتلة الذرية أقل منه","بروم-79 هو الأكثر وجودًا"]'::jsonb, '["منتصف الكتلتين = (78.918 + 80.917) ÷ 2 = 79.918 amu","الكتلة الذرية 79.904 amu أقل من المنتصف","فهي أقرب إلى بروم-79","إذن بروم-79 هو الأكثر وجودًا"]'::jsonb, '[{"element":"تخطئة قول الطالب وتعليله بأن بروم-80 غير موجود","marks":2},{"element":"توضيح أن الكتلة الذرية متوسط","marks":1},{"element":"حساب منتصف الكتلتين ومقارنته بالكتلة الذرية","marks":1},{"element":"تحديد بروم-79 الأكثر وجودًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"نقد صحيح وحساب وتحديد صحيحان"},{"level":"3–4 درجات","description":"نقد صحيح مع نقص في الحساب أو التحديد"},{"level":"1–2 درجة","description":"ملاحظة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول وجود نظير كتلته قريبة من الكتلة الذرية","اختيار بروم-81 لأن كتلته أكبر","عدم مقارنة الكتلة الذرية بمنتصف الكتلتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:27:04.739Z"}'::jsonb),
('essay', 3, null::int, null, null, 'إسهام سيليكون-28 = 0.9223 × 27.977 = 25.80 amu. إسهام سيليكون-29 = 0.0468 × 28.976 = 1.36 amu. إسهام سيليكون-30 = 0.0309 × 29.974 = 0.93 amu. الكتلة الذرية = 25.80 + 1.36 + 0.93 = 28.09 amu. النظير الأكثر وجودًا هو سيليكون-28 (92.23%)، ولذلك فالكتلة الذرية (28.09 amu) قريبة جدًا من كتلته (27.977 amu).', '["إسهام سيليكون-28 = 25.80 amu","إسهام سيليكون-29 = 1.36 amu","إسهام سيليكون-30 = 0.93 amu","الكتلة الذرية = 28.09 amu","الأكثر وجودًا سيليكون-28 وكتلته قريبة من الكتلة الذرية"]'::jsonb, '["0.9223 × 27.977 = 25.80 amu","0.0468 × 28.976 = 1.36 amu","0.0309 × 29.974 = 0.93 amu","الكتلة الذرية = 25.80 + 1.36 + 0.93 = 28.09 amu","سيليكون-28 الأكثر وجودًا والكتلة الذرية قريبة من كتلته"]'::jsonb, '[{"element":"إسهامات النظائر الثلاثة","marks":3},{"element":"الكتلة الذرية 28.09 amu","marks":1},{"element":"تحديد النظير الأكثر وجودًا وربطه بالكتلة الذرية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب كامل وصحيح مع تحديد النظير والربط"},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في الربط أو خطأ بسيط"},{"level":"1–2 درجة","description":"إسهام أو إسهامان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل النسب المئوية إلى كسور","إهمال أحد النظائر في الحساب","عدم ربط النظير الأكثر وجودًا بقرب الكتلة الذرية من كتلته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.739Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
