from (values
('mcq', 1, 'ما سبب تشابه نظائر العنصر الواحد في سلوكها الكيميائي رغم اختلاف كتلها؟', null, '["لأن لها الكتلة نفسها في جميع ذراتها","لأن عدد الإلكترونات المحدد للسلوك الكيميائي متساوٍ في ذراتها","لأن لها عدد النيوترونات نفسه في جميع ذراتها","لأنها تختلف في عدد البروتونات فقط دون غيره"]'::jsonb, 'فهم', 'تفسير تشابه السلوك الكيميائي', 'متوسط', 'الكتاب ص 91 — كتلة النظائر'),
('mcq', 2, 'أيّ مما يأتي يحدد السلوك الكيميائي للذرة؟', null, '["عدد النيوترونات في النواة","الكتلة الذرية للعنصر","عدد الإلكترونات في الذرة","العدد الكتلي للذرة"]'::jsonb, 'تذكر', 'تذكر ما يحدد السلوك الكيميائي', 'سهل', 'الكتاب ص 91 — كتلة النظائر'),
('mcq', 3, 'لماذا لا يؤدي اختلاف عدد النيوترونات بين النظائر إلى اختلاف سلوكها الكيميائي؟', null, '["لأن النيوترونات متعادلة ولا تغير عدد الإلكترونات في الذرة","لأن النيوترونات تزيد عدد الإلكترونات بالقدر نفسه","لأن كتلة النيوترونات صغيرة جدًا فلا تؤثر","لأن النيوترونات تقع خارج الذرة"]'::jsonb, 'فهم', 'تفسير أثر النيوترونات', 'متوسط', 'الكتاب ص 91 — كتلة النظائر'),
('mcq', 4, 'تتفاعل ذرات كلور-35 وكلور-37 مع فلز الصوديوم لتكوين كلوريد الصوديوم. ما المتوقع بشأن سلوكهما الكيميائي؟', null, '["يتفاعل نظير كلور-35 وحده مع الصوديوم","يتفاعل نظير كلور-37 وحده مع الصوديوم","يتفاعلان بطريقتين مختلفتين تمامًا عن بعضهما","يتفاعلان بالطريقة نفسها لأن لكل منهما 17 إلكترونًا"]'::jsonb, 'تطبيق', 'تطبيق على موقف تفاعل', 'صعب', 'الكتاب ص 91 — النظائر والسلوك الكيميائي'),
('mcq', 5, 'يبيّن الجدول عدد الجسيمات في ذرات ثلاثة نظائر متعادلة للبوتاسيوم. أيّ المعلومات الآتية تفسّر تشابهها في السلوك الكيميائي؟', '{"headers":["النظير","البروتونات","النيوترونات","الإلكترونات"],"rows":[["بوتاسيوم-39","19","20","19"],["بوتاسيوم-40","19","21","19"],["بوتاسيوم-41","19","22","19"]]}'::jsonb, '["تساوي عدد الإلكترونات (19) في الثلاثة","ازدياد عدد النيوترونات من نظير إلى آخر","اختلاف كتل النظائر الثلاثة فيما بينها","ازدياد العدد الكتلي من نظير إلى آخر"]'::jsonb, 'فهم', 'تفسير من بيانات', 'متوسط', 'الكتاب ص 91 — الشكل 3-17'),
('mcq', 6, 'أيّ جزء من فرضية دالتون تبيّن النظائر أنه غير صحيح؟', null, '["أن المادة تتكون من ذرات","أن ذرات العنصر تختلف عن ذرات العناصر الأخرى","أن جميع ذرات العنصر الواحد متماثلة في الكتلة","أن الذرات تتحد معًا بنسب عددية بسيطة ثابتة"]'::jsonb, 'فهم', 'ربط النظائر بفرضية دالتون', 'متوسط', 'الكتاب ص 91 — فرضية دالتون والنظائر'),
('mcq', 7, 'أيّ الزوجين الآتيين من الذرات يُتوقع أن يتشابه سلوكهما الكيميائي تشابهًا كبيرًا؟', null, '["كربون-12 ونيتروجين-14","كلور-35 وأرجون-40","صوديوم-23 ومغنيسيوم-24","كربون-12 وكربون-14"]'::jsonb, 'تطبيق', 'تمييز ذرات متشابهة السلوك', 'صعب', 'الكتاب ص 91 — النظائر والسلوك الكيميائي'),
('essay', 1, 'تختلف كتلة ذرة كلور-37 عن كتلة ذرة كلور-35، ومع ذلك يتشابه سلوكهما الكيميائي. فسّر سبب اختلاف الكتلتين، وسبب تشابه السلوك الكيميائي، مستعينًا بعدد كل من البروتونات والنيوترونات والإلكترونات في ذرة كل منهما (العدد الذري للكلور 17).', null, null, 'فهم', 'تفسير الاختلاف والتشابه', 'متوسط', 'الكتاب ص 91 — كتلة النظائر، ص 93 — الشكل 3-18'),
('essay', 2, 'حدّد ما يتغير وما يبقى ثابتًا بين نظائر البوتاسيوم الثلاثة (بوتاسيوم-39 وبوتاسيوم-40 وبوتاسيوم-41) من حيث عدد البروتونات وعدد النيوترونات وعدد الإلكترونات والكتلة، ثم بيّن كيف يخالف وجود النظائر فرضية دالتون القائلة إن جميع ذرات العنصر الواحد متماثلة.', null, null, 'تحليل', 'تحليل مقارن وربط بنموذج دالتون', 'صعب', 'الكتاب ص 91 — الشكل 3-17 والنظائر'),
('essay', 3, 'قال طالب: نظير الكربون الأثقل كتلة يجب أن يكون أكثر نشاطًا كيميائيًا من النظير الأخف لأن كتلته أكبر. قيّم قول الطالب، موضحًا ما الذي يحدد السلوك الكيميائي لنظائر الكربون.', null, null, 'تقويم', 'نقد استدلال خاطئ', 'صعب', 'الكتاب ص 91 — النظائر والسلوك الكيميائي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
