from (values
('mcq', 1, 1, 'نظائر العنصر الواحد لها عدد البروتونات نفسه، فيكون عدد الإلكترونات في ذراتها المتعادلة نفسه؛ والسلوك الكيميائي يحدده عدد الإلكترونات، لذلك تتشابه في السلوك رغم اختلاف كتلها.', '["النظائر تختلف في الكتلة لاختلاف عدد النيوترونات، وليس السبب تساوي الكتلة.","","النظائر تختلف في عدد النيوترونات ولا تتساوى فيه، وهو سبب اختلاف كتلها.","النظائر لا تختلف في عدد البروتونات؛ فاختلاف عدد البروتونات يعني اختلاف العنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.740Z"}'::jsonb),
('mcq', 2, 2, 'السلوك الكيميائي للذرة يحدده عدد الإلكترونات الموجودة فيها؛ إذ تشارك الإلكترونات وحدها في التفاعلات الكيميائية.', '["النيوترونات لا تشارك في التفاعلات الكيميائية، واختلافها بين النظائر لا يغير السلوك الكيميائي.","الكتلة الذرية تختلف بين النظائر دون أن يتغير السلوك الكيميائي، فهي لا تحدده.","","العدد الكتلي يتضمن النيوترونات ويختلف بين النظائر دون أن يتغير السلوك الكيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.740Z"}'::jsonb),
('mcq', 3, 0, 'النيوترونات جسيمات متعادلة الشحنة في النواة، ولا تغير عدد البروتونات ولا عدد الإلكترونات؛ فيبقى عدد الإلكترونات (المحدد للسلوك الكيميائي) ثابتًا.', '["","زيادة النيوترونات لا تضيف إلكترونات؛ فعدد الإلكترونات يساوي عدد البروتونات في الذرة المتعادلة.","كتلة النيوترون ليست صغيرة (حوالي 1 amu)، وسبب عدم التأثير هو عدم تغير عدد الإلكترونات.","النيوترونات تقع داخل النواة مع البروتونات وليست خارج الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.740Z"}'::jsonb),
('mcq', 4, 3, 'النظيران لعنصر واحد (العدد الذري 17)، فلكل منهما 17 إلكترونًا في الذرة المتعادلة؛ لذلك يتشابه سلوكهما الكيميائي ويتفاعلان بالطريقة نفسها مع الصوديوم.', '["كلور-37 له عدد الإلكترونات نفسه، فيتفاعل أيضًا.","كلور-35 له عدد الإلكترونات نفسه، فيتفاعل أيضًا.","اختلاف الكتلة لا يؤدي إلى اختلاف الطريقة؛ فعدد الإلكترونات واحد في النظيرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.740Z"}'::jsonb),
('mcq', 5, 0, 'السلوك الكيميائي يحدده عدد الإلكترونات، وهو متساوٍ (19) في الذرات الثلاث؛ لذلك تتشابه في سلوكها الكيميائي رغم اختلاف عدد النيوترونات والكتلة.', '["","ازدياد النيوترونات يفسّر اختلاف الكتلة لا تشابه السلوك الكيميائي.","اختلاف الكتل لا يفسّر التشابه؛ بل هو أحد وجوه الاختلاف بين النظائر.","ازدياد العدد الكتلي سببه زيادة النيوترونات وهو وجه اختلاف لا سبب تشابه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.740Z"}'::jsonb),
('mcq', 6, 2, 'النظائر ذرات للعنصر نفسه تختلف في عدد النيوترونات، فتختلف في الكتلة؛ وهذا يخالف اعتقاد دالتون أن ذرات العنصر الواحد متماثلة.', '["وجود النظائر لا ينفي أن المادة تتكون من ذرات.","ذرات العناصر تختلف فعلًا في عدد البروتونات؛ والنظائر لا تنفي ذلك.","","اتحاد الذرات بنسب بسيطة لا تتأثر بوجود النظائر ولا تتعارض معها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.741Z"}'::jsonb),
('mcq', 7, 3, 'كربون-12 وكربون-14 نظيران للعنصر نفسه (العدد الذري 6)، فلهما العدد نفسه من الإلكترونات وبالتالي السلوك الكيميائي نفسه؛ أما الأزواج الأخرى فمن عناصر مختلفة.', '["الكربون والنيتروجين عنصران مختلفان (6 و7 إلكترونات)، فلا يتشابه سلوكهما.","الكلور والأرجون عنصران مختلفان (17 و18 إلكترونًا)، فلا يتشابه سلوكهما.","الصوديوم والمغنيسيوم عنصران مختلفان (11 و12 إلكترونًا) رغم تقارب كتلتيهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.741Z"}'::jsonb),
('essay', 1, null::int, null, null, 'كلور-35 يحوي 17 بروتونًا و18 نيوترونًا و17 إلكترونًا، وكلور-37 يحوي 17 بروتونًا و20 نيوترونًا و17 إلكترونًا. تختلف الكتلتان لأن عدد النيوترونات يختلف (18 و20) والنيوترونات تسهم في كتلة الذرة بنحو 1 amu لكل نيوترون. ويتشابه السلوك الكيميائي لأن السلوك الكيميائي يحدده عدد الإلكترونات، وهو متساوٍ (17) في الذرتين؛ فالنيوترونات لا تغير عدد الإلكترونات.', '["عدد البروتونات والإلكترونات 17 في كل منهما","عدد النيوترونات 18 و20","اختلاف الكتلة سببه اختلاف عدد النيوترونات","السلوك الكيميائي يحدده عدد الإلكترونات وهو متساوٍ"]'::jsonb, '["كلور-35: نيوترونات = 35 − 17 = 18","كلور-37: نيوترونات = 37 − 17 = 20","البروتونات والإلكترونات = 17 في كل منهما"]'::jsonb, '[{"element":"عدد الجسيمات الثلاثة في النظيرين","marks":2},{"element":"تفسير اختلاف الكتلة بالنيوترونات","marks":1},{"element":"تفسير تشابه السلوك بتساوي عدد الإلكترونات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأعداد صحيحة مع تفسيري الاختلاف والتشابه"},{"level":"3–4 درجات","description":"تفسير صحيح لأحد الجانبين مع أعداد صحيحة"},{"level":"1–2 درجة","description":"معلومات جزئية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير تشابه السلوك بتساوي الكتلة","القول إن النيوترونات هي التي تحدد السلوك الكيميائي","الخطأ في حساب عدد النيوترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.741Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الثابت بين النظائر الثلاثة: عدد البروتونات (19) وعدد الإلكترونات في الذرة المتعادلة (19). المتغير: عدد النيوترونات (20 و21 و22) وبالتالي العدد الكتلي والكتلة (39 و40 و41). السلوك الكيميائي متشابه لأن عدد الإلكترونات متساوٍ. أما فرضية دالتون فتفترض تماثل ذرات العنصر الواحد، لكن النظائر ذرات للعنصر نفسه تختلف في عدد النيوترونات وفي الكتلة، فهي غير متماثلة؛ فالفرضية غير صحيحة.', '["الثابت: البروتونات 19 والإلكترونات 19","المتغير: النيوترونات 20 و21 و22","المتغير: العدد الكتلي والكتلة","السلوك الكيميائي متشابه لتساوي الإلكترونات","النظائر تخالف فرضية دالتون بتماثل ذرات العنصر"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الثوابت (البروتونات والإلكترونات)","marks":2},{"element":"تحديد المتغيرات (النيوترونات والكتلة)","marks":2},{"element":"ذكر تشابه السلوك الكيميائي وتعليله","marks":1},{"element":"بيان مخالفة فرضية دالتون","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"جميع العناصر صحيحة"},{"level":"4–5 درجات","description":"نقص في عنصر أو عنصرين"},{"level":"1–3 درجات","description":"تحديد جزئي للثوابت والمتغيرات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عدد البروتونات يتغير بين النظائر","إغفال أن الكتلة تتغير مع عدد النيوترونات","عدم ربط النظائر بمخالفة فرضية دالتون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.742Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. نظائر الكربون ذرات لعنصر واحد، لها العدد نفسه من البروتونات (6) وبالتالي العدد نفسه من الإلكترونات في الذرة المتعادلة (6)، وتختلف في عدد النيوترونات فقط، وهذا يجعل كتلها مختلفة. والسلوك الكيميائي يحدده عدد الإلكترونات لا الكتلة؛ لذلك يتشابه سلوك النظير الأثقل والنظير الأخف.', '["قول الطالب غير صحيح","النظائر لها عدد البروتونات والإلكترونات نفسه (6)","تختلف في النيوترونات فتختلف في الكتلة","السلوك الكيميائي يحدده عدد الإلكترونات لا الكتلة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بخطأ قول الطالب","marks":1},{"element":"بيان تساوي عدد البروتونات والإلكترونات في النظائر","marks":1},{"element":"بيان أن الاختلاف في النيوترونات والكتلة فقط","marks":1},{"element":"ذكر أن السلوك الكيميائي يحدده عدد الإلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقييم صحيح مع تعليل كامل"},{"level":"2–3 درجات","description":"تقييم صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الربط بين الكتلة الكبيرة والنشاط الكيميائي","القول إن النيوترونات تحدد السلوك الكيميائي","اعتبار الكربون-12 والكربون-14 عنصرين مختلفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.742Z"}'::jsonb)
