('mcq', 1, 2, 'اكتشف موزلي أن ذرات كل عنصر تحوي عددًا معينًا من البروتونات (الشحنات الموجبة) في نواتها، وأن هذا العدد (العدد الذري) يميز العنصر عن غيره.', '["اكتشاف الإلكترون يُنسب إلى طومسون وليس إلى موزلي.","اكتشاف النواة الموجبة يُنسب إلى رذرفورد وليس إلى موزلي.","","اكتشاف النيوترون يُنسب إلى عالم آخر ولا علاقة له بإسهام موزلي في تحديد هوية العنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.743Z"}'::jsonb),
('mcq', 2, 0, 'هنري موزلي هو العالم الذي اكتشف أن ذرات كل عنصر تحوي عددًا معينًا من البروتونات، وهو العدد الذري الذي يميز العنصر.', '["","دالتون وضع نظريته الذرية، واعتقد خطأً أن ذرات العنصر الواحد متشابهة تمامًا.","طومسون اكتشف الإلكترون واقترح نموذجه للذرة، ولم يحدد عدد البروتونات المميز للعنصر.","رذرفورد اكتشف النواة، أما العدد المميز للعنصر من البروتونات فاكتشفه موزلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.743Z"}'::jsonb),
('mcq', 3, 3, 'العدد المميز للعنصر الذي اكتشفه موزلي هو عدد البروتونات في النواة، ويُسمّى العدد الذري.', '["العدد الكتلي مجموع البروتونات والنيوترونات، وهو يختلف بين نظائر العنصر الواحد فلا يميز العنصر.","عدد النيوترونات يختلف في ذرات العنصر الواحد (النظائر) فلا يميز العنصر.","الكتلة الذرية متوسط كتل النظائر، وليست العدد الذي ميّز به موزلي العناصر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.743Z"}'::jsonb),
('mcq', 4, 1, 'ذرة كل عنصر تحوي عددًا معينًا من البروتونات في نواتها، وهو الذي يميزها عن ذرة أي عنصر آخر.', '["عدد النيوترونات قد يختلف في ذرات العنصر الواحد (النظائر)، فلا يميز عنصرًا عن آخر.","","الكتلة تختلف بين نظائر العنصر الواحد، فلا تحدد هوية العنصر.","الحجم لا يحدد هوية العنصر، وليس هو ما اكتشفه موزلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.743Z"}'::jsonb),
('mcq', 5, 3, 'ما يُنسب إلى موزلي هو أن ذرات كل عنصر تحوي عددًا معينًا من البروتونات في النواة، يميز العنصر عن غيره.', '["هذا وصف نموذج طومسون للذرة وليس اكتشاف موزلي.","هذا اعتقاد دالتون، وقد تبيّن عدم دقته بعد اكتشاف الجسيمات دون الذرية والنظائر.","هذا وصف نموذج رذرفورد للذرة وليس اكتشاف موزلي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.743Z"}'::jsonb),
('mcq', 6, 0, 'تُرتَّب العناصر في الجدول الدوري تصاعديًا بحسب أعدادها الذرية (عدد البروتونات)، وهو الذي ميّز به موزلي العناصر.', '["","الكتلة الذرية ليست أساس الترتيب في الجدول الدوري الحديث، فهي متوسط كتل النظائر.","العدد الكتلي يخص نظيرًا معينًا ويختلف بين نظائر العنصر الواحد، فلا يصلح أساسًا للترتيب.","عدد النيوترونات يختلف في ذرات العنصر الواحد، فلا يصلح أساسًا لترتيب العناصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.743Z"}'::jsonb),
('mcq', 7, 1, 'عدد البروتونات (العدد الذري) هو الذي يحدد نوع العنصر؛ وبما أنه 12 في الذرتين فهما للعنصر نفسه (المغنيسيوم)، ويختلفان في عدد النيوترونات (نظيران).', '["اختلاف الكتلة بسبب النيوترونات لا يغيّر العنصر؛ فهوية العنصر يحددها عدد البروتونات.","","اختلاف عدد النيوترونات يعني نظيرين لعنصر واحد، لا عنصرين مختلفين.","يمكن الحكم؛ فتساوي عدد البروتونات يكفي لتحديد أن الذرتين للعنصر نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.744Z"}'::jsonb),
('essay', 1, null::int, null, null, 'اكتشف هنري موزلي أن ذرات كل عنصر تحوي عددًا معينًا من البروتونات (الشحنات الموجبة) في نواتها، وأن هذا العدد يميز العنصر عن غيره، ويُسمّى العدد الذري. يُستعمل العدد الذري في تحديد نوع الذرة؛ فإذا عُرف عدد البروتونات في الذرة عُرف عددها الذري ومن ثم العنصر الذي تنتمي إليه، فالذرة التي تحوي 8 بروتونات مثلًا هي ذرة أكسجين.', '["اكتشف أن لذرات كل عنصر عددًا معينًا من البروتونات في النواة","هذا العدد يميز العنصر ويُسمّى العدد الذري","معرفة عدد البروتونات تحدد نوع الذرة","مثال: 8 بروتونات تعني الأكسجين"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر اكتشاف موزلي (عدد معين من البروتونات لكل عنصر)","marks":2},{"element":"تسمية العدد بالعدد الذري ودوره في التمييز","marks":1},{"element":"توضيح تحديد نوع الذرة بعدد البروتونات مع مثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر المساهمة والتسمية والتوضيح بمثال"},{"level":"2–3 درجات","description":"ذكر المساهمة مع نقص في التوضيح"},{"level":"1 درجة","description":"ذكر معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة اكتشاف الإلكترون أو النواة إلى موزلي","القول إن موزلي اكتشف النيوترونات","الخلط بين العدد الذري والعدد الكتلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.744Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وفق اكتشاف موزلي يحدد عدد البروتونات (العدد الذري) نوع العنصر. للذرتين A وB عدد البروتونات نفسه (11) فهما للعنصر نفسه (الصوديوم) وتختلفان في عدد النيوترونات (12 و13) أي أنهما نظيران. أما الذرة C ففيها 12 بروتونًا فعددها الذري يختلف عن A وB؛ لذلك هي لعنصر مختلف (المغنيسيوم) رغم تساوي عدد نيوتروناتها مع A.', '["A وB للعنصر نفسه لأن بروتونات كل منهما 11","اختلافهما في النيوترونات يعني أنهما نظيران","C لعنصر مختلف لأن بروتوناتها 12","عدد البروتونات هو المحدد لهوية العنصر"]'::jsonb, '["عدد البروتونات يحدد العنصر","A وB: 11 بروتونًا لكل منهما فهما للعنصر نفسه","C: 12 بروتونًا فهي لعنصر مختلف"]'::jsonb, '[{"element":"تحديد A وB للعنصر نفسه مع التعليل بالبروتونات","marks":2},{"element":"تحديد C لعنصر مختلف مع التعليل","marks":2},{"element":"الإشارة إلى أن عدد البروتونات هو المحدد للهوية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للذرات مع تعليل كامل"},{"level":"3–4 درجات","description":"تحديد صحيح مع تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد جزئي دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتماد على عدد النيوترونات في تحديد العنصر","عدّ A وC من العنصر نفسه لتساوي النيوترونات","عدم تعليل الاختيار بعدد البروتونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.744Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لا يكفي العدد الكتلي لتحديد نوع العنصر؛ فالكالسيوم-40 والأرجون-40 لهما العدد الكتلي نفسه (40) لكنهما عنصران مختلفان. وبحسب اكتشاف موزلي فإن عدد البروتونات في النواة (العدد الذري) هو الذي يميز العنصر: للكالسيوم 20 وللأرجون 18. فاختلاف العدد الذري يعني اختلاف العنصر حتى مع تساوي العدد الكتلي، أما العدد الكتلي فيشمل النيوترونات أيضًا التي قد تتغير مع بقاء العنصر نفسه (النظائر).', '["العدد الكتلي أو الكتلة لا يكفي لتحديد العنصر","الكالسيوم-40 والأرجون-40 عنصران مختلفان رغم تساوي العدد الكتلي","العدد الذري (عدد البروتونات) هو المحدد: 20 و18","العدد الكتلي يتضمن النيوترونات التي تتغير في النظائر"]'::jsonb, '[]'::jsonb, '[{"element":"الإجابة بأن العدد الكتلي لا يكفي مع الدليل","marks":1},{"element":"تحديد العدد الذري (20 و18) على أنه الفارق","marks":1},{"element":"الاستناد إلى اكتشاف موزلي في تحديد الهوية بالبروتونات","marks":1},{"element":"تعليل عدم كفاية العدد الكتلي بدخول النيوترونات فيه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع استناد إلى اكتشاف موزلي"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في التعليل"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تساوي العدد الكتلي يعني العنصر نفسه","عدم ذكر العدد الذري على أنه المحدد للهوية","الخلط بين العدد الكتلي والعدد الذري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.744Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C3-L3-O11') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

