select (select id from public.objectives where code = 'K1-C3-L4-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تقتصر المشاركة في التفاعل الكيميائي على أيّ مكوّنات الذرة؟', null, '["البروتونات الموجودة في النواة","إلكترونات الذرة","النيوترونات الموجودة في النواة","النواة بأكملها"]'::jsonb, 'فهم', 'تذكر مفهوم', 'سهل', 'الكتاب ص 96 — النشاط الإشعاعي (التفاعل الكيميائي)'),
('mcq', 2, 'أيّ مما يأتي يميّز التفاعل النووي عن التفاعل الكيميائي؟', null, '["تُعاد فيه ترتيب الذرات مع بقاء هويتها ثابتة","تقتصر فيه التغيرات على إلكترونات الذرة","لا يمكن أن يتكوّن فيه عنصر جديد","يحدث فيه تغير في نواة الذرة قد يحوّل العنصر إلى عنصر آخر"]'::jsonb, 'فهم', 'تمييز خاصية', 'سهل', 'الكتاب ص 96 — التفاعلات النووية'),
('mcq', 3, 'يصدر الثوريوم أشعة بيتا. كيف يُصنَّف هذا التغير؟', null, '["تفاعل نووي لأنه يتضمن تغيرًا في نواة الذرة","تفاعل كيميائي لأنه يتضمن تغيرًا في عدد الإلكترونات","تفاعل كيميائي لأن الذرة تبقى محتفظة بهويتها","ليس تفاعلًا لأن إصدار الأشعة عملية فيزيائية فقط"]'::jsonb, 'تطبيق', 'تصنيف تغير', 'متوسط', 'الكتاب ص 98 — التقويم 3-4 (سؤال 27)'),
('mcq', 4, 'أيّ العمليات الآتية تُعدّ تفاعلًا كيميائيًّا؟', null, '["تحلل الراديوم-226 إلى رادون-222","إصدار الثوريوم أشعة بيتا","تكوّن الصدأ على قطعة من الحديد","تحول الكربون-14 إلى نيتروجين-14"]'::jsonb, 'تحليل', 'تمييز تفاعل كيميائي', 'متوسط', 'الكتاب ص 98 — التقويم 3-4 (سؤال 27)'),
('mcq', 5, 'يبين الجدول خصائص تغيرين (س) و(ص) يحدثان في الذرات. أيّ الاستنتاجات الآتية صحيح؟', '{"headers":["الخاصية","التغير (س)","التغير (ص)"],"rows":[["ما الذي يتغير في الذرة","الإلكترونات المحيطة بالنواة","نواة الذرة"],["هوية العنصر","ثابتة","قد تتغير إلى عنصر آخر"]]}'::jsonb, '["(س) تفاعل نووي و(ص) تفاعل كيميائي","كلاهما تفاعل كيميائي","كلاهما تفاعل نووي","(س) تفاعل كيميائي و(ص) تفاعل نووي"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'متوسط', 'الكتاب ص 98 — الخلاصة'),
('mcq', 6, 'قال طالب: «يمكن أن يحوّل التفاعل الكيميائي عنصرًا إلى عنصر آخر». أيّ الحجج الآتية تدحض قوله؟', null, '["يصدر العنصر إشعاعات فتتحول نواته إلى نواة أخرى","الإلكترونات وحدها تشارك فيه، فتبقى هوية العنصر ثابتة","يتغير فيه عدد البروتونات دون أن تتغير الإلكترونات","تتحول الذرة فيه إلى ذرة مستقرة لعنصر آخر"]'::jsonb, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 96 — النشاط الإشعاعي (التفاعل الكيميائي)'),
('mcq', 7, 'تحلّلت ذرة راديوم-226 إلى ذرة رادون-222، بينما اتحدت ذرتا هيدروجين مع ذرة أكسجين لتكوين الماء. ما الفرق بين التغيرين من حيث هوية العنصر؟', null, '["تغيرت هوية العنصر في الأول لتغير نواته، وبقيت هويات العناصر ثابتة في الثاني","بقيت هوية العنصر ثابتة في الأول، وتغيرت هويات العناصر في الثاني","تغيرت هوية العنصر في التغيرين معًا","بقيت هوية العنصر ثابتة في التغيرين معًا"]'::jsonb, 'تحليل', 'مقارنة تغيرين', 'صعب', 'الكتاب ص 96 — النشاط الإشعاعي'),
('essay', 1, 'قارن بين التفاعل الكيميائي والتفاعل النووي من حيث: ما الذي يتغير في الذرة، ومصير هوية العنصر.', null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 96، 98 — النشاط الإشعاعي والخلاصة'),
('essay', 2, 'صنّف كلًّا مما يأتي إلى: تفاعل كيميائي، أو تفاعل نووي، أو لا شيء منهما، مع التبرير: (أ) الثوريوم يصدر أشعة بيتا. (ب) تشارك ذرتين في الإلكترونات لتكوين رابطة. (ج) عينة من الكبريت النقي تصدر طاقة حرارية عندما تبرد ببطء. (د) تكوّن الصدأ على قطعة من الحديد.', null, null, 'تطبيق', 'تصنيف مع تبرير', 'متوسط', 'الكتاب ص 98 — التقويم 3-4 (سؤال 27)'),
('essay', 3, 'عُدّ اكتشاف التفاعلات النووية اكتشافًا مهمًّا. فسّر ذلك بمقارنة ما تستطيع التفاعلات الكيميائية فعله بما تستطيع التفاعلات النووية فعله بالنسبة لهوية العنصر.', null, null, 'تقويم', 'تفسير أهمية', 'صعب', 'الكتاب ص 96 — التفاعلات النووية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C3-L4-O01') and x.type = v.type and x.number = v.number);
