select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'في التفاعل الكيميائي تشارك إلكترونات الذرة فقط، وقد يُعاد ترتيب الذرات لكن نواتها لا تتغير؛ لذلك الجواب هو إلكترونات الذرة.', '["البروتونات جزء من النواة، والنواة لا تتغير في التفاعل الكيميائي.","","النيوترونات جزء من النواة، والتغير فيها يحدث في التفاعل النووي لا الكيميائي.","التغير في النواة بأكملها من خصائص التفاعل النووي، أما الكيميائي فلا يمسّ النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.745Z"}'::jsonb),
('mcq', 2, 3, 'التفاعل النووي يتضمن تغيرًا في نواة الذرة، وقد يؤدي إلى تحويل عنصر إلى عنصر آخر؛ وهذا ما يميّزه عن التفاعل الكيميائي، لذلك الجواب هو الخيار الأخير.', '["إعادة ترتيب الذرات مع ثبات هويتها صفة التفاعل الكيميائي.","اقتصار التغير على الإلكترونات صفة التفاعل الكيميائي.","في التفاعل النووي قد يتكوّن عنصر جديد، كتحول الراديوم-226 إلى الرادون-222.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.745Z"}'::jsonb),
('mcq', 3, 0, 'إصدار أشعة بيتا ينتج عن تغير في نواة الذرة (تفكك نيوترون إلى بروتون وإلكترون)، فهو تفاعل نووي؛ لذلك الجواب هو الخيار الأول.', '["","التفاعل الكيميائي يتضمن تغيرًا في الإلكترونات المحيطة بالذرة، أما إصدار بيتا فمصدره النواة.","هوية الذرة تتغير عند إصدار بيتا، فالذرة تتحول إلى ذرة عنصر آخر، وهذا ليس من صفات التفاعل الكيميائي.","إصدار الإشعاعات من النواة تفاعل نووي وليس تغيرًا فيزيائيًّا بسيطًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.745Z"}'::jsonb),
('mcq', 4, 2, 'تكوّن الصدأ يتضمن تغيرًا في إلكترونات ذرات الحديد والأكسجين دون تغير في أنويتها، فهو تفاعل كيميائي؛ أما بقية الخيارات فتغيّر هوية العنصر بتغير نواته، فهي نووية.', '["تحول الراديوم إلى رادون يغيّر النواة وهوية العنصر، فهو تفاعل نووي.","إصدار بيتا تغير في نواة الذرة، فهو تفاعل نووي.","","تحول الكربون-14 إلى نيتروجين-14 تغير في النواة، فهو تفاعل نووي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.746Z"}'::jsonb),
('mcq', 5, 3, 'التغير (س) يقتصر على الإلكترونات وتبقى فيه هوية العنصر ثابتة، فهو تفاعل كيميائي؛ والتغير (ص) يمسّ النواة وقد يغيّر العنصر، فهو تفاعل نووي؛ لذلك الجواب هو الخيار الأخير.', '["هذا عكس الصحيح؛ فتغير الإلكترونات مع ثبات الهوية صفة التفاعل الكيميائي.","التغير (ص) يمسّ النواة، فهو نووي وليس كيميائيًّا.","التغير (س) يقتصر على الإلكترونات، فهو كيميائي وليس نوويًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.746Z"}'::jsonb),
('mcq', 6, 1, 'في التفاعل الكيميائي تشارك إلكترونات الذرة فقط ولا تتغير النواة، لذلك تبقى هوية العنصر ثابتة وإن أُعيد ترتيب الذرات؛ وهذه الحجة تدحض قول الطالب، والجواب هو الخيار الثاني.', '["إصدار الإشعاعات وتحول النواة من خصائص التفاعل النووي، ولا يدحض قول الطالب عن الكيميائي.","","تغير عدد البروتونات تغير في النواة، وهو لا يحدث في التفاعل الكيميائي.","تحول الذرة إلى ذرة عنصر آخر يحدث في التفاعل النووي، فهذه العبارة لا تدحض القول بل تصف تفاعلًا آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.746Z"}'::jsonb),
('mcq', 7, 0, 'تحلل الراديوم-226 تفاعل نووي تغيرت فيه النواة فتكوّن عنصر جديد هو الرادون؛ أما تكوين الماء فتفاعل كيميائي تشارك فيه الإلكترونات فتبقى هوية الهيدروجين والأكسجين ثابتة. لذلك الجواب هو الخيار الأول.', '["","هذا عكس الصحيح؛ فالهوية تتغير في التفاعل النووي (الأول) وتبقى ثابتة في الكيميائي (الثاني).","الهوية لا تتغير في تكوين الماء لأنه تفاعل كيميائي لا يمسّ النواة.","الهوية تتغير في الأول لأن تحلل الراديوم يغيّر نواته فيتكوّن الرادون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.746Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في التفاعل الكيميائي يحدث تغير في عدد الإلكترونات المحيطة بالذرة، وتشارك الإلكترونات فقط، وقد يُعاد ترتيب الذرات لكن هوية العنصر تبقى ثابتة. أما في التفاعل النووي فيحدث تغير في نواة الذرة، وقد يتحول العنصر إلى عنصر آخر، كتحول الراديوم-226 إلى الرادون-222.', '["الكيميائي: تغير في الإلكترونات المحيطة بالذرة","الكيميائي: هوية العنصر ثابتة","النووي: تغير في نواة الذرة","النووي: قد يتحول العنصر إلى عنصر آخر"]'::jsonb, '[]'::jsonb, '[{"element":"ما يتغير في التفاعل الكيميائي","marks":1},{"element":"ثبات هوية العنصر في التفاعل الكيميائي","marks":1},{"element":"ما يتغير في التفاعل النووي","marks":1},{"element":"إمكانية تحول العنصر في التفاعل النووي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة تذكر ما يتغير وهوية العنصر في كل من التفاعلين"},{"level":"2–3 درجات","description":"مقارنة صحيحة لأحد المحورين أو ذكر صحيح لثلاثة عناصر"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعل الكيميائي يغيّر النواة","القول إن هوية العنصر تتغير دائمًا في التفاعلات الكيميائية","عدم ذكر دور الإلكترونات في التفاعل الكيميائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.746Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تفاعل نووي؛ لأن إصدار بيتا ينتج عن تغير في نواة الذرة. (ب) تفاعل كيميائي؛ لأن الإلكترونات هي التي تشارك في تكوين الرابطة. (ج) لا شيء منهما؛ لأن فقد الحرارة عند التبريد لا يغيّر الإلكترونات ولا النواة، فهو تغير فيزيائي. (د) تفاعل كيميائي؛ لأن الصدأ مادة جديدة تنتج عن تغير في إلكترونات ذرات الحديد والأكسجين دون تغير في أنويتها.', '["(أ) نووي لأن التغير في النواة","(ب) كيميائي لأن الإلكترونات تشارك","(ج) لا شيء منهما لأن التغير فيزيائي","(د) كيميائي لأن التغير في الإلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التصنيف مع التبرير","marks":1},{"element":"(ب) التصنيف مع التبرير","marks":1},{"element":"(ج) التصنيف مع التبرير","marks":1},{"element":"(د) التصنيف مع التبرير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف الحالات الأربع تصنيفًا صحيحًا مع تبرير كل منها"},{"level":"2–3 درجات","description":"تصنيف صحيح مع تبرير لحالتين أو ثلاث"},{"level":"1 درجة","description":"تصنيف صحيح لحالة واحدة أو تصنيفات صحيحة دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ تبريد الكبريت تفاعلًا كيميائيًّا لأنه يصدر طاقة","عدّ إصدار بيتا تفاعلًا كيميائيًّا","ذكر التصنيف دون تبرير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.747Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفاعلات الكيميائية تغيّر الإلكترونات المحيطة بالذرة وتعيد ترتيب الذرات، لكن هوية العنصر تبقى ثابتة، فلم يسبق أن أدى تفاعل كيميائي إلى تكوين نوعين جديدين من الذرات. أما التفاعل النووي فيغيّر نواة الذرة، فيستطيع تحويل عنصر إلى عنصر آخر كتحول الراديوم-226 إلى الرادون-222؛ ولذلك كان اكتشافه مهمًّا، إذ تبيّن أن الذرة المشعة قد تتعرض لتغيرات تغيّر هويتها.', '["التفاعل الكيميائي لا يغيّر هوية العنصر","التفاعل الكيميائي يغيّر الإلكترونات فقط","التفاعل النووي يغيّر النواة ويحوّل عنصرًا إلى آخر","مثال على تحول عنصر إلى آخر"]'::jsonb, '[]'::jsonb, '[{"element":"حدود التفاعل الكيميائي (الإلكترونات وثبات الهوية)","marks":2},{"element":"قدرة التفاعل النووي على تحويل العنصر بتغير النواة","marks":2},{"element":"مثال صحيح على تحول عنصر إلى آخر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل يوضح حدود الكيميائي وقدرة النووي مع مثال صحيح"},{"level":"3–4 درجات","description":"تفسير صحيح لأحد التفاعلين وجزء من الآخر، أو دون مثال"},{"level":"1–2 درجة","description":"ذكر معلومة صحيحة واحدة عن أحد التفاعلين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعل الكيميائي ينتج عناصر جديدة","الخلط بين تكوين مركب جديد وتكوين عنصر جديد","عدم ذكر مثال على تحول العنصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:27:04.747Z"}'::jsonb)
