insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C3-L4-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا تصدر بعض الذرات إشعاعات؟', null, '["لأن عدد إلكتروناتها كبير جدًا","لأن عدد بروتوناتها زوجي دائمًا","لأن أنويتها غير مستقرة","لأنها تكتسب طاقة من الوسط المحيط"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 96 — النشاط الإشعاعي'),
('mcq', 2, 'ما المقصود بالتحلل الإشعاعي؟', null, '["فقد الأنوية غير المستقرة طاقة بإصدار إشعاعات في عملية تلقائية","تفاعل تتبادل فيه الذرات إلكتروناتها لتكوين مركب","اكتساب النواة طاقة من الوسط لتصبح مستقرة","تحول الذرة المستقرة إلى ذرة غير مستقرة بإضافة نيوترونات"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 96 — التحلل الإشعاعي'),
('mcq', 3, 'يُشبَّه التحلل الإشعاعي بحجر يسقط من ارتفاع إلى الأرض. أيّ العبارات الآتية تفسر هذا التشبيه تفسيرًا صحيحًا؟', null, '["الحجر يكتسب طاقة وضع عند وصوله إلى الأرض كما تكتسب النواة طاقة","الحجر تقل كتلته عند سقوطه كما تفقد الذرة إلكتروناتها","الحجر يصبح غير مستقر عند الأرض كما تصبح النواة المستقرة مشعة","الحجر يفقد طاقة وضعه ويستقر عند الأرض كما تفقد النواة غير المستقرة طاقة بالإشعاع وتستقر"]'::jsonb, 'فهم', 'تفسير تشبيه', 'متوسط', 'الكتاب ص 96 — الربط مع الحياة والتحلل الإشعاعي'),
('mcq', 4, 'ما نتيجة التحلل الإشعاعي لنواة غير مستقرة؟', null, '["تتحول إلى نواة أعلى طاقة وأقل استقرارًا","تتحول إلى ذرة مستقرة، وهي في الغالب ذرة عنصر آخر","تبقى ذرة العنصر نفسه لكن بنواة غير مستقرة جديدة","تبقى النواة دون تغير بينما تفقد الذرة إلكتروناتها"]'::jsonb, 'فهم', 'تفسير نتيجة', 'سهل', 'الكتاب ص 96 — التحلل الإشعاعي'),
('mcq', 5, 'نواة ذرة تحوي عددًا كبيرًا من النيوترونات قياسًا إلى بروتوناتها. ماذا يُتوقع أن يحدث لها؟', null, '["تبقى مستقرة لأن النيوترونات تثبّت النواة","تكتسب بروتونات من الوسط لتصبح مستقرة","تتحلل إشعاعيًّا وتطلق جسيمات تغيّر نسبة النيوترونات إلى البروتونات","تفقد إلكتروناتها فتصبح مستقرة"]'::jsonb, 'تطبيق', 'تطبيق على موقف', 'متوسط', 'الكتاب ص 98 — استقرار النواة'),
('mcq', 6, 'متى تتوقف ذرة مشعة عن التحلل الإشعاعي؟', null, '["عندما تصبح نواتها مستقرة بنسبة مناسبة من النيوترونات إلى البروتونات","عندما تفقد جميع إلكتروناتها","عندما تمتص طاقة من الوسط المحيط","عندما يتساوى عدد الإلكترونات وعدد النيوترونات"]'::jsonb, 'فهم', 'تفسير شرط', 'متوسط', 'الكتاب ص 105 — التقويم (سؤال 86)'),
('mcq', 7, 'لاحظ طالب أن نواة الراديوم-226 تحولت تلقائيًّا إلى نواة الرادون-222 بإصدار جسيم ألفا. أيّ التفسيرات الآتية أدق؟', null, '["نواة الراديوم-226 مستقرة اكتسبت طاقة من الوسط فتحولت","حدث تفاعل كيميائي غيّر إلكترونات الراديوم فتكوّن الرادون","نواة الراديوم-226 غير مستقرة تحلّلت إشعاعيًّا لتصل إلى الاستقرار","نواة الراديوم-226 فقدت إلكتروناتها فتحولت إلى عنصر آخر"]'::jsonb, 'تحليل', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 97 — أشعة ألفا'),
('essay', 1, 'فسّر لماذا تصدر بعض الذرات إشعاعات، ثم صف ما يحدث لهذه الذرات نتيجة التحلل الإشعاعي.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 96، 105 — التحلل الإشعاعي (سؤال 78)'),
('essay', 2, 'استعن بتشبيه الحجر الساقط من ارتفاع إلى الأرض لتوضح العلاقة بين الأنوية غير المستقرة والتحلل الإشعاعي.', null, null, 'فهم', 'تفسير بتشبيه', 'متوسط', 'الكتاب ص 96 — الربط مع الحياة'),
('essay', 3, 'اشرح كيف يرتبط فقدان الطاقة بالاستقرار النووي في التحلل الإشعاعي، وما الذي يجب أن يحدث قبل أن تتوقف ذرة مشعة عن التحلل، مبيّنًا دور نسبة النيوترونات إلى البروتونات.', null, null, 'تحليل', 'شرح علاقة', 'صعب', 'الكتاب ص 98، 105 — استقرار النواة (سؤالا 85 و86)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C3-L4-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تصدر الذرات المشعة الإشعاعات لأن أنويتها غير مستقرة وتفقد طاقة لتصل إلى حالة الاستقرار؛ لذلك الجواب هو أن أنويتها غير مستقرة.', '["عدد الإلكترونات لا علاقة له بإصدار الإشعاعات؛ فمصدرها النواة.","ليس عدد البروتونات الزوجي هو السبب؛ فالعامل الرئيس هو نسبة النيوترونات إلى البروتونات.","","الذرة المشعة تفقد طاقة عند إصدار الإشعاعات ولا تكتسبها من الوسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:27:04.747Z"}'::jsonb),
('mcq', 2, 0, 'التحلل الإشعاعي عملية تلقائية تفقد فيها الأنوية غير المستقرة طاقة بإصدار إشعاعات فتتحول إلى ذرات مستقرة؛ لذلك الجواب هو الخيار الأول.', '["","تبادل الإلكترونات لتكوين مركب تفاعل كيميائي وليس تحللًا إشعاعيًّا.","النواة غير المستقرة تفقد الطاقة ولا تكتسبها لتصل إلى الاستقرار.","التحلل الإشعاعي ينقل الذرة من حالة عدم الاستقرار إلى الاستقرار، لا العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.748Z"}'::jsonb),
('mcq', 3, 3, 'الحجر يملك طاقة وضع عالية عند الارتفاع وتقل عند الأرض فيستقر، وكذلك تفقد النواة غير المستقرة طاقة بإصدار الإشعاعات وتصل إلى حالة الاستقرار؛ لذلك الجواب هو الخيار الأخير.', '["طاقة وضع الحجر تقل عند وصوله إلى الأرض ولا تزداد، والنواة تفقد طاقة ولا تكتسبها.","التشبيه يتعلق بالطاقة والاستقرار، وليس بالكتلة أو بفقد الإلكترونات.","الحجر يصل إلى حالة أكثر استقرارًا عند الأرض، والنواة المستقرة لا تصدر إشعاعات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.748Z"}'::jsonb),
('mcq', 4, 1, 'تفقد الأنوية غير المستقرة الطاقة بالتحلل الإشعاعي وتتحول إلى ذرات مستقرة، وهي في الغالب ذرات عنصر آخر؛ لذلك الجواب هو الخيار الثاني.', '["التحلل يخفض طاقة النواة ويقرّبها من الاستقرار.","","التحلل يغيّر النواة فيتحول العنصر في الغالب إلى عنصر آخر، فلا تبقى الذرة ذرة العنصر نفسه بنواة غير مستقرة.","التحلل الإشعاعي تغير في النواة وليس في الإلكترونات، والناتج النهائي ذرة مستقرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.748Z"}'::jsonb),
('mcq', 5, 2, 'النسبة الكبيرة للنيوترونات تجعل النواة غير مستقرة، فتتحلل إشعاعيًّا وتطلق جسيمات ألفا أو بيتا لتغيّر هذه النسبة وتصل إلى نواة مستقرة؛ لذلك الجواب هو الخيار الثالث.', '["العدد الكبير من النيوترونات يجعل النواة غير مستقرة ولا يثبّتها.","النواة لا تكتسب بروتونات من الوسط؛ بل تصل إلى الاستقرار بإصدار إشعاعات.","","إلكترونات الذرة لا علاقة لها باستقرار النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.748Z"}'::jsonb),
('mcq', 6, 0, 'تستمر الذرة المشعة في التحلل حتى تفقد طاقة كافية لتصل إلى نواة مستقرة بنسبة مناسبة من النيوترونات إلى البروتونات، وعندها يتوقف التحلل؛ لذلك الجواب هو الخيار الأول.', '["","فقد الإلكترونات لا يؤثر في استقرار النواة ولا يوقف التحلل.","امتصاص الطاقة لا يوقف التحلل؛ فالتحلل يتوقف بفقد الطاقة والوصول إلى الاستقرار.","التساوي بين عدد الإلكترونات والنيوترونات ليس شرطًا للاستقرار؛ فالعامل هو نسبة النيوترونات إلى البروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.748Z"}'::jsonb),
('mcq', 7, 2, 'الراديوم-226 نواة غير مستقرة، فتفقد طاقة تلقائيًّا بإصدار جسيم ألفا في تحلل إشعاعي فتتحول إلى نواة أقرب إلى الاستقرار لعنصر آخر هو الرادون-222؛ لذلك الجواب هو الخيار الثالث.', '["التحول تلقائي ولا يحتاج إلى اكتساب طاقة، والنواة المستقرة لا تتحلل.","تغير العنصر هنا ناتج عن تغير في النواة، وليس عن تفاعل كيميائي يمسّ الإلكترونات.","","فقد الإلكترونات لا يغيّر هوية العنصر؛ فالتحول سببه تغير النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:27:04.749Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تصدر الذرات المشعة إشعاعات لأن أنويتها غير مستقرة. وتفقد الأنوية غير المستقرة الطاقة بإصدار إشعاعات في عملية تلقائية تسمى التحلل الإشعاعي، فتتحول إلى ذرات مستقرة، وهي في الغالب ذرات عنصر آخر.', '["سبب إصدار الإشعاعات: عدم استقرار النواة","التحلل الإشعاعي عملية تلقائية تفقد فيها النواة طاقة بإصدار إشعاعات","الناتج ذرة مستقرة","غالبًا ذرة عنصر آخر"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الإشعاع بعدم استقرار النواة","marks":1},{"element":"تعريف التحلل الإشعاعي (فقد طاقة بإصدار إشعاعات تلقائيًّا)","marks":1},{"element":"تحول الذرة إلى ذرة مستقرة","marks":1},{"element":"كونها في الغالب ذرة عنصر آخر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط عدم الاستقرار بالتحلل ويصف الناتج"},{"level":"2–3 درجات","description":"ذكر عناصر صحيحة ناقصة مثل إغفال تحول العنصر أو تلقائية العملية"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرة المشعة تكتسب طاقة لتصل إلى الاستقرار","الخلط بين التحلل الإشعاعي والتفاعل الكيميائي","نسبة الإشعاع إلى الإلكترونات لا إلى النواة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:27:04.749Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الحجر عند الارتفاع يملك طاقة وضع عالية، وعند سقوطه إلى الأرض تقل طاقة وضعه ويصل إلى حالة مستقرة. وكذلك النواة غير المستقرة تكون ذات طاقة عالية، فتفقد طاقة بإصدار الإشعاعات في عملية تلقائية هي التحلل الإشعاعي، فتصل إلى حالة من الاستقرار.', '["الحجر عند الارتفاع طاقة وضعه عالية","يفقد الحجر طاقة وضعه ويستقر عند الأرض","النواة غير المستقرة تفقد طاقة بإصدار إشعاعات","كلا الحالتين تنتهيان بالوصول إلى حالة مستقرة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الحجر قبل السقوط وبعده من حيث الطاقة","marks":1},{"element":"وصف النواة غير المستقرة وفقدها الطاقة بالإشعاع","marks":2},{"element":"المقابلة بين النموذجين وبلوغ الاستقرار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل مع مقابلة صحيحة بين الحجر والنواة"},{"level":"2–3 درجات","description":"وصف صحيح لأحد الطرفين مع مقابلة ناقصة"},{"level":"1 درجة","description":"ذكر جزء صحيح واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النواة تكتسب طاقة كما يكتسب الحجر سرعة","ربط التشبيه بالكتلة بدل الطاقة","عدم ذكر دور الإشعاعات في فقد الطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.749Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تفقد النواة غير المستقرة طاقة بإصدار إشعاعات، وبفقدها الطاقة تقترب من حالة الاستقرار. والعامل الرئيس في استقرار النواة هو نسبة النيوترونات إلى البروتونات، فالنواة التي تحوي عددًا كبيرًا أو قليلًا من النيوترونات غير مستقرة، وتطلق جسيمات ألفا وبيتا فتتغير هذه النسبة في النواة الجديدة. ولا تتوقف الذرة عن التحلل إلا بعد أن تصبح نسبة النيوترونات إلى البروتونات فيها مناسبة فتتكوّن نواة مستقرة.', '["فقد الطاقة بالإشعاع يقرّب النواة من الاستقرار","العامل الرئيس نسبة النيوترونات إلى البروتونات","إطلاق جسيمات ألفا وبيتا يغيّر هذه النسبة","يتوقف التحلل عند تكوّن نواة مستقرة بنسبة مناسبة"]'::jsonb, '[]'::jsonb, '[{"element":"ربط فقد الطاقة بالاقتراب من الاستقرار","marks":1},{"element":"ذكر نسبة النيوترونات إلى البروتونات عاملًا رئيسًا","marks":1},{"element":"دور جسيمات ألفا وبيتا في تغيير النسبة","marks":1},{"element":"شرط توقف التحلل: الوصول إلى نواة مستقرة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"شرح كامل يربط الطاقة والنسبة والجسيمات المنطلقة وشرط التوقف"},{"level":"3–4 درجات","description":"شرح صحيح لمعظم العناصر مع نقص في أحدها"},{"level":"1–2 درجة","description":"ذكر عنصر أو عنصرين صحيحين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر عدد الإلكترونات عاملًا في استقرار النواة","القول إن التحلل يستمر إلى ما لا نهاية","إغفال دور جسيمات ألفا وبيتا في تغيير النسبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.749Z"}'::jsonb)
