('mcq', 1, 3, 'أشعة جاما متعادلة الشحنة، فلا تنحرف في المجال الكهربائي ولا المغناطيسي؛ أما ألفا وبيتا فتحملان شحنة فتنحرفان. لذلك الجواب هو أشعة جاما.', '["جسيمات ألفا موجبة الشحنة (+2) فتنحرف نحو الصفيحة السالبة.","جسيمات بيتا سالبة الشحنة (−1) فتنحرف نحو الصفيحة الموجبة.","كلاهما يحمل شحنة فينحرف في المجال الكهربائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.750Z"}'::jsonb),
('mcq', 2, 1, 'الإشعاع (س) كتلته 4 amu وشحنته +2 فهو جسيم ألفا، و(ص) كتلته 1/1840 amu وشحنته −1 فهو جسيم بيتا، و(ع) بلا كتلة ولا شحنة فهو أشعة جاما؛ لذلك الجواب هو الخيار الثاني.', '["عكس صحيح؛ فكتلة 4 amu وشحنة +2 لجسيم ألفا، لا بيتا.","","(س) ذو كتلة وشحنة فلا يمكن أن يكون أشعة جاما التي لا كتلة لها ولا شحنة.","(ص) يحمل كتلة وشحنة سالبة فهو بيتا لا جاما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.750Z"}'::jsonb),
('mcq', 3, 0, 'جسيمات ألفا موجبة الشحنة فتنجذب نحو الصفيحة السالبة، وجسيمات بيتا سالبة الشحنة فتنجذب نحو الصفيحة الموجبة؛ لذلك الجواب هو الخيار الأول.', '["","هذا عكس الصحيح؛ فالشحنة الموجبة تنجذب نحو الصفيحة السالبة.","جسيمات بيتا سالبة الشحنة فلا تنجذب إلى الصفيحة السالبة.","جسيمات ألفا موجبة الشحنة فلا تنجذب إلى الصفيحة الموجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.751Z"}'::jsonb),
('mcq', 4, 2, 'جسيم ألفا يعادل نواة الهيليوم-4، ويحتوي على بروتونين ونيوترونين، ولذلك شحنته +2 وكتلته 4 amu؛ لذلك الجواب هو الخيار الثالث.', '["هذا يعطي شحنة +1 وكتلة 2 amu، وهما لا يطابقان جسيم ألفا.","الإلكترونان يعطيان شحنة سالبة، بينما شحنة جسيم ألفا موجبة (+2).","","أربعة بروتونات تعطي شحنة +4، وشحنة جسيم ألفا هي +2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.751Z"}'::jsonb),
('mcq', 5, 1, 'جسيم بيتا إلكترون مصدره النواة وليس السحابة الإلكترونية، ويتكوّن عندما يتفكك النيوترون غير المستقر إلى بروتون وإلكترون؛ لذلك الجواب هو الخيار الثاني.', '["مصدر الإلكترون هو النواة وليس السحابة الإلكترونية.","","نواة الهيليوم-4 هي جسيم ألفا نفسه، وليست مصدرًا لجسيم بيتا.","جسيم بيتا ينبعث من النواة ولا تمتصه النواة من الوسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.751Z"}'::jsonb),
('mcq', 6, 3, 'النسبة = 4 amu ÷ (1/1840 amu) = 4 × 1840 = 7360؛ لذلك الجواب هو 7360.', '["العدد 460 ناتج قسمة 1840 على 4، أي أن الطالب قسم بدل أن يضرب 4 في 1840.","هذا مقلوب كتلة بيتا وحده، دون ضربه في كتلة ألفا (4 amu).","العدد 0.0022 ناتج ضرب 4 × (1/1840)، أي ضرب الكتلتين بدل قسمة كتلة ألفا على كتلة بيتا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.751Z"}'::jsonb),
('mcq', 7, 2, 'أشعة جاما طاقة عالية بلا كتلة ولا شحنة، فلا تنحرف في المجالات، وترافق أشعة ألفا وبيتا عادة؛ لذلك الجواب هو الخيار الثالث.', '["هذه صفات جسيم بيتا.","الانحراف نحو الصفيحة الموجبة من صفات جسيمات بيتا لأنها سالبة الشحنة.","","هذه صفات جسيم ألفا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.751Z"}'::jsonb),
('essay', 1, null::int, null, null, 'جسيم ألفا: رمزه ⁴₂He أو α، كتلته 4 amu، شحنته +2، ينحرف نحو الصفيحة السالبة. جسيم بيتا: رمزه e⁻ أو β، كتلته 1/1840 amu، شحنته −1، ينحرف نحو الصفيحة الموجبة. أشعة جاما: رمزها γ، لا كتلة لها (0)، شحنتها 0، لا تنحرف في المجال الكهربائي.', '["ألفا: α، 4 amu، +2، نحو الصفيحة السالبة","بيتا: β، 1/1840 amu، −1، نحو الصفيحة الموجبة","جاما: γ، كتلة 0، شحنة 0، لا تنحرف"]'::jsonb, '[]'::jsonb, '[{"element":"خصائص ألفا (رمز، كتلة، شحنة، انحراف)","marks":2},{"element":"خصائص بيتا (رمز، كتلة، شحنة، انحراف)","marks":2},{"element":"خصائص جاما (رمز، كتلة، شحنة، انحراف)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة وصحيحة للإشعاعات الثلاثة في الخصائص الأربع"},{"level":"4–5 درجات","description":"مقارنة صحيحة لمعظم الخصائص مع خطأ أو نقص بسيط"},{"level":"2–3 درجات","description":"وصف صحيح لإشعاع واحد أو لخاصية واحدة في الثلاثة"},{"level":"1 درجة","description":"ذكر معلومة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس اتجاه انحراف ألفا وبيتا","القول إن لأشعة جاما شحنة أو كتلة","الخلط بين كتلة بيتا وكتلة ألفا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.751Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الانحراف يعتمد على الشحنة الكهربائية للإشعاع. جسيمات بيتا سالبة الشحنة (−1) فتنجذب نحو الصفيحة الموجبة. وجسيمات ألفا موجبة الشحنة (+2) فتنجذب نحو الصفيحة السالبة. أما أشعة جاما فمتعادلة الشحنة (لا كتلة لها ولا شحنة) فلا تتأثر بالمجال الكهربائي ولا تنحرف.', '["بيتا سالبة فتنجذب نحو الموجبة","ألفا موجبة فتنجذب نحو السالبة","جاما متعادلة فلا تنحرف","الانحراف يعتمد على الشحنة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير انحراف بيتا بشحنتها السالبة","marks":1},{"element":"تفسير انحراف ألفا بشحنتها الموجبة","marks":1},{"element":"تفسير عدم انحراف جاما بتعادلها","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير الانحرافات الثلاثة بالشحنة تفسيرًا صحيحًا"},{"level":"2 درجتان","description":"تفسير صحيح لاثنين من الثلاثة"},{"level":"1 درجة","description":"تفسير صحيح لواحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الانحراف بالكتلة وحدها","عكس الشحنتين أو اتجاهي الانحراف","القول إن جاما لا تنحرف لأنها سريعة جدًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.751Z"}'::jsonb),
('essay', 3, null::int, null, null, 'جسيم ألفا (نواة هيليوم-4 ذات كتلة 4 amu وشحنة +2) يحمل بروتونين ونيوترونين، لذلك يؤدي إصداره إلى تغير هوية الذرة: يتحول اليورانيوم-238 (العدد الذري 92) إلى الثوريوم-234 (العدد الذري 90). أما أشعة جاما فلا كتلة لها ولا شحنة، لذلك لا تغيّر هوية الذرة ولا تكوّن ذرة جديدة. وأشعة جاما هي المسؤولة عن معظم الطاقة التي تُفقد خلال التحلل الإشعاعي.', '["ألفا يغيّر هوية الذرة فيتكوّن الثوريوم-234","جاما لا كتلة لها ولا شحنة فلا تغيّر الهوية","جاما مسؤولة عن معظم الطاقة المفقودة"]'::jsonb, '[]'::jsonb, '[{"element":"دور ألفا في تغيير هوية الذرة مع التعليل","marks":2},{"element":"عدم تأثير جاما في الهوية مع التعليل","marks":1},{"element":"نسبة معظم الطاقة المفقودة إلى جاما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة تشمل الهوية والطاقة مع التعليل"},{"level":"2–3 درجات","description":"مقارنة صحيحة لجزء من المطلوب أو دون تعليل"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن أشعة جاما تغيّر العدد الذري","نسبة معظم الطاقة إلى جسيم ألفا","عدّ أشعة جاما جسيمات ذات كتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.752Z"}'::jsonb)
