('mcq', 3, 1, 'لاحظ العلماء في عام 1890م أن بعض المواد تصدر إشعاعات، وسُمّيت هذه العملية النشاط الإشعاعي؛ لذلك الجواب هو 1890م.', '["عام 1690م أسبق بكثير من ملاحظة النشاط الإشعاعي.","","عام 1910م لاحق لعام الملاحظة الأولى للنشاط الإشعاعي.","عام 1990م بعيد جدًّا عن عام ملاحظة النشاط الإشعاعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:27:04.752Z"}'::jsonb),
('mcq', 4, 3, 'تصدر الذرات المشعة الإشعاعات لأن أنويتها غير مستقرة؛ لذلك الجواب هو أن مصدرها الأنوية غير المستقرة.', '["الأنوية المستقرة لا تصدر إشعاعات.","تشارك الإلكترونات يكوّن الروابط الكيميائية ولا ينتج إشعاعات.","الإشعاعات مصدرها النواة وليست انتقالات الإلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.752Z"}'::jsonb),
('mcq', 5, 0, 'الطاقة والجسيمات المنبعثة من المواد المشعة هي الإشعاعات، والعملية التي تصدر فيها المواد الإشعاعات هي النشاط الإشعاعي؛ لذلك الجواب هو الخيار الأول.', '["","هذا خلط بين المصطلحين؛ فالنشاط الإشعاعي هو العملية، والإشعاعات هي المنبعث.","إصدار الإشعاعات من الأنوية ليس تفاعلًا كيميائيًّا.","الروابط الكيميائية لا علاقة لها بما ينبعث من النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:27:04.753Z"}'::jsonb),
('mcq', 6, 2, 'جسيمات ألفا المنبعثة من نواة غير مستقرة جسيمات تنبعث من مادة مشعة، فهي من الإشعاعات؛ لذلك الجواب هو الخيار الثالث.', '["هذه إلكترونات ذرة مستقرة ولا تنبعث منها.","البروتونات الثابتة في نواة مستقرة لا تنبعث ولا تُعدّ إشعاعًا.","","الأيونات المذابة لا علاقة لها بانبعاث الطاقة والجسيمات من المواد المشعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.753Z"}'::jsonb),
('mcq', 7, 1, 'النشاط الإشعاعي هو العملية التي تصدر فيها المواد إشعاعات، أما الإشعاعات فهي الطاقة والجسيمات المنبعثة؛ لذلك الجواب هو الخيار الثاني.', '["هذا عكس الصحيح لمعنى المصطلحين.","","المصطلحان مختلفان؛ أحدهما عملية والآخر ما ينبعث فيها.","كلاهما يتعلق بالأنوية غير المستقرة، وليس أحدهما بالإلكترونات والآخر بالنيوترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.753Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النشاط الإشعاعي: عملية تصدر فيها بعض المواد إشعاعات. الإشعاعات: الطاقة والجسيمات المنبعثة من المواد المشعة. وتصدر الإشعاعات الأنوية غير المستقرة.', '["النشاط الإشعاعي عملية تصدر فيها بعض المواد إشعاعات","الإشعاعات هي الطاقة والجسيمات المنبعثة من المواد المشعة","مصدر الإشعاعات الأنوية غير المستقرة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النشاط الإشعاعي","marks":1},{"element":"تعريف الإشعاعات","marks":1},{"element":"ذكر أن مصدرها الأنوية غير المستقرة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريفان صحيحان مع ذكر المصدر"},{"level":"2 درجتان","description":"عنصران صحيحان من الثلاثة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين النشاط الإشعاعي والإشعاعات","نسبة الإشعاعات إلى الإلكترونات","تعريف الإشعاعات بأنها المادة المشعة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.753Z"}'::jsonb),
('essay', 2, null::int, null, null, 'النشاط الإشعاعي هو العملية التي تصدر فيها بعض المواد إشعاعات، أما الإشعاعات فهي الطاقة والجسيمات المنبعثة من هذه المواد المشعة. وللإشعاعات ثلاثة أنواع: ألفا ورمزها α، وبيتا ورمزها β، وجاما ورمزها γ.', '["النشاط الإشعاعي عملية الإصدار","الإشعاعات الطاقة والجسيمات المنبعثة","ألفا α","بيتا β","جاما γ"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح الفرق بين النشاط الإشعاعي والإشعاعات","marks":2},{"element":"ذكر الأنواع الثلاثة","marks":1},{"element":"رموز الأنواع الثلاثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"فرق صحيح مع الأنواع الثلاثة ورموزها"},{"level":"2–3 درجات","description":"فرق صحيح مع نقص في الأنواع أو الرموز، أو العكس"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس معنى المصطلحين","الخلط بين رمزي ألفا وبيتا","ذكر نوع رابع غير ألفا وبيتا وجاما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.753Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لاحظ العلماء أن بعض المواد تصدر إشعاعات من خلال عملية سُمّيت النشاط الإشعاعي، وتُسمّى الطاقة والجسيمات المنبعثة من هذه المواد المشعة الإشعاعات. وتصدر الذرة المشعة الإشعاعات لأن نواتها غير مستقرة.', '["العملية التي تصدر فيها المواد إشعاعات هي النشاط الإشعاعي","الإشعاعات هي الطاقة والجسيمات المنبعثة","السبب: عدم استقرار النواة"]'::jsonb, '[]'::jsonb, '[{"element":"استخدام مصطلح النشاط الإشعاعي استخدامًا صحيحًا","marks":1},{"element":"استخدام مصطلح الإشعاعات استخدامًا صحيحًا","marks":1},{"element":"تعليل الإصدار بعدم استقرار النواة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"وصف صحيح بالمصطلحين مع التعليل"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل الإشعاع بعدد الإلكترونات","القول إن الإشعاعات تُصدرها الأنوية المستقرة","عدم التمييز بين العملية والمنبعث"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:27:04.753Z"}'::jsonb)
