('mcq', 2, 3, 'الأنوية التي تحوي عددًا كبيرًا أو قليلًا من النيوترونات غير مستقرة، وتفقد طاقة بالتحلل الإشعاعي لتكوين أنوية مستقرة؛ لذلك الجواب هو الخيار الأخير.', '["النسبة غير المناسبة للنيوترونات تجعل النواة غير مستقرة.","النواة غير المناسبة النسبة غير مستقرة، وهي لا تكتسب طاقة بل تفقدها.","النواة غير المستقرة تفقد طاقتها بالتحلل ولا تحتفظ بها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:27:04.754Z"}'::jsonb),
('mcq', 3, 2, 'تؤثر جسيمات ألفا وبيتا المنبعثة في نسبة النيوترونات إلى البروتونات في النواة الجديدة، وهي العامل الرئيس في الاستقرار؛ لذلك الجواب هو الخيار الثالث.', '["الإلكترونات المحيطة بالنواة لا ترتبط بإصدار جسيمات ألفا وبيتا.","الروابط بين الذرات لا علاقة لها بتغير نسبة مكونات النواة.","","الحالة الفيزيائية لا تتأثر بتحول نواة الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.754Z"}'::jsonb),
('mcq', 4, 0, 'استقرار النواة تحدده نسبة النيوترونات إلى البروتونات، فيحتاج العالم إلى عدد كل منهما؛ لذلك الجواب هو الخيار الأول.', '["","غلاف التكافؤ خارج النواة ولا يحدد استقرارها.","كتلة الذرة وحدها لا تكشف نسبة النيوترونات إلى البروتونات.","درجة الغليان خاصية فيزيائية للمادة ولا علاقة لها باستقرار النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.754Z"}'::jsonb),
('mcq', 5, 3, 'النواة التي تحوي عددًا قليلًا من النيوترونات تكون غير مستقرة لأن نسبة النيوترونات إلى البروتونات فيها غير مناسبة؛ لذلك الجواب هو الخيار الأخير.', '["زيادة البروتونات على النيوترونات لا تجعل النواة مستقرة؛ فالمهم النسبة المناسبة.","تعادل الذرة كهربائيًّا لا يحدد استقرار النواة.","عدد الإلكترونات لا يحدد استقرار النواة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.754Z"}'::jsonb),
('mcq', 6, 1, 'استقرار النواة يتحدد بنسبة النيوترونات إلى البروتونات، لذلك تكفي مقارنة هذه النسبة في النواتين؛ والجواب هو الخيار الثاني.', '["عدد الإلكترونات متساوٍ في الذرتين المتعادلتين، ولا يحدد استقرار النواة.","","الحالة الفيزيائية صفة للمادة ولا تعبّر عن استقرار النواة.","اللون صفة ظاهرية لا علاقة لها باستقرار النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.754Z"}'::jsonb),
('mcq', 7, 2, 'تطلق الأنوية غير المستقرة جسيمات ألفا وبيتا خلال التحلل الإشعاعي، فتتغير نسبة النيوترونات إلى البروتونات فيها وتصبح مستقرة؛ لذلك الجواب هو الخيار الثالث.', '["الإلكترونات المحيطة بالنواة لا تؤثر في نسبة مكونات النواة.","الأنوية لا تمتص نيوترونات من الوسط في هذه العملية بل تطلق جسيمات.","","ذرات الهيدروجين ليست من الجسيمات التي تطلقها الأنوية غير المستقرة هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.755Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العامل الرئيس في استقرار النواة هو نسبة النيوترونات إلى البروتونات فيها. فالأنوية التي تحوي عددًا كبيرًا أو قليلًا من النيوترونات غير مستقرة، وتفقد طاقة بالتحلل الإشعاعي لتكوين أنوية مستقرة.', '["العامل الرئيس نسبة النيوترونات إلى البروتونات","العدد الكبير أو القليل من النيوترونات يجعل النواة غير مستقرة","تفقد طاقة بالتحلل الإشعاعي","لتكوين أنوية مستقرة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نسبة النيوترونات إلى البروتونات عاملًا رئيسًا","marks":1},{"element":"عدم استقرار الأنوية ذات العدد الكبير أو القليل من النيوترونات","marks":1},{"element":"فقد الطاقة بالتحلل الإشعاعي","marks":1},{"element":"تكوين أنوية مستقرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد العامل وبيان كامل لما يحدث للأنوية غير المستقرة"},{"level":"2–3 درجات","description":"تحديد العامل مع بيان ناقص"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر عدد الإلكترونات عاملًا لاستقرار النواة","القول إن زيادة النيوترونات تزيد الاستقرار دائمًا","إغفال ذكر التحلل الإشعاعي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:27:04.755Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الذرات غير المستقرة أنويتها تحوي عددًا كبيرًا أو قليلًا من النيوترونات بالنسبة إلى البروتونات. وتصل إلى الاستقرار بفقد طاقة من خلال التحلل الإشعاعي، فتطلق جسيمات ألفا وبيتا فتتغير نسبة النيوترونات إلى البروتونات في النواة الجديدة وتصبح نواة مستقرة.', '["عدم الاستقرار سببه نسبة غير مناسبة للنيوترونات إلى البروتونات","فقد الطاقة بالتحلل الإشعاعي","إطلاق جسيمات ألفا وبيتا","تتغير النسبة فتتكوّن نواة مستقرة"]'::jsonb, '[]'::jsonb, '[{"element":"ربط عدم الاستقرار بنسبة النيوترونات إلى البروتونات","marks":1},{"element":"فقد الطاقة بالتحلل الإشعاعي","marks":1},{"element":"إطلاق جسيمات ألفا وبيتا","marks":1},{"element":"تغير النسبة وتكوّن نواة مستقرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل لمراحل الوصول إلى الاستقرار"},{"level":"2–3 درجات","description":"تفسير صحيح مع إغفال عنصر أو عنصرين"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرة تكتسب طاقة لتصبح مستقرة","إغفال أثر الجسيمات المنبعثة في نسبة النيوترونات إلى البروتونات","الخلط بين الاستقرار النووي والاستقرار الإلكتروني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.755Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العامل الذي استندت إليه هو نسبة النيوترونات إلى البروتونات. النواة (أ) غير مستقرة لأن فيها عددًا كبيرًا من النيوترونات، فتفقد طاقة بالتحلل الإشعاعي وتطلق جسيمات ألفا وبيتا لتغيّر هذه النسبة. النواة (ب) غير مستقرة لأن فيها عددًا قليلًا من النيوترونات، فتتحلل إشعاعيًّا بالطريقة نفسها لتكوين نواة مستقرة. النواة (ج) مستقرة لأن نسبتها مناسبة، فلا تتحلل ولا تصدر إشعاعات.', '["العامل: نسبة النيوترونات إلى البروتونات","(أ) غير مستقرة وتتحلل إشعاعيًّا","(ب) غير مستقرة وتتحلل إشعاعيًّا","(ج) مستقرة ولا تتحلل","إطلاق جسيمات ألفا وبيتا لتغيير النسبة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العامل (نسبة النيوترونات إلى البروتونات)","marks":1},{"element":"النواة (أ): تصنيف وتوقع","marks":1},{"element":"النواة (ب): تصنيف وتوقع","marks":1},{"element":"النواة (ج): تصنيف وتوقع","marks":1},{"element":"ذكر جسيمات ألفا وبيتا في تغيير النسبة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف النوى الثلاث مع توقع صحيح وذكر العامل والجسيمات"},{"level":"3–4 درجات","description":"تصنيف صحيح للنوى الثلاث أو توقع ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح لنواة أو نواتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ النواة ذات النيوترونات الكثيرة مستقرة","عدّ النواة القليلة النيوترونات مستقرة","عدم ذكر العامل الذي استُند إليه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.755Z"}'::jsonb)
