('mcq', 1, 2, 'جسيم ألفا نواة هيليوم-4 (⁴₂He) تحمل بروتونين ونيوترونين، فإصداره يُنقص العدد الذري بمقدار 2 والعدد الكتلي بمقدار 4؛ لذلك الجواب هو الخيار الثالث.', '["الإنقاص في العدد الذري هو 2 وليس 1؛ لأن ألفا يحمل بروتونين.","هذا عكس القيمتين؛ فالعدد الذري ينقص 2 والعدد الكتلي ينقص 4.","","العدد الذري ينقص عند إصدار ألفا ولا يزداد، لأن النواة تفقد بروتونين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:27:04.756Z"}'::jsonb),
('mcq', 2, 0, 'جسيم بيتا إلكترون ينتج عن تفكك نيوترون إلى بروتون وإلكترون، فيزداد العدد الذري بمقدار 1 ولا يتغير العدد الكتلي لأن مجموع البروتونات والنيوترونات ثابت؛ لذلك الجواب هو الخيار الأول.', '["","العدد الذري يزداد ولا ينقص، لأن النيوترون يتحول إلى بروتون.","العدد الكتلي لا يتغير لأن مجموع النيوكلونات ثابت.","العدد الذري يتغير بمقدار 1، والعدد الكتلي هو الذي يبقى ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:27:04.756Z"}'::jsonb),
('mcq', 3, 1, 'أشعة جاما طاقة عالية لا كتلة لها ولا شحنة، فلا تغيّر العدد الذري ولا العدد الكتلي؛ لذلك الجواب هو الخيار الثاني.', '["نقص العدد الذري بمقدار 2 يرتبط بإصدار جسيم ألفا لا جاما.","","نقص العدد الكتلي بمقدار 4 يرتبط بإصدار ألفا.","زيادة العدد الذري بمقدار 1 ترتبط بإصدار بيتا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.756Z"}'::jsonb),
('mcq', 4, 3, 'العدد الذري = 88 − 2 = 86، والعدد الكتلي = 226 − 4 = 222؛ فالناتج هو الرادون-222، والجواب هو الخيار الأخير.', '["هذا يطبّق نقص العدد الكتلي فقط، مع إهمال نقص العدد الذري بمقدار 2.","هذا يزيد العدد الذري بمقدار 2 بدل إنقاصه، ويهمل نقص العدد الكتلي.","هذا يطبّق نقص العدد الذري فقط، مع إهمال نقص العدد الكتلي بمقدار 4.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-18T03:27:04.756Z"}'::jsonb),
('mcq', 5, 0, 'العدد الذري = 6 + 1 = 7، والعدد الكتلي يبقى 14؛ فالناتج هو النيتروجين-14، والجواب هو الخيار الأول.', '["","هذا ينقص العدد الذري بمقدار 1، بينما إصدار بيتا يزيده.","هذا ينقص العدد الكتلي، وهو لا يتغير عند إصدار بيتا، ويهمل زيادة العدد الذري.","العدد الذري صحيح، لكن العدد الكتلي لا ينقص بمقدار 1 عند إصدار بيتا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-18T03:27:04.756Z"}'::jsonb),
('mcq', 6, 2, 'بعد إصدار ألفا: العدد الذري 92 − 2 = 90 والعدد الكتلي 238 − 4 = 234. وبعد إصدار بيتا يزداد العدد الذري إلى 91 ويبقى العدد الكتلي 234؛ لذلك الجواب هو الخيار الثالث.', '["هذه قيم النواة بعد ألفا فقط، دون أثر بيتا.","هذا ينقص العدد الذري عند إصدار بيتا، بينما هو يزداد.","","هذا يهمل نقص العدد الكتلي بمقدار 4 عند إصدار ألفا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-18T03:27:04.756Z"}'::jsonb),
('mcq', 7, 3, 'جسيم ألفا ينقص العدد الذري بمقدار 2 والعدد الكتلي بمقدار 4، وهو ما يطابق الانخفاض من 92 إلى 90 ومن 238 إلى 234، أما أشعة جاما فلا كتلة لها ولا شحنة فلا تغيّر العددين؛ لذلك الجواب هو الخيار الأخير.', '["أشعة جاما لا كتلة لها ولا شحنة فلا تغيّر العددين الذري والكتلي.","أشعة جاما لا تسهم في التغير؛ فالانخفاض كله بسبب ألفا.","فقد الإلكترونات لا يغيّر العددين الذري والكتلي للنواة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.756Z"}'::jsonb),
('essay', 1, null::int, null, null, 'جسيم ألفا: يقل العدد الذري بمقدار 2، ويقل العدد الكتلي بمقدار 4. جسيم بيتا: يزداد العدد الذري بمقدار 1، ولا يتغير العدد الكتلي. أشعة جاما: لا يتغير العدد الذري ولا العدد الكتلي.', '["ألفا: العدد الذري −2، العدد الكتلي −4","بيتا: العدد الذري +1، العدد الكتلي لا يتغير","جاما: لا تغيّر العددين"]'::jsonb, '[]'::jsonb, '[{"element":"تنظيم المعلومات في جدول بعمودين مناسبين","marks":1},{"element":"أثر ألفا في العددين","marks":1},{"element":"أثر بيتا في العددين","marks":1},{"element":"أثر جاما في العددين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جدول منظم وأثر صحيح للأنواع الثلاثة في العددين"},{"level":"2–3 درجات","description":"أثر صحيح لنوعين أو عدم تنظيم في جدول"},{"level":"1 درجة","description":"أثر صحيح لنوع واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن بيتا ينقص العدد الذري","القول إن بيتا يغيّر العدد الكتلي","القول إن جاما تغيّر العدد الذري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.757Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بعد إصدار بيتا: العدد الذري = 90 + 1 = 91، والعدد الكتلي يبقى 234. بعد إصدار ألفا: العدد الذري = 91 − 2 = 89، والعدد الكتلي = 234 − 4 = 230. فالنواة النهائية عددها الذري 89 وعددها الكتلي 230.', '["بعد بيتا: العدد الذري 91 والعدد الكتلي 234","بعد ألفا: العدد الذري 89 والعدد الكتلي 230"]'::jsonb, '["بيتا: العدد الذري يزداد 1، 90 + 1 = 91؛ العدد الكتلي ثابت = 234","ألفا: العدد الذري ينقص 2، 91 − 2 = 89","ألفا: العدد الكتلي ينقص 4، 234 − 4 = 230"]'::jsonb, '[{"element":"أثر بيتا في العدد الذري (91)","marks":1},{"element":"ثبات العدد الكتلي بعد بيتا (234)","marks":1},{"element":"العدد الذري بعد ألفا (89)","marks":1},{"element":"العدد الكتلي بعد ألفا (230)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح للعددين بعد الخطوتين مع توضيح الخطوات"},{"level":"2–3 درجات","description":"حساب صحيح لخطوة واحدة كاملة أو أخطاء حسابية بسيطة"},{"level":"1 درجة","description":"تطبيق صحيح لقاعدة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إنقاص العدد الذري عند إصدار بيتا","إنقاص العدد الكتلي بمقدار 2 بدل 4 عند ألفا","عدم استخدام نتيجة الخطوة الأولى في الثانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:27:04.757Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العدد الذري انخفض بمقدار 2 (من 92 إلى 90)، والعدد الكتلي انخفض بمقدار 4 (من 238 إلى 234). والمسؤول عن ذلك هو جسيم ألفا (⁴₂He) الذي يحمل بروتونين ونيوترونين. أما أشعة جاما فلا تغيّر العددين لأنها طاقة عالية لا كتلة لها ولا شحنة.', '["العدد الذري ينقص 2 والعدد الكتلي ينقص 4","المسؤول جسيم ألفا","جاما لا كتلة لها ولا شحنة فلا تغيّر العددين"]'::jsonb, '["العدد الذري: 92 − 90 = 2","العدد الكتلي: 238 − 234 = 4"]'::jsonb, '[{"element":"حساب التغير في العدد الذري والكتلي","marks":1},{"element":"تحديد جسيم ألفا مسؤولًا","marks":1},{"element":"تعليل عدم تأثير جاما بانعدام الكتلة والشحنة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حساب صحيح وتحديد صحيح وتعليل صحيح"},{"level":"2 درجتان","description":"عنصران صحيحان من الثلاثة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة التغير في العددين إلى أشعة جاما","حساب التغير في العدد الكتلي بمقدار 2","عدّ أشعة جاما جسيمات ذات كتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.757Z"}'::jsonb)
