('mcq', 1, 0, 'تُوزن المعادلة النووية بحيث يتساوى مجموع الأعداد الكتلية ومجموع الأعداد الذرية في طرفيها؛ لذلك الجواب هو الخيار الأول.', '["","عدد الإلكترونات وعدد النيوترونات لا يُحفظان بهذه الصورة في المعادلة النووية.","الإلكترونات المحيطة بالنواة لا تدخل في موازنة المعادلة النووية.","المولات والحجم كميات تخص المعادلات الكيميائية والغازات، لا موازنة المعادلة النووية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.758Z"}'::jsonb),
('mcq', 2, 1, 'ينقص العدد الكتلي بمقدار 4 (10 − 4 = 6) والعدد الذري بمقدار 2 (5 − 2 = 3)، فالناتج ⁶₃Li؛ ويتحقق التوازن: 6 + 4 = 10 و3 + 2 = 5. لذلك الجواب هو الخيار الثاني.', '["مجموع الأعداد الكتلية 8 + 4 = 12 لا يساوي 10، فالمعادلة غير موزونة.","","مجموع الأعداد الذرية 4 + 2 = 6 لا يساوي 5، فالمعادلة غير موزونة.","هذه المعادلة تجمع العددين بدل طرح قيم ألفا، فمجموع الأعداد الكتلية 14 + 4 = 18 لا يساوي 10."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.758Z"}'::jsonb),
('mcq', 3, 3, 'العدد الكتلي يبقى 137، والعدد الذري = 55 − (−1) = 56، والعنصر الذي عدده الذري 56 هو الباريوم؛ فالناتج ¹³⁷₅₆Ba. لذلك الجواب هو الخيار الأخير.', '["هذا ينقص العدد الذري بمقدار 1 بدل زيادته؛ فبيتا يزيد العدد الذري.","هذه نواة ناتجة عن إصدار ألفا (133 و53) وليست عن إصدار بيتا.","العدد الذري صحيح، لكن العدد الكتلي لا يتغير عند إصدار بيتا فيبقى 137.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:27:04.758Z"}'::jsonb),
('mcq', 4, 2, 'العدد الكتلي = 210 − 4 = 206، والعدد الذري = 84 − 2 = 82، والعنصر ذو العدد الذري 82 هو الرصاص؛ فالناتج ²⁰⁶₈₂Pb. لذلك الجواب هو الخيار الثالث.', '["العدد الذري 86 ناتج عن زيادة 2 بدل إنقاصها، فالمعادلة غير موزونة.","هذا يجمع القيم بدل طرحها، فالمعادلة غير موزونة في العددين.","","هذا يطبّق نقص العدد الكتلي فقط، ويهمل نقص العدد الذري بمقدار 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.758Z"}'::jsonb),
('mcq', 5, 1, 'فرق العدد الكتلي بين الطرفين = 14 − 14 = 0، وفرق العدد الذري = 6 − 7 = −1؛ فالجسيم X هو ⁰₋₁e (جسيم بيتا). لذلك الجواب هو الخيار الثاني.', '["جسيم ألفا يحمل عددًا كتليًّا 4 وذريًّا 2، وهما لا يحققان التوازن هنا.","","النيوترون عدده الكتلي 1 وعدده الذري 0، فلا يحقق التوازن في العددين.","نواة الهيدروجين عددها الكتلي 1 وعددها الذري 1، فلا تحقق التوازن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.758Z"}'::jsonb),
('mcq', 6, 0, 'العدد الكتلي يبقى 234، والعدد الذري = 90 + 1 = 91، والعنصر ذو العدد الذري 91 هو البروتكتينيوم Pa؛ فالناتج ²³⁴₉₁Pa. لذلك الجواب هو الخيار الأول.', '["","هذه نواة ناتجة عن إصدار ألفا (230 و88) وليست عن إصدار بيتا.","العدد الذري 89 يعني إنقاص العدد الذري بمقدار 1 بدل زيادته.","العدد الكتلي لا يتغير عند إصدار بيتا، فلا يصبح 235."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:27:04.758Z"}'::jsonb),
('mcq', 7, 3, 'في الخيار الأخير: 222 + 4 = 226 و86 + 2 = 88، فالعددان الكتلي والذري محفوظان في الطرفين، فالمعادلة موزونة. لذلك الجواب هو الخيار الأخير.', '["مجموع الأعداد الذرية 84 + 2 = 86 لا يساوي 88.","مجموع الأعداد الكتلية 226 + 4 = 230 لا يساوي 226.","مجموع الأعداد الذرية 86 + (−1) = 85 لا يساوي 88، ومجموع الأعداد الكتلية 222 لا يساوي 226.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.758Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تحلل البورون-10 بإصدار ألفا: ¹⁰₅B → ⁶₃Li + ⁴₂He، فالعدد الكتلي 10 = 6 + 4 والعدد الذري 5 = 3 + 2. تحلل السيزيوم-137 بإصدار بيتا: ¹³⁷₅₅Cs → ¹³⁷₅₆Ba + ⁰₋₁e، فالعدد الكتلي 137 = 137 + 0 والعدد الذري 55 = 56 + (−1).', '["¹⁰₅B → ⁶₃Li + ⁴₂He","¹³⁷₅₅Cs → ¹³⁷₅₆Ba + ⁰₋₁e","التحقق من حفظ العددين الكتلي والذري"]'::jsonb, '["ألفا: العدد الكتلي 10 − 4 = 6، العدد الذري 5 − 2 = 3 فالناتج Li","بيتا: العدد الكتلي يبقى 137، العدد الذري 55 + 1 = 56 فالناتج Ba","التحقق من تساوي مجموعي العددين الكتلي والذري في الطرفين"]'::jsonb, '[{"element":"معادلة تحلل البورون-10 صحيحة وموزونة","marks":2},{"element":"معادلة تحلل السيزيوم-137 صحيحة وموزونة","marks":2},{"element":"التحقق من حفظ العددين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان صحيحتان وموزونتان مع التحقق من حفظ العددين"},{"level":"3–4 درجات","description":"معادلة صحيحة كاملة وأخرى بخطأ بسيط، أو دون تحقق"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة جزئيًّا أو تطبيق صحيح لقاعدة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إنقاص العدد الذري عند إصدار بيتا","تغيير العدد الكتلي عند إصدار بيتا","الإخلال بتساوي مجموعي العددين الذريين في الطرفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.759Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة: ²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He + 2 ⁰₀γ. العدد الكتلي: 238 = 234 + 4 + 0، والعدد الذري: 92 = 90 + 2 + 0. وأشعة جاما لا كتلة لها ولا شحنة، فلا تؤثر في موازنة العددين، لكنها تحمل معظم الطاقة المفقودة في التحلل.', '["²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He + 2 ⁰₀γ","حفظ العدد الكتلي والعدد الذري","جاما عددها الكتلي والذري صفر فلا تؤثر في الموازنة"]'::jsonb, '["العدد الكتلي: 234 + 4 + 0 = 238","العدد الذري: 90 + 2 + 0 = 92","جاما: كتلة 0 وشحنة 0 فلا تغيّر المجموعين"]'::jsonb, '[{"element":"كتابة المعادلة بالرموز والأعداد الصحيحة","marks":2},{"element":"التحقق من حفظ العددين الكتلي والذري","marks":1},{"element":"توضيح دور أشعة جاما في الموازنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة صحيحة وموزونة مع التحقق وتوضيح دور جاما"},{"level":"2–3 درجات","description":"معادلة صحيحة مع نقص في التحقق أو في توضيح دور جاما"},{"level":"1 درجة","description":"ذكر المتفاعل والناتج دون موازنة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إسناد عدد كتلي أو ذري إلى أشعة جاما","إهمال جسيم ألفا في المعادلة","عدم كتابة المعامل 2 أمام أشعة جاما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.759Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطوة الأولى (ألفا): ²²²₈₆Rn → ²¹⁸₈₄Po + ⁴₂He؛ العدد الكتلي 222 − 4 = 218، والعدد الذري 86 − 2 = 84. الخطوة الثانية (بيتا): ²¹⁸₈₄Po → ²¹⁸₈₅At + ⁰₋₁e؛ العدد الكتلي يبقى 218، والعدد الذري 84 + 1 = 85. فالنواة النهائية عددها الذري 85 وعددها الكتلي 218.', '["²²²₈₆Rn → ²¹⁸₈₄Po + ⁴₂He","²¹⁸₈₄Po → ²¹⁸₈₅At + ⁰₋₁e","العددان الذري والكتلي للنواتين الناتجتين"]'::jsonb, '["ألفا: 222 − 4 = 218 و86 − 2 = 84","بيتا: العدد الكتلي 218 ثابت، والعدد الذري 84 + 1 = 85","التحقق من حفظ العددين في كل معادلة"]'::jsonb, '[{"element":"معادلة الخطوة الأولى (ألفا) موزونة","marks":2},{"element":"معادلة الخطوة الثانية (بيتا) موزونة","marks":2},{"element":"تحديد العددين للنواتين الناتجتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان موزونتان مع تحديد صحيح للعددين لكل ناتج"},{"level":"3–4 درجات","description":"معادلة صحيحة كاملة وأخرى بخطأ بسيط"},{"level":"1–2 درجة","description":"تطبيق صحيح لقاعدة واحدة أو معادلة جزئية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إنقاص العدد الذري عند إصدار بيتا","الخطأ في العدد الكتلي عند ألفا (إنقاصه بمقدار 2)","استخدام النواة الأصلية بدل الناتجة في الخطوة الثانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.759Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C3-L4-O07') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C4-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما التعريف الصحيح للتفاعل الكيميائي؟', null, '["عملية تتغير فيها حالة المادة الفيزيائية دون تغير تركيبها","عملية يُعاد فيها ترتيب الذرات في مادة أو أكثر لتكوين مواد مختلفة","عملية تفنى فيها ذرات المواد المتفاعلة وتتكون ذرات جديدة","عملية تمتزج فيها مادتان أو أكثر دون أن تتغير خصائص أيٍّ منهما"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 112 — التفاعلات الكيميائية'),
('mcq', 2, 'ما الاسم الآخر الذي يُطلق على التفاعل الكيميائي؟', null, '["التغير الفيزيائي","التغير في الحالة","التغير في الشكل","التغير الكيميائي"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 112 — التفاعلات الكيميائية'),
('mcq', 3, 'أيّ العمليات الآتية تُعدّ مثالًا على تفاعل كيميائي؟', null, '["إلقاء قرص فوار في كأس ماء","انصهار قطعة جليد في الجو الدافئ","تبخر الماء من كأس مكشوفة","تكسير قطعة زجاج إلى أجزاء صغيرة"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'متوسط', 'الكتاب ص 112 — التفاعلات الكيميائية (القرص الفوار)'),
('mcq', 4, 'عند احتراق الخشب في حرائق الغابات يُعاد ترتيب الذرات. ما النتيجة المباشرة لإعادة ترتيب الذرات في أي تفاعل كيميائي؟', null, '["ازدياد عدد ذرات كل عنصر في المواد","تحول ذرات عنصر إلى ذرات عنصر آخر","تكوّن مواد مختلفة عن المواد الأصلية","اختفاء المواد الأصلية دون تكوّن مواد جديدة"]'::jsonb, 'فهم', 'فهم نتيجة التعريف', 'متوسط', 'الكتاب ص 112 — التفاعلات الكيميائية'),
('mcq', 5, 'لاحظ طالب أن مسمارًا حديديًّا ملقى في الفناء تحوّل لونه من فضي إلى بني بعد مدة قصيرة. أيّ التفسيرات الآتية أصحّ؟', null, '["تغير فيزيائي، لأن الحديد غيّر لونه فقط وبقي حديدًا","تغير فيزيائي، لأن الحديد تبخر مع بخار الماء الموجود في الجو","ذوبان الحديد في الأكسجين الموجود في الجو دون تكوّن مادة جديدة","تفاعل كيميائي بين الحديد والأكسجين وبخار الماء كوّن مادة جديدة"]'::jsonb, 'تطبيق', 'تطبيق التعريف على موقف جديد', 'صعب', 'الكتاب ص 113 — مؤشرات حدوث التفاعل الكيميائي (تغير اللون)'),
('mcq', 6, 'يُعرَّف التغير الكيميائي بأنه عملية تتضمن:', null, '["تحول مادة أو أكثر إلى مادة جديدة","تغير شكل المادة أو حجمها فقط","انتقال المادة من حالة فيزيائية إلى أخرى","اختلاط مادتين دون تكوين مادة ثالثة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 112 — مراجعة المفردات (التغير الكيميائي)'),
('mcq', 7, 'أيّ العمليات الآتية ليست تفاعلًا كيميائيًّا؟', null, '["إنتاج النايلون من مواد أولية","احتراق الأشجار في حرائق الغابات","انصهار قطعة من الشمع بالتسخين","تحول لون الموز من الأخضر إلى الأصفر"]'::jsonb, 'فهم', 'تمييز التغير الفيزيائي', 'متوسط', 'الكتاب ص 112–113 — التفاعلات الكيميائية'),
('essay', 1, 'عرّف التفاعل الكيميائي، واذكر الاسم الآخر الذي يُطلق عليه، ثم اذكر مثالين عليه من الحياة.', null, null, 'تذكر', 'تعريف مع أمثلة', 'متوسط', 'الكتاب ص 112 — التفاعلات الكيميائية'),
('essay', 2, 'قارن بين ما يحدث للذرات عند تبخر الماء وما يحدث لها عند احتراق الخشب، موضحًا أيّ العمليتين تُعدّ تفاعلًا كيميائيًّا ولماذا.', null, null, 'فهم', 'مقارنة مع تعليل', 'صعب', 'الكتاب ص 112 — التفاعلات الكيميائية (احتراق الخشب)'),
('essay', 3, 'ألقى طالب قرصًا فوارًا في كأس ماء فلاحظ تصاعد فقاعات غاز. هل ما حدث تفاعل كيميائي؟ فسّر إجابتك بالاستناد إلى تعريف التفاعل الكيميائي.', null, null, 'تحليل', 'تفسير موقف بالاستناد إلى تعريف', 'صعب', 'الكتاب ص 111–112 — التجربة الاستهلالية والتفاعلات الكيميائية')
