select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'التفاعل الكيميائي عملية يُعاد فيها ترتيب الذرات في مادة أو أكثر لتكوين مواد مختلفة، فالذرات نفسها تبقى لكنها ترتبط بطريقة جديدة.', '["هذا وصف للتغير الفيزيائي كالانصهار والتبخر، إذ لا تتكوّن مادة جديدة.","","الذرات لا تفنى ولا تستحدث في التفاعل الكيميائي، وإنما يُعاد ترتيبها فقط.","هذا وصف للمخلوط الذي تحتفظ مكوناته بخصائصها، أما في التفاعل فتتكون مواد جديدة بخصائص مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('mcq', 2, 3, 'يسمى التفاعل الكيميائي أيضًا التغير الكيميائي، وهو عملية تتحول فيها مادة أو أكثر إلى مادة جديدة.', '["التغير الفيزيائي لا تتكوّن فيه مادة جديدة، فهو يقابل التغير الكيميائي ولا يرادفه.","التغير في الحالة (كالانصهار والتبخر) تغير فيزيائي وليس تفاعلًا كيميائيًّا.","التغير في الشكل تغير فيزيائي لا تتكوّن فيه مادة جديدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('mcq', 3, 0, 'عند إلقاء القرص الفوار في الماء يُعاد ترتيب الذرات وتتكوّن مواد جديدة منها غاز يتصاعد، فهو تفاعل كيميائي.', '["","الانصهار تغير في الحالة الفيزيائية؛ فالماء يبقى ماءً ولا تتكوّن مادة جديدة.","التبخر تحول الماء السائل إلى بخار ماء دون إعادة ترتيب للذرات، فهو تغير فيزيائي.","التكسير يغيّر شكل الزجاج وحجم قطعه فقط، ولا تتكوّن مادة جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('mcq', 4, 2, 'إعادة ترتيب الذرات في المواد المتفاعلة تؤدي إلى ارتباطها بطرائق جديدة، فتتكوّن مواد مختلفة عن المواد الأصلية.', '["عدد ذرات كل عنصر لا يزداد، فالذرات لا تُستحدث، وإنما تُرتّب ترتيبًا جديدًا.","الذرات في التفاعل الكيميائي تبقى ذرات العنصر نفسه، وتتغير طريقة ارتباطها فقط.","","المواد الأصلية تتحول إلى مواد جديدة ولا تختفي من غير ناتج، فالذرات محفوظة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('mcq', 5, 3, 'تغير اللون هنا يدل على تفاعل كيميائي بين الحديد والأكسجين وبخار الماء في الجو؛ فقد أُعيد ترتيب الذرات وتكوّنت مادة جديدة بنية اللون غير الحديد.', '["لو بقي الحديد حديدًا لما تغير لونه هذا التغير؛ فاللون الجديد يعود إلى مادة جديدة تكوّنت.","الحديد لا يتبخر في درجة حرارة الجو، وتغير لونه ناتج عن تفاعله مع مكونات الهواء.","الحديد لا يذوب في الأكسجين، والتغير الحاصل ينتج مادة جديدة وليس مجرد انتشار مادة في أخرى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('mcq', 6, 0, 'التغير الكيميائي عملية تتضمن تحول مادة أو أكثر إلى مادة جديدة؛ وهو الاسم الآخر للتفاعل الكيميائي.', '["","تغير الشكل أو الحجم تغير فيزيائي لا تتكوّن فيه مادة جديدة.","تغير الحالة الفيزيائية لا يغيّر نوع المادة، فهو ليس تفاعلًا كيميائيًّا.","الاختلاط دون تكوين مادة جديدة يكوّن مخلوطًا، وهذا ليس تغيرًا كيميائيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('mcq', 7, 2, 'انصهار الشمع تغير في الحالة الفيزيائية فقط، فالشمع السائل هو الشمع نفسه ولا تُعاد فيه ترتيب الذرات؛ أما الباقي فتتكوّن فيه مواد جديدة.', '["إنتاج النايلون تفاعل كيميائي تتكوّن فيه مادة جديدة من مواد أولية.","احتراق الأشجار تفاعل كيميائي يُعاد فيه ترتيب الذرات وتتكوّن مواد جديدة.","","تحول لون الموز دليل على تفاعل كيميائي، إذ تتكوّن مواد جديدة داخل الثمرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التفاعل الكيميائي هو العملية التي يُعاد فيها ترتيب الذرات في مادة أو أكثر لتكوين مواد مختلفة. ويسمى أيضًا التغير الكيميائي. ومن أمثلته حرائق الغابات، وإلقاء القرص الفوار في الماء، وإنتاج النايلون.', '["إعادة ترتيب الذرات في مادة أو أكثر","تكوّن مواد مختلفة","الاسم الآخر: التغير الكيميائي","مثال أول صحيح","مثال ثانٍ صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التفاعل الكيميائي كاملًا","marks":2},{"element":"ذكر الاسم الآخر (التغير الكيميائي)","marks":1},{"element":"مثالان صحيحان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعريف كامل، والاسم الآخر، ومثالان صحيحان"},{"level":"3–4 درجات","description":"تعريف صحيح مع نقص في الاسم الآخر أو في أحد المثالين"},{"level":"1–2 درجة","description":"ذكر جزء من التعريف أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرات تفنى وتتكون ذرات جديدة","عدّ الانصهار أو التبخر مثالًا على التفاعل الكيميائي","إغفال أن الناتج مواد مختلفة عن المواد الأصلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-18T03:27:04.760Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند تبخر الماء يتحول الماء السائل إلى بخار ماء، والمادة بعد التبخر هي الماء نفسه، ولا يُعاد ترتيب الذرات لتكوين مادة مختلفة؛ لذلك هو تغير فيزيائي. أما احتراق الخشب فيُعاد فيه ترتيب الذرات في الخشب والأكسجين فتتكوّن مواد مختلفة عن المواد الأصلية، ويصاحبه إطلاق طاقة على شكل حرارة وضوء؛ لذلك يُعدّ تفاعلًا كيميائيًّا.', '["تبخر الماء: المادة هي الماء نفسه ولا تتكوّن مادة جديدة","تبخر الماء تغير فيزيائي","احتراق الخشب: يُعاد ترتيب الذرات","تتكوّن مواد مختلفة عن المواد الأصلية","احتراق الخشب هو التفاعل الكيميائي"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تبخر الماء وأنه تغير فيزيائي دون مادة جديدة","marks":2},{"element":"وصف احتراق الخشب وإعادة ترتيب الذرات وتكوّن مواد مختلفة","marks":2},{"element":"تحديد التفاعل الكيميائي مع تعليل صحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح للعمليتين، وتحديد الاحتراق تفاعلًا كيميائيًّا مع التعليل"},{"level":"3–4 درجات","description":"وصف صحيح لإحدى العمليتين وتحديد صحيح مع تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد صحيح للتفاعل دون تعليل أو بتعليل غير دقيق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن ذرات الماء تتغير إلى ذرات عنصر آخر عند التبخر","عدّ التبخر تفاعلًا كيميائيًّا لأن المظهر تغيّر","ذكر الحرارة والضوء دليلًا وحيدًا دون ذكر تكوّن مواد جديدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.761Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نعم، ما حدث تفاعل كيميائي؛ لأن ذرات مواد القرص والماء أُعيد ترتيبها فتكوّنت مواد مختلفة عن المواد الأصلية، ومنها الغاز المتصاعد. وتصاعد الغاز مؤشر ملحوظ يدل على أن مادة جديدة تكوّنت، وهذا ما ينص عليه تعريف التفاعل الكيميائي.', '["الحكم: ما حدث تفاعل كيميائي","إعادة ترتيب ذرات المواد","تكوّن مواد مختلفة عن الأصلية","تصاعد الغاز دليل على تكوّن مادة جديدة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح بأنه تفاعل كيميائي","marks":1},{"element":"ذكر إعادة ترتيب الذرات","marks":1},{"element":"ذكر تكوّن مواد مختلفة أو مادة جديدة","marks":1},{"element":"ربط تصاعد الغاز بتكوّن مادة جديدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تفسير كامل يربط التعريف بالمشاهدة"},{"level":"2–3 درجات","description":"حكم صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار تصاعد الغاز تبخرًا للماء","الاكتفاء بذكر الفقاعات دون ربطها بتعريف التفاعل","القول إن القرص ذاب فقط وبقي كما هو"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.761Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
