('mcq', 3, 'أيّ المؤشرات الآتية يصاحب احتراق الخشب؟', null, '["امتصاص الحرارة من الوسط المحيط فقط","إطلاق طاقة على شكل حرارة وضوء","تكوّن مادة صلبة تترسب في قاع الإناء","تغير حالة الخشب إلى الحالة الغازية فقط"]'::jsonb, 'تذكر', 'تذكر مؤشر', 'متوسط', 'الكتاب ص 112 — مؤشرات حدوث التفاعل الكيميائي (تغير درجة الحرارة)'),
('mcq', 4, 'أُجريت أربع تجارب كما في البيانات الآتية. أيّ التجارب يدل على حدوث تفاعل كيميائي؟', '{"headers":["التجربة","المشاهدة"],"rows":[["1","قطعة جليد تُترك في كأس فتتحول إلى ماء سائل"],["2","ملعقة سكر تُحرَّك في ماء فتختفي بلوراتها ويصبح الماء حلوًا"],["3","ورقة تُمزَّق إلى قطع صغيرة"],["4","شريط معدني يوضع في محلول حمض فتتصاعد فقاعات غاز ويسخن الوعاء"]]}'::jsonb, '["التجربة 1","التجربة 2","التجربة 3","التجربة 4"]'::jsonb, 'تطبيق', 'تطبيق المؤشرات على بيانات', 'متوسط', 'الكتاب ص 113 — مؤشرات حدوث التفاعل الكيميائي (تصاعد الغاز وتغير الحرارة)'),
('mcq', 5, 'خُلط محلولان في كأس، فتصاعدت فقاعات غاز وارتفعت درجة حرارة الخليط. كم مؤشرًا على حدوث التفاعل الكيميائي ظهر في هذه التجربة؟', null, '["لم يظهر أي مؤشر","مؤشران","مؤشر واحد","ثلاثة مؤشرات"]'::jsonb, 'تطبيق', 'عدّ المؤشرات في موقف', 'صعب', 'الكتاب ص 111، 113 — التجربة الاستهلالية ومؤشرات التفاعل'),
('mcq', 6, 'أيّ الأزواج الآتية يضم مؤشرين من مؤشرات حدوث التفاعل الكيميائي؟', null, '["تغير الشكل وتغير الحجم","الانصهار والتبخر","تصاعد الغاز وتغير اللون","تمزق الورق وتكسر الزجاج"]'::jsonb, 'فهم', 'تمييز المؤشرات', 'سهل', 'الكتاب ص 113 — مؤشرات حدوث التفاعل الكيميائي'),
('mcq', 7, 'عند خلط محلولين رائقين تكوّنت مادة صلبة ترسبت في قاع الكأس. ماذا تدل عليه هذه المشاهدة؟', null, '["حدوث تفاعل كيميائي نتجت عنه مادة صلبة جديدة","ذوبان إحدى المادتين في الأخرى فقط","تبخر أحد المحلولين وبقاء مادته","تجمد المحلول بفعل الحرارة"]'::jsonb, 'فهم', 'تفسير مشاهدة', 'متوسط', 'الكتاب ص 113 — مؤشرات حدوث التفاعل الكيميائي (تكوّن مادة صلبة)'),
('essay', 1, 'اذكر ثلاثة من المؤشرات التي تدل على حدوث تفاعل كيميائي، ومثّل لكل مؤشر بمشاهدة واحدة.', null, null, 'تذكر', 'تعداد مع أمثلة', 'متوسط', 'الكتاب ص 122 — التقويم 4-1 (السؤال 10)'),
('essay', 2, 'قد يشير تغير درجة الحرارة إلى حدوث تفاعل كيميائي. وضّح ذلك بمثالين مختلفين على أنواع تغير الحرارة في التفاعلات.', null, null, 'فهم', 'توضيح مؤشر بأمثلة', 'صعب', 'الكتاب ص 112 — مؤشرات حدوث التفاعل الكيميائي (تغير درجة الحرارة)'),
('essay', 3, 'سجّل طالب المشاهدات الآتية عند مزج محلولين: (1) تحول لون المحلول من عديم اللون إلى أزرق. (2) انخفضت درجة حرارة الخليط من 25 °C إلى 21 °C. (3) تصاعدت فقاعات غاز. (4) بقي الوعاء على شكله وحجمه. حدّد المشاهدات التي تدل على حدوث تفاعل كيميائي ونوع المؤشر في كل منها، وبيّن المشاهدة التي لا تدل عليه.', null, null, 'تحليل', 'تحليل مشاهدات', 'صعب', 'الكتاب ص 111، 113 — التجربة الاستهلالية ومؤشرات التفاعل')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
