select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تصاعد الغاز من مؤشرات حدوث التفاعل الكيميائي، لأنه يدل على تكوّن مادة جديدة غازية؛ أما تغير الشكل أو الحالة أو التكسّر فتغيرات فيزيائية.', '["طيّ الورق يغيّر الشكل فقط، ولا تتكوّن مادة جديدة.","تجمد الماء تغير في الحالة الفيزيائية، والمادة تبقى ماءً.","","التكسّر يغيّر الحجم والشكل فقط، فلا يدل على تفاعل كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.761Z"}'::jsonb),
('mcq', 2, 0, 'تحول لون الموز من الأخضر إلى الأصفر مثال على مؤشر تغير اللون الذي يدل على حدوث تفاعل كيميائي.', '["","لا يُلاحَظ في هذه المشاهدة تصاعد غاز، والمؤشر الظاهر هو تغير اللون.","لم تتكوّن مادة صلبة تترسب أو تظهر، والمشاهدة هي تغير اللون.","لم يُذكر تغير في درجة الحرارة، والمؤشر المذكور هو تغير اللون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.761Z"}'::jsonb),
('mcq', 3, 1, 'يطلق احتراق الخشب طاقة على شكل حرارة وضوء، وهذا تغير في درجة الحرارة يدل على حدوث تفاعل كيميائي.', '["الاحتراق يطلق الحرارة ولا يمتصها؛ والتفاعلات الماصة للحرارة نوع آخر من التفاعلات.","","الاحتراق لا يكوّن راسبًا في قاع إناء، ومؤشره الواضح هو الحرارة والضوء.","تغير الحالة وحده لا يعبّر عن الاحتراق؛ فالمؤشر المميز هو إطلاق الحرارة والضوء مع تكوّن مواد جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.761Z"}'::jsonb),
('mcq', 4, 3, 'في التجربة 4 ظهر مؤشران على التفاعل الكيميائي هما تصاعد الغاز وتغير درجة الحرارة (سخونة الوعاء)، أما التجارب الأخرى فتغيرات فيزيائية.', '["انصهار الجليد تغير في الحالة الفيزيائية، والماء هو المادة نفسها.","ذوبان السكر عملية فيزيائية، والحلاوة دليل على بقاء السكر بخصائصه.","تمزيق الورقة يغيّر الشكل فقط ولا تتكوّن مادة جديدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.762Z"}'::jsonb),
('mcq', 5, 1, 'ظهر مؤشران هما تصاعد الغاز وتغير درجة الحرارة (ارتفاعها)، ولم يُذكر تغير لون أو راسب أو رائحة.', '["لا صحة لذلك؛ فقد ظهر مؤشران فعلًا هما تصاعد الغاز وارتفاع درجة الحرارة.","","ظهر مؤشران لا مؤشر واحد؛ فتصاعد الغاز مؤشر وارتفاع الحرارة مؤشر آخر.","لم تُذكر في التجربة سوى مشاهدتين، ولم يُلاحَظ تغير لون أو راسب أو رائحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.762Z"}'::jsonb),
('mcq', 6, 2, 'تصاعد الغاز وتغير اللون كلاهما من مؤشرات التفاعل الكيميائي؛ أما بقية الأزواج فتغيرات فيزيائية لا تتكوّن فيها مادة جديدة.', '["تغير الشكل والحجم تغيران فيزيائيان فقط.","الانصهار والتبخر تغيران في الحالة الفيزيائية ولا يدلان على تفاعل.","","تمزق الورق وتكسر الزجاج تغيران في الشكل والحجم لا يكوّنان مادة جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.762Z"}'::jsonb),
('mcq', 7, 0, 'ظهور مادة صلبة من خلط محلولين رائقين مؤشر على حدوث تفاعل كيميائي تكوّن فيه ناتج صلب جديد.', '["","الذوبان لا يكوّن مادة صلبة جديدة تترسب من محلولين رائقين.","التبخر لا يكوّن مادة صلبة في القاع، والمحلولان لم يتبخرا.","التجمد يحتاج إلى خفض الحرارة، ولا ينتج مادة صلبة جديدة من خلط محلولين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.762Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من المؤشرات: (1) تغير اللون، مثل تحول لون الموز من الأخضر إلى الأصفر. (2) تصاعد غاز، مثل تصاعد فقاعات الغاز عند إلقاء قرص فوار في الماء. (3) تغير درجة الحرارة، مثل إطلاق الحرارة والضوء عند احتراق الخشب. ومن المؤشرات الأخرى ظهور رائحة، وتكوّن مادة صلبة.', '["ذكر ثلاثة مؤشرات صحيحة","مثال أو مشاهدة صحيحة لكل مؤشر"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر ثلاثة مؤشرات صحيحة (درجة لكل مؤشر)","marks":3},{"element":"ذكر مشاهدة صحيحة لكل مؤشر (درجة لكل مثال)","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"ثلاثة مؤشرات صحيحة مع مثال صحيح لكل منها"},{"level":"4–5 درجات","description":"ثلاثة مؤشرات صحيحة مع نقص في بعض الأمثلة"},{"level":"2–3 درجات","description":"مؤشران صحيحان أو ثلاثة مؤشرات دون أمثلة"},{"level":"1 درجة","description":"مؤشر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر تغير الحالة أو الشكل مؤشرًا على التفاعل الكيميائي","ذكر المؤشر دون مشاهدة تمثّله","تكرار المؤشر نفسه بصياغتين مختلفتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.762Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بعض التفاعلات تطلق طاقة على شكل حرارة وضوء، كاحتراق الخشب، فترتفع درجة حرارة الوسط ويظهر الضوء. وبعض التفاعلات تمتص الحرارة من الوسط المحيط فتنخفض درجة حرارته. وفي الحالتين يكون تغير درجة الحرارة مؤشرًا على حدوث التفاعل الكيميائي.', '["تفاعل يطلق حرارة وضوءًا مثل احتراق الخشب","ارتفاع درجة حرارة الوسط","تفاعل يمتص الحرارة","انخفاض درجة حرارة الوسط","تغير الحرارة مؤشر على التفاعل"]'::jsonb, '[]'::jsonb, '[{"element":"تفاعل يطلق الحرارة مع مثال صحيح","marks":2},{"element":"تفاعل يمتص الحرارة مع تأثيره في درجة حرارة الوسط","marks":1},{"element":"الربط بين تغير الحرارة وحدوث التفاعل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح النوعين وبمثال صحيح مع الربط بحدوث التفاعل"},{"level":"2–3 درجات","description":"توضيح أحد النوعين توضيحًا كاملًا مع ذكر ناقص للآخر"},{"level":"1 درجة","description":"ذكر أن الحرارة تتغير دون تفصيل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعلات كلها تطلق حرارة","ذكر ارتفاع الحرارة بسبب التسخين الخارجي دليلًا على التفاعل","الخلط بين الحرارة المطلقة والحرارة الممتصة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.763Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المشاهدة (1) تدل على تفاعل كيميائي، والمؤشر هو تغير اللون. المشاهدة (2) تدل على تفاعل، والمؤشر هو تغير درجة الحرارة (انخفاضها، أي أن التفاعل امتص الحرارة). المشاهدة (3) تدل على تفاعل، والمؤشر هو تصاعد غاز. أما المشاهدة (4) فلا تدل على تفاعل؛ لأن بقاء شكل الوعاء وحجمه لا علاقة له بتكوّن مادة جديدة، وهو ليس من مؤشرات التفاعل الكيميائي.', '["المشاهدة 1: تغير اللون","المشاهدة 2: تغير درجة الحرارة (انخفاض)","المشاهدة 3: تصاعد غاز","المشاهدة 4 لا تدل على تفاعل مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"المشاهدة 1 ومؤشرها","marks":1},{"element":"المشاهدة 2 ومؤشرها","marks":1},{"element":"المشاهدة 3 ومؤشرها","marks":1},{"element":"المشاهدة 4 لا تدل على تفاعل مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد المشاهدات الثلاث مع مؤشراتها، واستبعاد الرابعة مع تعليل صحيح"},{"level":"2–3 درجات","description":"تحديد صحيح لمعظم المشاهدات مع نقص في المؤشر أو التعليل"},{"level":"1 درجة","description":"تحديد مشاهدة واحدة فقط تحديدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استبعاد انخفاض درجة الحرارة لأن التفاعلات في نظر الطالب تطلق حرارة دائمًا","اعتبار بقاء الشكل والحجم مؤشرًا على التفاعل","ذكر المشاهدة دون تسمية المؤشر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.763Z"}'::jsonb)
