('essay', 2, null::int, null, null, 'سعة المستوى الأول = 2 × 1² = 2، والثاني = 2 × 2² = 8، والثالث = 2 × 3² = 18. المجموع = 2 + 8 + 18 = 28 إلكترونًا. سعة المستوى الرابع = 2 × 4² = 32. الزيادة = 32 − 28 = 4 إلكترونات.', '["سعات المستويات 1 و2 و3 هي 2 و8 و18","المجموع 28 إلكترونًا","سعة المستوى الرابع 32","الفرق 4 إلكترونات"]'::jsonb, '["e₁ = 2 × 1² = 2","e₂ = 2 × 2² = 8","e₃ = 2 × 3² = 18","المجموع = 2 + 8 + 18 = 28","e₄ = 2 × 4² = 32","الزيادة = 32 − 28 = 4"]'::jsonb, '[{"element":"حساب سعات المستويات الثلاثة الأولى بالقانون","marks":1},{"element":"جمع السعات للحصول على 28","marks":1},{"element":"حساب سعة المستوى الرابع (32)","marks":1},{"element":"حساب الفرق 4 إلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل بالخطوات والنتيجتين 28 و4"},{"level":"2–3 درجات","description":"حساب صحيح لبعض الخطوات مع خطأ حسابي أو نقص في الخطوات"},{"level":"1 درجة","description":"تطبيق القانون على مستوى واحد فقط تطبيقًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب سعة المستوى الرابع وحدها على أنها المجموع","استعمال e = n² أو e = 2n","طرح 32 من 18 بدل طرح مجموع السعات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.765Z"}'::jsonb),
('essay', 3, null::int, null, null, 'سعة المستوى الثاني e = 2 × 2² = 8، وسعة المستوى الرابع e = 2 × 4² = 32. النسبة 32 ÷ 8 = 4؛ أي أن سعة المستوى الرابع أربعة أضعاف سعة المستوى الثاني وليست ضعفها. فادّعاء الطالب غير صحيح؛ لأن السعة تتناسب مع مربع رقم المستوى (n²) وليس مع n نفسه، فمضاعفة n تضاعف السعة أربع مرات.', '["سعة المستوى الثاني 8","سعة المستوى الرابع 32","النسبة 4 وليست 2","الادّعاء غير صحيح","السبب: السعة تتناسب مع n²"]'::jsonb, '["e₂ = 2 × 2² = 8","e₄ = 2 × 4² = 32","32 ÷ 8 = 4","النسبة 4 ≠ 2؛ فالادّعاء غير صحيح"]'::jsonb, '[{"element":"حساب سعة المستوى الثاني (8)","marks":1},{"element":"حساب سعة المستوى الرابع (32)","marks":1},{"element":"حساب النسبة (4) والحكم بعدم صحة الادّعاء","marks":1},{"element":"تعليل ذلك بأن السعة تتناسب مع n²","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب السعتين والنسبة، والحكم الصحيح مع التعليل بـ n²"},{"level":"2–3 درجات","description":"حساب صحيح للسعتين والحكم دون تعليل، أو تعليل مع خطأ حسابي"},{"level":"1 درجة","description":"حساب سعة واحدة فقط حسابًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول الادّعاء لأن 4 = 2 × 2 دون حساب السعتين","قسمة 8 على 32 فتأتي النسبة معكوسة","الخلط بين التناسب مع n والتناسب مع n²"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.765Z"}'::jsonb)
